  "aftercare": {label:"Nachsorge",gender:"die",plural:"Nachsorgen", ex5:[{t:1,s:"Eine richtige Nachsorge ist für eine schnelle Genesung nach der Operation wichtig."},{t:2,s:"Der Tätowierer erklärte die Anweisungen zur Nachsorge."},{t:3,s:"Unsere Schule bietet eine Nachsorge für Kinder berufstätiger Eltern an."},{t:4,s:"Die medizinische Nachsorge ist ein wichtiger Teil des Heilungsprozesses."},{t:5,s:"Nach der Behandlung ist eine gute Nachsorge entscheidend."}]},
  "afterglow": {label:"Nachglühen",gender:"das",plural:"—", ex5:[{t:1,s:"Wir saßen am Strand und genossen das Nachglühen des Sonnenuntergangs."},{t:2,s:"Der Himmel war erfüllt vom sanften Nachglühen des Abends."},{t:3,s:"Sie spürte ein Nachglühen des Glücks nach ihrem Erfolg."},{t:4,s:"Das Nachglühen am Horizont war wunderschön."},{t:5,s:"Wir beobachteten das Nachglühen über den Bergen."}]},
  "afterlife": {label:"Jenseits",gender:"das",plural:"—", ex5:[{t:1,s:"Das Jenseits fasziniert die Menschen."},{t:2,s:"Das Jenseits ist ein mysteriöser Ort."},{t:3,s:"Sie stellen sich ein Leben im Jenseits vor."},{t:4,s:"Viele Kulturen haben Vorstellungen vom Jenseits."},{t:5,s:"Niemand weiß genau, was es im Jenseits gibt."}]},
  "aftermarket": {label:"Aftermarket",gender:"das",plural:"—", ex5:[{t:1,s:"Man kann im Aftermarket günstigere Ersatzteile kaufen."},{t:2,s:"Er hat Aftermarket-Felgen an seinen Sportwagen montiert."},{t:3,s:"Der Aftermarket für Smartphone-Zubehör ist riesig."},{t:4,s:"Viele Werkstätten bieten Teile aus dem Aftermarket an."},{t:5,s:"Der Aftermarket bietet viele Optionen für Autotuning."}]},
