  "afterthought": {label:"Nachtrag",gender:"der",plural:"Nachträge", ex5:[{t:1,s:"Die Veranda war offensichtlich ein späterer Nachtrag zum Haus."},{t:2,s:"Er erwähnte den Preis als Nachtrag am Ende des Telefonats."},{t:3,s:"Betrachte deine Gesundheit nicht als einen bloßen Nachtrag."},{t:4,s:"Dieser Punkt war nur ein Nachtrag in seinem Bericht."},{t:5,s:"Der Brief enthielt einen wichtigen Nachtrag."}]},
  "afterward": {label:"danach",gender:"",plural:"—", ex5:[{t:1,s:"Sie sprachen danach miteinander."},{t:2,s:"Die Stimmung war danach sehr ruhig."},{t:3,s:"Wir haben uns danach getroffen."},{t:4,s:"Danach gingen wir direkt nach Hause."},{t:5,s:"Was passierte danach?"}]},
