  "agent": {label:"Agent",gender:"der",plural:"Agenten", ex5:[{t:1,s:"Der Agent hat den Bericht eingereicht."},{t:2,s:"Der Agent ist sehr scharfsinnig."},{t:3,s:"Wir haben uns mit dem Agenten getroffen."},{t:4,s:"Er arbeitet als Agent für eine Versicherung."},{t:5,s:"Der Agent hat den Vertrag vorbereitet."}]},
  "agents": {label:"Agenten",gender:"die",plural:"Agenten", ex5:[{t:1,s:"Die Agenten haben sich versammelt."},{t:2,s:"Die Agenten sind bestens ausgebildet."},{t:3,s:"Wir haben die Agenten kurz gebrieft."},{t:4,s:"Mehrere Agenten waren an dem Projekt beteiligt."},{t:5,s:"Die Agenten arbeiten im Geheimen."}]},
