  "angie": {label:"Angie",gender:"die",plural:"—", ex5:[{t:1,s:"Angie kommt später mit ihren Freunden zur Party."},{t:2,s:"Ich habe Angie gefragt, ob sie in unserer Lerngruppe mitmachen möchte."},{t:3,s:"Angie arbeitet als Grafikdesignerin in der Innenstadt."},{t:4,s:"Angie hat zwei Katzen und einen Hund."},{t:5,s:"Am Wochenende gehe ich oft mit Angie einkaufen."}]},
  "angina": {label:"Angina",gender:"die",plural:"Anginen", ex5:[{t:1,s:"Er leidet an Angina und muss täglich seine Medikamente nehmen."},{t:2,s:"Brustschmerzen sind das häufigste Symptom bei Angina."},{t:3,s:"Der Arzt warnte ihn, dass Stress seine Angina verschlimmern könnte."},{t:4,s:"Wegen seiner Angina muss er sich körperlich schonen."},{t:5,s:"Die Angina wurde frühzeitig erkannt und behandelt."}]},
