  "ants": {label:"Ameisen",gender:"die",plural:"Ameisen", ex5:[{t:1,s:"Schau dir die Ameisen an, die in einer Reihe marschieren."},{t:2,s:"Ich habe einige Ameisen in der Küche gefunden."},{t:3,s:"Lass kein Essen offen stehen, sonst kommen die Ameisen."},{t:4,s:"Im Garten gibt es viele Ameisen."},{t:5,s:"Ameisen sind sehr fleißige Tiere."}]},
  "antsy": {label:"unruhig",gender:"",plural:"—", ex5:[{t:1,s:"Ich werde bei langen Meetings immer unruhig."},{t:2,s:"Die Kinder waren vor der Reise sehr unruhig."},{t:3,s:"Er fühlte sich unruhig, während er auf die Ergebnisse wartete."},{t:4,s:"Warum bist du so unruhig heute?"},{t:5,s:"Es macht mich unruhig, wenn ich nichts zu tun habe."}]},
  "antwerp": {label:"Antwerpen",gender:"",plural:"—", ex5:[{t:1,s:"Antwerpen ist eine berühmte Hafenstadt in Belgien."},{t:2,s:"Wir haben ein wundervolles Wochenende in Antwerpen verbracht."},{t:3,s:"Das Diamantenviertel in Antwerpen ist weltberühmt."},{t:4,s:"Antwerpen ist eine sehr geschäftige Stadt."},{t:5,s:"Ich möchte unbedingt einmal nach Antwerpen reisen."}]},
  "anu": {label:"Anu",gender:"",plural:"—", ex5:[{t:1,s:"Anu galt in der sumerischen Mythologie als der König der Götter."},{t:2,s:"Die Schüler lasen im Geschichtsunterricht Geschichten über Anu."},{t:3,s:"Der Tempel wurde der Verehrung von Anu gewidmet."},{t:4,s:"Anu ist eine zentrale Figur in alten Mythen."},{t:5,s:"Man findet viele Texte über den Gott Anu."}]},
  "anvil": {label:"Amboss",gender:"der",plural:"Ambosse", ex5:[{t:1,s:"Der Schmied legte das heiße Metall auf den Amboss."},{t:2,s:"Ein Amboss ist ein schwerer Stahlblock, der zum Formen von Metall dient."},{t:3,s:"Er schlug mit einem Hammer gegen das Metall auf dem Amboss."},{t:4,s:"In der Werkstatt steht ein sehr alter Amboss."},{t:5,s:"Der Schmied hämmert das Eisen auf dem Amboss."}]},
  "anwar": {label:"Anwar",gender:"",plural:"—", ex5:[{t:1,s:"Anwar plant, nächsten Monat seine Familie zu besuchen."},{t:2,s:"Ich habe Anwar gestern in der Bibliothek getroffen."},{t:3,s:"Anwar ist der beste Schüler in unserem naturwissenschaftlichen Kurs."},{t:4,s:"Anwar lernt sehr fleißig für die Prüfung."},{t:5,s:"Ich habe mich gestern mit Anwar unterhalten."}]},
  "anxieties": {label:"Ängste",gender:"die",plural:"Ängste", ex5:[{t:1,s:"Das Gespräch mit einem Freund kann helfen, Ängste abzubauen."},{t:2,s:"Viele Schüler haben Ängste vor den Abschlussprüfungen."},{t:3,s:"Sie äußerte ihre tiefen Ängste bezüglich der Zukunft."},{t:4,s:"Man sollte seine Ängste nicht einfach ignorieren."},{t:5,s:"Er sprach offen über seine Ängste."}]},
  "anxiety": {label:"Angst",gender:"die",plural:"Ängste", ex5:[{t:1,s:"Die Angst stieg stetig an."},{t:2,s:"Die Angst ist ein ständiger Begleiter."},{t:3,s:"Wir haben unsere Angst bewältigt."},{t:4,s:"Vor der Prüfung hatte ich große Angst."},{t:5,s:"Sie konnte ihre Angst nicht verbergen."}]},
  "anxious": {label:"ängstlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie fühlte sich ängstlich."},{t:2,s:"Er wirkt heute sehr ängstlich."},{t:3,s:"Wir wurden mit der Zeit ängstlich."},{t:4,s:"Das Kind war ängstlich vor dem Hund."},{t:5,s:"Sei nicht so ängstlich."}]},
  "anxiously": {label:"ängstlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie warteten ängstlich auf das Ergebnis."},{t:2,s:"Sie blickte ängstlich zur Tür."},{t:3,s:"Wir beobachteten die Situation ängstlich."},{t:4,s:"Er fragte ängstlich nach dem Weg."},{t:5,s:"Das Tier sah ängstlich um sich."}]},
  "any": {label:"irgendein",gender:"",plural:"—", ex5:[{t:1,s:"Irgendein Buch wird schon passen."},{t:2,s:"Ich nehme irgendein Getränk."},{t:3,s:"Hast du irgendeine Idee?"},{t:4,s:"Irgendein Weg führt sicher zum Ziel."},{t:5,s:"Gibt es irgendein Problem?"}]},
  "anya": {label:"Anya",gender:"",plural:"—", ex5:[{t:1,s:"Anya ist meine beste Freundin in der Schule."},{t:2,s:"Hast du Anya heute in der Bibliothek gesehen?"},{t:3,s:"Anya malt gerne schöne Bilder."},{t:4,s:"Anya ist ein sehr nettes Mädchen."},{t:5,s:"Anya hat uns besucht."}]},
  "anybody": {label:"jemand",gender:"",plural:"—", ex5:[{t:1,s:"Jemand kann das sicher erklären."},{t:2,s:"Ist jemand zu Hause?"},{t:3,s:"Wir fragten, ob jemand Bescheid wusste."},{t:4,s:"Jemand muss den Schlüssel haben."},{t:5,s:"Kann mir jemand kurz helfen?"}]},
  "anyhow": {label:"auf jeden Fall",gender:"",plural:"—", ex5:[{t:1,s:"Auf jeden Fall sind wir gegangen."},{t:2,s:"Es regnete, aber wir gingen auf jeden Fall."},{t:3,s:"Wir haben es auf jeden Fall beendet."},{t:4,s:"Auf jeden Fall ist das eine gute Idee."},{t:5,s:"Ich komme auf jeden Fall vorbei."}]},
