  "anyone": {label:"jeder",gender:"",plural:"—", ex5:[{t:1,s:"Jeder kann das lernen."},{t:2,s:"Jeder ist dazu in der Lage."},{t:3,s:"Wir haben jedem geholfen, der Hilfe brauchte."},{t:4,s:"Jeder weiß, wie es geht."},{t:5,s:"Das kann jeder schaffen."}]},
  "anyplace": {label:"überall",gender:"",plural:"—", ex5:[{t:1,s:"Man kann in dieser Stadt überall Cafés finden."},{t:2,s:"Ich würde überall hingehen, wenn ich mit dir reisen könnte."},{t:3,s:"Er fühlte sich, als würde er überall nicht dazugehören."},{t:4,s:"Du kannst dich überall hinsetzen, wo du willst."},{t:5,s:"Mit dem Internet kann man überall arbeiten."}]},
  "anything": {label:"alles",gender:"",plural:"—", ex5:[{t:1,s:"Alles kann passieren."},{t:2,s:"Alles ist möglich."},{t:3,s:"Wir probieren alles einmal aus."},{t:4,s:"Du kannst mich alles fragen."},{t:5,s:"Er kann alles essen, was er will."}]},
  "anytime": {label:"jederzeit",gender:"",plural:"—", ex5:[{t:1,s:"Rufen Sie mich jederzeit an."},{t:2,s:"Das Geschäft ist jederzeit geöffnet."},{t:3,s:"Wir können uns jederzeit treffen."},{t:4,s:"Ich bin jederzeit bereit zu helfen."},{t:5,s:"Sie können jederzeit Fragen stellen."}]},
  "anyway": {label:"jedenfalls",gender:"",plural:"—", ex5:[{t:1,s:"Jedenfalls ist es vorbei."},{t:2,s:"Es war spät, aber wir sind jedenfalls geblieben."},{t:3,s:"Wir haben es jedenfalls versucht."},{t:4,s:"Jedenfalls ist er jetzt hier."},{t:5,s:"Ich danke dir jedenfalls für deine Hilfe."}]},
  "anyways": {label:"jedenfalls",gender:"",plural:"—", ex5:[{t:1,s:"Ich stimme nicht zu, aber jedenfalls machen wir weiter."},{t:2,s:"Er kam zu spät, aber jedenfalls hat er sich entschuldigt."},{t:3,s:"Es ist ein schwieriges Problem, aber jedenfalls müssen wir es versuchen."},{t:4,s:"Jedenfalls bin ich morgen wieder da."},{t:5,s:"Das ist jedenfalls eine gute Idee."}]},
  "anywhere": {label:"überall",gender:"",plural:"—", ex5:[{t:1,s:"Du kannst überall hingehen, wo du möchtest."},{t:2,s:"Das Signal funktioniert überall."},{t:3,s:"Wir können überall lernen."},{t:4,s:"Es regnet heute überall im Land."},{t:5,s:"Ich habe überall nach meinem Schlüssel gesucht."}]},
  "anzac": {label:"ANZAC",gender:"",plural:"—", ex5:[{t:1,s:"Die Menschen ehren die ANZAC-Soldaten an besonderen Tagen."},{t:2,s:"Der ANZAC-Geist wird für seinen Mut in Erinnerung gerufen."},{t:3,s:"Viele Australier nehmen an der ANZAC-Tag-Parade teil."},{t:4,s:"ANZAC steht für Soldaten des Ersten Weltkriegs."},{t:5,s:"Das Erbe der ANZAC wird geehrt."}]},
  "aorta": {label:"Aorta",gender:"die",plural:"Aorten", ex5:[{t:1,s:"Die Aorta ist die größte Arterie im menschlichen Körper."},{t:2,s:"Blut fließt vom Herzen in die Aorta."},{t:3,s:"Der Chirurg operierte die Aorta des Patienten."},{t:4,s:"Die Aorta versorgt den Körper mit Blut."},{t:5,s:"Ein Riss in der Aorta ist lebensgefährlich."}]},
  "aortic": {label:"aortisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Chirurg untersuchte die aortische Klappe sorgfältig."},{t:2,s:"Ein aortisches Aneurysma erfordert sofortige medizinische Hilfe."},{t:3,s:"Das Blut fließt durch den aortischen Bogen."},{t:4,s:"Sie leidet unter einem aortischen Klappenfehler."},{t:5,s:"Die aortische Wand muss stabil bleiben."}]},
  "apace": {label:"schnell",gender:"",plural:"—", ex5:[{t:1,s:"Die Arbeit ging am Vormittag schnell voran."},{t:2,s:"Die Reformen wurden unter dem neuen Leiter schnell umgesetzt."},{t:3,s:"Die Stadt wuchs in jenen Jahren sehr schnell."},{t:4,s:"Die Entwicklung schreitet schnell voran."},{t:5,s:"Wir müssen schnell handeln."}]},
  "apache": {label:"Apache",gender:"der",plural:"Apachen", ex5:[{t:1,s:"Das Volk der Apache hat eine reiche Kulturgeschichte."},{t:2,s:"Wir haben heute in der Schule viel über die Apache gelernt."},{t:3,s:"Das Museum zeigt eine Ausstellung über die Traditionen der Apache."},{t:4,s:"Die Geschichte der Apache ist sehr faszinierend."},{t:5,s:"Er interessiert sich für die Kultur der Apache."}]},
  "apart": {label:"auseinander",gender:"",plural:"—", ex5:[{t:1,s:"Sie haben sich mit der Zeit auseinander gelebt."},{t:2,s:"Das Spielzeug ist ganz einfach auseinander gefallen."},{t:3,s:"Wir haben das Gerät vorsichtig auseinander genommen."},{t:4,s:"Die beiden Häuser stehen ein Stück auseinander."},{t:5,s:"Man muss die Teile auseinander halten."}]},
  "apartheid": {label:"Apartheid",gender:"die",plural:"—", ex5:[{t:1,s:"Die Apartheid ist glücklicherweise beendet worden."},{t:2,s:"Die Apartheid war ein grausames System."},{t:3,s:"Viele Menschen haben gegen die Apartheid gekämpft."},{t:4,s:"Wir haben im Geschichtsunterricht über die Apartheid gesprochen."},{t:5,s:"Die Apartheid hinterließ tiefe Wunden in der Gesellschaft."}]},
