  "apartments": {label:"Apartments",gender:"die",plural:"Apartments", ex5:[{t:1,s:"In der Stadt wurden viele neue Apartments gebaut."},{t:2,s:"Die Apartments in diesem Komplex sind sehr modern."},{t:3,s:"Wir haben uns heute mehrere Apartments angesehen."},{t:4,s:"Diese Apartments sind bei Studenten sehr beliebt."},{t:5,s:"Die Apartments bieten eine tolle Aussicht auf den Park."}]},
  "apathetic": {label:"apathetisch",gender:"",plural:"—", ex5:[{t:1,s:"Er wirkte völlig apathetisch gegenüber dem Ergebnis des Spiels."},{t:2,s:"Die Schüler waren während der langen Vorlesung sehr apathetisch."},{t:3,s:"Man sollte nicht apathetisch in Bezug auf die eigene Zukunft sein."},{t:4,s:"Sie zeigte eine apathetische Haltung gegenüber der Diskussion."},{t:5,s:"Sein apathetisches Verhalten hat uns alle überrascht."}]},
  "apathy": {label:"Apathie",gender:"die",plural:"—", ex5:[{t:1,s:"Eine gewisse Apathie hat sich in der Gruppe ausgebreitet."},{t:2,s:"Die allgemeine Apathie der Bevölkerung ist beunruhigend."},{t:3,s:"Wir haben versucht, gegen die Apathie der Wähler anzukämpfen."},{t:4,s:"Seine Apathie macht es schwer, mit ihm zu reden."},{t:5,s:"Man muss die Apathie überwinden, um etwas zu verändern."}]},
  "ape": {label:"Affe",gender:"der",plural:"Affen", ex5:[{t:1,s:"Der Affe kletterte geschickt auf den Baum."},{t:2,s:"Ein großer Affe ist erstaunlich stark."},{t:3,s:"Wir haben den Affen im Zoo beobachtet."},{t:4,s:"Der Affe ist ein faszinierendes Tier."},{t:5,s:"Im Dschungel sahen wir viele Affen."}]},
  "aperitif": {label:"Aperitif",gender:"der",plural:"Aperitifs", ex5:[{t:1,s:"Vor dem Abendessen gab es einen Aperitif."},{t:2,s:"Ein leichter Aperitif regt den Appetit an."},{t:3,s:"Er trank seinen Aperitif gemütlich auf der Terrasse."},{t:4,s:"Wir haben uns vor dem Essen einen Aperitif gegönnt."},{t:5,s:"Der Aperitif wurde in kleinen Gläsern serviert."}]},
  "aperture": {label:"Blende",gender:"die",plural:"Blenden", ex5:[{t:1,s:"Eine große Blende lässt mehr Licht in die Kamera."},{t:2,s:"Der Fotograf stellte die Blende für den dunklen Raum ein."},{t:3,s:"Eine kleine Blende erhöht die Schärfentiefe."},{t:4,s:"Man muss die Blende genau an das Licht anpassen."},{t:5,s:"Durch die Blende kann man die Belichtung steuern."}]},
  "apertures": {label:"Blende",gender:"die",plural:"Blenden", ex5:[{t:1,s:"Die Kamera hat eine einstellbare Blende."},{t:2,s:"Durch die kleine Blende fällt nur wenig Licht ein."},{t:3,s:"Er hat die Blende des Teleskops genau untersucht."},{t:4,s:"Eine große Blende sorgt für einen unscharfen Hintergrund."},{t:5,s:"Die Blende muss für dieses Foto angepasst werden."}]},
  "apes": {label:"Menschenaffe",gender:"der",plural:"Menschenaffen", ex5:[{t:1,s:"Menschenaffen sind für ihre Intelligenz bekannt."},{t:2,s:"Wir sahen einen Film über das Verhalten von Menschenaffen."},{t:3,s:"Manche Menschenaffen benutzen einfache Werkzeuge."},{t:4,s:"Der Schutz der Menschenaffen ist sehr wichtig."},{t:5,s:"Menschenaffen leben in sozialen Gruppen."}]},
  "apex": {label:"Spitze",gender:"die",plural:"Spitzen", ex5:[{t:1,s:"Die Spitze des Berges leuchtete in der Sonne."},{t:2,s:"Die Spitze ist sehr scharf."},{t:3,s:"Wir haben die Spitze erreicht."},{t:4,s:"Er berührte die Spitze des Turms."},{t:5,s:"An der Spitze des Baumes saß ein Vogel."}]},
  "aphasia": {label:"Aphasie",gender:"die",plural:"Aphasien", ex5:[{t:1,s:"Er litt nach dem Unfall an einer Aphasie."},{t:2,s:"Aphasie kann das Sprachverständnis erschweren."},{t:3,s:"Sie geht zur Therapie, um ihre Aphasie zu behandeln."},{t:4,s:"Menschen mit Aphasie brauchen viel Geduld."},{t:5,s:"Die Aphasie beeinträchtigt seine tägliche Kommunikation."}]},
  "aphid": {label:"Blattlaus",gender:"die",plural:"Blattläuse", ex5:[{t:1,s:"Eine einzelne Blattlaus sitzt auf dem Blatt."},{t:2,s:"Die Blattlaus saugt den Saft der Pflanze aus."},{t:3,s:"Ich habe eine Blattlaus an der Rose entdeckt."},{t:4,s:"Jede Blattlaus schadet dem Wachstum der Pflanze."},{t:5,s:"Man kann die Blattlaus vorsichtig entfernen."}]},
  "aphids": {label:"Blattläuse",gender:"die",plural:"Blattläuse", ex5:[{t:1,s:"Blattläuse schädigen die Pflanzen durch das Saugen von Saft."},{t:2,s:"Der Gärtner bekämpft die Blattläuse mit Seifenlauge."},{t:3,s:"Kleine Kolonien von Blattläusen waren auf den Blättern."},{t:4,s:"Man muss die Blattläuse regelmäßig kontrollieren."},{t:5,s:"Diese Pflanze ist anfällig für Blattläuse."}]},
  "aphrodite": {label:"Aphrodite",gender:"die",plural:"—", ex5:[{t:1,s:"Aphrodite ist die Göttin der Liebe und Schönheit."},{t:2,s:"Wir haben im Unterricht über Aphrodite gesprochen."},{t:3,s:"Viele Statuen der Aphrodite wurden in Griechenland gefunden."},{t:4,s:"Aphrodite spielt in vielen Mythen eine Rolle."},{t:5,s:"Das Bild zeigt die Geburt der Aphrodite."}]},
  "api": {label:"API",gender:"die",plural:"APIs", ex5:[{t:1,s:"Der Entwickler arbeitet an der API-Integration."},{t:2,s:"Wir müssen die Daten über die öffentliche API abrufen."},{t:3,s:"Die App nutzt eine Wetter-API für die Vorhersage."},{t:4,s:"Diese API ist sehr einfach zu bedienen."},{t:5,s:"Die Dokumentation der API ist online verfügbar."}]},
  "apical": {label:"apikal",gender:"",plural:"—", ex5:[{t:1,s:"Die apikalen Knospen steuern das vertikale Wachstum."},{t:2,s:"Apikale Dominanz verhindert ein zu schnelles Wachstum der Seitentriebe."},{t:3,s:"Die Infektion saß im apikalen Bereich der Zahnwurzel."},{t:4,s:"Das apikale Ende der Pflanze ist besonders empfindlich."},{t:5,s:"Wir untersuchten die apikale Struktur unter dem Mikroskop."}]},
  "apiece": {label:"pro Stück",gender:"",plural:"—", ex5:[{t:1,s:"Sie kosten einen Dollar pro Stück."},{t:2,s:"Die Kuchen kosten fünf Euro pro Stück."},{t:3,s:"Wir haben zwei pro Stück gekauft."},{t:4,s:"Der Preis liegt bei zwei Euro pro Stück."},{t:5,s:"Jeder bekommt einen Apfel pro Stück."}]},
