  "aqua": {label:"Aquablau",gender:"das",plural:"—", ex5:[{t:1,s:"Das Wasser im Pool hatte ein klares Aquablau."},{t:2,s:"Sie trug einen Badeanzug in Aquablau."},{t:3,s:"Die Wandfarbe ist ein helles Aquablau."},{t:4,s:"Aquablau erinnert an das Meer."},{t:5,s:"Er mischte die Farben zu einem schönen Aquablau."}]},
  "aquaculture": {label:"Aquakultur",gender:"die",plural:"Aquakulturen", ex5:[{t:1,s:"Die Aquakultur gewinnt als Industrie an Bedeutung."},{t:2,s:"Sie nutzen nachhaltige Methoden für ihre Aquakultur."},{t:3,s:"Er studiert Aquakultur an der Universität."},{t:4,s:"Die Aquakultur bietet eine Alternative zum Fischfang."},{t:5,s:"In der Aquakultur werden verschiedene Fischarten gezüchtet."}]},
