  "aquatic": {label:"aquatisch",gender:"",plural:"—", ex5:[{t:1,s:"Viele aquatische Lebewesen gedeihen in diesem See."},{t:2,s:"Diese Pflanze ist aquatisch und braucht viel Wasser."},{t:3,s:"Wir erforschen aquatische Tiere und ihre Lebensräume."},{t:4,s:"Der Fluss ist ein wichtiger Lebensraum für aquatische Insekten."},{t:5,s:"Umweltverschmutzung bedroht viele aquatische Arten."}]},
  "aqueduct": {label:"Aquädukt",gender:"das",plural:"Aquädukte", ex5:[{t:1,s:"Das antike römische Aquädukt ist noch heute ein Wahrzeichen."},{t:2,s:"Ingenieure bauten ein Aquädukt, um Wasser in die trockene Stadt zu leiten."},{t:3,s:"Wir besuchten die Ruinen eines alten Aquädukts auf unserem Schulausflug."},{t:4,s:"Aquädukte sind beeindruckende Zeugnisse römischer Baukunst."},{t:5,s:"Man kann noch viele gut erhaltene Aquädukte in Südeuropa finden."}]},
  "aqueous": {label:"wässrig",gender:"",plural:"—", ex5:[{t:1,s:"Der Wissenschaftler untersuchte die wässrige Lösung im Labor."},{t:2,s:"Viele Pflanzen gedeihen in einer wässrigen Umgebung."},{t:3,s:"Diese Farbe ist wässrig und leicht abwaschbar."},{t:4,s:"Eine wässrige Suspension ist eine Mischung aus Feststoff und Wasser."},{t:5,s:"Manche Medikamente müssen in einer wässrigen Lösung eingenommen werden."}]},
  "aquifer": {label:"Aquifer",gender:"der",plural:"Aquifere", ex5:[{t:1,s:"Die Stadt bezieht ihr Wasser aus einem unterirdischen Aquifer."},{t:2,s:"Übermäßiges Abpumpen kann einen Aquifer erschöpfen."},{t:3,s:"Der Aquifer liefert den größten Teil des Wassers der Region."},{t:4,s:"Ein Aquifer ist eine wasserführende Gesteinsschicht im Untergrund."},{t:5,s:"Der Schutz der Aquifere ist entscheidend für unsere Wasserversorgung."}]},
  "aquifers": {label:"Aquifere",gender:"die",plural:"—", ex5:[{t:1,s:"Die Stadt bezieht Wasser aus tiefen unterirdischen Aquiferen."},{t:2,s:"Verschmutzung kann diese Aquifere leicht erreichen."},{t:3,s:"Viele Bauern verlassen sich auf Aquifere zur Bewässerung."},{t:4,s:"Der Schutz unserer Aquifere ist für die Zukunft entscheidend."},{t:5,s:"Einige Aquifere sind durch Übernutzung gefährdet."}]},
  "aquinas": {label:"Aquinas",gender:"der",plural:"—", ex5:[{t:1,s:"Wir studieren die Philosophie von Aquinas im Unterricht."},{t:2,s:"Thomas von Aquinas schrieb viele bedeutende Werke."},{t:3,s:"Seine Ideen sind stark von Aquinas beeinflusst."},{t:4,s:"Aquinas ist ein wichtiger Denker des Mittelalters."},{t:5,s:"Wir lesen einen Text über Aquinas."}]},
