  "assemblyman": {label:"Abgeordneter",gender:"der",plural:"Abgeordnete", ex5:[{t:1,s:"Der lokale Abgeordnete besuchte unsere Schule, um über neue Richtlinien zu sprechen."},{t:2,s:"Viele Leute schrieben Briefe an den Abgeordneten wegen des Verkehrsproblems."},{t:3,s:"Der Abgeordnete versprach, die Einrichtungen des öffentlichen Parks zu verbessern."},{t:4,s:"Der Abgeordnete setzt sich für die Bürger ein."},{t:5,s:"Wir haben den Abgeordneten bei der Wahl unterstützt."}]},
  "assent": {label:"Zustimmung",gender:"die",plural:"Zustimmungen", ex5:[{t:1,s:"Das Komitee gab seine Zustimmung zu dem neuen Plan."},{t:2,s:"Sie nickte stumm zur Zustimmung."},{t:3,s:"Ohne seine Zustimmung können wir das Projekt nicht starten."},{t:4,s:"Wir warten noch auf die Zustimmung des Chefs."},{t:5,s:"Er gab seine Zustimmung zu dem Vorschlag."}]},
