  "barb": {label:"Widerhaken",gender:"der",plural:"Widerhaken", ex5:[{t:1,s:"Der Angelhaken hat einen kleinen Widerhaken."},{t:2,s:"Sie spürte einen scharfen Widerhaken an der Rose."},{t:3,s:"Vorsicht vor den Widerhaken am Stacheldrahtzaun."},{t:4,s:"Der Widerhaken verhindert, dass der Haken herausrutscht."},{t:5,s:"Beim Entfernen des Hakens muss man auf den Widerhaken achten."}]},
  "barbados": {label:"Barbados",gender:"das",plural:"—", ex5:[{t:1,s:"Barbados ist ein schöner Inselstaat in der Karibik."},{t:2,s:"Wir haben auf Barbados frischen Fisch gegessen."},{t:3,s:"Viele Menschen träumen von einem Urlaub auf Barbados."},{t:4,s:"Das Klima auf Barbados ist das ganze Jahr über warm."},{t:5,s:"Barbados ist für seine weißen Sandstrände bekannt."}]},
  "barbara": {label:"Barbara",gender:"",plural:"—", ex5:[{t:1,s:"Barbara hat uns zum Abendessen zu sich nach Hause eingeladen."},{t:2,s:"Ich habe gestern mit Barbara über das Projekt gesprochen."},{t:3,s:"Barbara ist eine sehr talentierte Künstlerin."},{t:4,s:"Barbara hat ein neues Buch veröffentlicht."},{t:5,s:"Barbaras Essen ist immer köstlich."}]},
  "barbarian": {label:"Barbar",gender:"der",plural:"Barbaren", ex5:[{t:1,s:"Die Geschichte handelt von einem barbarischen Krieger aus dem Norden."},{t:2,s:"In der Antike wurden sie oft von ihren Nachbarn als Barbaren bezeichnet."},{t:3,s:"Der Stamm der Barbaren zog über die weiten Ebenen."},{t:4,s:"Er kämpfte wie ein Barbar in der Schlacht."},{t:5,s:"Früher fürchtete man sich vor den einfallenden Barbaren."}]},
  "barbarians": {label:"Barbaren",gender:"die",plural:"Barbaren", ex5:[{t:1,s:"Die alte Stadt wurde von Barbaren angegriffen."},{t:2,s:"Benehmt euch nicht wie Barbaren am Esstisch!"},{t:3,s:"Geschichtsbücher beschreiben die Invasoren oft als Barbaren."},{t:4,s:"Die Barbaren zerstörten die Bibliothek der Stadt."},{t:5,s:"Die Verteidiger leisteten gegen die Barbaren Widerstand."}]},
  "barbaric": {label:"barbarisch",gender:"",plural:"—", ex5:[{t:1,s:"Es ist barbarisch, Tiere so grausam zu behandeln."},{t:2,s:"Der alte König war für seine barbarischen Strafen berüchtigt."},{t:3,s:"Solch ein barbarisches Verhalten hat in unserer Gesellschaft keinen Platz."},{t:4,s:"Die barbarischen Übergriffe schockierten die Welt."},{t:5,s:"Es ist ein barbarischer Akt der Zerstörung."}]},
  "barbarism": {label:"Barbarei",gender:"die",plural:"Barbareien", ex5:[{t:1,s:"Der Krieg führte zu Akten reiner Barbarei gegen Zivilisten."},{t:2,s:"Wir müssen gegen die Barbarei kämpfen, die noch immer existiert."},{t:3,s:"Die Geschichte zeigt, wie leicht die Zivilisation in Barbarei zurückfallen kann."},{t:4,s:"Die Barbarei des Krieges hinterließ tiefe Wunden."},{t:5,s:"Er verurteilte die Barbarei der damaligen Zeit."}]},
  "barbarity": {label:"Grausamkeit",gender:"die",plural:"Grausamkeiten", ex5:[{t:1,s:"Die Öffentlichkeit verurteilte die Grausamkeit des Angriffs."},{t:2,s:"Solche Grausamkeit hat in einer zivilisierten Gesellschaft keinen Platz."},{t:3,s:"Sie waren schockiert über die pure Grausamkeit der Behandlung."},{t:4,s:"Die Grausamkeit des Krieges ist unerträglich."},{t:5,s:"Man darf die Grausamkeit nicht ignorieren."}]},
