  "barnes": {label:"Scheune",gender:"die",plural:"Scheunen", ex5:[{t:1,s:"Wir sahen viele alte rote Scheunen, als wir durch die Landschaft fuhren."},{t:2,s:"Der Bauer hatte mehrere Scheunen, um seine Kühe und Pferde im Winter warm zu halten."},{t:3,s:"Einige der alten Scheunen auf dem verlassenen Bauernhof fielen auseinander."},{t:4,s:"Die Scheune diente als Lager für das Heu."},{t:5,s:"In den Scheunen befanden sich landwirtschaftliche Geräte."}]},
  "barnett": {label:"Barnett",gender:"",plural:"—", ex5:[{t:1,s:"Professor Barnett ist ein Experte für Meeresbiologie."},{t:2,s:"Ich habe Barnett eine E-Mail geschickt, um ihn um Rat zu bitten."},{t:3,s:"Barnett präsentierte seine Forschung auf der internationalen Konferenz."},{t:4,s:"Wir haben Barnett um seine Meinung gebeten."},{t:5,s:"Die Arbeit von Barnett ist sehr wichtig."}]},
