  "barnsley": {label:"Barnsley",gender:"",plural:"—", ex5:[{t:1,s:"Barnsley ist eine Stadt in South Yorkshire, England."},{t:2,s:"Er wurde in Barnsley geboren und ist dort aufgewachsen."},{t:3,s:"Wir planen, Barnsley während unserer UK-Reise zu besuchen."},{t:4,s:"Ich habe Verwandte in Barnsley."},{t:5,s:"Die Landschaft um Barnsley ist sehr schön."}]},
  "barnyard": {label:"Hof",gender:"der",plural:"Höfe", ex5:[{t:1,s:"Die Hühner liefen auf dem schlammigen Hof herum."},{t:2,s:"Der Geruch vom Hof erinnerte mich an meine Kindheit."},{t:3,s:"Früh am Morgen hörten wir Tiere auf dem Hof."},{t:4,s:"Der Hof war nach dem Regen sehr schlammig."},{t:5,s:"Die Kinder spielen gerne auf dem Hof."}]},
