  "behaviors": {label:"Verhaltensweisen",gender:"die",plural:"Verhaltensweisen", ex5:[{t:1,s:"Die Verhaltensweisen variieren von Person zu Person."},{t:2,s:"Diese Verhaltensweisen sind erlernt."},{t:3,s:"Wir haben die Verhaltensweisen der Tiere dokumentiert."},{t:4,s:"Es gibt viele verschiedene soziale Verhaltensweisen."},{t:5,s:"Wir analysierten ihre Verhaltensweisen genau."}]},
  "behaviour": {label:"Verhalten",gender:"das",plural:"Verhalten", ex5:[{t:1,s:"Gutes Verhalten ist sehr wichtig."},{t:2,s:"Sein Verhalten war heute sehr höflich."},{t:3,s:"Wir haben ihr vorbildliches Verhalten gelobt."},{t:4,s:"Ich verstehe ihr Verhalten nicht ganz."},{t:5,s:"Das Verhalten der Kinder ist heute einwandfrei."}]},
