  "belies": {label:"widerlegen",gender:"",plural:"—", ex5:[{t:1,s:"Sein junges Aussehen widerlegt sein wahres Alter."},{t:2,s:"Die ruhige See widerlegt die Gefahr unter der Oberfläche."},{t:3,s:"Ihr Lächeln widerlegt die Traurigkeit in ihrem Herzen."},{t:4,s:"Die Fakten widerlegen seine Behauptung."},{t:5,s:"Seine Worte widerlegen seine Taten."}]},
  "believable": {label:"glaubwürdig",gender:"",plural:"—", ex5:[{t:1,s:"Seine Ausrede klang für mich absolut glaubwürdig."},{t:2,s:"Die Geschichte im Buch ist durchaus glaubwürdig."},{t:3,s:"Wir brauchen eine glaubwürdigere Erklärung."},{t:4,s:"Das klingt sehr glaubwürdig."},{t:5,s:"Ein glaubwürdiges Zeugnis ist wichtig."}]},
  "believe": {label:"glauben",gender:"",plural:"—", ex5:[{t:1,s:"Die Leute glauben daran."},{t:2,s:"Man muss diese Geschichte einfach glauben."},{t:3,s:"Wir glauben die Nachrichten."},{t:4,s:"Ich glaube dir jedes Wort."},{t:5,s:"Wir glauben an eine bessere Zukunft."}]},
  "believed": {label:"geglaubt",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat daran fest geglaubt."},{t:2,s:"Der Mythos wird allgemein geglaubt."},{t:3,s:"Sie haben die Geschichte geglaubt."},{t:4,s:"Es wurde lange Zeit so geglaubt."},{t:5,s:"Er hat ihr alles geglaubt."}]},
