  "believes": {label:"glaubt",gender:"",plural:"—", ex5:[{t:1,s:"Sie glaubt fest daran."},{t:2,s:"Er glaubt die Nachrichten sofort."},{t:3,s:"Sie glaubt an uns alle."},{t:4,s:"Er glaubt, dass es morgen regnet."},{t:5,s:"Sie glaubt an die Gerechtigkeit."}]},
