  "belittle": {label:"herabsetzen",gender:"",plural:"—", ex5:[{t:1,s:"Du solltest ihre harte Arbeit nicht herabsetzen."},{t:2,s:"Er hat ihre kleinen Erfolge herabgesetzt."},{t:3,s:"Es ist falsch, andere Leute herabzusetzen."},{t:4,s:"Lass dich von niemandem herabsetzen."},{t:5,s:"Er versucht ständig, andere herabzusetzen."}]},
