  "bios": {label:"BIOS",gender:"das",plural:"BIOS", ex5:[{t:1,s:"Sie müssen die Einstellungen im BIOS ändern, um vom USB-Stick zu booten."},{t:2,s:"Der Zugriff auf das BIOS kann für Anfänger schwierig sein."},{t:3,s:"Ich habe das BIOS meines Computers aktualisiert, um den Fehler zu beheben."},{t:4,s:"Das BIOS steuert die grundlegenden Hardwarefunktionen beim Start."},{t:5,s:"Man kann das BIOS über ein spezielles Menü aufrufen."}]},
  "bioscience": {label:"Biowissenschaft",gender:"die",plural:"Biowissenschaften", ex5:[{t:1,s:"Sie studiert Biowissenschaft im Hauptfach."},{t:2,s:"Das Labor für Biowissenschaft ist sehr modern ausgestattet."},{t:3,s:"Er arbeitet für ein Unternehmen im Bereich der Biowissenschaft."},{t:4,s:"Die Biowissenschaft bietet viele spannende Karrieremöglichkeiten."},{t:5,s:"Forschung in der Biowissenschaft ist essenziell für die Medizin."}]},
  "biosphere": {label:"Biosphäre",gender:"die",plural:"Biosphären", ex5:[{t:1,s:"Die Biosphäre erhält alle Lebensformen auf der Erde."},{t:2,s:"Umweltverschmutzung schädigt unsere empfindliche Biosphäre."},{t:3,s:"Wir müssen die Biosphäre für zukünftige Generationen schützen."},{t:4,s:"Die Biosphäre ist ein komplexes System aus Lebewesen und Umwelt."},{t:5,s:"Der Schutz der Biosphäre ist eine globale Aufgabe."}]},
  "biosynthesis": {label:"Biosynthese",gender:"die",plural:"Biosynthesen", ex5:[{t:1,s:"Pflanzen nutzen die Biosynthese, um ihre eigenen Nährstoffe herzustellen."},{t:2,s:"Das Labor untersucht den Prozess der Proteinbiosynthese."},{t:3,s:"Biosynthese ist für das Wachstum lebender Organismen unerlässlich."},{t:4,s:"Durch Biosynthese werden komplexe Moleküle in Zellen aufgebaut."},{t:5,s:"Die Effizienz der Biosynthese kann durch Enzyme gesteuert werden."}]},
  "biotech": {label:"Biotech",gender:"die",plural:"—", ex5:[{t:1,s:"Sie möchte nächstes Jahr an der Universität Biotech studieren."},{t:2,s:"Die Biotech-Branche wächst derzeit sehr schnell."},{t:3,s:"Unser Unternehmen konzentriert sich auf innovative Biotech-Lösungen."},{t:4,s:"Biotech spielt eine wichtige Rolle in der modernen Forschung."},{t:5,s:"Viele Start-ups im Bereich Biotech entwickeln neue Medikamente."}]},
  "biotechnology": {label:"Biotechnologie",gender:"die",plural:"Biotechnologien", ex5:[{t:1,s:"Er studiert Biotechnologie an der Universität."},{t:2,s:"Die Biotechnologie hilft uns bei der Entwicklung neuer Medikamente."},{t:3,s:"Das Unternehmen ist führend im Bereich der Biotechnologie."},{t:4,s:"Moderne Biotechnologie ermöglicht neue Therapien gegen Krankheiten."},{t:5,s:"Die Anwendung von Biotechnologie ist in vielen Bereichen verbreitet."}]},
  "biotic": {label:"biotisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Ökosystem hängt sowohl von biotischen als auch von abiotischen Faktoren ab."},{t:2,s:"Sie untersuchten die biotischen Komponenten des Waldes."},{t:3,s:"Biotischer Stress kann das Wachstum dieser Pflanzen beeinträchtigen."},{t:4,s:"Biotische Einflüsse verändern die Zusammensetzung der Lebensgemeinschaft."},{t:5,s:"Die Forscher analysierten die biotische Vielfalt in diesem Gebiet."}]},
  "biotin": {label:"Biotin",gender:"das",plural:"—", ex5:[{t:1,s:"Biotin ist bekannt dafür, gesund für Haare und Nägel zu sein."},{t:2,s:"Mein Arzt hat mir empfohlen, Biotin als Nahrungsergänzung zu nehmen."},{t:3,s:"Lebensmittel wie Eier sind reich an Biotin."},{t:4,s:"Ein Mangel an Biotin kann zu spröden Haaren führen."},{t:5,s:"Biotin spielt eine wichtige Rolle im Stoffwechsel."}]},
