  "brawl": {label:"die Schlägerei",gender:"die",plural:"die Schlägereien", ex5:[{t:1,s:"Nach dem Spiel gab es eine Schlägerei."},{t:2,s:"Die Polizei beendete die Schlägerei auf der Straße."},{t:3,s:"Es ist traurig, eine Schlägerei unter Freunden zu sehen."},{t:4,s:"Die Schlägerei in der Kneipe war heftig."},{t:5,s:"Er wurde in eine Schlägerei verwickelt."}]},
  "brawling": {label:"schlägern",gender:"",plural:"—", ex5:[{t:1,s:"Die Polizei stoppte das Schlägern auf der Straße."},{t:2,s:"Er wurde wegen des Schlägerns aus der Bar geworfen."},{t:3,s:"Schlägern in der Öffentlichkeit ist verboten."},{t:4,s:"Es bringt nichts, sich ständig zu schlägern."},{t:5,s:"Das Schlägern hat zu einer Anzeige geführt."}]},
  "brawn": {label:"Kraft",gender:"die",plural:"Kräfte", ex5:[{t:1,s:"Er verlässt sich bei der Arbeit mehr auf seine Kraft als auf seinen Verstand."},{t:2,s:"Der Job erfordert viel Kraft, da die Kisten sehr schwer sind."},{t:3,s:"Im Sport werden oft sowohl Eleganz als auch Kraft geschätzt."},{t:4,s:"Er hat viel Kraft in den Armen."},{t:5,s:"Man braucht nicht nur Kraft, sondern auch Köpfchen."}]},
  "braxton": {label:"Braxton",gender:"der",plural:"—", ex5:[{t:1,s:"Braxton kommt diese Saison in unser Fußballteam."},{t:2,s:"Ich habe Braxton angerufen, um die Zeit für unser Treffen zu bestätigen."},{t:3,s:"Braxton spielt in seiner Freizeit sehr gerne Gitarre."},{t:4,s:"Braxton ist ein wichtiges Mitglied unserer Mannschaft."},{t:5,s:"Ich habe mich mit Braxton zum Training verabredet."}]},
  "bray": {label:"wiehern",gender:"",plural:"—", ex5:[{t:1,s:"Der Esel begann laut zu wiehern, als er den Bauern sah."},{t:2,s:"Ich konnte die Esel von der anderen Seite des Feldes wiehern hören."},{t:3,s:"Das plötzliche Wiehern des Esels erschreckte den schlafenden Hund."},{t:4,s:"Das Wiehern der Tiere war weithin zu vernehmen."},{t:5,s:"Er wiehert wie ein Esel, wenn er lacht."}]},
  "brazen": {label:"unverschämt",gender:"",plural:"—", ex5:[{t:1,s:"Es war eine unverschämte Lüge, die er ihr ins Gesicht sagte."},{t:2,s:"Er machte einen unverschämten Versuch, sich vorzudrängeln."},{t:3,s:"Ihr unverschämtes Selbstvertrauen schockierte die Jury."},{t:4,s:"Das ist eine sehr unverschämte Art, mit Leuten zu reden."},{t:5,s:"Er stellte eine unverschämte Forderung."}]},
  "brazenly": {label:"unverschämt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sich unverschämt in der Schlange vorgedrängelt."},{t:2,s:"Sie hat unverschämt jede Beteiligung geleugnet."},{t:3,s:"Sie haben unverschämt gegen die Vereinbarung verstoßen."},{t:4,s:"Er hat unverschämt nach mehr Geld gefragt."},{t:5,s:"Sie verhielt sich unverschämt gegenüber dem Lehrer."}]},
  "brazier": {label:"Kohlenbecken",gender:"das",plural:"Kohlenbecken", ex5:[{t:1,s:"Wir saßen um das Kohlenbecken, um uns draußen warm zu halten."},{t:2,s:"Das Kohlenbecken war mit glühender Kohle gefüllt."},{t:3,s:"Sie benutzten ein metallenes Kohlenbecken, um im Innenhof zu kochen."},{t:4,s:"Das Kohlenbecken strahlte eine angenehme Wärme aus."},{t:5,s:"In alten Zeiten nutzte man oft ein Kohlenbecken zum Heizen."}]},
  "brazil": {label:"Brasilien",gender:"das",plural:"—", ex5:[{t:1,s:"Ich möchte eines Tages Brasilien besuchen."},{t:2,s:"Brasilien ist das größte Land in Südamerika."},{t:3,s:"Mein Freund kommt aus Brasilien."},{t:4,s:"Brasilien ist bekannt für seinen Fußball."},{t:5,s:"Das Klima in Brasilien ist sehr warm."}]},
  "brazilian": {label:"brasilianisch",gender:"",plural:"—", ex5:[{t:1,s:"Mein bester Freund ist ein brasilianischer Student."},{t:2,s:"Ich liebe es, in dem neuen brasilianischen Restaurant in der Stadt zu essen."},{t:3,s:"Er ist ein berühmter brasilianischer Fußballspieler."},{t:4,s:"Die brasilianische Musik gefällt mir sehr."},{t:5,s:"Wir haben eine brasilianische Spezialität gekocht."}]},
  "brazilians": {label:"Brasilianer",gender:"der",plural:"Brasilianer", ex5:[{t:1,s:"Viele Brasilianer spielen leidenschaftlich gern Fußball am Strand."},{t:2,s:"Ich habe während meiner Reise nach Lissabon mehrere Brasilianer getroffen."},{t:3,s:"Brasilianer sind für ihre herzliche und freundliche Gastfreundschaft bekannt."},{t:4,s:"Die Brasilianer feiern gerne große Feste."},{t:5,s:"Viele Brasilianer leben in verschiedenen Teilen der Welt."}]},
  "breach": {label:"Bruch",gender:"der",plural:"Brüche", ex5:[{t:1,s:"Die Flut verursachte einen Bruch in der Mauer."},{t:2,s:"Lügen ist ein Bruch des Vertrauens."},{t:3,s:"Sie meldeten einen Bruch der Regeln."},{t:4,s:"Das ist ein klarer Bruch des Vertrages."},{t:5,s:"Der Bruch der Sicherheitsvorkehrungen hatte Konsequenzen."}]},
  "breached": {label:"verletzt",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma hat letzten Monat den Vertrag verletzt."},{t:2,s:"Sie haben die Sicherheitsregeln durch das Eindringen verletzt."},{t:3,s:"Der Damm wurde durch den starken Regen verletzt."},{t:4,s:"Er hat die Regeln des Spiels verletzt."},{t:5,s:"Das Gesetz wurde in diesem Punkt verletzt."}]},
  "breaches": {label:"verletzt",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma verletzt den Vertrag, indem sie nicht pünktlich zahlt."},{t:2,s:"Sicherheitsverstöße können zum Verlust privater Daten führen."},{t:3,s:"Er verletzt wiederholt die Regeln des Spiels."},{t:4,s:"Das Unternehmen verletzt häufig die internen Richtlinien."},{t:5,s:"Jeder, der die Regeln verletzt, muss mit Konsequenzen rechnen."}]},
