  "carcinogenic": {label:"krebserregend",gender:"",plural:"—", ex5:[{t:1,s:"Einige Chemikalien sind als krebserregend bekannt."},{t:2,s:"Sie versuchen, krebserregende Materialien aus dem Produkt zu entfernen."},{t:3,s:"Rauchen ist eine Hauptursache für krebserregende Krankheiten."},{t:4,s:"Dieses Reinigungsmittel ist leider krebserregend."},{t:5,s:"Wir vermeiden den Einsatz krebserregender Stoffe in der Produktion."}]},
  "carcinogens": {label:"Karzinogene",gender:"die",plural:"Karzinogene", ex5:[{t:1,s:"Zigarettenrauch enthält viele gefährliche Karzinogene."},{t:2,s:"Wissenschaftler untersuchen die Wirkung dieser Karzinogene."},{t:3,s:"Wir sollten den Kontakt mit bekannten Karzinogenen vermeiden."},{t:4,s:"Es gibt verschiedene Karzinogene in unserer Umwelt."},{t:5,s:"Die Belastung durch Karzinogene muss minimiert werden."}]},
