  "cellulite": {label:"Cellulite",gender:"die",plural:"—", ex5:[{t:1,s:"Viele Menschen versuchen, Cellulite durch Sport zu reduzieren."},{t:2,s:"Es ist normal, etwas Cellulite an den Beinen zu haben."},{t:3,s:"Sie sucht eine Creme zur Behandlung ihrer Cellulite."},{t:4,s:"Cellulite ist bei Frauen häufig."},{t:5,s:"Diese Massage soll gegen Cellulite helfen."}]},
  "celluloid": {label:"Celluloid",gender:"das",plural:"—", ex5:[{t:1,s:"Alte Filme wurden oft auf brennbarem Celluloid aufgenommen."},{t:2,s:"Die Vintage-Puppe war aus Celluloid gefertigt."},{t:3,s:"Celluloid war der erste synthetische Kunststoff für die Fotografie."},{t:4,s:"Celluloid war früher ein Material für Filme."},{t:5,s:"Dieses Spielzeug ist aus Celluloid."}]},
