  "chafing": {label:"Wundreiben",gender:"das",plural:"—", ex5:[{t:1,s:"Meine Schuhe verursachen beim langen Gehen ein Wundreiben an den Fersen."},{t:2,s:"Tragen Sie eine Creme auf, um ein Wundreiben der Haut zu verhindern."},{t:3,s:"Der enge Kragen führte zu einem schmerzhaften Wundreiben am Hals."},{t:4,s:"Durch das Wundreiben entstehen oft rote Stellen auf der Haut."},{t:5,s:"Sportler nutzen oft spezielle Salben gegen das Wundreiben."}]},
  "chagrin": {label:"Verdruss",gender:"der",plural:"—", ex5:[{t:1,s:"Zu seinem großen Verdruss scheiterte der Plan."},{t:2,s:"Sie verbarg ihren Verdruss hinter einem Lächeln."},{t:3,s:"Zu meinem großen Verdruss hatte ich die Schlüssel vergessen."},{t:4,s:"Er konnte seinen Verdruss über die Niederlage nicht verbergen."},{t:5,s:"Mit großem Verdruss nahm er die Nachricht zur Kenntnis."}]},
  "chai": {label:"Chai",gender:"der",plural:"Chais", ex5:[{t:1,s:"Ich mag es, Gewürze in meinen Chai zu geben."},{t:2,s:"Dieser Laden serviert den besten Chai der Stadt."},{t:3,s:"Möchtest du einen Chai mit extra viel Zimt?"},{t:4,s:"Ein heißer Chai wärmt an kalten Tagen wunderbar."},{t:5,s:"Er trinkt am liebsten Chai mit aufgeschäumter Milch."}]},
  "chain": {label:"Kette",gender:"die",plural:"Ketten", ex5:[{t:1,s:"Die Kette rasselte laut."},{t:2,s:"Diese Kette ist sehr stabil."},{t:3,s:"Wir zogen an der Kette."},{t:4,s:"Er trägt eine goldene Kette um den Hals."},{t:5,s:"Das Fahrrad ist mit einer Kette gesichert."}]},
  "chained": {label:"angekettet",gender:"",plural:"—", ex5:[{t:1,s:"Der Hund war an einen Pfosten im Garten angekettet."},{t:2,s:"Er hat sein Fahrrad sicher an den Zaun angekettet."},{t:3,s:"Das schwere Tor war nachts fest angekettet."},{t:4,s:"Das Boot liegt am Ufer angekettet."},{t:5,s:"Der Gefangene wurde an die Wand angekettet."}]},
  "chaining": {label:"anketten",gender:"",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, sein Fahrrad an den Pfosten zu anketten."},{t:2,s:"Das Anketten der Ereignisse erklärt die ganze Geschichte."},{t:3,s:"Sie verbrachte den Tag damit, Perlen aneinander zu anketten."},{t:4,s:"Das Anketten des Tores ist sehr wichtig für die Sicherheit."},{t:5,s:"Wir müssen die Kisten anketten, damit sie nicht verrutschen."}]},
  "chains": {label:"Kette",gender:"die",plural:"Ketten", ex5:[{t:1,s:"Das Tor war mit schweren Ketten verschlossen."},{t:2,s:"Sie trug eine feine Kette um ihren Hals."},{t:3,s:"Das Fahrrad wurde mit einer Kette gesichert."},{t:4,s:"Die Kette ist aus purem Gold."},{t:5,s:"Er löste die Kette vom Fahrrad."}]},
  "chainsaw": {label:"Kettensäge",gender:"die",plural:"Kettensägen", ex5:[{t:1,s:"Der Gärtner benutzte eine Kettensäge für den Baum."},{t:2,s:"Sei vorsichtig bei der Arbeit mit der Kettensäge."},{t:3,s:"Er kaufte eine Kettensäge für das Brennholz."},{t:4,s:"Die Kettensäge ist sehr laut."},{t:5,s:"Er wartet seine Kettensäge regelmäßig."}]},
  "chair": {label:"Stuhl",gender:"der",plural:"Stühle", ex5:[{t:1,s:"Der Stuhl hat geknarrt."},{t:2,s:"Dieser Stuhl ist sehr bequem."},{t:3,s:"Wir haben einen zusätzlichen Stuhl geholt."},{t:4,s:"Der Stuhl steht am Fenster."},{t:5,s:"Setz dich bitte auf den Stuhl."}]},
  "chaired": {label:"leitete",gender:"",plural:"—", ex5:[{t:1,s:"Sie leitete heute Morgen das Komitee."},{t:2,s:"Er leitete den Vorstand über zehn Jahre lang."},{t:3,s:"Der Professor leitete die Sitzung zum Klimawandel."},{t:4,s:"Sie leitete die Diskussion sehr souverän."},{t:5,s:"Er leitete das Treffen effizient."}]},
  "chairing": {label:"leitend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade leitend bei der Umweltkonferenz tätig."},{t:2,s:"Ich mag es, die wöchentlichen Meetings zu leiten."},{t:3,s:"Er leitet das Komitee seit über fünf Jahren."},{t:4,s:"Sie leitet derzeit die wichtige Sitzung."},{t:5,s:"Das Leiten der Versammlung erfordert viel Geduld."}]},
  "chairman": {label:"Vorsitzender",gender:"der",plural:"Vorsitzenden", ex5:[{t:1,s:"Der Vorsitzende hat gesprochen."},{t:2,s:"Der Vorsitzende bleibt bei seiner Meinung."},{t:3,s:"Wir haben einen neuen Vorsitzenden gewählt."},{t:4,s:"Der Vorsitzende leitet die Sitzung."},{t:5,s:"Das ist das Büro des Vorsitzenden."}]},
  "chairmanship": {label:"Vorsitz",gender:"der",plural:"—", ex5:[{t:1,s:"Er hatte den Vorsitz über zehn Jahre inne."},{t:2,s:"Sie kandidiert für den Vorsitz des Komitees."},{t:3,s:"Der Vorstand bot ihm den Vorsitz an."},{t:4,s:"Der Vorsitz erfordert viel Erfahrung."},{t:5,s:"Er übernahm den Vorsitz der Gruppe."}]},
