  "chairperson": {label:"Vorsitzende",gender:"die",plural:"Vorsitzenden", ex5:[{t:1,s:"Die Vorsitzende eröffnete die Sitzung um neun."},{t:2,s:"Sie wurde zur Vorsitzenden des Clubs gewählt."},{t:3,s:"Bitte sende den Bericht an die Vorsitzende."},{t:4,s:"Die Vorsitzende hat das Wort ergriffen."},{t:5,s:"Die Vorsitzende leitet die Diskussion."}]},
  "chairs": {label:"Stühle",gender:"die",plural:"Stühle", ex5:[{t:1,s:"Es stehen drei Stühle um den Tisch."},{t:2,s:"Die neuen Bürostühle sind sehr ergonomisch."},{t:3,s:"Bitte rück die Stühle näher an den Bildschirm."},{t:4,s:"Wir brauchen mehr Stühle für die Gäste."},{t:5,s:"Die Stühle sind aus Holz gefertigt."}]},
  "chairwoman": {label:"Vorsitzende",gender:"die",plural:"Vorsitzenden", ex5:[{t:1,s:"Die Vorsitzende eröffnete die Sitzung pünktlich."},{t:2,s:"Sie wurde zur neuen Vorsitzenden des Vorstands gewählt."},{t:3,s:"Die Vorsitzende hörte sich die Meinung aller an."},{t:4,s:"Die Vorsitzende leitet die heutige Diskussion."},{t:5,s:"Alle respektieren die Entscheidung der Vorsitzenden."}]},
  "chaise": {label:"Chaiselongue",gender:"die",plural:"Chaiselongues", ex5:[{t:1,s:"Sie entspannte sich mit einem guten Buch auf der Chaiselongue."},{t:2,s:"Die antike Chaiselongue sieht im Wintergarten wunderschön aus."},{t:3,s:"Er kaufte eine Chaiselongue aus Samt für seine Leseecke."},{t:4,s:"Auf der Chaiselongue kann man herrlich ruhen."},{t:5,s:"Die neue Chaiselongue ist sehr bequem."}]},
  "chakra": {label:"Chakra",gender:"das",plural:"Chakren", ex5:[{t:1,s:"Sie praktiziert Yoga, um ihr Chakra in Einklang zu bringen."},{t:2,s:"Meditation hilft dabei, jedes Chakra zu öffnen."},{t:3,s:"Er glaubt an die Energie eines jeden Chakras."},{t:4,s:"Die Arbeit mit den Chakren entspannt den Körper."},{t:5,s:"Jedes Chakra hat eine eigene Bedeutung."}]},
  "chalet": {label:"Chalet",gender:"das",plural:"Chalets", ex5:[{t:1,s:"Wir haben für unseren Skiurlaub ein hölzernes Chalet gemietet."},{t:2,s:"Das Chalet bietet einen atemberaubenden Blick auf die verschneiten Berge."},{t:3,s:"Im Inneren des Berg-Chalets gibt es einen gemütlichen Kamin."},{t:4,s:"Wir verbringen das Wochenende in einem schönen Chalet."},{t:5,s:"Das Chalet ist sehr rustikal eingerichtet."}]},
  "chalets": {label:"Chalets",gender:"die",plural:"Chalets", ex5:[{t:1,s:"Wir wohnten in einem der hölzernen Chalets in den Bergen."},{t:2,s:"Das Resort bietet gemütliche Chalets für den Winterurlaub an."},{t:3,s:"Viele Chalets haben einen schönen Blick auf die schneebedeckten Gipfel."},{t:4,s:"Die Chalets sind im Sommer sehr beliebt."},{t:5,s:"Alle Chalets sind modern ausgestattet."}]},
  "chalice": {label:"Kelch",gender:"der",plural:"Kelche", ex5:[{t:1,s:"Der Priester hob während der Zeremonie einen goldenen Kelch empor."},{t:2,s:"Wein wurde vorsichtig in den juwelenbesetzten Kelch gegossen."},{t:3,s:"Der antike Kelch wurde in einem verschlossenen Schaukasten aufbewahrt."},{t:4,s:"Der Kelch glänzt im Licht der Kerzen."},{t:5,s:"Er hielt den Kelch mit beiden Händen fest."}]},
  "chalk": {label:"Kreide",gender:"die",plural:"Kreiden", ex5:[{t:1,s:"Der Lehrer schrieb die Matheaufgabe mit Kreide an die Tafel."},{t:2,s:"Kannst du mir ein Stück weiße Kreide geben?"},{t:3,s:"Wir haben mit bunter Kreide ein Hüpfspiel auf den Boden gemalt."},{t:4,s:"Meine Finger sind voller Kreide."},{t:5,s:"Benutze bitte die Kreide für die Zeichnung."}]},
  "chalkboard": {label:"Tafel",gender:"die",plural:"Tafeln", ex5:[{t:1,s:"Der Lehrer schrieb an die Tafel."},{t:2,s:"Kreidestaub bedeckte die Tafel."},{t:3,s:"Er wischte die alten Notizen von der Tafel."},{t:4,s:"Bitte schau nach vorne an die Tafel."},{t:5,s:"Die Tafel wurde heute gründlich gereinigt."}]},
  "chalked": {label:"mit Kreide schreiben",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer hat die Matheaufgabe mit Kreide an die Tafel geschrieben."},{t:2,s:"Er hat seinen Namen mit Kreide auf den Gehweg geschrieben."},{t:3,s:"Sie hat den Punktestand mit Kreide an die Wand geschrieben."},{t:4,s:"Wir haben das Spielfeld mit Kreide markiert."},{t:5,s:"Er hat die Zahlen mit Kreide auf den Boden geschrieben."}]},
  "chalky": {label:"kreidig",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser hatte nach der Rohrreparatur einen kreidigen Geschmack."},{t:2,s:"Ihre Hände waren kreidig vom Kletterpuder."},{t:3,s:"Der Boden in dieser Gegend ist ziemlich kreidig."},{t:4,s:"Die Oberfläche fühlt sich ganz kreidig an."},{t:5,s:"Er hat einen kreidigen Film auf den Fingern."}]},
