  "chalmers": {label:"Chalmers",gender:"",plural:"—", ex5:[{t:1,s:"Rektor Chalmers gab heute Morgen eine Durchsage."},{t:2,s:"Ich sprach mit Herrn Chalmers über meine Projektideen."},{t:3,s:"Das Chalmers-Gebäude befindet sich im Stadtzentrum."},{t:4,s:"Mein Lehrer heißt Chalmers."},{t:5,s:"Ich habe die Meinung von Chalmers eingeholt."}]},
  "chamber": {label:"Kammer",gender:"die",plural:"Kammern", ex5:[{t:1,s:"Die Kammer hallte wider."},{t:2,s:"Die Kammer ist fest verschlossen."},{t:3,s:"Wir betraten die Kammer."},{t:4,s:"Das Licht drang in die Kammer."},{t:5,s:"Es gibt eine geheime Kammer."}]},
  "chambered": {label:"gekammert",gender:"",plural:"—", ex5:[{t:1,s:"Der Nautilus hat eine wunderschön gekammerte Schale."},{t:2,s:"Das Grab war in mehrere gekammerte Räume unterteilt."},{t:3,s:"Wir betraten den gekammerten Bereich des Schlosses."},{t:4,s:"Das Objekt hat eine gekammerte Struktur."},{t:5,s:"Dieser Teil ist speziell gekammert."}]},
  "chamberlain": {label:"Chamberlain",gender:"",plural:"—", ex5:[{t:1,s:"Neville Chamberlain war ein bekannter britischer Politiker."},{t:2,s:"Das Buch diskutiert die Entscheidungen, die Chamberlain traf."},{t:3,s:"Chamberlain diente in der Vergangenheit als Premierminister."},{t:4,s:"Ich habe über Chamberlain gelesen."},{t:5,s:"Chamberlains Politik war einflussreich."}]},
  "chambers": {label:"Kammer",gender:"die",plural:"Kammern", ex5:[{t:1,s:"Das Schloss hat viele geheime Kammern."},{t:2,s:"Die Kammern des Parlaments waren gut besetzt."},{t:3,s:"Das Herz besteht aus vier Kammern."},{t:4,s:"Er bewahrt seine Schätze in einer kleinen Kammer auf."},{t:5,s:"Die Kammer ist sehr dunkel und kühl."}]},
  "chameleon": {label:"Chamäleon",gender:"das",plural:"Chamäleons", ex5:[{t:1,s:"Ein Chamäleon kann seine Hautfarbe an die Umgebung anpassen."},{t:2,s:"Sie ist wie ein Chamäleon und passt sich jeder Gruppe an."},{t:3,s:"Hast du das Chamäleon im Baum gesehen?"},{t:4,s:"Das Chamäleon bewegt sich sehr langsam."},{t:5,s:"Ein Chamäleon hat eine sehr lange Zunge."}]},
