  "champ": {label:"Champion",gender:"der",plural:"Champions", ex5:[{t:1,s:"Er wurde nach dem Sieg der neue Champion."},{t:2,s:"Du schaffst das, Champion!"},{t:3,s:"Unser Team hat einen großartigen Champion als Anführer."},{t:4,s:"Jeder will ein echter Champion sein."},{t:5,s:"Der Champion hielt eine Rede nach dem Spiel."}]},
  "champagne": {label:"Champagner",gender:"der",plural:"—", ex5:[{t:1,s:"Sie öffneten eine Flasche Champagner zur Feier."},{t:2,s:"Möchten Sie etwas Champagner zum Essen?"},{t:3,s:"Der Champagner schmeckte süß und erfrischend."},{t:4,s:"Wir stießen mit Champagner auf den Erfolg an."},{t:5,s:"Er kaufte den teuersten Champagner im Laden."}]},
  "champaign": {label:"Champaign",gender:"",plural:"—", ex5:[{t:1,s:"Wir fuhren durch Champaign auf dem Weg nach Chicago."},{t:2,s:"Champaign ist die Heimat der University of Illinois."},{t:3,s:"Er machte seinen Abschluss an einer Universität in Champaign."},{t:4,s:"Champaign ist eine angenehme Stadt."},{t:5,s:"Ich habe mich in Champaign mit einem Freund getroffen."}]},
  "champion": {label:"Champion",gender:"der",plural:"Champions", ex5:[{t:1,s:"Der Champion hat gewonnen."},{t:2,s:"Der Champion ist bescheiden."},{t:3,s:"Wir haben den Champion lautstark angefeuert."},{t:4,s:"Jeder möchte der Champion sein."},{t:5,s:"Der Champion trainiert jeden Tag hart."}]},
  "championed": {label:"verfechten",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat jahrelang die Tierrechte verfochten."},{t:2,s:"Der Senator hat die neue Bildungspolitik verfochten."},{t:3,s:"Er hat sein Team bis zum Sieg verfochten."},{t:4,s:"Sie hat ihre Ideale mutig verfochten."},{t:5,s:"Er hat die Interessen der Arbeiter verfochten."}]},
  "championing": {label:"verfechten",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist dabei, die Rechte der Bauern zu verfechten."},{t:2,s:"Er verfechtet derzeit eine neue Umweltpolitik."},{t:3,s:"Sie verfechten gemeinsam eine bessere Bildung für alle Kinder."},{t:4,s:"Er verfechtet aktiv die Gleichberechtigung."},{t:5,s:"Sie verfechten mutig ihre Meinung in der Debatte."}]},
  "champions": {label:"Champions",gender:"die",plural:"Champions", ex5:[{t:1,s:"Das Team wurde dieses Jahr der Champion der Liga."},{t:2,s:"Wahre Champions geben niemals auf, selbst wenn es schwer wird."},{t:3,s:"Sie feierten ihren Sieg wie wahre Champions."},{t:4,s:"Viele Champions nehmen an diesem Wettbewerb teil."},{t:5,s:"Champions zeichnen sich durch Disziplin aus."}]},
  "championship": {label:"Meisterschaft",gender:"die",plural:"Meisterschaften", ex5:[{t:1,s:"Die Meisterschaft ging zu Ende."},{t:2,s:"Der Kampf um die Meisterschaft ist hart."},{t:3,s:"Wir haben die Meisterschaft gewonnen."},{t:4,s:"Die Meisterschaft findet jedes Jahr statt."},{t:5,s:"Er trainiert für die Meisterschaft."}]},
  "championships": {label:"Meisterschaften",gender:"die",plural:"Meisterschaften", ex5:[{t:1,s:"Unser Team hat drei Meisterschaften in Folge gewonnen."},{t:2,s:"Viele Athleten bereiten sich auf diese Meisterschaften vor."},{t:3,s:"Die Schule organisiert verschiedene Meisterschaften."},{t:4,s:"Bei diesen Meisterschaften gibt es viele Talente."},{t:5,s:"Die Meisterschaften sind für alle sehr wichtig."}]},
  "champs": {label:"Champions",gender:"die",plural:"Champions", ex5:[{t:1,s:"Unser Schulteam wurde regionaler Champion."},{t:2,s:"Ihr seid echte Champions, weil ihr das Projekt beendet habt."},{t:3,s:"Die Champions besuchen nächste Woche unsere Stadt."},{t:4,s:"Sie sind wahre Champions im Teamgeist."},{t:5,s:"Jeder möchte gern zu den Champions gehören."}]},
  "chance": {label:"Chance",gender:"die",plural:"Chancen", ex5:[{t:1,s:"Eine Chance hat sich ergeben."},{t:2,s:"Die Chance ist sehr gering."},{t:3,s:"Wir haben die Chance genutzt."},{t:4,s:"Das ist eine gute Chance für uns."},{t:5,s:"Man muss seine Chance ergreifen."}]},
  "chancel": {label:"Altarraum",gender:"der",plural:"Altarräume", ex5:[{t:1,s:"Der Chor stand während des Gottesdienstes im Altarraum."},{t:2,s:"Der Altarraum war mit schönen Blumen geschmückt."},{t:3,s:"Der Priester schritt langsam zum Altarraum."},{t:4,s:"Der Altarraum ist ein besonderer Teil der Kirche."},{t:5,s:"Man kann den Altarraum vom Kirchenschiff aus sehen."}]},
  "chancellor": {label:"Kanzler",gender:"der",plural:"Kanzler", ex5:[{t:1,s:"Der Kanzler hielt eine Rede zur neuen Wirtschaftspolitik."},{t:2,s:"Der Universitätskanzler besucht morgen unseren Campus."},{t:3,s:"Viele Menschen kamen, um den Kanzler zu hören."},{t:4,s:"Der Kanzler hat heute eine wichtige Entscheidung getroffen."},{t:5,s:"Das Büro vom Kanzler ist sehr beschäftigt."}]},
  "chancery": {label:"Kanzlei",gender:"die",plural:"Kanzleien", ex5:[{t:1,s:"Der Fall wurde vor der Kanzlei verhandelt."},{t:2,s:"Er arbeitet als Angestellter in der örtlichen Kanzlei."},{t:3,s:"Die Kanzlei befasst sich mit komplexen Rechtsstreitigkeiten."},{t:4,s:"Alle Unterlagen liegen in der Kanzlei bereit."},{t:5,s:"Die Arbeit in der Kanzlei ist sehr anspruchsvoll."}]},
