  "chore": {label:"Hausarbeit",gender:"die",plural:"Hausarbeiten", ex5:[{t:1,s:"Das Geschirr spülen ist eine tägliche Hausarbeit."},{t:2,s:"Die Kinder teilen sich die Hausarbeiten im Haushalt."},{t:3,s:"Er erledigte seine Hausarbeiten früh."},{t:4,s:"Die Hausarbeit ist wichtig."},{t:5,s:"Ich habe eine Hausarbeit zu erledigen."}]},
  "choreographed": {label:"choreographiert",gender:"",plural:"—", ex5:[{t:1,s:"Die Tänzer choreographierten eine schöne Performance für das Festival."},{t:2,s:"Jede Bewegung in der Show wurde sorgfältig choreographiert."},{t:3,s:"Sie choreographierte die gesamte Routine in nur zwei Tagen."},{t:4,s:"Der Tanz wurde professionell choreographiert."},{t:5,s:"Das Stück wurde neu choreographiert."}]},
