  "choreography": {label:"Choreographie",gender:"die",plural:"Choreographien", ex5:[{t:1,s:"Der Tänzer lobte die kühne Choreographie."},{t:2,s:"Sie schuf die Choreographie für die Show."},{t:3,s:"Die Choreographie war komplex, aber anmutig."},{t:4,s:"Die Choreographie ist sehr originell."},{t:5,s:"Ich mag diese Choreographie."}]},
  "chores": {label:"Hausarbeiten",gender:"die",plural:"Hausarbeiten", ex5:[{t:1,s:"Ich habe viele Hausarbeiten dieses Wochenende zu erledigen."},{t:2,s:"Tägliche Hausarbeiten helfen Kindern, Verantwortung zu lernen."},{t:3,s:"Wir teilen uns die Hausarbeiten, um das Haus sauber zu halten."},{t:4,s:"Die Kinder haben ihre Hausarbeiten beendet."},{t:5,s:"Diese Hausarbeiten sind wichtig."}]},
  "chorizo": {label:"Chorizo",gender:"der",plural:"—", ex5:[{t:1,s:"Ich habe scharfe Chorizo zur Nudelsoße gegeben."},{t:2,s:"Möchtest du gegrillte Chorizo probieren?"},{t:3,s:"Die Pizza ist mit frischer Chorizo und Käse belegt."},{t:4,s:"Chorizo ist eine würzige Paprikawurst."},{t:5,s:"Diese Chorizo ist sehr scharf."}]},
  "chortle": {label:"kichern",gender:"",plural:"—", ex5:[{t:1,s:"Der Großvater kicherte über die lustige Geschichte seines Enkels."},{t:2,s:"Sie kicherte glücklich, als sie das Überraschungsgeschenk sah."},{t:3,s:"Sie kicherten alle, als der Hund seinem eigenen Schwanz nachjagte."},{t:4,s:"Die Kinder kicherten über den Witz des Lehrers."},{t:5,s:"Die Situation war so komisch, dass ich kichern musste."}]},
