  "chose": {label:"wählte",gender:"",plural:"—", ex5:[{t:1,s:"Sie wählte gut."},{t:2,s:"Das Team wählte einen Anführer."},{t:3,s:"Wir wählten das blaue."},{t:4,s:"Er wählte das Buch aus."},{t:5,s:"Welche Farbe wählten Sie?"}]},
  "chosen": {label:"auserwählt",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde auserwählt."},{t:2,s:"Der Weg wurde auserwählt."},{t:3,s:"Sie wählten einen Gewinner aus."},{t:4,s:"Für dieses Projekt wurde sie auserwählt."},{t:5,s:"Das ist der Weg, den wir auserwählt haben."}]},
  "chou": {label:"Chou",gender:"",plural:"—", ex5:[{t:1,s:"Herr Chou wird unser Gastredner morgen sein."},{t:2,s:"Ich traf Dr. Chou auf der medizinischen Konferenz."},{t:3,s:"Der Bericht wurde von Frau Chou geschrieben."},{t:4,s:"Bitte geben Sie uns die Meinung von Chou."},{t:5,s:"Ich habe im Laden von Chou eingekauft."}]},
