  "christ": {label:"Christus",gender:"der",plural:"—", ex5:[{t:1,s:"Viele Menschen feiern die Geburt von Christus."},{t:2,s:"Die Geschichte von Christus wird in der Bibel erzählt."},{t:3,s:"Sie gingen in die Kirche, um Christus zu ehren."},{t:4,s:"Für Christen ist Christus der Messias."},{t:5,s:"Die Lehren von Christus sind sehr einflussreich."}]},
  "christchurch": {label:"Christchurch",gender:"",plural:"—", ex5:[{t:1,s:"Christchurch ist die größte Stadt auf der Südinsel."},{t:2,s:"Sie hat an der Universität in Christchurch studiert."},{t:3,s:"Wir haben den botanischen Garten in Christchurch besucht."},{t:4,s:"Christchurch ist ein beliebtes Reiseziel."},{t:5,s:"Das Wetter in Christchurch ist heute sehr angenehm."}]},
  "christen": {label:"taufen",gender:"",plural:"—", ex5:[{t:1,s:"Sie beschlossen, das Baby in der alten Kirche zu taufen."},{t:2,s:"Wir werden das neue Schiff morgen früh taufen."},{t:3,s:"Sie wurde in der örtlichen Gemeinde Sarah getauft."},{t:4,s:"Die Eltern ließen ihr Kind in der Kathedrale taufen."},{t:5,s:"Es ist Tradition, ein neues Schiff feierlich zu taufen."}]},
  "christendom": {label:"Christenheit",gender:"die",plural:"—", ex5:[{t:1,s:"Die Nachricht verbreitete sich schnell in der ganzen Christenheit."},{t:2,s:"Im Mittelalter war die Christenheit sehr einflussreich."},{t:3,s:"Er reiste durch die Christenheit, um andere Kulturen kennenzulernen."},{t:4,s:"Die Christenheit umfasst viele Länder und Völker."},{t:5,s:"Die Geschichte der Christenheit ist lang und komplex."}]},
