  "christening": {label:"Taufe",gender:"die",plural:"Taufen", ex5:[{t:1,s:"Wir besuchten gestern die Taufe unseres Neffen."},{t:2,s:"Sie trug ein wunderschönes weißes Kleid für ihre Taufe."},{t:3,s:"Die Familie versammelte sich in der Kirche zur Taufe."},{t:4,s:"Die Taufe ist ein wichtiges Sakrament im Christentum."},{t:5,s:"Wir planen eine große Feier nach der Taufe."}]},
  "christensen": {label:"Christensen",gender:"",plural:"—", ex5:[{t:1,s:"Herr Christensen hat uns erklärt, wie man die Gleichung löst."},{t:2,s:"Ich habe Dr. Christensen eine E-Mail bezüglich meiner Abschlussarbeit gesendet."},{t:3,s:"Die Familie Christensen hat uns heute zum Abendessen eingeladen."},{t:4,s:"Herr Christensen hält eine sehr interessante Vorlesung."},{t:5,s:"Ich habe mich gestern mit Christensen getroffen."}]},
  "christi": {label:"Christi",gender:"",plural:"—", ex5:[{t:1,s:"Wir planen für diesen Sommer eine Reise nach Corpus Christi."},{t:2,s:"Der Strand in Corpus Christi ist wunderschön."},{t:3,s:"Mein Cousin wohnt in der Nähe von Corpus Christi."},{t:4,s:"Corpus Christi liegt direkt an der Küste."},{t:5,s:"Wir haben unseren Urlaub in Corpus Christi verbracht."}]},
  "christian": {label:"Christ",gender:"der",plural:"Christen", ex5:[{t:1,s:"Er ist ein gläubiger Christ."},{t:2,s:"Sie besuchen eine christliche Schule."},{t:3,s:"Die Kirche hat viele christliche Mitglieder."},{t:4,s:"Als Christ glaubt er an die Lehren Jesu."},{t:5,s:"Die Christen feiern Weihnachten und Ostern."}]},
  "christianity": {label:"Christentum",gender:"das",plural:"—", ex5:[{t:1,s:"Er studierte die Geschichte des Christentums am College."},{t:2,s:"Das Christentum verbreitete sich mit der Zeit auf der ganzen Welt."},{t:3,s:"Viele Menschen praktizieren das Christentum in diesem Land."},{t:4,s:"Das Christentum hat eine lange und reiche Geschichte."},{t:5,s:"Die Grundsätze des Christentums sind Liebe und Vergebung."}]},
  "christians": {label:"Christ",gender:"der",plural:"Christen", ex5:[{t:1,s:"Viele Christen gehen sonntags in die Kirche."},{t:2,s:"Die Gemeinschaft steht allen Christen offen."},{t:3,s:"Christen feiern jedes Jahr Weihnachten."},{t:4,s:"Er ist ein treuer Christ."},{t:5,s:"Wie viele Christen leben in diesem Land?"}]},
  "christie": {label:"Christie",gender:"",plural:"—", ex5:[{t:1,s:"Christie liest gerade einen Krimi im Park."},{t:2,s:"Ich habe Christie zu meiner Geburtstagsparty eingeladen."},{t:3,s:"Christie spielt sehr schön Klavier."},{t:4,s:"Christie ist eine gute Freundin von mir."},{t:5,s:"Morgen fährt Christie nach Japan."}]},
