  "christophe": {label:"Christophe",gender:"",plural:"—", ex5:[{t:1,s:"Christophe ist mein Freund aus Frankreich."},{t:2,s:"Ich habe Christophe eine E-Mail über unser Projekt geschickt."},{t:3,s:"Christophe spricht fließend drei Sprachen."},{t:4,s:"Christophe wohnt derzeit in Paris."},{t:5,s:"Ich bin mit Christophe ins Kino gegangen."}]},
  "christopher": {label:"Christopher",gender:"",plural:"—", ex5:[{t:1,s:"Christopher ist eine sehr freundliche und hilfsbereite Person."},{t:2,s:"Ich habe um zwei Uhr ein Treffen mit Christopher."},{t:3,s:"Christopher liest in seiner Freizeit gerne Kriminalromane."},{t:4,s:"Christopher hat mir sehr geholfen."},{t:5,s:"Christopher spielt sehr gut Tennis."}]},
