  "citadel": {label:"Zitadelle",gender:"die",plural:"Zitadellen", ex5:[{t:1,s:"Die antike Zitadelle ragte hoch über der Stadt auf."},{t:2,s:"Soldaten verteidigten die Zitadelle gegen die Belagerung."},{t:3,s:"Die Universität wurde zu einer Zitadelle des freien Denkens."},{t:4,s:"Man kann die alte Zitadelle von weitem sehen."},{t:5,s:"Die Zitadelle dient heute als Museum."}]},
  "citation": {label:"Zitat",gender:"das",plural:"Zitate", ex5:[{t:1,s:"Du musst für jede Quelle ein Zitat angeben."},{t:2,s:"Der Lehrer verlangte ein korrektes Zitat in dem Aufsatz."},{t:3,s:"Überprüfe das Format für das Zitat, bevor du die Arbeit abgibst."},{t:4,s:"Ein gutes Zitat untermauert deine Argumentation."},{t:5,s:"Das Zitat stammt aus einem berühmten Roman."}]},
  "citations": {label:"Zitation",gender:"die",plural:"Zitationen", ex5:[{t:1,s:"Bitte fügen Sie alle notwendigen Zitationen in Ihre Arbeit ein."},{t:2,s:"Der Professor prüfte die Zitationen auf ihre Richtigkeit."},{t:3,s:"Sie fand viele hilfreiche Zitationen in der Datenbank."},{t:4,s:"Korrekte Zitationen sind für eine wissenschaftliche Arbeit unerlässlich."},{t:5,s:"Er hat die Zitationen am Ende des Textes aufgelistet."}]},
  "cite": {label:"zitieren",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat ein berühmtes Buch in ihrem Aufsatz zitiert."},{t:2,s:"Er konnte mehrere Gründe für die Änderung zitieren."},{t:3,s:"Bitte zitieren Sie Ihre Quellen deutlich."},{t:4,s:"Man sollte immer korrekt zitieren."},{t:5,s:"Er hat den Dichter in seiner Rede zitiert."}]},
  "cited": {label:"zitierte",gender:"",plural:"—", ex5:[{t:1,s:"Der Professor zitierte mehrere Studien, um sein Argument zu stützen."},{t:2,s:"Sie zitierte ein bekanntes Gedicht in ihrem Aufsatz."},{t:3,s:"Er zitierte die Sicherheitsregeln, als er das Experiment erklärte."},{t:4,s:"Die Autorin zitierte verschiedene Quellen für ihre Analyse."},{t:5,s:"Er zitierte ein altes Sprichwort, um den Punkt zu verdeutlichen."}]},
  "cites": {label:"zitiert",gender:"",plural:"—", ex5:[{t:1,s:"Sie zitiert in ihrem Bericht mehrere Quellen."},{t:2,s:"Der Autor zitiert ein berühmtes Gedicht in dem Buch."},{t:3,s:"Er zitiert die hohen Kosten als Hauptgrund."},{t:4,s:"Das Dokument zitiert aktuelle wissenschaftliche Erkenntnisse."},{t:5,s:"Sie zitiert oft klassische Literatur in ihren Texten."}]},
  "citi": {label:"Citi",gender:"",plural:"—", ex5:[{t:1,s:"Ich muss zur Citi Bank gehen, um ein Konto zu eröffnen."},{t:2,s:"Meine Citi-Kreditkarte bietet tolle Reiseprämien."},{t:3,s:"Man findet fast an jeder Straßenecke einen Citi-Geldautomaten."},{t:4,s:"Citi ist ein großes internationales Finanzunternehmen."},{t:5,s:"Ich habe eine neue Karte von Citi beantragt."}]},
  "cities": {label:"Städte",gender:"die",plural:"Städte", ex5:[{t:1,s:"Ich möchte viele Städte auf der ganzen Welt besuchen."},{t:2,s:"Große Städte haben oft viel Verkehr."},{t:3,s:"Diese zwei Städte sind durch einen Schnellzug verbunden."},{t:4,s:"Viele Städte bieten eine reiche Kultur."},{t:5,s:"Er hat schon in vielen verschiedenen Städten gelebt."}]},
  "citing": {label:"zitierend",gender:"",plural:"—", ex5:[{t:1,s:"Sie stützte ihr Argument, indem sie aktuelle Studien zitierte."},{t:2,s:"Der Anwalt war dabei, frühere Gerichtsurteile zitierend, seinen Punkt zu machen."},{t:3,s:"Er vermied es, unzuverlässige Quellen in seiner Arbeit zu zitieren."},{t:4,s:"Indem man Quellen korrekt zitiert, wird die Arbeit glaubwürdiger."},{t:5,s:"Er sprach, dabei viele Statistiken zitierend."}]},
  "citizen": {label:"Bürger",gender:"der",plural:"Bürger", ex5:[{t:1,s:"Der Bürger ging wählen."},{t:2,s:"Der Bürger ist stolz auf seine Stadt."},{t:3,s:"Wir wurden Staatsbürger eines neuen Landes."},{t:4,s:"Jeder Bürger hat bestimmte Rechte."},{t:5,s:"Der Bürger engagiert sich für seine Gemeinde."}]},
  "citizenry": {label:"Bürgerschaft",gender:"die",plural:"Bürgerschaften", ex5:[{t:1,s:"Die Regierung sollte auf die Bedürfnisse der Bürgerschaft hören."},{t:2,s:"Die gesamte Bürgerschaft nahm an der Wahl teil."},{t:3,s:"Das Projekt zielt darauf ab, das Leben der Bürgerschaft zu verbessern."},{t:4,s:"Die Bürgerschaft ist sehr engagiert."},{t:5,s:"Das Wohl der Bürgerschaft steht an erster Stelle."}]},
  "citizens": {label:"Bürger",gender:"die",plural:"Bürger", ex5:[{t:1,s:"Die Bürger versammelten sich auf dem Platz."},{t:2,s:"Die Bürger sind ihrem Land gegenüber loyal."},{t:3,s:"Wir haben die Bürger zu ihrer Meinung befragt."},{t:4,s:"Viele Bürger kamen zur Versammlung."},{t:5,s:"Die Bürger fordern bessere Straßen."}]},
  "citizenship": {label:"Staatsbürgerschaft",gender:"die",plural:"Staatsbürgerschaften", ex5:[{t:1,s:"Er hat letzte Woche seine Staatsbürgerschaft erhalten."},{t:2,s:"Die Beantragung der Staatsbürgerschaft dauert lange."},{t:3,s:"Sie ist stolz auf ihre doppelte Staatsbürgerschaft."},{t:4,s:"Die Staatsbürgerschaft ist ein wichtiges Recht."},{t:5,s:"Man muss bestimmte Bedingungen für die Staatsbürgerschaft erfüllen."}]},
  "citrate": {label:"Citrat",gender:"das",plural:"Citrate", ex5:[{t:1,s:"Natriumcitrat wird häufig als Lebensmittelzusatzstoff verwendet."},{t:2,s:"Der Arzt verschrieb ihm ein Citrat-Präparat für seinen Zustand."},{t:3,s:"Citrate helfen dabei, bestimmte Arten von Nierensteinen zu verhindern."},{t:4,s:"Die Lösung enthält eine hohe Konzentration an Citrat."},{t:5,s:"Man verwendet Citrat oft zur Stabilisierung von Blutproben."}]},
  "citric": {label:"Zitronensäure-",gender:"",plural:"—", ex5:[{t:1,s:"Zitronen enthalten einen hohen Anteil an Zitronensäure."},{t:2,s:"Das Getränk hat einen scharfen Zitronensäure-Geschmack."},{t:3,s:"Sie fügte dem Salatdressing etwas Zitronensäure hinzu."},{t:4,s:"Die Reinigungskraft basiert auf der Wirkung der Zitronensäure."},{t:5,s:"Zitronensäure ist ein natürliches Konservierungsmittel."}]},
  "citrus": {label:"Zitrusfrucht",gender:"die",plural:"Zitrusfrüchte", ex5:[{t:1,s:"Ich mag den frischen Duft von Zitrusfrüchten."},{t:2,s:"Zitrusfrüchte wachsen gut in warmen Klimazonen."},{t:3,s:"Sie trinkt jeden Morgen warmes Wasser mit einer Scheibe Zitrusfrucht."},{t:4,s:"Im Garten stehen verschiedene Zitrusfrüchte."},{t:5,s:"Die Schale der Zitrusfrucht ist sehr aromatisch."}]},
  "city": {label:"Stadt",gender:"die",plural:"Städte", ex5:[{t:1,s:"Die Stadt erwachte zum Leben."},{t:2,s:"Die Stadt ist sehr geschäftig."},{t:3,s:"Wir haben die Stadt besichtigt."},{t:4,s:"Das Leben in der Stadt ist aufregend."},{t:5,s:"Jede Stadt hat ihren eigenen Charme."}]},
  "cityscape": {label:"Stadtbild",gender:"das",plural:"Stadtbilder", ex5:[{t:1,s:"Das Stadtbild bei Nacht ist absolut wunderschön."},{t:2,s:"Wir genossen den Blick auf das Stadtbild vom Balkon aus."},{t:3,s:"Der Künstler malte das sich verändernde Stadtbild von Seoul."},{t:4,s:"Das historische Stadtbild ist gut erhalten geblieben."},{t:5,s:"Moderne Hochhäuser prägen heute das Stadtbild."}]},
  "citywide": {label:"stadtweit",gender:"",plural:"—", ex5:[{t:1,s:"Es wird heute Nacht einen stadtweiten Stromausfall geben."},{t:2,s:"Das stadtweite Festival beginnt an diesem Wochenende."},{t:3,s:"Sie organisierten eine stadtweite Aufräumaktion."},{t:4,s:"Die stadtweite Umfrage zeigt große Zustimmung."},{t:5,s:"Das stadtweite Internetnetzwerk wird modernisiert."}]},
  "civic": {label:"bürgerlich",gender:"",plural:"—", ex5:[{t:1,s:"Der bürgerliche Stolz wuchs an."},{t:2,s:"Diese Pflicht ist bürgerlicher Natur."},{t:3,s:"Wir haben uns bürgerlichen Gruppen angeschlossen."},{t:4,s:"Das bürgerliche Engagement ist sehr wichtig."},{t:5,s:"Er setzt sich für bürgerliche Belange ein."}]},
  "civics": {label:"Gemeinschaftskunde",gender:"die",plural:"—", ex5:[{t:1,s:"Wir lernen grundlegende Rechte und Pflichten in der Gemeinschaftskunde."},{t:2,s:"Gemeinschaftskunde hilft Schülern zu verstehen, wie die Regierung funktioniert."},{t:3,s:"Der Lehrer gab ein Projekt über lokale Gemeinschaftskunde auf."},{t:4,s:"Gemeinschaftskunde ist ein wichtiges Schulfach."},{t:5,s:"In der Gemeinschaftskunde diskutieren wir aktuelle politische Themen."}]},
