  "civilian": {label:"Zivilist",gender:"der",plural:"Zivilisten", ex5:[{t:1,s:"Der Zivilist floh vor der Gefahr."},{t:2,s:"Der Zivilist ist in Sicherheit."},{t:3,s:"Wir haben dem Zivilisten geholfen."},{t:4,s:"Jeder Zivilist hat das Recht auf Schutz."},{t:5,s:"Der Zivilist erzählte seine Geschichte."}]},
  "civilians": {label:"Zivilisten",gender:"die",plural:"Zivilisten", ex5:[{t:1,s:"Die Armee schützte die Zivilisten."},{t:2,s:"Viele Zivilisten wurden aus der Stadt evakuiert."},{t:3,s:"Zivilisten waren nicht in den Konflikt verwickelt."},{t:4,s:"Die Zivilisten hoffen auf Frieden."},{t:5,s:"Man muss die Zivilisten in Kriegszeiten schonen."}]},
  "civilisation": {label:"Zivilisation",gender:"die",plural:"Zivilisationen", ex5:[{t:1,s:"Die antike Zivilisation blühte am Fluss auf."},{t:2,s:"Wir untersuchten den Untergang der Maya-Zivilisation."},{t:3,s:"Bildung ist das Fundament einer modernen Zivilisation."},{t:4,s:"Jede Zivilisation hat ihre eigenen Werte."},{t:5,s:"Die Zivilisation hat sich stark verändert."}]},
  "civilised": {label:"zivilisiert",gender:"",plural:"—", ex5:[{t:1,s:"Die alten Römer waren ein sehr zivilisiertes Volk."},{t:2,s:"Sie hofften, eine zivilisiertere Gesellschaft aufzubauen."},{t:3,s:"Das ist eine zivilisierte Art, Konflikte zu lösen."},{t:4,s:"Wir führen ein zivilisiertes Gespräch."},{t:5,s:"Ein zivilisiertes Leben ist ihr Ziel."}]},
  "civility": {label:"Höflichkeit",gender:"die",plural:"Höflichkeiten", ex5:[{t:1,s:"Wir sollten jedem mit Höflichkeit begegnen."},{t:2,s:"Die Debatte wurde mit überraschender Höflichkeit geführt."},{t:3,s:"Er dankte seinem Gegner für dessen Höflichkeit."},{t:4,s:"Höflichkeit ist in der Gesellschaft wichtig."},{t:5,s:"Trotz des Streits bewahrte er seine Höflichkeit."}]},
  "civilization": {label:"Zivilisation",gender:"die",plural:"Zivilisationen", ex5:[{t:1,s:"Die Zivilisation ist erblüht."},{t:2,s:"Die Zivilisation ist uralt."},{t:3,s:"Wir haben die Zivilisation erforscht."},{t:4,s:"Die Zivilisation entwickelt sich weiter."},{t:5,s:"Jede Zivilisation hat ihre Blütezeit."}]},
  "civilizations": {label:"Zivilisationen",gender:"die",plural:"Zivilisationen", ex5:[{t:1,s:"Antike Zivilisationen entwickelten sich oft an großen Flüssen."},{t:2,s:"Wir studieren vergangene Zivilisationen, um unsere Geschichte zu verstehen."},{t:3,s:"Das Museum hat eine tolle Ausstellung über verlorene Zivilisationen."},{t:4,s:"Viele Zivilisationen sind im Laufe der Zeit verschwunden."},{t:5,s:"Wir vergleichen verschiedene Zivilisationen miteinander."}]},
  "civilized": {label:"zivilisiert",gender:"",plural:"—", ex5:[{t:1,s:"Es ist wichtig, eine zivilisierte Diskussion über diese Themen zu führen."},{t:2,s:"Sie versuchten, eine zivilisierte Einigung zu erzielen."},{t:3,s:"Auch in schwierigen Zeiten sollten wir zivilisiert bleiben."},{t:4,s:"Ein zivilisiertes Verhalten ist überall gefragt."},{t:5,s:"Wir brauchen einen zivilisierten Umgang miteinander."}]},
  "clack": {label:"Klappern",gender:"das",plural:"—", ex5:[{t:1,s:"Die Absätze ihrer Schuhe machten ein scharfes Klappern auf dem Boden."},{t:2,s:"Ich konnte das Klappern der Tastatur hören, als er schnell tippte."},{t:3,s:"Die hölzernen Fensterläden begannen im starken Wind zu klappern."},{t:4,s:"Das Klappern der Tassen war in der Küche zu hören."},{t:5,s:"Ein leises Klappern kam aus der Ecke."}]},
