  "cladding": {label:"Verkleidung",gender:"die",plural:"Verkleidungen", ex5:[{t:1,s:"Das Gebäude hat eine moderne Metallverkleidung."},{t:2,s:"Sie ersetzen die alte Verkleidung für eine bessere Isolierung."},{t:3,s:"Die Holzverkleidung verleiht dem Haus ein gemütliches Aussehen."},{t:4,s:"Die Fassadenverkleidung schützt vor Witterungseinflüssen."},{t:5,s:"Die Verkleidung des Hauses wurde komplett erneuert."}]},
  "claim": {label:"Anspruch",gender:"der",plural:"Ansprüche", ex5:[{t:1,s:"Er hat einen Anspruch auf Entschädigung."},{t:2,s:"Dieser Anspruch ist sehr hoch."},{t:3,s:"Wir haben unseren Anspruch angemeldet."},{t:4,s:"Der Anspruch auf Urlaub ist gesetzlich geregelt."},{t:5,s:"Er erhebt Anspruch auf das Erbe."}]},
  "claimant": {label:"Antragsteller",gender:"der",plural:"Antragsteller", ex5:[{t:1,s:"Der Antragsteller muss das Formular unterschreiben."},{t:2,s:"Wir haben den Antragsteller kontaktiert."},{t:3,s:"Der Antragsteller wartet auf eine Antwort."},{t:4,s:"Die Unterlagen des Antragstellers sind vollständig."},{t:5,s:"Jeder Antragsteller erhält eine Bestätigung."}]},
