  "claimed": {label:"beansprucht",gender:"",plural:"—", ex5:[{t:1,s:"Er hat den Sieg für sich beansprucht."},{t:2,s:"Das Land wird von beiden Seiten beansprucht."},{t:3,s:"Sie hat den Preis für sich beansprucht."},{t:4,s:"Er hat das Eigentum an der Sache beansprucht."},{t:5,s:"Die Aufgabe hat viel Zeit beansprucht."}]},
  "claiming": {label:"beanspruchend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist dabei, seinen Anteil beanspruchend einzufordern."},{t:2,s:"Die Firma ist ihre Rechte beanspruchend aufgetreten."},{t:3,s:"Sie ist den Preis beanspruchend zum Schalter gegangen."},{t:4,s:"Er ist die Wahrheit beanspruchend in die Diskussion gegangen."},{t:5,s:"Das Projekt ist viel Aufmerksamkeit beanspruchend."}]},
