  "clairvoyant": {label:"Hellseher",gender:"der",plural:"Hellseher", ex5:[{t:1,s:"Sie behauptete, ein wahrer Hellseher zu sein."},{t:2,s:"Der Hellseher sagte, dass Gefahr droht."},{t:3,s:"Seine Vorhersage als Hellseher war erstaunlich korrekt."},{t:4,s:"Der Hellseher blickte in die Zukunft."},{t:5,s:"Viele Menschen glauben nicht an einen Hellseher."}]},
  "clam": {label:"Muschel",gender:"die",plural:"Muscheln", ex5:[{t:1,s:"Wir haben am Strand nach einer Muschel gesucht."},{t:2,s:"Die Muschel vergräbt sich im nassen Sand."},{t:3,s:"Sie hat frische Muscheln in die Suppe gegeben."},{t:4,s:"Ich habe eine schöne Muschel am Meer gefunden."},{t:5,s:"Muscheln schmecken am besten mit etwas Zitrone."}]},
  "clamber": {label:"klettern",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind über die Felsen geklettert."},{t:2,s:"Der Junge ist geschickt auf den Baum geklettert."},{t:3,s:"Sie kletterte mühsam in den hohen LKW."},{t:4,s:"Wir sind gestern auf den Berg geklettert."},{t:5,s:"Das Kind klettert gerne auf das Klettergerüst."}]},
  "clammy": {label:"klamm",gender:"",plural:"—", ex5:[{t:1,s:"Seine Hände waren kalt und klamm."},{t:2,s:"Die klamme Luft fühlte sich unangenehm an."},{t:3,s:"Sie wischte sich über die klamme Stirn."},{t:4,s:"Bei diesem Wetter sind meine Socken ganz klamm."},{t:5,s:"Die Wäsche ist noch etwas klamm."}]},
  "clamor": {label:"Lärm",gender:"der",plural:"—", ex5:[{t:1,s:"Die Menge machte einen großen Lärm."},{t:2,s:"Ich konnte wegen des Lärms nicht schlafen."},{t:3,s:"Draußen vor dem Tor gab es einen plötzlichen Lärm."},{t:4,s:"Der Lärm der Stadt ist manchmal anstrengend."},{t:5,s:"Hör auf mit diesem Lärm!"}]},
  "clamoring": {label:"fordernd",gender:"",plural:"—", ex5:[{t:1,s:"Die Fans riefen fordernd nach einem Autogramm."},{t:2,s:"Die Menschenmenge war fordernd und wollte Veränderungen."},{t:3,s:"Die Kinder waren fordernd, als sie mehr Eis wollten."},{t:4,s:"Die Menge wirkte ungeduldig und fordernd."},{t:5,s:"Er reagierte auf die fordernde Art der Leute."}]},
  "clamorous": {label:"lärmend",gender:"",plural:"—", ex5:[{t:1,s:"Die lärmende Menge jubelte der Mannschaft zu."},{t:2,s:"Ich konnte wegen der lärmenden Nachbarn nicht schlafen."},{t:3,s:"Vögel machten am Morgen ein lärmendes Geräusch."},{t:4,s:"Es war eine sehr lärmende Veranstaltung."},{t:5,s:"Die Kinder spielten auf dem lärmenden Spielplatz."}]},
  "clamour": {label:"Geschrei",gender:"das",plural:"—", ex5:[{t:1,s:"Es gab ein lautes Geschrei auf der Straße."},{t:2,s:"Das öffentliche Geschrei nach besseren Schulen wird lauter."},{t:3,s:"Sie ignorierte das Geschrei und arbeitete weiter."},{t:4,s:"Das Geschrei der Kinder war im ganzen Haus zu hören."},{t:5,s:"Nach dem Geschrei wurde es plötzlich still."}]},
  "clamp": {label:"Klemme",gender:"die",plural:"Klemmen", ex5:[{t:1,s:"Er benutzte eine Klemme, um das Holz zu halten."},{t:2,s:"Die Klemme hielt die beiden Teile zusammen."},{t:3,s:"Sie zog die Klemme vorsichtig fest."},{t:4,s:"Diese Klemme ist sehr stabil."},{t:5,s:"Ich brauche eine Klemme für dieses Projekt."}]},
  "clamped": {label:"festgeklemmt",gender:"",plural:"—", ex5:[{t:1,s:"Der Schreiner hat die Holzteile festgeklemmt."},{t:2,s:"Er hat sich die Ohren festgeklemmt, um nichts zu hören."},{t:3,s:"Die Polizei hat das Rad des Autos festgeklemmt."},{t:4,s:"Das Papier ist im Drucker festgeklemmt."},{t:5,s:"Sie hat das Werkstück sicher festgeklemmt."}]},
  "clamping": {label:"Festklemmen",gender:"das",plural:"—", ex5:[{t:1,s:"Er benutzte ein Werkzeug zum Festklemmen des Holzes."},{t:2,s:"Der Mechanismus zum Festklemmen war sehr sicher."},{t:3,s:"Beim Festklemmen des Stoffes war sie sehr vorsichtig."},{t:4,s:"Das Festklemmen dauert nur wenige Sekunden."},{t:5,s:"Er achtet beim Festklemmen auf die richtige Position."}]},
  "clamps": {label:"Schraubzwinge",gender:"die",plural:"Schraubzwingen", ex5:[{t:1,s:"Benutze die Schraubzwingen, um die Teile fest zusammenzuhalten."},{t:2,s:"Er zog die Schraubzwingen fest, um das Holzbrett zu sichern."},{t:3,s:"Die Werkstatt ist mit verschiedenen Schraubzwingen ausgestattet."},{t:4,s:"Löse die Schraubzwingen vorsichtig."},{t:5,s:"Ich brauche noch eine Schraubzwinge für dieses Projekt."}]},
