  "closeness": {label:"Nähe",gender:"die",plural:"Nähen", ex5:[{t:1,s:"Die Nähe ihrer Freundschaft ist inspirierend."},{t:2,s:"Ich schätze die Nähe zu meiner Familie."},{t:3,s:"Die Nähe des Ergebnisses war überraschend."},{t:4,s:"Man spürt die Nähe zwischen ihnen."},{t:5,s:"Die physische Nähe ist wichtig."}]},
  "closer": {label:"näher",gender:"",plural:"—", ex5:[{t:1,s:"Der Sturm kommt näher."},{t:2,s:"Das Ziel ist nun näher."},{t:3,s:"Wir sind näher zusammengerückt."},{t:4,s:"Komm bitte ein Stück näher."},{t:5,s:"Das Ende rückt immer näher."}]},
