  "closings": {label:"Schließungen",gender:"die",plural:"Schließungen", ex5:[{t:1,s:"Das Geschäft kündigte seine frühen Schließungen an Feiertagen an."},{t:2,s:"Es gab mehrere Straßenschließungen wegen des Sturms."},{t:3,s:"Er leitete die Schließungen vieler Bankfilialen."},{t:4,s:"Die Schließungen betreffen viele Mitarbeiter."},{t:5,s:"Wir haben von den Schließungen in der Zeitung gelesen."}]},
  "clostridium": {label:"Clostridium",gender:"das",plural:"Clostridien", ex5:[{t:1,s:"Clostridium-Bakterien können in Umgebungen ohne Sauerstoff wachsen."},{t:2,s:"Einige Arten von Clostridium sind für Lebensmittelvergiftungen verantwortlich."},{t:3,s:"Das Labor untersucht, wie Clostridium auf bestimmte Antibiotika reagiert."},{t:4,s:"Clostridien sind weit verbreitet in der Natur."},{t:5,s:"Diese Infektion wird durch Clostridium verursacht."}]},
  "closure": {label:"Abschluss",gender:"der",plural:"Abschlüsse", ex5:[{t:1,s:"Der Abschluss war schmerzhaft."},{t:2,s:"Dieser Abschluss ist endgültig."},{t:3,s:"Wir suchten nach einem inneren Abschluss."},{t:4,s:"Sie brauchte einen Abschluss für diese Angelegenheit."},{t:5,s:"Der Abschluss des Projekts fiel uns schwer."}]},
  "closures": {label:"Schließung",gender:"die",plural:"Schließungen", ex5:[{t:1,s:"Wegen Bauarbeiten sind Straßensperrungen zu erwarten."},{t:2,s:"Die Firma kündigte mehrere Werksschließungen an."},{t:3,s:"Während des Wintersturms gab es viele Schulschließungen."},{t:4,s:"Die plötzliche Schließung traf alle hart."},{t:5,s:"Wir protestierten gegen die Schließung der Bibliothek."}]},
  "clot": {label:"Blutgerinnsel",gender:"das",plural:"Blutgerinnsel", ex5:[{t:1,s:"Der Arzt sagte, das Blutgerinnsel sei gefährlich."},{t:2,s:"Nach der Operation bildete sich ein kleines Blutgerinnsel."},{t:3,s:"Medikamente können helfen, ein Blutgerinnsel aufzulösen."},{t:4,s:"Das Blutgerinnsel wurde rechtzeitig entdeckt."},{t:5,s:"Er hat Angst vor einem erneuten Blutgerinnsel."}]},
