  "clothing": {label:"Kleidung",gender:"die",plural:"—", ex5:[{t:1,s:"Kleidung verkauft sich schnell."},{t:2,s:"Die Kleidung hält warm."},{t:3,s:"Wir haben Kleidung gespendet."},{t:4,s:"Er braucht neue Kleidung für die Arbeit."},{t:5,s:"Die Kleidung ist aus biologischen Materialien hergestellt."}]},
  "cloths": {label:"Tücher",gender:"die",plural:"Tücher", ex5:[{t:1,s:"Sie kaufte verschiedene farbige Tücher zum Nähen."},{t:2,s:"Bitte benutze diese sauberen Tücher, um den Tisch abzuwischen."},{t:3,s:"Der Künstler verwendete verschiedene Tücher, um Strukturen zu erzeugen."},{t:4,s:"Sie legte die Tücher ordentlich in den Schrank."},{t:5,s:"Wir brauchen neue Tücher für die Küche."}]},
  "clots": {label:"Blutgerinnsel",gender:"das",plural:"Blutgerinnsel", ex5:[{t:1,s:"Hoher Blutdruck kann das Risiko für Blutgerinnsel erhöhen."},{t:2,s:"Das Medikament wurde entwickelt, um gefährliche Blutgerinnsel zu verhindern."},{t:3,s:"Die Ärzte untersuchten ihn auf Anzeichen von inneren Blutgerinnseln."},{t:4,s:"Ein Blutgerinnsel kann den Blutfluss blockieren."},{t:5,s:"Er nimmt Medikamente gegen Blutgerinnsel."}]},
  "clotting": {label:"Blutgerinnung",gender:"die",plural:"—", ex5:[{t:1,s:"Vitamin K ist wichtig für eine gesunde Blutgerinnung."},{t:2,s:"Das Medikament hilft, eine abnormale Blutgerinnung in den Venen zu verhindern."},{t:3,s:"Er leidet an einer Krankheit, die seine Blutgerinnung beeinträchtigt."},{t:4,s:"Die Blutgerinnung stoppt die Blutung bei einer Wunde."},{t:5,s:"Eine gestörte Blutgerinnung kann gefährlich sein."}]},
  "cloud": {label:"Wolke",gender:"die",plural:"Wolken", ex5:[{t:1,s:"Eine Wolke zog am Himmel vorbei."},{t:2,s:"Die Wolke ist grau."},{t:3,s:"Wir beobachteten die Wolke."},{t:4,s:"Eine einzelne Wolke verdeckte kurz die Sonne."},{t:5,s:"Die Wolke hat eine interessante Form."}]},
