  "colonoscopy": {label:"Koloskopie",gender:"die",plural:"Koloskopien", ex5:[{t:1,s:"Der Arzt empfahl eine **Koloskopie** zur regelmäßigen Vorsorgeuntersuchung."},{t:2,s:"Ich war vor meiner ersten **Koloskopie** nervös."},{t:3,s:"Vor der **Koloskopie** müssen Sie eine spezielle Diät einhalten."},{t:4,s:"Die **Koloskopie** ist ein wichtiges Instrument zur Darmkrebsfrüherkennung."},{t:5,s:"Nach der **Koloskopie** fühlte ich mich schnell wieder fit."}]},
  "colony": {label:"Kolonie",gender:"die",plural:"Kolonien", ex5:[{t:1,s:"Die Ameisen**kolonie** wuchs schnell."},{t:2,s:"Diese Vogel**kolonie** ist sehr groß."},{t:3,s:"Wir haben die Bakterien**kolonie** untersucht."},{t:4,s:"Früher waren viele Länder europäische **Kolonien**."},{t:5,s:"Die neue **Kolonie** wurde erfolgreich gegründet."}]},
