  "configurations": {label:"Konfigurationen",gender:"die",plural:"Konfigurationen", ex5:[{t:1,s:"Die Software unterstützt verschiedene Konfigurationen."},{t:2,s:"Wir müssen die Konfigurationen des Systems prüfen."},{t:3,s:"Diese Konfigurationen verbessern die Geschwindigkeit."},{t:4,s:"Er hat die neuen Konfigurationen gespeichert."},{t:5,s:"Es gibt viele mögliche Konfigurationen für dieses Gerät."}]},
  "configure": {label:"konfigurieren",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen den neuen Server konfigurieren."},{t:2,s:"Sie können das Programm nach Ihren Wünschen konfigurieren."},{t:3,s:"Ich werde heute mein neues Handy konfigurieren."},{t:4,s:"Es ist einfach, dieses Gerät zu konfigurieren."},{t:5,s:"Der Techniker hilft uns, das Netzwerk zu konfigurieren."}]},
