  "confinement": {label:"die Haft",gender:"die",plural:"Haften", ex5:[{t:1,s:"Das Tier wurde in strikter Haft gehalten."},{t:2,s:"Einzelhaft ist eine harte Form der Bestrafung."},{t:3,s:"Er fühlte ein Gefühl der Haft in dem kleinen Zimmer."},{t:4,s:"Die Haft dauerte viel zu lange."},{t:5,s:"Er wurde aus der Haft entlassen."}]},
  "confines": {label:"beschränken",gender:"",plural:"—", ex5:[{t:1,s:"Das Gesetz beschränkt die Haftung der Firma auf ihr eigenes Vermögen."},{t:2,s:"Er beschränkt sein Training auf Spaziergänge im Park."},{t:3,s:"Der kleine Käfig beschränkt den Vogel in seiner Freiheit."},{t:4,s:"Ich beschränke mich bei meiner Arbeit auf dieses Thema."},{t:5,s:"Man sollte den Lärm auf ein Minimum beschränken."}]},
  "confining": {label:"beschränkend",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt ist gerade dabei, den Patienten auf das Bett beschränkend zu behandeln."},{t:2,s:"Ich bin meine Studie beschränkend auf dieses Kapitel am Ausarbeiten."},{t:3,s:"Das beschränkende Halten von Tieren in kleinen Käfigen ist grausam."},{t:4,s:"Er wirkt auf die Gruppe sehr beschränkend."},{t:5,s:"Diese Regelung ist für uns alle beschränkend."}]},
