  "confirms": {label:"bestätigt",gender:"",plural:"—", ex5:[{t:1,s:"Die E-Mail bestätigt die Zeit unseres Treffens."},{t:2,s:"Die Wissenschaft bestätigt, dass Wasser lebensnotwendig ist."},{t:3,s:"Sie bestätigt, dass sie zur Party kommt."},{t:4,s:"Dieser Bericht bestätigt meine Vermutung."},{t:5,s:"Der Lehrer bestätigt den Termin."}]},
  "confiscate": {label:"beschlagnahmen",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer musste das Handy beschlagnahmen."},{t:2,s:"Sie werden alle illegalen Gegenstände beschlagnahmen."},{t:3,s:"Die Polizei entschied, das gestohlene Auto zu beschlagnahmen."},{t:4,s:"Wir müssen alle verbotenen Dinge beschlagnahmen."},{t:5,s:"Der Zoll wird die Ware beschlagnahmen."}]},
  "confiscated": {label:"beschlagnahmt",gender:"",plural:"—", ex5:[{t:1,s:"Der Sicherheitsdienst hat meine Wasserflasche am Tor beschlagnahmt."},{t:2,s:"Der Lehrer beschlagnahmte das Handy, weil er im Unterricht tippte."},{t:3,s:"Alle illegalen Gegenstände wurden von der Polizei beschlagnahmt."},{t:4,s:"Mein Pass wurde beschlagnahmt."},{t:5,s:"Das beschlagnahmte Auto wurde abtransportiert."}]},
  "confiscating": {label:"beschlagnahmend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer ist gerade dabei, Handys während der Prüfung zu beschlagnahmen."},{t:2,s:"Die Sicherheitsleute waren damit beschäftigt, verbotene Gegenstände zu beschlagnahmen."},{t:3,s:"Das grundlose Beschlagnahmen von Privateigentum ist falsch."},{t:4,s:"Wir sind beim Beschlagnahmen der illegalen Ware."},{t:5,s:"Er war damit beschäftigt, die Waren zu beschlagnahmen."}]},
  "confiscation": {label:"Beschlagnahmung",gender:"die",plural:"Beschlagnahmungen", ex5:[{t:1,s:"Die Beschlagnahmung der Waren verärgerte den Händler."},{t:2,s:"Der Zoll ordnete die Beschlagnahmung der Ladung an."},{t:3,s:"Die Beschlagnahmung der Waffen war rechtmäßig."},{t:4,s:"Diese Beschlagnahmung war notwendig."},{t:5,s:"Nach der Beschlagnahmung gab es eine Klage."}]},
  "conflagration": {label:"Großbrand",gender:"der",plural:"Großbrände", ex5:[{t:1,s:"Der Großbrand zerstörte die halbe Stadt."},{t:2,s:"Die Feuerwehr bekämpfte den riesigen Großbrand."},{t:3,s:"Ein einziger Funke entfachte den Großbrand."},{t:4,s:"Der Großbrand war weithin sichtbar."},{t:5,s:"Nach dem Großbrand blieb nur Asche übrig."}]},
  "conflate": {label:"verwechseln",gender:"",plural:"—", ex5:[{t:1,s:"Du solltest die beiden Ideen nicht verwechseln."},{t:2,s:"Er hat Fakten mit Meinungen verwechselt."},{t:3,s:"Man verwechselt diese beiden Begriffe oft miteinander."},{t:4,s:"Träume und Realität darf man nicht verwechseln."},{t:5,s:"Ich habe die beiden Termine miteinander verwechselt."}]},
  "conflict": {label:"Konflikt",gender:"der",plural:"Konflikte", ex5:[{t:1,s:"Ein Konflikt ist ausgebrochen."},{t:2,s:"Der Konflikt sitzt tief."},{t:3,s:"Wir haben den Konflikt gelöst."},{t:4,s:"Es kam zu einem Konflikt zwischen den Freunden."},{t:5,s:"Der Konflikt lässt sich nicht so einfach beilegen."}]},
  "conflicted": {label:"hin- und hergerissen",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin hin- und hergerissen, ob ich in eine neue Stadt ziehen soll."},{t:2,s:"Die beiden Freunde waren nach ihrem Streit hin- und hergerissen."},{t:3,s:"Sie war hin- und hergerissen zwischen ihrem Beruf und ihrer Familie."},{t:4,s:"Ich bin innerlich hin- und hergerissen."},{t:5,s:"Er fühlte sich hin- und hergerissen bei dieser Entscheidung."}]},
