  "conflicts": {label:"Konflikte",gender:"die",plural:"Konflikte", ex5:[{t:1,s:"Der Film zeigt historische Konflikte zwischen Nationen."},{t:2,s:"Innere Konflikte können schwer zu lösen sein."},{t:3,s:"Die Geschichte erforscht die Konflikte innerhalb der Familie."},{t:4,s:"Es gibt viele Konflikte in ihrer Beziehung."},{t:5,s:"Wir müssen diese Konflikte offen ansprechen."}]},
  "confluence": {label:"Zusammenfluss",gender:"der",plural:"Zusammenflüsse", ex5:[{t:1,s:"Die Stadt liegt an einem Zusammenfluss."},{t:2,s:"Ein Zusammenfluss von Ereignissen hat das verursacht."},{t:3,s:"Die beiden Ströme treffen sich am Zusammenfluss."},{t:4,s:"Wir trafen uns direkt am Zusammenfluss der Flüsse."},{t:5,s:"Der Zusammenfluss ist ein wichtiger geografischer Punkt."}]},
  "conform": {label:"entsprechen",gender:"",plural:"—", ex5:[{t:1,s:"Die Teile entsprechen der Norm."},{t:2,s:"Das Design entspricht den geltenden Regeln."},{t:3,s:"Wir entsprechen dem Standard."},{t:4,s:"Das Produkt entspricht allen Anforderungen."},{t:5,s:"Er wollte nicht immer der Norm entsprechen."}]},
  "conformal": {label:"winkeltreu",gender:"",plural:"—", ex5:[{t:1,s:"Die Kartenprojektion wird als winkeltreu beschrieben."},{t:2,s:"Wir haben winkeltreue Abbildungen im Geometrieunterricht gelernt."},{t:3,s:"Eine winkeltreue Transformation bewahrt die Winkel zwischen Kurven."},{t:4,s:"Diese Abbildung ist winkeltreu."},{t:5,s:"In der Kartografie ist winkeltreu sehr wichtig."}]},
  "conformation": {label:"Konformation",gender:"die",plural:"Konformationen", ex5:[{t:1,s:"Die Konformation des Proteins beeinflusst seine Funktion."},{t:2,s:"Die Konformation des Hundes entsprach dem Rassestandard."},{t:3,s:"Eine Änderung in der Konformation veränderte die Reaktion."},{t:4,s:"Man untersucht die Konformation von Molekülen."},{t:5,s:"Die räumliche Konformation ist entscheidend."}]},
  "conformed": {label:"angepasst",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sich ohne Klagen an die Schulregeln angepasst."},{t:2,s:"Das Produkt hat sich an alle internationalen Sicherheitsnormen angepasst."},{t:3,s:"Die meisten Schüler haben sich an die Kleiderordnung angepasst."},{t:4,s:"Er hat sich den neuen Bedingungen angepasst."},{t:5,s:"Das Design hat sich an die Vorgaben angepasst."}]},
  "conforming": {label:"konform",gender:"",plural:"—", ex5:[{t:1,s:"Er ist konform mit den neuen Sicherheitsvorschriften."},{t:2,s:"Sie mag es nicht, konform mit dem sozialen Druck zu sein."},{t:3,s:"Das Gebäude ist konform mit modernen Baustandards."},{t:4,s:"Er handelt konform zu den Regeln der Schule."},{t:5,s:"Wir sind konform mit den geltenden Gesetzen."}]},
  "conformist": {label:"Konformist",gender:"der",plural:"Konformisten", ex5:[{t:1,s:"Der Konformist befolgte jede Regel ohne Fragen."},{t:2,s:"Er war ein Konformist, der Konflikte vermied."},{t:3,s:"Der Konformist kleidete sich wie alle anderen."},{t:4,s:"Er gilt in der Gruppe als echter Konformist."},{t:5,s:"Ein Konformist passt sich leicht an die Mehrheit an."}]},
  "conformity": {label:"Konformität",gender:"die",plural:"Konformitäten", ex5:[{t:1,s:"Er weigerte sich, in Konformität mit den Schulregeln zu leben."},{t:2,s:"In großen Gruppen herrscht oft ein hoher Druck zur Konformität."},{t:3,s:"Der Bericht wurde in Konformität mit internationalen Standards verfasst."},{t:4,s:"Die Konformität mit der Norm ist ihm wichtig."},{t:5,s:"Manchmal ist Konformität in einer Gruppe erwünscht."}]},
  "conforms": {label:"konform gehen",gender:"",plural:"—", ex5:[{t:1,s:"Er geht jeden Tag konform mit der Schulordnung."},{t:2,s:"Das neue Produkt geht konform mit den Sicherheitsstandards."},{t:3,s:"Sie geht konform mit den sozialen Normen ihrer Gemeinde."},{t:4,s:"Diese Entscheidung geht konform mit unseren Werten."},{t:5,s:"Die Firma geht konform mit den neuen Richtlinien."}]},
  "confound": {label:"verwirren",gender:"",plural:"—", ex5:[{t:1,s:"Der plötzliche Wetterumschwung konnte unsere Pläne verwirren."},{t:2,s:"Sein seltsames Verhalten wird seine Freunde weiterhin verwirren."},{t:3,s:"Die komplexen Regeln des Spiels verwirren die meisten Anfänger."},{t:4,s:"Diese unerwartete Nachricht wird ihn sicher verwirren."},{t:5,s:"Die widersprüchlichen Aussagen verwirren alle Beteiligten."}]},
  "confounded": {label:"verwirrt",gender:"",plural:"—", ex5:[{t:1,s:"Die schwierige Matheaufgabe hat die Schüler verwirrt."},{t:2,s:"Sie war von seinem seltsamen Verhalten verwirrt."},{t:3,s:"Das Rätsel hat die Ermittler jahrelang verwirrt."},{t:4,s:"Er war über den plötzlichen Vorschlag verwirrt."},{t:5,s:"Das Publikum war vom Ende völlig verwirrt."}]},
  "confounding": {label:"verwirrend",gender:"",plural:"—", ex5:[{t:1,s:"Der Trick des Zauberers war wirklich verwirrend."},{t:2,s:"Die komplexen Anweisungen waren selbst für erfahrene Nutzer verwirrend."},{t:3,s:"Sein plötzlicher Einstellungswechsel war für alle verwirrend."},{t:4,s:"Das war eine sehr verwirrende Situation."},{t:5,s:"Bitte stellen Sie keine verwirrenden Fragen."}]},
  "confront": {label:"konfrontieren",gender:"",plural:"—", ex5:[{t:1,s:"Helden konfrontieren ihre Angst."},{t:2,s:"Das Team muss das Problem konfrontieren."},{t:3,s:"Wir konfrontieren die Schwierigkeiten mutig."},{t:4,s:"Er wird mit der Wahrheit konfrontiert."},{t:5,s:"Man sollte Probleme direkt konfrontieren."}]},
  "confrontation": {label:"Konfrontation",gender:"die",plural:"Konfrontationen", ex5:[{t:1,s:"Die Konfrontation zwischen den beiden Seiten wurde angespannt."},{t:2,s:"Er vermied eine direkte Konfrontation."},{t:3,s:"Die Konfrontation endete ohne Gewalt."},{t:4,s:"Sie suchten den Weg aus der Konfrontation."},{t:5,s:"Diese Konfrontation war unvermeidlich."}]},
