  "confrontations": {label:"Konfrontation",gender:"die",plural:"Konfrontationen", ex5:[{t:1,s:"Wir sollten direkte Konfrontationen am Arbeitsplatz vermeiden."},{t:2,s:"Häufige Konfrontationen können der Stimmung im Team schaden."},{t:3,s:"Die Polizei verhinderte gewaltsame Konfrontationen."},{t:4,s:"Ich möchte jede unnötige Konfrontation vermeiden."},{t:5,s:"Diese Konfrontation hat zu keiner Lösung geführt."}]},
