  "confronts": {label:"konfrontiert",gender:"",plural:"—", ex5:[{t:1,s:"Er konfrontiert seine Ängste jeden Morgen."},{t:2,s:"Der Held konfrontiert den Bösewicht in der letzten Szene."},{t:3,s:"Sie konfrontiert das Problem, anstatt wegzulaufen."},{t:4,s:"Der Lehrer konfrontiert den Schüler mit der Wahrheit."},{t:5,s:"Sie konfrontiert ihre Gegner ohne Angst."}]},
  "confucian": {label:"konfuzianisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule folgt traditionellen konfuzianischen Werten."},{t:2,s:"Die konfuzianische Ethik betont den Respekt vor den Eltern."},{t:3,s:"Viele historische Gebäude zeigen einen konfuzianischen Stil."},{t:4,s:"Er interessiert sich für konfuzianische Lehren."},{t:5,s:"Diese Tradition hat einen konfuzianischen Ursprung."}]},
  "confucianism": {label:"Konfuzianismus",gender:"der",plural:"—", ex5:[{t:1,s:"Der Konfuzianismus hat die Kultur Ostasiens tief geprägt."},{t:2,s:"Er studierte den Konfuzianismus, um die Geschichte zu verstehen."},{t:3,s:"Respekt vor Älteren ist ein Kernwert im Konfuzianismus."},{t:4,s:"Der Konfuzianismus ist keine Religion im westlichen Sinne."},{t:5,s:"Die Prinzipien des Konfuzianismus sind heute noch wichtig."}]},
  "confucius": {label:"Konfuzius",gender:"",plural:"—", ex5:[{t:1,s:"Konfuzius war ein bedeutender chinesischer Philosoph."},{t:2,s:"Viele Lehren des Konfuzius sind auch heute noch aktuell."},{t:3,s:"Die Analekte enthalten die Aussprüche von Konfuzius."},{t:4,s:"Wir haben im Geschichtsunterricht viel über Konfuzius gelernt."},{t:5,s:"Die Philosophie von Konfuzius fasziniert mich sehr."}]},
  "confuse": {label:"verwirren",gender:"",plural:"—", ex5:[{t:1,s:"Komplizierte Karten verwirren die Touristen."},{t:2,s:"Die Schilder verwirren die Autofahrer."},{t:3,s:"Zu viele Optionen verwirren die Kunden."},{t:4,s:"Seine unklare Antwort wird alle verwirren."},{t:5,s:"Diese Regeln verwirren mich nur."}]},
  "confused": {label:"verwirrt",gender:"",plural:"—", ex5:[{t:1,s:"Er sah völlig verwirrt aus."},{t:2,s:"Die Menschenmenge war verwirrt."},{t:3,s:"Ich bin wegen der Termine verwirrt."},{t:4,s:"Seine Erklärung hat mich nur verwirrt zurückgelassen."},{t:5,s:"Die Schüler waren über die Hausaufgaben verwirrt."}]},
