  "constable": {label:"Polizist",gender:"der",plural:"Polizisten", ex5:[{t:1,s:"Der Polizist ging die Straße entlang, um die Geschäfte zu kontrollieren."},{t:2,s:"Der örtliche Polizist half dem verlorenen Kind, seine Eltern zu finden."},{t:3,s:"Ein Polizist ist dafür verantwortlich, für Ordnung in der Stadt zu sorgen."},{t:4,s:"Der Polizist bat den Fahrer, anzuhalten."},{t:5,s:"Ich habe den Polizisten nach dem Weg gefragt."}]},
  "constables": {label:"Polizisten",gender:"die",plural:"Polizisten", ex5:[{t:1,s:"Zwei Polizisten patrouillierten letzte Nacht auf dem Dorfplatz."},{t:2,s:"Die Polizisten halfen dem verlorenen Kind, seine Eltern zu finden."},{t:3,s:"Die örtlichen Polizisten sind hier für die Aufrechterhaltung der Ordnung zuständig."},{t:4,s:"Die Polizisten leiteten den Verkehr um."},{t:5,s:"Mehrere Polizisten waren bei der Veranstaltung anwesend."}]},
  "constabulary": {label:"Polizeitruppe",gender:"die",plural:"Polizeitruppen", ex5:[{t:1,s:"Die regionale Polizeitruppe stellt neue Beamte ein."},{t:2,s:"Er hat zehn Jahre lang in der örtlichen Polizeitruppe gedient."},{t:3,s:"Die Polizeitruppe gab eine Warnung bezüglich des Sturms heraus."},{t:4,s:"Die Polizeitruppe sicherte das gesamte Gebiet ab."},{t:5,s:"Sie ist stolz auf ihre Arbeit bei der Polizeitruppe."}]},
  "constancy": {label:"Beständigkeit",gender:"die",plural:"Beständigkeiten", ex5:[{t:1,s:"Ihre Beständigkeit in schwierigen Zeiten war bewundernswert."},{t:2,s:"Er schätzte Beständigkeit mehr als alles andere bei einem Freund."},{t:3,s:"Die Beständigkeit der Jahreszeiten schenkt uns Trost."},{t:4,s:"Man kann sich auf die Beständigkeit seines Charakters verlassen."},{t:5,s:"Beständigkeit ist der Schlüssel zum Erfolg."}]},
  "constant": {label:"konstant",gender:"",plural:"—", ex5:[{t:1,s:"Das Geräusch ist konstant."},{t:2,s:"Die Geschwindigkeit ist konstant."},{t:3,s:"Wir hielten eine konstante Wache."},{t:4,s:"Er arbeitet mit konstantem Tempo."},{t:5,s:"Der konstante Druck ist ein Problem."}]},
  "constantinople": {label:"Konstantinopel",gender:"",plural:"—", ex5:[{t:1,s:"Konstantinopel war einst die Hauptstadt des Byzantinischen Reiches."},{t:2,s:"Die Geschichte von Konstantinopel ist sehr faszinierend."},{t:3,s:"Viele Händler reisten nach Konstantinopel, um ihre Waren zu verkaufen."},{t:4,s:"Konstantinopel liegt an einer strategisch wichtigen Stelle."},{t:5,s:"Heute ist Konstantinopel unter dem Namen Istanbul bekannt."}]},
  "constantly": {label:"ständig",gender:"",plural:"—", ex5:[{t:1,s:"Es klingelt ständig."},{t:2,s:"Das Licht blinkt ständig."},{t:3,s:"Wir verbessern uns ständig."},{t:4,s:"Er beschwert sich ständig über das Wetter."},{t:5,s:"Das Baby schreit ständig."}]},
  "constants": {label:"Konstanten",gender:"die",plural:"Konstanten", ex5:[{t:1,s:"Veränderung ist eine der wenigen Konstanten in unserem Leben."},{t:2,s:"Die Mathematik verwendet viele Konstanten in komplexen Formeln."},{t:3,s:"Seine Güte und Geduld waren die Konstanten in ihrer Ehe."},{t:4,s:"In dieser Welt gibt es nur wenige Konstanten."},{t:5,s:"Physikalische Konstanten sind für die Wissenschaft wichtig."}]},
  "constellation": {label:"Sternbild",gender:"das",plural:"Sternbilder", ex5:[{t:1,s:"Sie entdeckten ein berühmtes Sternbild."},{t:2,s:"Das Sternbild sieht aus wie ein Bär."},{t:3,s:"Er benannte jedes Sternbild am Himmel."},{t:4,s:"Welches Sternbild ist das dort oben?"},{t:5,s:"Das Sternbild Orion ist sehr hell."}]},
