  "constituent": {label:"Wähler",gender:"der",plural:"Wähler", ex5:[{t:1,s:"Der Wähler hat angerufen."},{t:2,s:"Der Wähler ist verärgert."},{t:3,s:"Wir haben den Wähler angehört."},{t:4,s:"Die Politiker müssen den Wähler ernst nehmen."},{t:5,s:"Jeder Wähler hat seine eigenen Interessen."}]},
  "constituents": {label:"Bestandteil",gender:"der",plural:"Bestandteile", ex5:[{t:1,s:"Wasser ist einer der wichtigsten Bestandteile des Körpers."},{t:2,s:"Der Politiker hörte seinen Wählern aufmerksam zu."},{t:3,s:"Wir analysierten die chemischen Bestandteile des Bodens."},{t:4,s:"Das sind die wesentlichen Bestandteile des Produkts."},{t:5,s:"Die Bestandteile wurden sorgfältig geprüft."}]},
