  "cougars": {label:"Pumas",gender:"die",plural:"Pumas", ex5:[{t:1,s:"Pumas sind für ihre enorme Sprungkraft bekannt."},{t:2,s:"Wir haben zwei Pumas in der Nähe des Wanderwegs gesehen."},{t:3,s:"Pumas leben in vielen verschiedenen Lebensräumen in Amerika."},{t:4,s:"Pumas sind sehr anpassungsfähige Tiere."},{t:5,s:"Man sieht Pumas nur selten in freier Wildbahn."}]},
  "cough": {label:"Husten",gender:"der",plural:"—", ex5:[{t:1,s:"Der Husten will einfach nicht weggehen."},{t:2,s:"Er hat einen trockenen Husten."},{t:3,s:"Ich habe seit gestern Husten."},{t:4,s:"Der Husten klingt sehr hart."},{t:5,s:"Gegen den Husten hilft oft ein warmer Tee."}]},
  "coughed": {label:"hustete",gender:"",plural:"—", ex5:[{t:1,s:"Er hustete laut während des ruhigen Films."},{t:2,s:"Sie hustete ein wenig wegen des Staubes."},{t:3,s:"Der alte Mann hustete und räusperte sich."},{t:4,s:"Er hustete kurz, bevor er anfing zu sprechen."},{t:5,s:"Sie hustete mehrmals, weil sie sich verschluckt hatte."}]},
  "coughing": {label:"hustend",gender:"",plural:"—", ex5:[{t:1,s:"Er liegt hustend im Bett, weil er eine Erkältung hat."},{t:2,s:"Bitte halte dir den Mund zu, wenn du hustend sprichst."},{t:3,s:"Der Rauch im Raum sorgt dafür, dass alle hustend reagieren."},{t:4,s:"Sie kam hustend in das Zimmer."},{t:5,s:"Er ist schon den ganzen Tag hustend unterwegs."}]},
  "coughs": {label:"hustet",gender:"",plural:"—", ex5:[{t:1,s:"Er hustet oft wegen der kalten Luft."},{t:2,s:"Der Patient hustet die ganze Nacht hindurch."},{t:3,s:"Wenn sie hustet, sollte sie sich den Mund zuhalten."},{t:4,s:"Er hustet jedes Mal, wenn er den Raum betritt."},{t:5,s:"Das Kind hustet seit heute Morgen."}]},
