  "coulter": {label:"Coulter",gender:"",plural:"—", ex5:[{t:1,s:"Coulter ist ein sehr erfahrener Anwalt."},{t:2,s:"Ich habe kürzlich ein Buch gelesen, das von Coulter geschrieben wurde."},{t:3,s:"Coulter wird morgen auf der Konferenz sprechen."},{t:4,s:"Der Name Coulter ist in Schottland verbreitet."},{t:5,s:"Ich habe Frau Coulter noch nie persönlich getroffen."}]},
  "council": {label:"Rat",gender:"der",plural:"Räte", ex5:[{t:1,s:"Der Rat der Stadt trifft sich heute."},{t:2,s:"Wir haben den Rat um Hilfe gebeten."},{t:3,s:"Der Stadtrat hat eine neue Verordnung erlassen."},{t:4,s:"Sie ist Mitglied im wissenschaftlichen Rat."},{t:5,s:"Der Rat kam zu einer schnellen Entscheidung."}]},
