  "counseled": {label:"beriet",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer beriet den Schüler bei der Wahl seines Berufswegs."},{t:2,s:"Er beriet mich, in dieser schwierigen Zeit geduldig zu bleiben."},{t:3,s:"Sie beriet bereits viele Menschen mit Angstzuständen."},{t:4,s:"Der Experte beriet uns ausführlich zu diesem Thema."},{t:5,s:"Meine Mutter beriet mich bei meiner Entscheidung."}]},
  "counseling": {label:"Beratung",gender:"die",plural:"Beratungen", ex5:[{t:1,s:"Sie entschied sich, professionelle Beratung für ihren Stress zu suchen."},{t:2,s:"Die Schule bietet allen Schülern eine kostenlose Beratung an."},{t:3,s:"Ich fand die Beratung zur beruflichen Laufbahn sehr hilfreich."},{t:4,s:"Eine gute Beratung kann bei Lebenskrisen helfen."},{t:5,s:"Er nahm das Angebot einer psychologischen Beratung an."}]},
  "counselling": {label:"Beratung",gender:"die",plural:"Beratungen", ex5:[{t:1,s:"Sie sucht derzeit professionelle Beratung für ihren Stress."},{t:2,s:"Die Schule bietet eine einfühlsame Beratung für Schüler an."},{t:3,s:"Nach dem Unfall nahm er an einer Beratung zur Trauerbewältigung teil."},{t:4,s:"Die Beratung hat ihm sehr geholfen, den Verlust zu verarbeiten."},{t:5,s:"Manchmal ist eine externe Beratung der beste Weg."}]},
  "counsellor": {label:"Berater",gender:"der",plural:"Berater", ex5:[{t:1,s:"Der Berater half mir, mit meinem Stress umzugehen."},{t:2,s:"Ich beschloss, heute mit einem professionellen Berater zu sprechen."},{t:3,s:"Ein guter Berater hört zu, ohne einen zu verurteilen."},{t:4,s:"Mein Berater gab mir wertvolle Tipps für den Alltag."},{t:5,s:"Der Berater ist ein sehr erfahrener Fachmann."}]},
  "counselor": {label:"Berater",gender:"der",plural:"Berater", ex5:[{t:1,s:"Der Berater hörte sich ihre Sorgen aufmerksam an."},{t:2,s:"Ein Berater half ihm bei der Berufswahl."},{t:3,s:"Der Berater bot hilfreiche und praktische Ratschläge an."},{t:4,s:"Wenn man nicht weiterweiß, kann ein Berater helfen."},{t:5,s:"Der Berater nimmt sich immer viel Zeit für die Patienten."}]},
  "counselors": {label:"Berater",gender:"die",plural:"Berater", ex5:[{t:1,s:"Die Berater sind an der Schule, um die Schüler zu unterstützen."},{t:2,s:"Wir haben mit zwei Beratern über unsere Probleme gesprochen."},{t:3,s:"Die Berater im Camp führten die Kinder nach draußen."},{t:4,s:"Viele Berater arbeiten heutzutage online."},{t:5,s:"Die Berater trafen sich zu einer wöchentlichen Besprechung."}]},
