  "countered": {label:"entgegnen",gender:"",plural:"—", ex5:[{t:1,s:"Er entgegnete meinem Argument mit starken Beweisen."},{t:2,s:"Sie entgegnete seiner Behauptung, indem sie die Fakten nannte."},{t:3,s:"Der Anwalt entgegnete jedem Punkt, den der Zeuge machte."},{t:4,s:"Er hat auf den Vorwurf sofort entgegnet."},{t:5,s:"Sie entgegnete ruhig auf seine Kritik."}]},
