  "counterparts": {label:"Gegenüber",gender:"das",plural:"Gegenüber", ex5:[{t:1,s:"Der Minister traf sich mit seinen Gegenübern aus anderen Ländern."},{t:2,s:"Die männlichen Studenten schnitten besser ab als ihre weiblichen Gegenüber."},{t:3,s:"Unsere Firma arbeitet eng mit ihren internationalen Gegenübern zusammen."},{t:4,s:"Die Verhandlungspartner trafen ihre jeweiligen Gegenüber."},{t:5,s:"Wir tauschten uns mit unseren Gegenübern aus der Industrie aus."}]},
  "counterpoint": {label:"Kontrapunkt",gender:"der",plural:"Kontrapunkte", ex5:[{t:1,s:"Ihr Optimismus diente als Kontrapunkt zu seinem Zynismus."},{t:2,s:"Der Regisseur nutzte Farbe als Kontrapunkt zum dunklen Thema."},{t:3,s:"In der Musik beinhaltet der Kontrapunkt die Kombination unabhängiger Melodielinien."},{t:4,s:"Das Gebäude bildet einen architektonischen Kontrapunkt zur Altstadt."},{t:5,s:"Seine ruhige Art war ein Kontrapunkt zur hektischen Umgebung."}]},
