  "covington": {label:"Covington",gender:"",plural:"—", ex5:[{t:1,s:"Mein Cousin lebt in einer ruhigen Stadt namens Covington."},{t:2,s:"Covington liegt im Bundesstaat Kentucky."},{t:3,s:"Wir fuhren durch Covington auf unserem Weg in die Berge."},{t:4,s:"Covington ist eine charmante Kleinstadt."},{t:5,s:"Ich habe gehört, Covington hat eine interessante Geschichte."}]},
  "cow": {label:"Kuh",gender:"die",plural:"Kühe", ex5:[{t:1,s:"Die Kuh hat laut gemuht."},{t:2,s:"Die Kuh auf der Weide ist sehr sanft."},{t:3,s:"Wir haben die Kuh heute Morgen gemolken."},{t:4,s:"Auf dem Bauernhof stehen viele Kühe."},{t:5,s:"Die Kuh frisst frisches Gras."}]},
  "cowan": {label:"Cowan",gender:"",plural:"—", ex5:[{t:1,s:"Herr Cowan ist unser neuer Geschichtslehrer."},{t:2,s:"Ich habe Sarah Cowan gestern in der Bibliothek getroffen."},{t:3,s:"Bitte rufen Sie Frau Cowan an, um das Treffen zu bestätigen."},{t:4,s:"Der Name Cowan ist in Irland und Schottland verbreitet."},{t:5,s:"Ich kenne Herrn Cowan von der Arbeit."}]},
  "coward": {label:"Feigling",gender:"der",plural:"Feiglinge", ex5:[{t:1,s:"Der Feigling ist sofort davongelaufen."},{t:2,s:"Ein Feigling hat immer Angst vor der Wahrheit."},{t:3,s:"Wir haben uns dem Feigling gestellt."},{t:4,s:"Niemand mag einen Feigling."},{t:5,s:"Er hat sich wie ein Feigling verhalten."}]},
  "cowardice": {label:"Feigheit",gender:"die",plural:"Feigheiten", ex5:[{t:1,s:"Seine Feigheit hielt ihn davon ab, seine Meinung zu sagen."},{t:2,s:"Der General warf den Soldaten Feigheit vor."},{t:3,s:"Wahrer Mut ist nicht die Abwesenheit von Angst, sondern der Sieg über die Feigheit."},{t:4,s:"Man sollte sich nicht von seiner Feigheit leiten lassen."},{t:5,s:"Es war reine Feigheit, dass er nicht zur Wahrheit stand."}]},
  "cowardly": {label:"feige",gender:"",plural:"—", ex5:[{t:1,s:"Es war feige von ihm, vor dem Problem wegzulaufen."},{t:2,s:"Sei nicht so feige und sag einfach die Wahrheit."},{t:3,s:"Sein feiges Verhalten hat alle seine Freunde enttäuscht."},{t:4,s:"Es ist feige, anderen die Schuld zu geben."},{t:5,s:"Er wollte nicht feige erscheinen."}]},
  "cowards": {label:"Feigling",gender:"der",plural:"Feiglinge", ex5:[{t:1,s:"Nur Feiglinge laufen vor ihrer Verantwortung weg."},{t:2,s:"Er sagte ihnen, sie sollten keine Feiglinge sein und der Wahrheit ins Auge sehen."},{t:3,s:"Die Geschichte erinnert sich nicht an die Namen der Feiglinge."},{t:4,s:"Sei kein Feigling und sag, was du denkst."},{t:5,s:"Die Feiglinge versteckten sich, als es ernst wurde."}]},
  "cowboy": {label:"Cowboy",gender:"der",plural:"Cowboys", ex5:[{t:1,s:"Der Cowboy ritt auf seinem Pferd über das Feld."},{t:2,s:"Er trug einen Hut wie ein echter Cowboy."},{t:3,s:"Der junge Junge träumt davon, ein Cowboy zu werden."},{t:4,s:"Der Cowboy passte auf seine Herde auf."},{t:5,s:"Das Leben als Cowboy ist nicht immer einfach."}]},
