  "coworkers": {label:"Kollegen",gender:"die",plural:"Kollegen", ex5:[{t:1,s:"Ich esse freitags oft mit meinen Kollegen zu Mittag."},{t:2,s:"Meine Kollegen unterstützen mich bei meinem neuen Projekt."},{t:3,s:"Wir haben alle unsere Kollegen zur Büroparty eingeladen."},{t:4,s:"Die Kollegen haben heute viel zu tun."},{t:5,s:"Ich verstehe mich sehr gut mit meinen Kollegen."}]},
  "cows": {label:"Kühe",gender:"die",plural:"Kühe", ex5:[{t:1,s:"Die Kühe grasten friedlich auf der grünen Wiese."},{t:2,s:"Viele Kühe liefern die Milch für unsere Molkereiprodukte."},{t:3,s:"Wir haben bei unserem Besuch eine große Herde Kühe auf dem Bauernhof gesehen."},{t:4,s:"Die Kühe stehen den ganzen Tag draußen auf der Weide."},{t:5,s:"Auf dem Bauernhof gibt es viele glückliche Kühe."}]},
