  "cruciate": {label:"Kreuzband",gender:"das",plural:"Kreuzbänder", ex5:[{t:1,s:"Der Athlet riss sich das vordere Kreuzband."},{t:2,s:"Das Kreuzband ist wichtig für die Kniestabilität."},{t:3,s:"Er brauchte eine OP am Kreuzband."},{t:4,s:"Ein Riss im Kreuzband ist sehr schmerzhaft."},{t:5,s:"Das Kreuzband muss nach der Verletzung heilen."}]},
  "crucible": {label:"Tiegel",gender:"der",plural:"Tiegel", ex5:[{t:1,s:"Das Metall wurde im glühenden Tiegel geschmolzen."},{t:2,s:"Der Krieg wurde zum Tiegel für ihren Mut."},{t:3,s:"Das Labor erhitzte die Probe im Keramiktiegel."},{t:4,s:"Er goss die Schmelze aus dem Tiegel."},{t:5,s:"Ein Tiegel ist ein wichtiges Werkzeug in der Chemie."}]},
