  "crucify": {label:"kreuzigen",gender:"",plural:"—", ex5:[{t:1,s:"Die Geschichtsbücher beschreiben, wie man früher Kriminelle kreuzigte."},{t:2,s:"Er hatte das Gefühl, als wollten die Medien seinen Ruf kreuzigen."},{t:3,s:"Du musst dich nicht wegen eines kleinen Fehlers selbst kreuzigen."},{t:4,s:"Der Tyrann befahl, die Rebellen zu kreuzigen."},{t:5,s:"Sie kreuzigen die Gefangenen zur Abschreckung."}]},
  "crud": {label:"Dreck",gender:"der",plural:"—", ex5:[{t:1,s:"Am Boden der Pfanne klebt etwas schwarzer Dreck."},{t:2,s:"Du musst den Dreck von deiner Fahrradkette entfernen."},{t:3,s:"Das Waschbecken war mit Haaren und anderem Dreck verstopft."},{t:4,s:"An dieser alten Maschine klebt hartnäckiger Dreck."},{t:5,s:"Wische den Dreck bitte mit einem Tuch weg."}]},
