  "cruel": {label:"grausam",gender:"",plural:"—", ex5:[{t:1,s:"Die Tat war grausam."},{t:2,s:"Der Winter ist grausam."},{t:3,s:"Wir haben die grausame Tat gestoppt."},{t:4,s:"Grausame Behandlung von Tieren darf nicht sein."},{t:5,s:"Er war einem grausamen Schicksal ausgeliefert."}]},
