  "crumble": {label:"zerbröckeln",gender:"",plural:"—", ex5:[{t:1,s:"Die alten Mauern beginnen zu zerbröckeln."},{t:2,s:"Der Keks fängt an zu zerbröckeln."},{t:3,s:"Wir sahen zu, wie alles zu zerbröckeln begann."},{t:4,s:"Der trockene Boden wird bald zerbröckeln."},{t:5,s:"Lass den Teig nicht zerbröckeln."}]},
