  "crumbling": {label:"bröckelig",gender:"",plural:"—", ex5:[{t:1,s:"Die alte Mauer ist aufgrund des starken Regens bröckelig."},{t:2,s:"Ich sah die bröckeligen Ruinen der alten Burg."},{t:3,s:"Sein Vertrauen war nach der Prüfung völlig bröckelig."},{t:4,s:"Wir sahen uns das bröckelige Mauerwerk an."},{t:5,s:"Der bröckelige Stein fällt einfach ab."}]},
  "crumbs": {label:"Krümel",gender:"der",plural:"Krümel", ex5:[{t:1,s:"Bitte wische die Krümel vom Tisch."},{t:2,s:"Die Vögel fraßen schnell die Krümel auf dem Boden."},{t:3,s:"Ich fand überall auf meiner Tastatur Keks-Krümel."},{t:4,s:"Es liegen noch Krümel auf dem Sofa."},{t:5,s:"Schüttle die Krümel aus der Tischdecke."}]},
  "crummy": {label:"mies",gender:"",plural:"—", ex5:[{t:1,s:"Ich hatte einen miesen Tag bei der Arbeit, weil alles schiefging."},{t:2,s:"Wir wohnten in einem miesen Hotel mit kaputten Fenstern und ohne Heizung."},{t:3,s:"Ich fühle mich mies, weil ich den Geburtstag meines besten Freundes vergessen habe."},{t:4,s:"Das ist wirklich ein mieses Wetter heute."},{t:5,s:"Er hat eine miese Laune."}]},
  "crumpled": {label:"zerknittert",gender:"",plural:"—", ex5:[{t:1,s:"Er hat das Papier in der Hand zerknittert."},{t:2,s:"Ihr Kleid war nach der langen Reise völlig zerknittert."},{t:3,s:"Ich fand einen zerknitterten Zettel in meiner Tasche."},{t:4,s:"Das Hemd ist ganz zerknittert."},{t:5,s:"Sie hat den Brief zerknittert und weggeworfen."}]},
