  "crusaders": {label:"Kreuzritter",gender:"die",plural:"Kreuzritter", ex5:[{t:1,s:"Die ökologischen Kreuzritter säubern heute den Strand."},{t:2,s:"Sie ist bekannt als eine der Kreuzritter für Tierrechte."},{t:3,s:"Viele Kreuzritter nahmen an der Demonstration im Stadtzentrum teil."},{t:4,s:"Diese Kreuzritter setzen sich für den Frieden ein."},{t:5,s:"Die Kreuzritter organisierten ein großes Treffen."}]},
  "crusades": {label:"Kreuzzüge",gender:"die",plural:"Kreuzzüge", ex5:[{t:1,s:"Die Kreuzzüge hatten einen bedeutenden Einfluss auf das Mittelalter."},{t:2,s:"Historiker diskutieren oft über die langfristigen Folgen der Kreuzzüge."},{t:3,s:"Wir haben heute im Geschichtsunterricht über die Kreuzzüge gesprochen."},{t:4,s:"Die Epoche der Kreuzzüge war sehr turbulent."},{t:5,s:"Es gibt viele Bücher über die Geschichte der Kreuzzüge."}]},
  "crusading": {label:"kämpferisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist eine kämpferische Journalistin, die Korruption aufdeckt."},{t:2,s:"Er verbrachte sein Leben damit, sich kämpferisch für die Rechte der Armen einzusetzen."},{t:3,s:"Der kämpferische Geist der Schüler führte zu einer Änderung der Schulpolitik."},{t:4,s:"Sie vertrat eine sehr kämpferische Haltung in der Debatte."},{t:5,s:"Mit kämpferischem Engagement kämpfte er für seine Ideale."}]},
  "crush": {label:"zerquetschen",gender:"",plural:"—", ex5:[{t:1,s:"Maschinen zerquetschen die Steine."},{t:2,s:"Die Presse zerquetscht die Dosen."},{t:3,s:"Wir zerquetschen den Knoblauch für die Soße."},{t:4,s:"Er kann die Dose mit der Hand zerquetschen."},{t:5,s:"Pass auf, dass du die Beeren nicht zerquetschst."}]},
  "crushed": {label:"zerquetscht",gender:"",plural:"—", ex5:[{t:1,s:"Er hat die leere Dose versehentlich mit dem Fuß zerquetscht."},{t:2,s:"Die Blume wurde unter dem schweren Buch zerquetscht."},{t:3,s:"Sie hat den Knoblauch für das Rezept zerquetscht."},{t:4,s:"Die zerquetschte Dose liegt im Müll."},{t:5,s:"Die Erdbeeren waren in der Tasche völlig zerquetscht."}]},
  "crusher": {label:"Zerkleinerer",gender:"der",plural:"Zerkleinerer", ex5:[{t:1,s:"Der Gesteinszerkleinerer ist gestern ausgefallen."},{t:2,s:"Er arbeitet als Bediener eines Autozerkleinerers."},{t:3,s:"Wir brauchen einen leistungsstarken Zerkleinerer für das Recycling."},{t:4,s:"Der Zerkleinerer ist sehr laut."},{t:5,s:"Dieser elektrische Zerkleinerer ist sehr praktisch in der Küche."}]},
