  "crustacean": {label:"Krustentier",gender:"das",plural:"Krustentiere", ex5:[{t:1,s:"Hummer und Krabben gehören zu den Krustentieren."},{t:2,s:"Das Restaurant bietet eine Auswahl an frischen Krustentieren an."},{t:3,s:"Er ist allergisch gegen jede Art von Krustentier."},{t:4,s:"Krustentiere leben meistens im Wasser."},{t:5,s:"Auf der Speisekarte stehen heute Krustentiere."}]},
  "crusted": {label:"verkrustet",gender:"",plural:"—", ex5:[{t:1,s:"Das Brot war mit Zucker und Zimt verkrustet."},{t:2,s:"Seine Stiefel waren mit getrocknetem Schlamm verkrustet."},{t:3,s:"Die Wunde war nach ein paar Tagen verkrustet."},{t:4,s:"Der Boden war mit einer dicken Eisschicht verkrustet."},{t:5,s:"Das alte Geschirr war mit Essensresten verkrustet."}]},
  "crusty": {label:"krustig",gender:"",plural:"—", ex5:[{t:1,s:"Ich liebe die krustige Kruste von frisch gebackenem Brot."},{t:2,s:"Das alte Brot war hart und krustig."},{t:3,s:"Er wirkt nach außen hin krustig, hat aber ein weiches Herz."},{t:4,s:"Die Oberfläche des Kuchens ist schön krustig gebacken."},{t:5,s:"Das Fleisch bekommt eine krustige Schicht beim Braten."}]},
  "crutch": {label:"Krücke",gender:"die",plural:"Krücken", ex5:[{t:1,s:"Er ging nach dem Sturz an einer Krücke."},{t:2,s:"Sie stützte sich auf eine einzelne Krücke."},{t:3,s:"Die Krücke half ihm, sich fortzubewegen."},{t:4,s:"Er braucht eine Krücke, um das Bein zu entlasten."},{t:5,s:"Ohne seine Krücke kommt er nicht weit."}]},
  "crutches": {label:"Krücken",gender:"die",plural:"Krücken", ex5:[{t:1,s:"Er muss nach seiner Beinverletzung Krücken benutzen."},{t:2,s:"Das Gehen mit Krücken ist anfangs sehr anstrengend."},{t:3,s:"Sie stützte sich auf ihre Krücken, um aufzustehen."},{t:4,s:"Mit den Krücken kommt er die Treppe nur langsam hoch."},{t:5,s:"Er hat die Krücken endlich in die Ecke gestellt."}]},
  "crux": {label:"Kernpunkt",gender:"der",plural:"Kernpunkte", ex5:[{t:1,s:"Das ist der Kernpunkt der Angelegenheit."},{t:2,s:"Der Kernpunkt seines Plans waren die Kosten."},{t:3,s:"Wir sind endlich zum Kernpunkt gelangt."},{t:4,s:"Das ist der Kernpunkt, den wir diskutieren müssen."},{t:5,s:"Der Kernpunkt liegt in der Qualität der Arbeit."}]},
  "cry": {label:"weinen",gender:"",plural:"—", ex5:[{t:1,s:"Babys weinen oft."},{t:2,s:"Das Kind weint gerade."},{t:3,s:"Wir weinen bei diesem Film immer."},{t:4,s:"Hör auf zu weinen, alles wird gut."},{t:5,s:"Sie musste vor Freude weinen."}]},
  "crybaby": {label:"Heulsuse",gender:"die",plural:"Heulsusen", ex5:[{t:1,s:"Sei wegen eines kleinen Fehlers keine Heulsuse."},{t:2,s:"Er wurde von seinen Mitschülern Heulsuse genannt, als er anfing zu schluchzen."},{t:3,s:"Benimm dich nicht wie eine Heulsuse, wenn es nicht nach deinem Kopf geht."},{t:4,s:"Hör auf, so eine Heulsuse zu sein."},{t:5,s:"Er ist eine echte Heulsuse bei jedem kleinen Problem."}]},
  "crying": {label:"weinen",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby hat plötzlich angefangen zu weinen."},{t:2,s:"Warum weinst du in der Ecke?"},{t:3,s:"Ich habe jemanden auf dem Flur weinen hören."},{t:4,s:"Sie ist traurig und muss weinen."},{t:5,s:"Das weinende Kind braucht Hilfe."}]},
