  "darkened": {label:"verdunkelt",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel hatte sich verdunkelt, bevor der Sturm ankam."},{t:2,s:"Er hat das Zimmer verdunkelt, um einen Film zu schauen."},{t:3,s:"Die Wolken haben den hellen Nachmittag verdunkelt."},{t:4,s:"Das Zimmer wirkte verdunkelt durch die geschlossenen Rollläden."},{t:5,s:"Durch den Regen hat sich der Tag verdunkelt."}]},
  "darkening": {label:"Verdunkelung",gender:"die",plural:"Verdunkelungen", ex5:[{t:1,s:"Der sich verdunkelnde Himmel deutete darauf hin, dass bald ein Sturm kommt."},{t:2,s:"Er bemerkte die Verdunkelung des Raumes, als die Sonne unterging."},{t:3,s:"Die sich verdunkelnden Wolken beunruhigten die Bauern während der Ernte."},{t:4,s:"Die Verdunkelung am Abend geschah sehr schnell."},{t:5,s:"Wegen der Verdunkelung konnten wir den Weg kaum sehen."}]},
  "darker": {label:"dunkler",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel wird dunkler, während sich der Sturm nähert."},{t:2,s:"Ich bevorzuge die dunklere blaue Farbe für mein Schlafzimmer."},{t:3,s:"Der Raum fühlte sich viel dunkler an, ohne dass die Lampen an waren."},{t:4,s:"Es wird draußen immer dunkler."},{t:5,s:"Diese Ecke ist viel dunkler als der Rest des Zimmers."}]},
  "darkest": {label:"dunkelste",gender:"",plural:"—", ex5:[{t:1,s:"Das ist das dunkelste Zimmer im Haus."},{t:2,s:"Die dunkelste Stunde ist kurz vor der Morgendämmerung."},{t:3,s:"Er trug seinen dunkelsten Anzug zur Beerdigung."},{t:4,s:"Das ist das dunkelste Geheimnis der Familie."},{t:5,s:"Der dunkelste Ort ist oft direkt unter der Lampe."}]},
  "darkly": {label:"düster",gender:"",plural:"—", ex5:[{t:1,s:"Der Raum war nur düster von einer Kerze beleuchtet."},{t:2,s:"Er sah mich nach dem Streit düster an."},{t:3,s:"Der Himmel war vor dem Sturm düster bewölkt."},{t:4,s:"Er blickte düster in die Zukunft."},{t:5,s:"Das Zimmer wirkte durch die Schatten sehr düster."}]},
