  "delirium": {label:"das Delirium",gender:"das",plural:"die Delirien", ex5:[{t:1,s:"Der Patient litt unter hohem Fieber und einem Delirium."},{t:2,s:"Er schrie in einem Zustand des Deliriums."},{t:3,s:"Der Arzt prüfte, ob er sich noch im Delirium befand."},{t:4,s:"Das Delirium ist ein ernsthafter medizinischer Zustand."},{t:5,s:"Er erwachte langsam aus seinem Delirium."}]},
  "delisted": {label:"degradiert",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen wurde gestern von der Börse degradiert."},{t:2,s:"Viele Produkte wurden degradiert, weil sie Sicherheitsstandards nicht erfüllten."},{t:3,s:"Die Aktie wurde nach der Insolvenz der Firma degradiert."},{t:4,s:"Viele Anleger verloren Geld, nachdem das Unternehmen degradiert wurde."},{t:5,s:"Die Entscheidung zur Streichung wurde als degradiert gemeldet."}]},
