  "demands": {label:"verlangen",gender:"",plural:"—", ex5:[{t:1,s:"Der Chef verlangt Respekt von jedem."},{t:2,s:"Dieser Job verlangt viel Geduld."},{t:3,s:"Die Gewerkschaft verlangt dieses Jahr höhere Löhne."},{t:4,s:"Die Situation verlangt eine schnelle Entscheidung."},{t:5,s:"Der Lehrer verlangt Aufmerksamkeit von den Schülern."}]},
  "demarcate": {label:"abgrenzen",gender:"",plural:"—", ex5:[{t:1,s:"Ein Zaun grenzt die beiden Felder voneinander ab."},{t:2,s:"Sie haben die neue Grenze abgegrenzt."},{t:3,s:"Linien grenzen jeden Parkplatz ab."},{t:4,s:"Der Fluss grenzt das Gebiet deutlich ab."},{t:5,s:"Das Komitee hat die Zuständigkeiten klar abgegrenzt."}]},
  "demarcation": {label:"Abgrenzung",gender:"die",plural:"Abgrenzungen", ex5:[{t:1,s:"Es gibt eine klare Abgrenzung zwischen den beiden Zonen."},{t:2,s:"Der Vertrag legte die Abgrenzung der Grenze fest."},{t:3,s:"Die Abgrenzung der Aufgaben war nicht eindeutig."},{t:4,s:"Eine scharfe Abgrenzung ist hier notwendig."},{t:5,s:"Er achtet stets auf die Abgrenzung von Beruf und Privatleben."}]},
