  "dion": {label:"Dion",gender:"",plural:"—", ex5:[{t:1,s:"Dion ist ein sehr talentierter Sänger in unserer Schulband."},{t:2,s:"Ich bin gestern in den Park gegangen, um Dion zu treffen."},{t:3,s:"Dion sagte mir, dass er zu spät zum Abendessen kommen würde."},{t:4,s:"Dion hat ein Stipendium für seine musikalischen Fähigkeiten bekommen."},{t:5,s:"Wir haben Dion zum Grillen am Wochenende eingeladen."}]},
  "dionysus": {label:"Dionysos",gender:"der",plural:"—", ex5:[{t:1,s:"Dionysos ist der griechische Gott des Weines."},{t:2,s:"Viele antike Stücke wurden zu Ehren von Dionysos aufgeführt."},{t:3,s:"Die Statue von Dionysos steht in der Mitte des Museums."},{t:4,s:"Er liest viel über den Gott Dionysos."},{t:5,s:"Dionysos wird oft mit Wein und Festen assoziiert."}]},
