  "disco": {label:"Disco",gender:"die",plural:"Discos", ex5:[{t:1,s:"Wir haben die ganze Nacht in der Disco getanzt."},{t:2,s:"Sie liebt es, glitzernde Kleidung in der Disco zu tragen."},{t:3,s:"Die Musik in der Disco war unglaublich laut."},{t:4,s:"Wir gehen am Wochenende in die Disco."},{t:5,s:"Die Disco war gestern Abend sehr voll."}]},
  "discography": {label:"Diskografie",gender:"die",plural:"Diskografien", ex5:[{t:1,s:"Ich habe nach der vollständigen Diskografie der Band gesucht."},{t:2,s:"Ihre Diskografie umfasst mehrere Platin-Alben."},{t:3,s:"Die Website listet die gesamte Diskografie des Künstlers auf."},{t:4,s:"Seine Diskografie ist sehr beeindruckend."},{t:5,s:"Ich habe mir seine Diskografie angesehen."}]},
  "discolor": {label:"verfärben",gender:"",plural:"—", ex5:[{t:1,s:"Das starke Sonnenlicht begann, die alten Vorhänge zu verfärben."},{t:2,s:"Lassen Sie den Holztisch nicht draußen stehen, da Regen ihn verfärben wird."},{t:3,s:"Chemikalien im Pool können Ihr Haar verfärben."},{t:4,s:"Die Sonne kann die Farbe der Möbel verfärben."},{t:5,s:"Feuchtigkeit wird das Papier verfärben."}]},
