  "disconnection": {label:"die Trennung",gender:"die",plural:"Trennungen", ex5:[{t:1,s:"Eine plötzliche Trennung ließ den Videoanruf abrupt enden."},{t:2,s:"Es gibt eine Trennung zwischen dem, was er sagt und was er tut."},{t:3,s:"Die Trennung der Stromversorgung war für Reparaturen notwendig."},{t:4,s:"Die Trennung der Leitung verursachte Probleme."},{t:5,s:"Man spürt die Trennung zwischen den beiden Gruppen."}]},
  "disconnects": {label:"trennt",gender:"",plural:"—", ex5:[{t:1,s:"Die App trennt automatisch, wenn das Internet schwach ist."},{t:2,s:"Er trennt den Strom, bevor er das Gerät repariert."},{t:3,s:"Manchmal trennt er sich von der Welt, um sich zu entspannen."},{t:4,s:"Das System trennt die Verbindung nach einer Stunde."},{t:5,s:"Er trennt das Kabel, wenn er fertig ist."}]},
