  "dogging": {label:"verfolgen",gender:"",plural:"—", ex5:[{t:1,s:"Er verbrachte den ganzen Nachmittag damit, den Spuren seines Freundes zu verfolgen."},{t:2,s:"Die Reporter waren dabei, den Schauspieler zu verfolgen, um eine Story zu bekommen."},{t:3,s:"Hartnäckige Gerüchte verfolgen den Politiker seit Jahren."},{t:4,s:"Der kleine Hund begann, die Katze durch den Garten zu verfolgen."},{t:5,s:"Die Polizei verfolgt die Spur des Diebes."}]},
  "doggy": {label:"Hündchen",gender:"das",plural:"Hündchen", ex5:[{t:1,s:"Der kleine Junge spielte mit seinem süßen Hündchen im Garten."},{t:2,s:"Schau mal, wie das Hündchen im Park mit dem Schwanz wedelt!"},{t:3,s:"Sie hat ein weiches Bett für ihr Hündchen gekauft."},{t:4,s:"Das Hündchen freut sich, wenn wir nach Hause kommen."},{t:5,s:"Wir gehen jeden Tag mit dem Hündchen spazieren."}]},
  "doghouse": {label:"Hundehütte",gender:"die",plural:"Hundehütten", ex5:[{t:1,s:"Der Hund schlief friedlich in seiner hölzernen Hundehütte draußen."},{t:2,s:"Er hat vor dem Winter eine neue Hundehütte für seinen Welpen gebaut."},{t:3,s:"Der streunende Hund fand Schutz in einer kleinen Hundehütte."},{t:4,s:"Die Hundehütte steht geschützt unter dem großen Baum."},{t:5,s:"Wir haben die Hundehütte im Frühling gestrichen."}]},
  "dogma": {label:"Dogma",gender:"das",plural:"Dogmen", ex5:[{t:1,s:"Er weigerte sich, dem alten religiösen Dogma zu folgen."},{t:2,s:"Wissenschaft basiert auf Beweisen, nicht auf Dogmen."},{t:3,s:"Sie hinterfragten das politische Dogma der Partei."},{t:4,s:"Man sollte sich nicht von einem starren Dogma einschränken lassen."},{t:5,s:"Dieses Dogma hat in der modernen Gesellschaft keinen Platz mehr."}]},
  "dogmatic": {label:"dogmatisch",gender:"",plural:"—", ex5:[{t:1,s:"Er ist bei seinen Methoden sehr dogmatisch."},{t:2,s:"Ein dogmatischer Ton verschließt die Herzen der Menschen."},{t:3,s:"Sie wies seine dogmatische Sichtweise zurück."},{t:4,s:"In einer offenen Diskussion ist ein dogmatisches Verhalten fehl am Platz."},{t:5,s:"Wir sollten weniger dogmatisch an diese Aufgabe herangehen."}]},
  "dogmatism": {label:"Dogmatismus",gender:"der",plural:"—", ex5:[{t:1,s:"Sein Dogmatismus hindert ihn daran, andere Meinungen zu hören."},{t:2,s:"Wissenschaft ist das Gegenteil von Dogmatismus, da sie offen für Veränderungen ist."},{t:3,s:"Wir müssen bei der Lösung komplexer sozialer Probleme Dogmatismus vermeiden."},{t:4,s:"Der Dogmatismus verhindert oft einen konstruktiven Dialog."},{t:5,s:"Sie kämpfte gegen den Dogmatismus in ihrer Organisation."}]},
  "dogs": {label:"Hunde",gender:"die",plural:"Hunde", ex5:[{t:1,s:"Ich liebe es, mit Hunden im Park zu spielen."},{t:2,s:"Manche Hunde werden ausgebildet, um Menschen zu helfen."},{t:3,s:"Mein Nachbar hat zwei große Hunde."},{t:4,s:"Hunde sind treue Begleiter des Menschen."},{t:5,s:"In diesem Park müssen Hunde an der Leine geführt werden."}]},
  "dogwood": {label:"Hartriegel",gender:"der",plural:"Hartriegel", ex5:[{t:1,s:"Die Hartriegel blühen wunderschön im Garten."},{t:2,s:"Sie hat einen weißen Hartriegel in ihrem Hinterhof gepflanzt."},{t:3,s:"Die Blüten des Hartriegels sehen im Frühling bezaubernd aus."},{t:4,s:"Der Hartriegel ist ein beliebter Zierstrauch."},{t:5,s:"Im Herbst bekommt der Hartriegel eine tolle Farbe."}]},
