  "dojo": {label:"Dojo",gender:"das",plural:"Dojos", ex5:[{t:1,s:"Er geht jeden Morgen ins Dojo, um Karate zu üben."},{t:2,s:"Das Dojo ist ein Ort für Disziplin und Respekt."},{t:3,s:"Sie hat gerade im örtlichen Dojo ihren schwarzen Gürtel erreicht."},{t:4,s:"Wir treffen uns morgen im Dojo."},{t:5,s:"Das Training im Dojo beginnt pünktlich."}]},
