  "dolby": {label:"Dolby",gender:"das",plural:"—", ex5:[{t:1,s:"Dieses Kino nutzt Dolby-Soundtechnologie."},{t:2,s:"Die Audioqualität ist dank Dolby ausgezeichnet."},{t:3,s:"Man kann den Unterschied mit Dolby-Surround-Sound hören."},{t:4,s:"Dolby sorgt für ein tolles Klangerlebnis."},{t:5,s:"Wir haben das Dolby-System installiert."}]},
  "dolce": {label:"Dolce",gender:"das",plural:"Dolces", ex5:[{t:1,s:"Wir genossen ein süßes Dolce nach unserem köstlichen Abendessen."},{t:2,s:"Die Musik spielte in einem langsamen und dolce Tempo."},{t:3,s:"Sie liebt das Dolce Vita, während sie in Italien lebt."},{t:4,s:"Ein kleines Dolce zum Kaffee ist perfekt."},{t:5,s:"Das Dolce war sehr lecker."}]},
