  "double": {label:"verdoppeln",gender:"",plural:"—", ex5:[{t:1,s:"Der Umsatz kann sich jedes Jahr verdoppeln."},{t:2,s:"Das Zimmer ist ein Doppelzimmer."},{t:3,s:"Wir verdoppeln die Bestellung für die Party."},{t:4,s:"Man sollte die Anstrengungen verdoppeln."},{t:5,s:"Das Risiko kann sich schnell verdoppeln."}]},
  "doubled": {label:"verdoppelt",gender:"",plural:"—", ex5:[{t:1,s:"Der Gewinn der Firma hat sich letztes Jahr verdoppelt."},{t:2,s:"Ich habe die Menge des Zuckers im Rezept verdoppelt."},{t:3,s:"Er hat seine Anstrengungen verdoppelt, um die Prüfung zu bestehen."},{t:4,s:"Die Anzahl der Teilnehmer hat sich verdoppelt."},{t:5,s:"Sie hat ihre Geschwindigkeit verdoppelt."}]},
  "doubleday": {label:"Doubleday",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe einen neuen Roman gekauft, der bei Doubleday erschienen ist."},{t:2,s:"Doubleday ist ein bekannter Name in der Verlagsbranche."},{t:3,s:"Der Autor hat letztes Jahr einen Vertrag bei Doubleday unterschrieben."},{t:4,s:"Viele bekannte Autoren veröffentlichen ihre Bücher bei Doubleday."},{t:5,s:"Doubleday hat dieses Buch sehr erfolgreich vermarktet."}]},
  "doubleheader": {label:"Doubleheader",gender:"der",plural:"Doubleheader", ex5:[{t:1,s:"Wir gehen heute für den Baseball-Doubleheader ins Stadion."},{t:2,s:"Das Team hat beide Spiele des Doubleheaders gewonnen."},{t:3,s:"Ein Doubleheader kann ein sehr langer Tag für die Spieler sein."},{t:4,s:"Tickets für den Doubleheader sind oft schnell ausverkauft."},{t:5,s:"Der Doubleheader gestern war ein echtes Spektakel."}]},
  "doubles": {label:"dient auch als",gender:"",plural:"—", ex5:[{t:1,s:"Dieses Medikament dient auch als Schmerzmittel."},{t:2,s:"Er verdoppelt den Spaß, indem er seine Gitarre mitbringt."},{t:3,s:"Das Hotelzimmer dient auch als kleines Büro."},{t:4,s:"Das Sofa dient auch als Gästebett."},{t:5,s:"Dieser Tisch dient auch als Arbeitsplatz."}]},
  "doubling": {label:"Verdopplung",gender:"die",plural:"Verdopplungen", ex5:[{t:1,s:"Die Bevölkerung erlebt eine Verdopplung alle zehn Jahre."},{t:2,s:"Sie arbeitet an einer Verdopplung ihrer Anstrengungen für die Prüfung."},{t:3,s:"Das Unternehmen plant eine Verdopplung des Umsatzes in diesem Jahr."},{t:4,s:"Die Verdopplung der Produktion ist notwendig."},{t:5,s:"Er strebt eine Verdopplung seines Einkommens an."}]},
  "doubly": {label:"doppelt",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin doppelt so aufgeregt, weil wir das Spiel gewonnen haben."},{t:2,s:"Die Sicherheitsregeln müssen doppelt überprüft werden."},{t:3,s:"Sie fühlte sich doppelt verantwortlich für den Erfolg des Teams."},{t:4,s:"Das ist doppelt wichtig für unsere Sicherheit."},{t:5,s:"Er hat doppelt so viel gearbeitet wie sonst."}]},
  "doubt": {label:"Zweifel",gender:"der",plural:"Zweifel", ex5:[{t:1,s:"Der Zweifel kam leise auf."},{t:2,s:"Der Zweifel ist in dieser Situation völlig berechtigt."},{t:3,s:"Wir hatten keinerlei Zweifel an seiner Ehrlichkeit."},{t:4,s:"Ich hege keinen Zweifel an seinem Erfolg."},{t:5,s:"Jeder Zweifel sollte nun ausgeräumt sein."}]},
  "doubted": {label:"bezweifelte",gender:"",plural:"—", ex5:[{t:1,s:"Sie bezweifelte seine Fähigkeit, die Aufgabe zu beenden."},{t:2,s:"Ich bezweifelte, dass er die Wahrheit sagte."},{t:3,s:"Er bezweifelte seine eigenen Chancen auf den Sieg."},{t:4,s:"Wir bezweifelten seine Geschichte von Anfang an."},{t:5,s:"Sie bezweifelte, ob das der richtige Weg war."}]},
  "doubtful": {label:"zweifelhaft",gender:"",plural:"—", ex5:[{t:1,s:"Es ist zweifelhaft, ob er die Aufgabe rechtzeitig beenden kann."},{t:2,s:"Das Wetter sieht zweifelhaft für unser Picknick aus."},{t:3,s:"Es ist zweifelhaft, ob das Geschäft noch geöffnet hat."},{t:4,s:"Der Erfolg des Plans erscheint mir zweifelhaft."},{t:5,s:"Seine Absichten sind in dieser Sache zweifelhaft."}]},
  "doubting": {label:"zweifelnd",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin zweifelnd, ob dieser Plan wirklich funktioniert."},{t:2,s:"Hör auf, dich selbst zu zweifeln, und glaub an deine Fähigkeiten."},{t:3,s:"Sie war von Anfang an zweifelnd gegenüber seiner Geschichte."},{t:4,s:"Er blickte zweifelnd auf das Ergebnis."},{t:5,s:"Wir sind alle noch etwas zweifelnd bezüglich der Lösung."}]},
  "doubtless": {label:"zweifellos",gender:"",plural:"—", ex5:[{t:1,s:"Zweifellos wird er mit seiner harten Arbeit Erfolg haben."},{t:2,s:"Sie wird zweifellos verärgert sein, wenn sie die Nachrichten hört."},{t:3,s:"Zweifellos wird die neue Politik auf Widerstand stoßen."},{t:4,s:"Das ist zweifellos die beste Lösung für alle."},{t:5,s:"Er wird zweifellos pünktlich erscheinen."}]},
  "doubts": {label:"Zweifel",gender:"der",plural:"Zweifel", ex5:[{t:1,s:"Er hat immer noch Zweifel, ob es heute regnen wird."},{t:2,s:"Sie hat keine Zweifel an seiner Ehrlichkeit."},{t:3,s:"Der Lehrer hegt Zweifel, dass er die Hausaufgaben allein gemacht hat."},{t:4,s:"Es gibt noch einige Zweifel an diesem Vorschlag."},{t:5,s:"Meine Zweifel sind inzwischen völlig verschwunden."}]},
  "doug": {label:"Doug",gender:"",plural:"—", ex5:[{t:1,s:"Doug repariert gerade sein kaputtes Fahrrad."},{t:2,s:"Ich habe Doug zu unserem Abendessen eingeladen."},{t:3,s:"Doug kann sehr gut Gitarre spielen."},{t:4,s:"Morgen gehe ich mit Doug ins Kino."},{t:5,s:"Doug ist ein sehr guter Freund von mir."}]},
  "dough": {label:"Teig",gender:"der",plural:"Teige", ex5:[{t:1,s:"Der Teig ist gut aufgegangen."},{t:2,s:"Der Teig fühlt sich sehr weich an."},{t:3,s:"Wir haben den Teig gründlich geknetet."},{t:4,s:"Ich rolle den Teig für den Kuchen aus."},{t:5,s:"Der Teig muss noch eine Weile ruhen."}]},
  "doughnut": {label:"Donut",gender:"der",plural:"Donuts", ex5:[{t:1,s:"Ich habe mir einen frischen Donut zum Frühstück gekauft."},{t:2,s:"Möchtest du einen Donut mit Schokoladenglasur?"},{t:3,s:"Das kleine Mädchen genoss jeden Bissen von ihrem süßen Donut."},{t:4,s:"Ich esse am Nachmittag gerne einen Donut."},{t:5,s:"Dieser Donut schmeckt wirklich ausgezeichnet."}]},
