  "drafted": {label:"entworfen",gender:"",plural:"—", ex5:[{t:1,s:"Er hat einen Brief an den Direktor entworfen."},{t:2,s:"Der Anwalt hat den Vertrag für die Firma entworfen."},{t:3,s:"Sie hat einen Plan zum Sparen entworfen."},{t:4,s:"Wir haben den Text gemeinsam entworfen."},{t:5,s:"Er hat ein neues Design für das Logo entworfen."}]},
  "drafting": {label:"Entwerfen",gender:"das",plural:"—", ex5:[{t:1,s:"Sie ist mit dem Entwerfen eines neuen Vorschlags für das Projekt beschäftigt."},{t:2,s:"Das Entwerfen des Vertrags nahm den Großteil des Vormittags in Anspruch."},{t:3,s:"Er ist sehr geschickt im Entwerfen von architektonischen Plänen."},{t:4,s:"Das Entwerfen eines Konzepts erfordert viel Zeit."},{t:5,s:"Wir begannen heute mit dem Entwerfen des neuen Designs."}]},
  "drafts": {label:"Entwürfe",gender:"die",plural:"Entwürfe", ex5:[{t:1,s:"Er schrieb mehrere Entwürfe, bevor er den Aufsatz fertigstellte."},{t:2,s:"Bitte speichern Sie Ihre Entwürfe in dem Ordner."},{t:3,s:"Ich habe die Entwürfe des Vertrags durchgesehen."},{t:4,s:"Es gibt noch einige Entwürfe für diesen Bericht."},{t:5,s:"Die Entwürfe liegen auf dem Schreibtisch."}]},
