  "drag": {label:"ziehen",gender:"",plural:"—", ex5:[{t:1,s:"Die Arbeiter ziehen die Kisten."},{t:2,s:"Die Maus zieht es über den Bildschirm."},{t:3,s:"Wir ziehen den schweren Karton zur Seite."},{t:4,s:"Könntest du bitte den Tisch ein Stück ziehen?"},{t:5,s:"Sie ziehen den Wagen hinter sich her."}]},
  "dragged": {label:"zog",gender:"",plural:"—", ex5:[{t:1,s:"Er zog den schweren Kasten über den Boden."},{t:2,s:"Der Hund zog an seiner Leine, weil er spielen wollte."},{t:3,s:"Sie fühlte sich durch die vielen schlechten Nachrichten heruntergezogen."},{t:4,s:"Er zog die schwere Tasche hinter sich her."},{t:5,s:"Wir haben den Tisch in den anderen Raum gezogen."}]},
  "dragging": {label:"ziehend",gender:"",plural:"—", ex5:[{t:1,s:"Der schwere Karton war über den Boden ziehend zu hören."},{t:2,s:"Er läuft ziehend mit den Füßen, weil er müde ist."},{t:3,s:"Hör auf, deinen Stuhl ziehend über den Boden zu bewegen, das macht Lärm."},{t:4,s:"Sie kommt ziehend mit ihrem Koffer an."},{t:5,s:"Das ziehend auf dem Boden liegende Kabel ist gefährlich."}]},
  "dragon": {label:"Drache",gender:"der",plural:"Drachen", ex5:[{t:1,s:"Der Drache brüllte laut."},{t:2,s:"Der Drache ist sehr wild."},{t:3,s:"Wir haben einen Drachen gezeichnet."},{t:4,s:"In alten Geschichten bewacht der Drache einen Schatz."},{t:5,s:"Ein riesiger Drache flog über das Schloss."}]},
  "dragonflies": {label:"Libellen",gender:"die",plural:"Libellen", ex5:[{t:1,s:"Libellen sieht man im Sommer oft in der Nähe von Teichen."},{t:2,s:"Die Farben der Libellen waren leuchtend und wunderschön."},{t:3,s:"Libellen fressen viele kleine Insekten wie Mücken."},{t:4,s:"Über dem Wasser fliegen viele Libellen."},{t:5,s:"Die Libellen im Garten wirken sehr elegant."}]},
  "dragonfly": {label:"Libelle",gender:"die",plural:"Libellen", ex5:[{t:1,s:"Eine Libelle schwebte über dem Teich."},{t:2,s:"Die Libelle hat schimmernde, zarte Flügel."},{t:3,s:"Eine blaue Libelle landete auf dem Schilf."},{t:4,s:"Ich habe heute eine Libelle im Garten gesehen."},{t:5,s:"Die Libelle ist ein faszinierendes Insekt."}]},
  "dragons": {label:"Drachen",gender:"die",plural:"Drachen", ex5:[{t:1,s:"In der Legende kämpften Ritter gegen wilde Drachen."},{t:2,s:"Die Kinder lieben Geschichten über magische Drachen."},{t:3,s:"Das alte Grab wurde von steinernen Drachen bewacht."},{t:4,s:"Es gibt viele verschiedene Arten von Drachen in diesem Buch."},{t:5,s:"Die Drachen in den Filmen sehen sehr echt aus."}]},
  "dragoon": {label:"Dragoner",gender:"der",plural:"Dragoner", ex5:[{t:1,s:"Der Dragoner ritt auf seinem Pferd über das Schlachtfeld."},{t:2,s:"Historisch gesehen war ein Dragoner ein Soldat, der zu Pferd kämpfte."},{t:3,s:"Das Museum stellte die Uniform eines alten Dragoners aus."},{t:4,s:"Die Dragoner spielten eine wichtige Rolle in der Kavallerie."},{t:5,s:"Er las ein Buch über das Leben eines Dragoners."}]},
  "drags": {label:"schleppen",gender:"",plural:"—", ex5:[{t:1,s:"Er schleppt seinen schweren Koffer über den Boden des Flughafens."},{t:2,s:"Die lange Sitzung schleppt sich stundenlang ohne klares Ergebnis hin."},{t:3,s:"Sie schleppt ihre Füße, wenn sie nach einem langen Schultag müde ist."},{t:4,s:"Warum schleppst du diese alte Tasche immer noch mit dir herum?"},{t:5,s:"Der Hund schleppt seinen Knochen in den Garten."}]},
  "drain": {label:"abfließen",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser muss aus den Waschbecken abfließen."},{t:2,s:"Die Wanne ist am Abfließen."},{t:3,s:"Wir lassen das Wasser aus dem Pool abfließen."},{t:4,s:"Das Regenwasser kann hier nicht schnell genug abfließen."},{t:5,s:"Lass das Wasser bitte vollständig abfließen."}]},
