  "drains": {label:"Abflüsse",gender:"die",plural:"Abflüsse", ex5:[{t:1,s:"Die Abflüsse in der Küche sind durch Essensreste verstopft."},{t:2,s:"Starker Regen überflutet oft die Abflüsse der Straße."},{t:3,s:"Er reinigte die Abflüsse im Garten vor dem Sturm."},{t:4,s:"Die Abflüsse müssen regelmäßig gesäubert werden."},{t:5,s:"Das Wasser staut sich, weil die Abflüsse blockiert sind."}]},
  "dram": {label:"Schluck",gender:"der",plural:"Schlucke", ex5:[{t:1,s:"Er genoss einen kleinen Schluck Whisky vor dem Kamin."},{t:2,s:"Ein Schluck ist ein sehr kleines Maß für eine Flüssigkeit."},{t:3,s:"Sie goss einen Schluck Medizin in den Löffel."},{t:4,s:"Er nahm einen kleinen Schluck aus seinem Glas."},{t:5,s:"Nur ein Schluck Wasser reicht mir jetzt."}]},
