  "duct": {label:"Lüftungskanal",gender:"der",plural:"Lüftungskanäle", ex5:[{t:1,s:"Die Luft kommt durch den Lüftungskanal."},{t:2,s:"Er hat den beschädigten Lüftungskanal an der Decke repariert."},{t:3,s:"Im Lüftungskanal hat sich Staub angesammelt."},{t:4,s:"Der Lüftungskanal muss gereinigt werden."},{t:5,s:"Durch den Lüftungskanal zieht ein kühler Luftzug."}]},
  "ductile": {label:"duktil",gender:"",plural:"—", ex5:[{t:1,s:"Kupfer ist ein sehr duktiles Metall, das leicht zu Drähten gezogen werden kann."},{t:2,s:"Der Ingenieur wählte ein duktiles Material, um Brüche zu verhindern."},{t:3,s:"Gold ist so duktil, dass man es zu sehr dünnen Blättern schlagen kann."},{t:4,s:"Das Material ist bekannt für seine duktile Eigenschaft."},{t:5,s:"Duktiler Stahl lässt sich unter Druck gut verformen."}]},
  "ductility": {label:"Duktilität",gender:"die",plural:"Duktilitäten", ex5:[{t:1,s:"Gold zeichnet sich durch seine hohe Duktilität aus, wodurch es zu dünnen Drähten gezogen werden kann."},{t:2,s:"Ingenieure prüfen die Duktilität von Metallen, bevor sie sie im Bauwesen einsetzen."},{t:3,s:"Die Duktilität des Materials bestimmt, wie weit es sich biegen lässt, ohne zu brechen."},{t:4,s:"Duktilität ist eine wichtige Eigenschaft bei der Verarbeitung von Werkstoffen."},{t:5,s:"Durch das Erhitzen wurde die Duktilität des Stahls verbessert."}]},
  "ducts": {label:"Kanäle",gender:"die",plural:"Kanäle", ex5:[{t:1,s:"Die Luftkanäle in diesem Gebäude müssen gereinigt werden."},{t:2,s:"Tränen fließen durch die Tränenkanäle, um die Augen feucht zu halten."},{t:3,s:"Der Techniker untersuchte die Lüftungskanäle auf mögliche Verstopfungen."},{t:4,s:"Durch die Kanäle wird die frische Luft in alle Räume geleitet."},{t:5,s:"In den Kanälen hat sich über die Jahre viel Staub angesammelt."}]},
  "dud": {label:"Niete",gender:"die",plural:"Nieten", ex5:[{t:1,s:"Das Feuerwerk war eine Niete und leuchtete nicht am Himmel."},{t:2,s:"Ich habe eine billige Kamera gekauft, aber sie erwies sich als Niete."},{t:3,s:"Der Film war an der Kinokasse eine absolute Niete."},{t:4,s:"Dieses neue Produkt ist leider eine Niete."},{t:5,s:"Ich hatte gehofft, das Gerät funktioniert, aber es war eine Niete."}]},
  "dude": {label:"Typ",gender:"der",plural:"Typen", ex5:[{t:1,s:"Hey Typ, was machst du heute?"},{t:2,s:"Dieser Typ da drüben ist mein bester Freund."},{t:3,s:"Typ, du hast mich wirklich überrascht!"},{t:4,s:"Er ist ein netter Typ, den man gerne kennenlernt."},{t:5,s:"Was für ein komischer Typ ist das denn?"}]},
  "dudes": {label:"Typen",gender:"die",plural:"Typen", ex5:[{t:1,s:"Hey Typen, was macht ihr am Wochenende?"},{t:2,s:"Diese Typen hängen ständig im Park ab."},{t:3,s:"Ich habe gestern auf dem Musikfestival ein paar coole Typen getroffen."},{t:4,s:"Die Typen dort drüben spielen Fußball."},{t:5,s:"Das sind alles gute Typen, mit denen man Spaß haben kann."}]},
  "due": {label:"fällig",gender:"",plural:"—", ex5:[{t:1,s:"Die Miete ist fällig."},{t:2,s:"Das Buch ist zur Rückgabe fällig."},{t:3,s:"Wir haben die fällige Gebühr bezahlt."},{t:4,s:"Die Rechnung ist heute fällig."},{t:5,s:"Es ist Zeit, dass diese Arbeit fällig wird."}]},
