  "dull": {label:"stumpf",gender:"",plural:"—", ex5:[{t:1,s:"Das Messer ist stumpf."},{t:2,s:"Die Vorlesung ist sehr langweilig."},{t:3,s:"Wir haben die stumpfe Klinge geschärft."},{t:4,s:"Das Werkzeug ist mittlerweile stumpf geworden."},{t:5,s:"Ein stumpfes Messer ist gefährlicher als ein scharfes."}]},
  "dulled": {label:"stumpf machen",gender:"",plural:"—", ex5:[{t:1,s:"Der lange Winter hat seine Begeisterung gedämpft."},{t:2,s:"Ständige Wiederholungen haben die Freude am Spiel gedämpft."},{t:3,s:"Das Messer wurde durch die lange Benutzung stumpf."},{t:4,s:"Die Kälte hat seine Motivation gedämpft."},{t:5,s:"Das viele Üben hat seine Sinne etwas abgestumpft."}]},
