  "dumps": {label:"Mülldeponie",gender:"die",plural:"Mülldeponien", ex5:[{t:1,s:"Die Stadt hat kürzlich mehrere illegale Mülldeponien geschlossen."},{t:2,s:"Der LKW brachte den Abfall zur städtischen Mülldeponie."},{t:3,s:"Es gibt zu viele giftige Mülldeponien in der Nähe des Flusses."},{t:4,s:"Die Mülldeponie liegt weit außerhalb der Stadt."},{t:5,s:"Die Sanierung der alten Mülldeponie dauert lange."}]},
  "dumpster": {label:"Müllcontainer",gender:"der",plural:"Müllcontainer", ex5:[{t:1,s:"Bitte wirf die Pappkartons in den Müllcontainer."},{t:2,s:"Die alten Möbel wurden direkt neben den Müllcontainer gestellt."},{t:3,s:"Er hat versehentlich seine Schlüssel in den Müllcontainer fallen lassen."},{t:4,s:"Der Müllcontainer wird morgen geleert."},{t:5,s:"Der Müllcontainer steht hinter dem Haus."}]},
  "dun": {label:"fahlbraun",gender:"",plural:"—", ex5:[{t:1,s:"Die Wände des alten Hauses waren in einem fahlbraunen Ton gestrichen."},{t:2,s:"Das Pferd hatte ein schönes fahlbraunes Fell, das auf der Weide auffiel."},{t:3,s:"Sie trug einen einfachen fahlbraunen Schal, der zu ihrem Mantel passte."},{t:4,s:"Die Landschaft wirkte im Herbst etwas fahlbraun."},{t:5,s:"Er malte den Hintergrund in einem fahlbraunen Farbton."}]},
  "dunbar": {label:"Dunbar",gender:"",plural:"—", ex5:[{t:1,s:"Herr Dunbar ist der beliebteste Lehrer an unserer Schule."},{t:2,s:"Ich habe gestern auf der Konferenz jemanden namens Dunbar getroffen."},{t:3,s:"Das Forschungspapier wurde von Dr. Dunbar verfasst."},{t:4,s:"Dunbar hat mir bei meiner Arbeit geholfen."},{t:5,s:"Wir warten noch auf die Antwort von Herrn Dunbar."}]},
