  "dundee": {label:"Dundee",gender:"",plural:"—", ex5:[{t:1,s:"Dundee ist eine Stadt in Schottland."},{t:2,s:"Wir planen, nächsten Sommer Dundee zu besuchen."},{t:3,s:"Die Universität von Dundee ist sehr bekannt."},{t:4,s:"Dundee liegt an der Ostküste Schottlands."},{t:5,s:"Ich habe eine Reise nach Dundee gebucht."}]},
  "dune": {label:"Düne",gender:"die",plural:"Dünen", ex5:[{t:1,s:"Der Wind formte den Sand zu einer Düne."},{t:2,s:"Sie sind auf die hohe Düne geklettert."},{t:3,s:"Fußspuren zogen sich über die leere Düne."},{t:4,s:"Die Düne schützt den Strand vor dem Wind."},{t:5,s:"Wir haben den Sonnenuntergang auf der Düne genossen."}]},
  "dunedin": {label:"Dunedin",gender:"",plural:"—", ex5:[{t:1,s:"Dunedin ist eine wunderschöne Stadt in Neuseeland."},{t:2,s:"Wir haben letztes Jahr unseren Sommerurlaub in Dunedin verbracht."},{t:3,s:"Das Wetter in Dunedin kann sehr schnell umschlagen."},{t:4,s:"Dunedin ist bekannt für seine hügelige Landschaft."},{t:5,s:"Viele Touristen besuchen Dunedin wegen der Natur."}]},
  "dunes": {label:"Dünen",gender:"die",plural:"Dünen", ex5:[{t:1,s:"Der Wind veränderte die Form der Dünen."},{t:2,s:"Wir sind auf die hohen Dünen geklettert, um den Sonnenuntergang zu sehen."},{t:3,s:"Auf den Dünen nahe dem Strand wachsen kleine Pflanzen."},{t:4,s:"Die Dünen erstrecken sich entlang der gesamten Küste."},{t:5,s:"Man sollte die Dünen nicht abseits der Wege betreten."}]},
