  "egotist": {label:"Egoist",gender:"der",plural:"Egoisten", ex5:[{t:1,s:"Er ist ein unverbesserlicher Egoist."},{t:2,s:"Ein Egoist denkt nur an sich selbst."},{t:3,s:"Niemand mag einen eingebildeten Egoisten."},{t:4,s:"Sei kein Egoist und teile dein Spielzeug."},{t:5,s:"Der Egoist wollte den Erfolg für sich allein."}]},
  "egotistical": {label:"egoistisch",gender:"",plural:"—", ex5:[{t:1,s:"Seine egoistische Art nervt alle."},{t:2,s:"Warum bist du immer so egoistisch?"},{t:3,s:"Es ist schwer, mit einer egoistischen Person zu arbeiten."},{t:4,s:"Sie traf eine egoistische Entscheidung."},{t:5,s:"Denk auch an andere und sei nicht so egoistisch."}]},
  "egregious": {label:"ungeheuerlich",gender:"",plural:"—", ex5:[{t:1,s:"Das war ein ungeheuerlicher Fehler von ihm."},{t:2,s:"Seine Lüge ist einfach ungeheuerlich."},{t:3,s:"So ein ungeheuerliches Benehmen wird nicht toleriert."},{t:4,s:"Das Gericht bestrafte dieses ungeheuerliche Verbrechen."},{t:5,s:"Es ist ungeheuerlich, wie er uns behandelt hat."}]},
  "egress": {label:"Ausgang",gender:"der",plural:"Ausgänge", ex5:[{t:1,s:"Wo ist der nächste Ausgang?"},{t:2,s:"Dieser Ausgang muss immer frei bleiben."},{t:3,s:"Die Halle hat zwei große Ausgänge."},{t:4,s:"Sie blockierten den einzigen Ausgang."},{t:5,s:"Bitte gehen Sie ruhig zum Ausgang."}]},
  "egypt": {label:"Ägypten",gender:"das",plural:"—", ex5:[{t:1,s:"Ich möchte nächsten Sommer nach Ägypten reisen."},{t:2,s:"Ägypten ist bekannt für seine Pyramiden."},{t:3,s:"Der Nil fließt durch Ägypten."},{t:4,s:"Die Geschichte von Ägypten ist sehr alt."},{t:5,s:"Er hat viele Jahre in Ägypten gelebt."}]},
  "egyptian": {label:"ägyptisch",gender:"",plural:"—", ex5:[{t:1,s:"Die ägyptischen Pyramiden sind weltberühmt."},{t:2,s:"Sie liest ein Buch über ägyptische Geschichte."},{t:3,s:"Wir haben gestern ein ägyptisches Restaurant besucht."},{t:4,s:"Er interessiert sich für ägyptische Kunst."},{t:5,s:"Diese ägyptische Münze ist sehr alt."}]},
  "egyptians": {label:"Ägypter",gender:"der",plural:"Ägypter", ex5:[{t:1,s:"Die alten Ägypter bauten die großen Pyramiden."},{t:2,s:"Viele Ägypter trinken nachmittags gerne Tee."},{t:3,s:"Er hat sich mit einigen Ägyptern angefreundet."},{t:4,s:"Die Geschichte der Ägypter ist faszinierend."},{t:5,s:"Als Ägypter spricht er fließend Arabisch."}]},
  "eid": {label:"Eid-Fest",gender:"das",plural:"Eid-Feste", ex5:[{t:1,s:"Nach dem Ramadan feiern Muslime das Eid-Fest."},{t:2,s:"Zum Eid-Fest kommen alle Familienmitglieder zusammen."},{t:3,s:"Wir haben während des Eid-Fests Geschenke ausgetauscht."},{t:4,s:"Das Eid-Fest ist eine Zeit der Freude."},{t:5,s:"Sie bereiten süße Speisen für das Eid-Fest vor."}]},
  "eiffel": {label:"Eiffelturm",gender:"der",plural:"—", ex5:[{t:1,s:"Wir haben viele Fotos vor dem Eiffelturm gemacht."},{t:2,s:"Gustave Eiffel hat den berühmten Eiffelturm entworfen."},{t:3,s:"Der Eiffelturm leuchtet nachts wunderschön."},{t:4,s:"Ich möchte unbedingt einmal den Eiffelturm besuchen."},{t:5,s:"Der Eiffelturm ist das Wahrzeichen von Paris."}]},
  "eigenvalue": {label:"Eigenwert",gender:"der",plural:"Eigenwerte", ex5:[{t:1,s:"Der Professor erklärte, wie man den Eigenwert berechnet."},{t:2,s:"Wir müssen den Eigenwert dieser Matrix bestimmen."},{t:3,s:"Der größte Eigenwert ist für die Stabilität wichtig."},{t:4,s:"Jede lineare Abbildung kann einen Eigenwert haben."},{t:5,s:"Er hat den Eigenwert der Gleichung schnell gefunden."}]},
