  "eighteen": {label:"achtzehn",gender:"",plural:"—", ex5:[{t:1,s:"Ich werde nächsten Monat achtzehn Jahre alt."},{t:2,s:"Es sind achtzehn Schüler in der Klasse."},{t:3,s:"Sie hat mit achtzehn angefangen zu arbeiten."},{t:4,s:"Ich habe achtzehn Eier gekauft."},{t:5,s:"Die Zahl achtzehn ist heute wichtig."}]},
  "eighteenth": {label:"achtzehnt",gender:"",plural:"—", ex5:[{t:1,s:"Heute ist mein achtzehnter Geburtstag."},{t:2,s:"Er wohnt im achtzehnten Stock."},{t:3,s:"Dies ist das achtzehnte Kapitel des Buches."},{t:4,s:"Der achtzehnte Läufer kam ins Ziel."},{t:5,s:"Es ist die achtzehnte Seite des Dokuments."}]},
