  "eighties": {label:"achtziger Jahre",gender:"die",plural:"—", ex5:[{t:1,s:"Meine Eltern lieben die Musik aus den achtziger Jahren."},{t:2,s:"Die Mode in den achtziger Jahren war sehr bunt."},{t:3,s:"Viele Menschen in den Achtzigern gehen gerne spazieren."},{t:4,s:"Filme aus den achtziger Jahren sind heute noch beliebt."},{t:5,s:"Ich bin in den achtziger Jahren geboren."}]},
  "eights": {label:"Achten",gender:"die",plural:"—", ex5:[{t:1,s:"Wir haben die Gruppe in Achten eingeteilt."},{t:2,s:"Das Muster besteht aus wiederholten Achten."},{t:3,s:"Die Tanzschritte folgen einem Rhythmus von Achten."},{t:4,s:"Wir bilden Achten für das Teamspiel."},{t:5,s:"In der Musik zählt man oft in Achten."}]},
