  "eisenhower": {label:"Eisenhower",gender:"",plural:"—", ex5:[{t:1,s:"Eisenhower diente als der 34. Präsident der Vereinigten Staaten."},{t:2,s:"Wir lernen im Geschichtsunterricht viel über Eisenhower."},{t:3,s:"Während des Zweiten Weltkriegs war Eisenhower ein Fünf-Sterne-General."},{t:4,s:"Das Erbe von Eisenhower ist bis heute bedeutend."},{t:5,s:"Viele Historiker schreiben über das Leben von Eisenhower."}]},
  "either": {label:"entweder",gender:"",plural:"—", ex5:[{t:1,s:"Entweder der linke oder der rechte Weg ist richtig."},{t:2,s:"Sie können entweder hier oder dort sitzen."},{t:3,s:"Wir können entweder jetzt oder später gehen."},{t:4,s:"Er mag entweder Kuchen oder Eis."},{t:5,s:"Entweder du hilfst mir, oder ich mache es allein."}]},
  "eject": {label:"auswerfen",gender:"",plural:"—", ex5:[{t:1,s:"Drücken Sie die Taste, um die CD auszuwerfen."},{t:2,s:"Der Pilot musste sich aus dem Flugzeug auswerfen."},{t:3,s:"Der Schiedsrichter beschloss, den Spieler auszuwerfen."},{t:4,s:"Die Maschine wird den Umschlag auswerfen."},{t:5,s:"Es ist wichtig, das defekte Teil auszuwerfen."}]},
