  "electorates": {label:"Wahlkreise",gender:"die",plural:"—", ex5:[{t:1,s:"Verschiedene Wahlkreise haben unterschiedliche Prioritäten für die Regierung."},{t:2,s:"Der Politiker besuchte mehrere Wahlkreise, um den Menschen zuzuhören."},{t:3,s:"Wahlkreise spielen eine entscheidende Rolle bei der Gestaltung der Zukunft des Landes."},{t:4,s:"Die Ergebnisse in den einzelnen Wahlkreisen waren sehr unterschiedlich."},{t:5,s:"Die Umverteilung der Wahlkreise ist ein umstrittenes Thema."}]},
  "electors": {label:"Wähler",gender:"die",plural:"—", ex5:[{t:1,s:"Die Wähler werden bald den neuen Präsidenten wählen."},{t:2,s:"Viele Wähler versammelten sich am Wahllokal."},{t:3,s:"Die Wähler sollen heute ihre endgültige Entscheidung treffen."},{t:4,s:"Die Stimmen der Wähler sind entscheidend."},{t:5,s:"Die Wähler erwarten Transparenz von den Politikern."}]},
  "electric": {label:"elektrisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Auto ist elektrisch."},{t:2,s:"Der Zaun ist elektrisch geladen."},{t:3,s:"Wir haben einen elektrischen Wasserkocher gekauft."},{t:4,s:"Das ist eine elektrische Zahnbürste."},{t:5,s:"Wir fahren mit einem elektrischen Zug."}]},
