  "electrically": {label:"elektrisch",gender:"",plural:"—", ex5:[{t:1,s:"Dieses Auto wird elektrisch angetrieben."},{t:2,s:"Das Tor wird elektrisch gesteuert."},{t:3,s:"Das Gerät wird elektrisch beheizt."},{t:4,s:"Der Stuhl lässt sich elektrisch verstellen."},{t:5,s:"Die Anlage arbeitet vollkommen elektrisch."}]},
  "electrician": {label:"Elektriker",gender:"der",plural:"Elektriker", ex5:[{t:1,s:"Der Elektriker hat das Licht repariert."},{t:2,s:"Wir haben einen Elektriker für die Verkabelung gerufen."},{t:3,s:"Der Elektriker prüft den Sicherungskasten."},{t:4,s:"Mein Bruder ist gelernter Elektriker."},{t:5,s:"Der Elektriker kommt morgen vorbei."}]},
