  "elsewhere": {label:"anderswo",gender:"",plural:"—", ex5:[{t:1,s:"Wenn dir dieser Laden nicht gefällt, können wir anderswo schauen."},{t:2,s:"Der Preis ist anderswo viel günstiger."},{t:3,s:"Er hat beschlossen, anderswo nach einem besseren Job zu suchen."},{t:4,s:"Wir müssen anderswo nach einer Lösung suchen."},{t:5,s:"Das kann man auch anderswo kaufen."}]},
  "elsie": {label:"Elsie",gender:"",plural:"—", ex5:[{t:1,s:"Meine Großmutter Elsie erzählt immer die besten Geschichten."},{t:2,s:"Elsie hat einen selbstgebackenen Kuchen zum Treffen mitgebracht."},{t:3,s:"Wir haben Elsie in ihrem gemütlichen Haus auf dem Land besucht."},{t:4,s:"Elsie liebt es, Zeit in ihrem Garten zu verbringen."},{t:5,s:"Ich habe gestern mit Elsie telefoniert."}]},
  "elton": {label:"Elton",gender:"",plural:"—", ex5:[{t:1,s:"Elton besucht uns an diesem Wochenende."},{t:2,s:"Ich habe in der Schule einen Jungen namens Elton kennengelernt."},{t:3,s:"Elton spielt sehr gerne Klavier."},{t:4,s:"Elton ist ein wirklich guter Freund von mir."},{t:5,s:"Nach der Schule sind Elton und ich in die Bibliothek gegangen."}]},
  "elucidate": {label:"erläutern",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat das schwierige Konzept ausführlich erläutert."},{t:2,s:"Der Reiseführer wird uns jeden Schritt genau erläutern."},{t:3,s:"Er hat dem Vorstand seinen Plan erläutert."},{t:4,s:"Es ist wichtig, diese Regeln klar zu erläutern."},{t:5,s:"Könnten Sie mir das bitte noch einmal erläutern?"}]},
  "elude": {label:"entgehen",gender:"",plural:"—", ex5:[{t:1,s:"Der Dieb konnte der Polizei knapp entgehen."},{t:2,s:"Der Erfolg scheint ihm in letzter Zeit zu entgehen."},{t:3,s:"Die richtige Antwort will mir einfach entgehen."},{t:4,s:"Niemandem sollte diese wichtige Information entgehen."},{t:5,s:"Er versuchte, der unangenehmen Situation zu entgehen."}]},
  "eluded": {label:"entging",gender:"",plural:"—", ex5:[{t:1,s:"Der Dieb entging der Polizei für mehrere Wochen."},{t:2,s:"Die Antwort entging mir schon immer."},{t:3,s:"Er entging der schwierigen Frage mit einem Lächeln."},{t:4,s:"Kein Detail entging ihr bei der Untersuchung."},{t:5,s:"Er entging dem Stau durch eine Abkürzung."}]},
  "elusive": {label:"schwer fassbar",gender:"",plural:"—", ex5:[{t:1,s:"Die Antwort blieb lange schwer fassbar."},{t:2,s:"Der Fuchs ist ein scheues und schwer fassbares Tier."},{t:3,s:"Der Erfolg war anfangs sehr schwer fassbar."},{t:4,s:"Er hat eine etwas schwer fassbare Persönlichkeit."},{t:5,s:"Das Ziel ist leider noch schwer fassbar."}]},
  "elves": {label:"Elfen",gender:"die",plural:"Elfen", ex5:[{t:1,s:"Die Elfen halfen dem Weihnachtsmann bei der Spielzeugproduktion."},{t:2,s:"In vielen Märchen kommen magische Elfen vor."},{t:3,s:"Die Elfen lebten tief im verzauberten Wald."},{t:4,s:"Die Kinder hören gerne Geschichten über kleine Elfen."},{t:5,s:"Im Wald sind die Elfen zu Hause."}]},
  "elvis": {label:"Elvis",gender:"",plural:"—", ex5:[{t:1,s:"Elvis ist eine legendäre Ikone des Rock and Roll."},{t:2,s:"Mein Vater hört jeden Morgen Lieder von Elvis."},{t:3,s:"Elvis war für seinen einzigartigen Tanzstil berühmt."},{t:4,s:"Ich besitze einige Schallplatten von Elvis."},{t:5,s:"Die Musik von Elvis bleibt unvergessen."}]},
  "ely": {label:"Ely",gender:"",plural:"—", ex5:[{t:1,s:"Ely ist eine historische Stadt, die für ihre schöne Kathedrale bekannt ist."},{t:2,s:"Wir sind im Urlaub mit dem Zug nach Ely gefahren."},{t:3,s:"Es ist bezaubernd, durch die alten Straßen von Ely zu spazieren."},{t:4,s:"Viele Touristen besuchen Ely wegen der Architektur."},{t:5,s:"Ely hat einen ganz besonderen Charme."}]},
  "elysium": {label:"Elysium",gender:"das",plural:"Elysien", ex5:[{t:1,s:"Der Garten fühlte sich an wie ein friedliches Elysium."},{t:2,s:"In der Mythologie kommen Helden nach dem Tod in das Elysium."},{t:3,s:"Sie fand ihr eigenes Elysium in der ruhigen Bibliothek."},{t:4,s:"Dieser Ort gleicht einem wahren Elysium."},{t:5,s:"Jeder Mensch sucht nach seinem persönlichen Elysium."}]},
  "emaciated": {label:"abgemagert",gender:"",plural:"—", ex5:[{t:1,s:"Der streunende Hund war dünn und abgemagert."},{t:2,s:"Die Hungersnot ließ die Menschen abgemagert zurück."},{t:3,s:"Der abgemagerte Patient brauchte eine sorgfältige Ernährung."},{t:4,s:"Nach der langen Krankheit sah er sehr abgemagert aus."},{t:5,s:"Das abgemagerte Kind erholte sich langsam im Krankenhaus."}]},
  "email": {label:"E-Mail",gender:"die",plural:"E-Mails", ex5:[{t:1,s:"Die E-Mail ist angekommen."},{t:2,s:"Die E-Mail ist sehr lang."},{t:3,s:"Wir haben eine E-Mail geschickt."},{t:4,s:"Ich habe deine E-Mail gelesen."},{t:5,s:"Hast du die E-Mail schon beantwortet?"}]},
  "emailed": {label:"mailte",gender:"",plural:"—", ex5:[{t:1,s:"Ich mailte den Bericht heute Morgen an meinen Chef."},{t:2,s:"Sie mailte mir die Anweisungen für das Projekt."},{t:3,s:"Wir mailten dem Hotel, um unsere Reservierung zu bestätigen."},{t:4,s:"Er mailte mir die Details zum Treffen."},{t:5,s:"Ich mailte ihr gestern Abend noch kurz."}]},
  "emailing": {label:"mailend",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe den ganzen Nachmittag damit verbracht, Freunden zu mailen."},{t:2,s:"Sie ist damit beschäftigt, den Kunden wegen des neuen Projekts zu mailen."},{t:3,s:"Das Mailen ist eine schnelle Art der Kommunikation im Büro."},{t:4,s:"Er ist gerade beim Mailen an die Kollegen."},{t:5,s:"Ständiges Mailen kann manchmal anstrengend sein."}]},
  "emails": {label:"E-Mails",gender:"die",plural:"E-Mails", ex5:[{t:1,s:"Ich habe zu viele ungelesene E-Mails in meinem Posteingang."},{t:2,s:"Bitte prüfe deine E-Mails wegen des Zeitplans für das Meeting."},{t:3,s:"Sie hat gestern mehrere E-Mails an den Manager geschickt."},{t:4,s:"Ich muss heute noch viele E-Mails beantworten."},{t:5,s:"Haben Sie meine E-Mails erhalten?"}]},
  "emanate": {label:"ausströmen",gender:"",plural:"—", ex5:[{t:1,s:"Ein sanftes Licht strömte von der Lampe aus."},{t:2,s:"Wärme strömte vom Kamin aus."},{t:3,s:"Ruhe schien von ihr auszuströmen."},{t:4,s:"Die Blumen strömen einen wunderbaren Duft aus."},{t:5,s:"Von dem alten Haus strömt eine geheimnisvolle Stimmung aus."}]},
  "emanates": {label:"strömt aus",gender:"",plural:"—", ex5:[{t:1,s:"Ein herrlicher Duft strömt aus dem blühenden Garten aus."},{t:2,s:"Großes Selbstvertrauen strömt aus ihr aus, jedes Mal wenn sie spricht."},{t:3,s:"Wärme strömt aus dem Kamin im Wohnzimmer aus."},{t:4,s:"Aus seinen Worten strömt tiefe Überzeugung aus."},{t:5,s:"Ein angenehmes Aroma strömt aus der Küche aus."}]},
  "emanating": {label:"ausströmend",gender:"",plural:"—", ex5:[{t:1,s:"Ein seltsamer Geruch strömte aus der Küche aus."},{t:2,s:"Wärme strömte aus dem Kamin in der Halle aus."},{t:3,s:"Selbstvertrauen strömte aus ihr aus, während sie sprach."},{t:4,s:"Ein unheimliches Leuchten strömte aus der Höhle aus."},{t:5,s:"Die Freude strömte förmlich aus seinem Gesicht aus."}]},
  "emanation": {label:"Ausstrahlung",gender:"die",plural:"Ausstrahlungen", ex5:[{t:1,s:"Ein schwaches Licht war eine Ausstrahlung der Lampe."},{t:2,s:"Die Ausstrahlung von Wärme wärmte sie auf."},{t:3,s:"Ruhe schien eine Ausstrahlung ihrer Stimmung zu sein."},{t:4,s:"Sie hat eine sehr positive Ausstrahlung."},{t:5,s:"Das Leuchten war eine direkte Ausstrahlung des Feuers."}]},
  "emancipate": {label:"befreien",gender:"",plural:"—", ex5:[{t:1,s:"Das Gesetz versuchte, die Sklaven zu befreien."},{t:2,s:"Bildung kann die Armen befreien."},{t:3,s:"Sie kämpften dafür, die Arbeiter zu befreien."},{t:4,s:"Er wollte sich von seinen alten Ängsten befreien."},{t:5,s:"Wir müssen das Land von der Unterdrückung befreien."}]},
  "emancipated": {label:"befreit",gender:"",plural:"—", ex5:[{t:1,s:"Nach dem Krieg wurden die Sklaven endlich befreit."},{t:2,s:"Sie fühlte sich befreit, als sie ihr eigenes Unternehmen gründete."},{t:3,s:"Das Land hat seine Bürger von ungerechten Gesetzen befreit."},{t:4,s:"Er hat sich von seinen alten Ängsten befreit."},{t:5,s:"Die Stadt wurde von der Besatzung befreit."}]},
