  "embarrass": {label:"in Verlegenheit bringen",gender:"",plural:"—", ex5:[{t:1,s:"Fehler bringen uns in Verlegenheit."},{t:2,s:"Der Ausrutscher bringt ihn in Verlegenheit."},{t:3,s:"Wir bringen niemanden in Verlegenheit."},{t:4,s:"Solche Fragen bringen mich oft in Verlegenheit."},{t:5,s:"Er wollte sie nicht in Verlegenheit bringen."}]},
  "embarrassed": {label:"verlegen",gender:"",plural:"—", ex5:[{t:1,s:"Sie fühlte sich verlegen."},{t:2,s:"Der Junge ist verlegen."},{t:3,s:"Wir waren sehr verlegen."},{t:4,s:"Ich bin verlegen wegen meines Fehlers."},{t:5,s:"Er lächelte verlegen."}]},
