  "embarrassingly": {label:"peinlich",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe mein Passwort vergessen, was peinlich einfach war."},{t:2,s:"Er sang auf der Party peinlich schief."},{t:3,s:"Sie bemerkte peinlich berührt, dass ihr Hemd falsch herum war."},{t:4,s:"Das Ergebnis war peinlich schlecht."},{t:5,s:"Er hat sich peinlich genau an die Regeln gehalten."}]},
  "embarrassment": {label:"Verlegenheit",gender:"die",plural:"Verlegenheiten", ex5:[{t:1,s:"Ich spürte eine tiefe Verlegenheit, als ich vor allen stolperte."},{t:2,s:"Zu meiner Verlegenheit vergaß ich den Namen meines besten Freundes."},{t:3,s:"Sie versuchte, ihre Verlegenheit zu verbergen."},{t:4,s:"Die Verlegenheit war ihm deutlich anzusehen."},{t:5,s:"Er überwand seine Verlegenheit und sprach."}]},
  "embassies": {label:"Botschaften",gender:"die",plural:"Botschaften", ex5:[{t:1,s:"In der Stadt gibt es mehrere ausländische Botschaften."},{t:2,s:"Diplomaten aus verschiedenen Botschaften nahmen am Abendessen teil."},{t:3,s:"Wir besuchten die Botschaften, um unsere Visa zu beantragen."},{t:4,s:"Die Botschaften liegen nah beieinander."},{t:5,s:"Er hat Kontakte zu vielen Botschaften."}]},
