  "embattled": {label:"bedrängt",gender:"",plural:"—", ex5:[{t:1,s:"Der bedrängte Anführer trat schließlich zurück."},{t:2,s:"Das bedrängte Unternehmen kämpft ums Überleben."},{t:3,s:"Reporter versammelten sich um den bedrängten Politiker."},{t:4,s:"Die bedrängte Firma sucht nach neuen Investoren."},{t:5,s:"Er fühlt sich in dieser Lage sehr bedrängt."}]},
  "embed": {label:"einbetten",gender:"",plural:"—", ex5:[{t:1,s:"Der Edelstein war in den Ring eingebettet."},{t:2,s:"Sie haben einen Chip in die Karte eingebettet."},{t:3,s:"Ein Nagel war in das Holz eingebettet."},{t:4,s:"Wir müssen das Video in die Seite einbetten."},{t:5,s:"Die Daten sind im Code eingebettet."}]},
