  "embedding": {label:"einbetten",gender:"",plural:"—", ex5:[{t:1,s:"Er bettet ein Video in seine Präsentationsfolie ein."},{t:2,s:"Der Künstler bettet kleine Juwelen in den Ton ein."},{t:3,s:"Es ist sehr wichtig, Kindern tiefe Werte einzubetten."},{t:4,s:"Man kann diese Karte einfach in die Webseite einbetten."},{t:5,s:"Die Software hilft dabei, Daten in das System einzubetten."}]},
  "embellish": {label:"ausschmücken",gender:"",plural:"—", ex5:[{t:1,s:"Sie schmückt ihre Geschichten gerne aus."},{t:2,s:"Goldfaden wurde verwendet, um das Kleid auszuschmücken."},{t:3,s:"Er neigt dazu, die Wahrheit ein wenig auszuschmücken."},{t:4,s:"Sie schmückte den Bericht mit vielen Details aus."},{t:5,s:"Man sollte die Erzählung nicht unnötig ausschmücken."}]},
  "embellished": {label:"ausgeschmückt",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat ihre Geschichte mit vielen Details ausgeschmückt."},{t:2,s:"Das Kleid war wunderschön mit Goldperlen ausgeschmückt."},{t:3,s:"Er hat die Wahrheit ausgeschmückt, um besser dazustehen."},{t:4,s:"Der Text war mit vielen Metaphern ausgeschmückt."},{t:5,s:"Ein ausgeschmücktes Zimmer wirkt sehr festlich."}]},
  "embellishment": {label:"Verzierung",gender:"die",plural:"Verzierungen", ex5:[{t:1,s:"Das Kleid hatte eine schöne goldene Verzierung am Kragen."},{t:2,s:"Seine Geschichte war voller Verzierung, um sie spannend zu machen."},{t:3,s:"Der Architekt fügte dem Eingangstor eine schlichte Verzierung hinzu."},{t:4,s:"Die Verzierung an der Wand ist sehr alt."},{t:5,s:"Diese Verzierung macht das Möbelstück einzigartig."}]},
  "ember": {label:"Glut",gender:"die",plural:"Gluten", ex5:[{t:1,s:"Eine einzelne Glut begann im Kamin zu glühen."},{t:2,s:"Er rührte in der Asche, um eine heiße Glut zu finden."},{t:3,s:"Das erlöschende Feuer hinterließ nur eine schwache Glut."},{t:4,s:"Die Glut im Ofen wärmte das Zimmer."},{t:5,s:"Man muss vorsichtig mit der heißen Glut umgehen."}]},
  "embezzle": {label:"veruntreuen",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde erwischt, als er versuchte, Gelder zu veruntreuen."},{t:2,s:"Sie beschuldigten sie, Geld veruntreut zu haben."},{t:3,s:"Der Angestellte hat das Geld der Firma veruntreut."},{t:4,s:"Wer Firmengelder veruntreut, muss mit einer Strafe rechnen."},{t:5,s:"Es ist illegal, öffentliche Gelder zu veruntreuen."}]},
