  "embezzlement": {label:"Veruntreuung",gender:"die",plural:"Veruntreuungen", ex5:[{t:1,s:"Der Buchhalter wurde wegen Veruntreuung von Firmengeldern verhaftet."},{t:2,s:"Ihm drohen zehn Jahre Haft für seine Rolle bei der Veruntreuung."},{t:3,s:"Der Skandal um die Veruntreuung ruinierte den Ruf des Geschäftsführers."},{t:4,s:"Die Veruntreuung wurde durch eine Prüfung aufgedeckt."},{t:5,s:"Er wurde wegen schwerer Veruntreuung angeklagt."}]},
  "embezzler": {label:"Veruntreuer",gender:"der",plural:"Veruntreuer", ex5:[{t:1,s:"Der Veruntreuer stahl über viele Jahre hinweg Gelder."},{t:2,s:"Die Prüfer haben den Veruntreuer endlich gefasst."},{t:3,s:"Der Veruntreuer fälschte die Unterlagen der Firma."},{t:4,s:"Der Veruntreuer muss nun vor Gericht erscheinen."},{t:5,s:"Ein Veruntreuer schädigt das Vertrauen aller Mitarbeiter."}]},
  "embezzling": {label:"Veruntreuung",gender:"die",plural:"Veruntreuungen", ex5:[{t:1,s:"Der Buchhalter wurde beim Veruntreuen von Firmengeldern erwischt."},{t:2,s:"Er verbrachte Jahre damit, Gelder für seinen Luxus zu veruntreuen."},{t:3,s:"Das Veruntreuen von Geld ist ein schweres Verbrechen."},{t:4,s:"Beim Veruntreuen wurde er schließlich entdeckt."},{t:5,s:"Er bereut das Veruntreuen der Gelder zutiefst."}]},
  "embittered": {label:"verbittert",gender:"",plural:"—", ex5:[{t:1,s:"Jahrelange Entbehrungen haben ihn gegenüber der Gesellschaft verbittert gemacht."},{t:2,s:"Nach der ungerechten Behandlung bei der Arbeit wurde sie völlig verbittert."},{t:3,s:"Lass dich durch deine Misserfolge nicht verbittert und hoffnungslos machen."},{t:4,s:"Er ist ein verbitterter Mann geworden, der niemandem mehr vertraut."},{t:5,s:"Trotz der Schwierigkeiten blieb sie, ohne verbittert zu sein."}]},
