  "eminent": {label:"eminent",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist eine eminente Wissenschaftlerin."},{t:2,s:"Der eminente Arzt hielt eine Rede."},{t:3,s:"Er wurde auf seinem Gebiet ein eminenter Experte."},{t:4,s:"Das ist von eminenter Bedeutung für unser Projekt."},{t:5,s:"Ein eminenter Professor leitet das Institut."}]},
