  "emir": {label:"Emir",gender:"der",plural:"Emire", ex5:[{t:1,s:"Der Emir regierte sein Land mit Weisheit und Gerechtigkeit."},{t:2,s:"Die antike Stadt wurde einst von einem mächtigen Emir beherrscht."},{t:3,s:"Der Palast des Emirs ist ein prächtiges Beispiel traditioneller Architektur."},{t:4,s:"Der Emir traf sich mit den Stammesführern."},{t:5,s:"Die Macht des Emirs war in der Region sehr groß."}]},
  "emirate": {label:"Emirat",gender:"das",plural:"Emirate", ex5:[{t:1,s:"Dubai ist einer der sieben Staaten, die das Emirat bilden."},{t:2,s:"Sie reisten letzten Winter durch das gesamte Emirat."},{t:3,s:"Das Emirat ist für seine moderne Architektur bekannt."},{t:4,s:"Das Emirat hat in den letzten Jahren ein schnelles Wachstum erlebt."},{t:5,s:"Wir besuchen bald ein neues Emirat am Golf."}]},
  "emirates": {label:"Emirate",gender:"die",plural:"—", ex5:[{t:1,s:"Sie reisen in die Vereinigten Arabischen Emirate."},{t:2,s:"Die Vereinigten Arabischen Emirate haben ein heißes Klima."},{t:3,s:"Ich habe eine Dokumentation über die Emirate gesehen."},{t:4,s:"Die Emirate sind ein beliebtes Reiseziel."},{t:5,s:"Viele Menschen arbeiten in den Emiraten."}]},
  "emissaries": {label:"Gesandter",gender:"der",plural:"Gesandten", ex5:[{t:1,s:"Der König sandte Gesandte, um den Friedensvertrag zu besprechen."},{t:2,s:"Diese Gesandten vertreten die Interessen ihres Landes."},{t:3,s:"Die Firma schickte Gesandte, um den Deal auszuhandeln."},{t:4,s:"Die Gesandten trafen gestern ein."},{t:5,s:"Er wurde als Gesandter in das ferne Land geschickt."}]},
  "emissary": {label:"Gesandter",gender:"der",plural:"Gesandten", ex5:[{t:1,s:"Der König schickte einen Gesandten, um über Frieden zu verhandeln."},{t:2,s:"Ein vertrauenswürdiger Gesandter überbrachte die geheime Nachricht."},{t:3,s:"Der Gesandte erreichte den fremden Hof bei Tagesanbruch."},{t:4,s:"Er wurde als diplomatischer Gesandter entsandt."},{t:5,s:"Der Gesandte wartet auf eine Antwort des Herrschers."}]},
  "emission": {label:"Emission",gender:"die",plural:"Emissionen", ex5:[{t:1,s:"Wir müssen die Emission von Treibhausgasen reduzieren."},{t:2,s:"Das Auto hat eine sehr niedrige Emissionsrate."},{t:3,s:"Strenge Gesetze begrenzen die Emission schädlicher Chemikalien."},{t:4,s:"Die Emission von Schadstoffen belastet die Umwelt."},{t:5,s:"Diese Technologie hilft bei der Kontrolle der Emission."}]},
  "emissions": {label:"Emissionen",gender:"die",plural:"Emissionen", ex5:[{t:1,s:"Wir müssen unsere CO2-Emissionen verringern."},{t:2,s:"Die Fabrik kontrolliert ihre gasförmigen Emissionen."},{t:3,s:"Fahrzeugemissionen beeinträchtigen die Luftqualität."},{t:4,s:"Die Industrie arbeitet an der Senkung der Emissionen."},{t:5,s:"Diese Emissionen sind schädlich für das Klima."}]},
