  "emmett": {label:"Emmett",gender:"",plural:"—", ex5:[{t:1,s:"Emmett liest gerne Comics."},{t:2,s:"Ich gehe mit Emmett ins Kino."},{t:3,s:"Emmett hat einen leckeren Schokoladenkuchen gebacken."},{t:4,s:"Hast du Emmett heute schon gesehen?"},{t:5,s:"Emmett spielt am Nachmittag Fußball."}]},
  "emmy": {label:"Emmy",gender:"der",plural:"Emmys", ex5:[{t:1,s:"Sie hat für ihre Darstellung einen Emmy gewonnen."},{t:2,s:"Der Schauspieler wurde erneut für einen Emmy nominiert."},{t:3,s:"Hast du gestern Abend die Emmy-Verleihung gesehen?"},{t:4,s:"Ein Emmy ist eine große Auszeichnung im Fernsehen."},{t:5,s:"Der Regisseur freute sich sehr über seinen Emmy."}]},
  "emmys": {label:"Emmys",gender:"",plural:"—", ex5:[{t:1,s:"Die Emmys zeichnen herausragende Fernsehproduktionen aus."},{t:2,s:"Sie war begeistert, dieses Jahr an den Emmys teilzunehmen."},{t:3,s:"Die Serie gewann drei Auszeichnungen bei den Emmys."},{t:4,s:"Viele Prominente besuchen die jährlichen Emmys."},{t:5,s:"Die Vergabe der Emmys wird weltweit übertragen."}]},
  "emo": {label:"Emo",gender:"der",plural:"Emos", ex5:[{t:1,s:"Mein Bruder hört sehr gerne Emo-Musik."},{t:2,s:"Sie kleidete sich im Emo-Stil mit schwarzem Eyeliner."},{t:3,s:"Als Teenager war ich ein großer Fan von Emo-Bands."},{t:4,s:"Der Emo-Look war damals sehr populär."},{t:5,s:"Viele Jugendliche identifizierten sich mit Emo."}]},
