  "emphasising": {label:"betonend",gender:"",plural:"—", ex5:[{t:1,s:"Er sprach laut, die Wichtigkeit des Lesens betonend."},{t:2,s:"Sie zeigte auf die Grafik, den Unterschied betonend."},{t:3,s:"Der Chef nickte freundlich, seine Zustimmung betonend."},{t:4,s:"Er machte eine Geste, seine Worte betonend."},{t:5,s:"Sie schrieb den Brief, ihre Entschuldigung betonend."}]},
  "emphasize": {label:"betonen",gender:"",plural:"—", ex5:[{t:1,s:"Die Trainer wollen die Bedeutung von Grundübungen betonen."},{t:2,s:"Der Chef möchte die Sicherheit am Arbeitsplatz betonen."},{t:3,s:"Wir müssen diese wichtige Regel betonen."},{t:4,s:"Meine Mutter möchte eine gesunde Ernährung betonen."},{t:5,s:"Lehrer wollen oft die Wichtigkeit von Hausaufgaben betonen."}]},
  "emphasized": {label:"betonte",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer betonte die Wichtigkeit des Lesens."},{t:2,s:"Er betonte, dass Sicherheit an erster Stelle steht."},{t:3,s:"Der Bericht betonte die Notwendigkeit für neue Veränderungen."},{t:4,s:"Sie betonte die Rolle der Kommunikation im Team."},{t:5,s:"Der Trainer betonte die Ausdauer im letzten Spiel."}]},
  "emphasizes": {label:"betont",gender:"",plural:"—", ex5:[{t:1,s:"Der Bericht betont die Bedeutung von Teamarbeit."},{t:2,s:"Meine Mutter betont immer eine gesunde Ernährung."},{t:3,s:"Der Trainer betont die Schnelligkeit in jedem Training."},{t:4,s:"Dieses Buch betont die Wichtigkeit der Praxis."},{t:5,s:"Er betont oft seine jahrelange Erfahrung."}]},
  "emphasizing": {label:"betonend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer spricht, die Wichtigkeit des Lesens betonend."},{t:2,s:"Sie wiederholte den Satz, die richtige Aussprache betonend."},{t:3,s:"Er erklärte den Plan, jeden einzelnen Schritt betonend."},{t:4,s:"Der Künstler malte das Bild, die feinen Details betonend."},{t:5,s:"Sie stand vor uns, ihre Unabhängigkeit betonend."}]},
  "emphatic": {label:"nachdrücklich",gender:"",plural:"—", ex5:[{t:1,s:"Sie gab eine nachdrückliche Absage."},{t:2,s:"Sein nachdrücklicher Ton ließ keinen Zweifel offen."},{t:3,s:"Das Team errang einen nachdrücklichen Sieg."},{t:4,s:"Er betonte seine Meinung in nachdrücklicher Weise."},{t:5,s:"Es war eine nachdrückliche Bitte um Hilfe."}]},
  "emphatically": {label:"nachdrücklich",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat die Gerüchte nachdrücklich dementiert."},{t:2,s:"Er erklärte nachdrücklich, dass er nicht zurücktreten werde."},{t:3,s:"Sie haben den neuen Vorschlag nachdrücklich abgelehnt."},{t:4,s:"Er widersprach dem Bericht nachdrücklich."},{t:5,s:"Wir müssen nachdrücklich auf die Regeln hinweisen."}]},
  "emphysema": {label:"Lungenemphysem",gender:"das",plural:"Lungenemphyseme", ex5:[{t:1,s:"Rauchen ist eine Hauptursache für ein Lungenemphysem."},{t:2,s:"Er hat wegen seines Lungenemphysems Atembeschwerden."},{t:3,s:"Das Lungenemphysem verursacht bleibende Schäden an der Lunge."},{t:4,s:"Ein Lungenemphysem wird oft erst spät erkannt."},{t:5,s:"Die Therapie bei einem Lungenemphysem ist langwierig."}]},
  "empire": {label:"Reich",gender:"das",plural:"Reiche", ex5:[{t:1,s:"Das Reich ist untergegangen."},{t:2,s:"Das Reich erstreckte sich über viele Länder."},{t:3,s:"Wir haben im Unterricht viel über das römische Reich gelernt."},{t:4,s:"Die Geschichte zeigt den Aufstieg und Fall jedes Reichs."},{t:5,s:"Das Reich war für seine Kultur bekannt."}]},
  "empires": {label:"Reiche",gender:"die (Pl.)",plural:"Reiche", ex5:[{t:1,s:"Wir haben den Aufstieg und Fall antiker Reiche studiert."},{t:2,s:"Die Geschichte ist voller Geschichten über mächtige Reiche."},{t:3,s:"Die Karte zeigt die Grenzen verschiedener Reiche."},{t:4,s:"Viele Reiche sind im Laufe der Zeit verschwunden."},{t:5,s:"Man kann viel aus dem Vergleich alter Reiche lernen."}]},
  "empirical": {label:"empirisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie stützten sich auf empirische Belege."},{t:2,s:"Die Behauptung mangelt an empirischer Grundlage."},{t:3,s:"Empirische Tests haben die Theorie bestätigt."},{t:4,s:"Wir brauchen empirische Daten für diese Studie."},{t:5,s:"Das ist eine empirische Untersuchung."}]},
  "empirically": {label:"empirisch",gender:"",plural:"—", ex5:[{t:1,s:"Diese Theorie wurde von vielen Wissenschaftlern empirisch überprüft."},{t:2,s:"Wir müssen diese Ergebnisse empirisch verifizieren, bevor wir sie veröffentlichen."},{t:3,s:"Die Studie zeigt empirisch den Zusammenhang zwischen Ernährung und Gesundheit."},{t:4,s:"Der Effekt lässt sich empirisch nachweisen."},{t:5,s:"Die Daten wurden empirisch erhoben."}]},
