  "entree": {label:"Hauptgericht",gender:"das",plural:"Hauptgerichte", ex5:[{t:1,s:"Ich habe das Steak als Hauptgericht gewählt."},{t:2,s:"Das Restaurant bietet viele verschiedene Hauptgerichte an."},{t:3,s:"Welches Hauptgericht können Sie heute empfehlen?"},{t:4,s:"Das Hauptgericht hat sehr gut geschmeckt."},{t:5,s:"Nach dem Hauptgericht gab es ein Dessert."}]},
  "entrench": {label:"verankern",gender:"",plural:"—", ex5:[{t:1,s:"Alte Gewohnheiten sind tief verankert."},{t:2,s:"Sie konnten ihre Machtposition weiter verankern."},{t:3,s:"Diese Idee ist fest in ihrer Kultur verankert."},{t:4,s:"Wir müssen die neuen Regeln im Unternehmen verankern."},{t:5,s:"Solche Werte sind tief in unserem Denken verankert."}]},
  "entrenched": {label:"verankert",gender:"",plural:"—", ex5:[{t:1,s:"Diese Überzeugungen sind tief in ihrer Kultur verankert."},{t:2,s:"Die Soldaten waren in den tiefen Schützengräben verankert."},{t:3,s:"Alte Gewohnheiten sind oft schwer zu ändern, wenn sie erst einmal verankert sind."},{t:4,s:"Vorurteile sind fest in der Gesellschaft verankert."},{t:5,s:"Diese Idee ist tief in unserem Denken verankert."}]},
