  "entrepreneurial": {label:"unternehmerisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat einen sehr unternehmerischen Geist."},{t:2,s:"Das Programm fördert unternehmerisches Denken bei den Studierenden."},{t:3,s:"Er hat sein eigenes Unternehmen mit seinen unternehmerischen Fähigkeiten gegründet."},{t:4,s:"Sie zeigte ein unternehmerisches Talent bei diesem Projekt."},{t:5,s:"Das ist eine sehr unternehmerische Herangehensweise."}]},
  "entrepreneurs": {label:"Unternehmer",gender:"der",plural:"Unternehmer", ex5:[{t:1,s:"Viele junge Unternehmer gründen ihre eigenen Firmen."},{t:2,s:"Erfolgreiche Unternehmer gehen oft kalkulierte Risiken ein."},{t:3,s:"Die Konferenz versammelte berühmte Unternehmer aus der ganzen Welt."},{t:4,s:"Unternehmer spielen eine wichtige Rolle für die Wirtschaft."},{t:5,s:"Sie ist eine der bekanntesten Unternehmerinnen des Landes."}]},
  "entrepreneurship": {label:"Unternehmertum",gender:"das",plural:"—", ex5:[{t:1,s:"Der Kurs lehrt Unternehmertum."},{t:2,s:"Unternehmertum treibt neue Geschäftsideen voran."},{t:3,s:"Sie hat ein echtes Talent für Unternehmertum."},{t:4,s:"Das Unternehmertum ist ein wichtiger Motor der Wirtschaft."},{t:5,s:"Er interessiert sich sehr für das Thema Unternehmertum."}]},
  "entries": {label:"Einträge",gender:"die",plural:"Einträge", ex5:[{t:1,s:"Bitte reichen Sie Ihre Beiträge für den Wettbewerb bis Freitag ein."},{t:2,s:"Das Tagebuch enthält viele interessante Einträge von ihrer Reise."},{t:3,s:"Überprüfen Sie die Datenbank auf alle neuen Einträge."},{t:4,s:"Ich habe alle Einträge in der Liste gelesen."},{t:5,s:"Die Einträge im Kalender sind sehr wichtig."}]},
  "entropy": {label:"Entropie",gender:"die",plural:"—", ex5:[{t:1,s:"Das Konzept der Entropie erklärt, warum Systeme unordentlicher werden."},{t:2,s:"In der Physik ist die Entropie ein Maß für die Unordnung."},{t:3,s:"Mit der Zeit nimmt die Entropie des Universums tendenziell zu."},{t:4,s:"Die Entropie ist ein zentraler Begriff der Thermodynamik."},{t:5,s:"Man kann die Entropie eines Systems berechnen."}]},
  "entrust": {label:"anvertrauen",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat ihrer Freundin die Schlüssel anvertraut."},{t:2,s:"Sie haben das Kind einem Babysitter anvertraut."},{t:3,s:"Er hat die Aufgabe seinem Team anvertraut."},{t:4,s:"Ich kann dir mein Geheimnis anvertrauen."},{t:5,s:"Er vertraute ihr die Leitung des Projekts an."}]},
