  "enumeration": {label:"Aufzählung",gender:"die",plural:"Aufzählungen", ex5:[{t:1,s:"Der Bericht enthält eine Aufzählung aller Kosten."},{t:2,s:"Die Lehrerin bat um eine Aufzählung der Planeten."},{t:3,s:"Eine genaue Aufzählung der Gegenstände ist wichtig."},{t:4,s:"Die Aufzählung der Fehler dauerte lange."},{t:5,s:"Hier finden Sie eine kurze Aufzählung der Regeln."}]},
  "enunciate": {label:"deutlich aussprechen",gender:"",plural:"—", ex5:[{t:1,s:"Bitte versuchen Sie, jedes Wort deutlich aussprechen."},{t:2,s:"Sie muss ihre Pläne vor dem Team deutlich aussprechen."},{t:3,s:"Er hat gelernt, auf der Bühne deutlich aussprechen."},{t:4,s:"Man sollte die Wörter immer deutlich aussprechen."},{t:5,s:"Er konnte die schwierigen Begriffe deutlich aussprechen."}]},
  "enunciation": {label:"Aussprache",gender:"die",plural:"Aussprachen", ex5:[{t:1,s:"Durch ihre klare Aussprache war jedes Wort verständlich."},{t:2,s:"Eine gute Aussprache hilft dem Sprecher sehr."},{t:3,s:"Der Schauspieler übte eine sorgfältige Aussprache."},{t:4,s:"Er hat eine sehr deutliche Aussprache."},{t:5,s:"Die Aussprache ist wichtig beim Lernen einer Sprache."}]},
  "envelop": {label:"einhüllen",gender:"",plural:"—", ex5:[{t:1,s:"Nebel begann das ganze Tal zu einhüllen."},{t:2,s:"Die Dunkelheit konnte die stille Straße einhüllen."},{t:3,s:"Sie wollte das Baby in eine warme Decke einhüllen."},{t:4,s:"Der Rauch begann das Zimmer zu einhüllen."},{t:5,s:"Schnee wird bald die ganze Stadt einhüllen."}]},
  "envelope": {label:"Umschlag",gender:"der",plural:"Umschläge", ex5:[{t:1,s:"Der Umschlag ist fest verschlossen."},{t:2,s:"Ich habe einen weißen Umschlag gekauft."},{t:3,s:"Wir haben den Umschlag vorsichtig geöffnet."},{t:4,s:"Der Umschlag liegt auf dem Tisch."},{t:5,s:"Leg das Dokument bitte in einen Umschlag."}]},
  "enveloped": {label:"eingehüllt",gender:"",plural:"—", ex5:[{t:1,s:"Ein dichter Nebel hatte die ganze Stadt eingehüllt."},{t:2,s:"Sie hat sich in eine warme Decke eingehüllt."},{t:3,s:"Das geheimnisvolle Paket war in braunes Papier eingehüllt."},{t:4,s:"Die Berge waren in Wolken eingehüllt."},{t:5,s:"Er war in einen dicken Mantel eingehüllt."}]},
  "envelopes": {label:"umhüllen",gender:"",plural:"—", ex5:[{t:1,s:"Der Morgennebel beginnt den Berg zu umhüllen."},{t:2,s:"Stille beginnt den Raum zu umhüllen, wenn er liest."},{t:3,s:"Dunkle Wolken umhüllen die Stadt vor dem Sturm."},{t:4,s:"Der Duft der Blumen beginnt den Garten zu umhüllen."},{t:5,s:"Die Nacht wird bald die Welt umhüllen."}]},
  "enveloping": {label:"einhüllend",gender:"",plural:"—", ex5:[{t:1,s:"Ein dichter Nebel ist heute Morgen den ganzen Berg einhüllend."},{t:2,s:"Die Dunkelheit war den Wald einhüllend, als die Sonne unterging."},{t:3,s:"Sie fühlte eine warme Decke, die sie in der kalten Nacht einhüllend umschloss."},{t:4,s:"Die einhüllende Stille des Waldes wirkte beruhigend."},{t:5,s:"Der einhüllende Duft von frischem Kaffee weckte mich."}]},
  "enviable": {label:"beneidenswert",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat ein beneidenswertes Talent für das Klavierspielen."},{t:2,s:"Seine Fähigkeit, unter Druck ruhig zu bleiben, ist beneidenswert."},{t:3,s:"Sie leben in einem beneidenswerten Haus am Meer."},{t:4,s:"Er besitzt eine beneidenswerte Ausstrahlung."},{t:5,s:"Das ist eine beneidenswerte Gelegenheit für dich."}]},
  "envied": {label:"beneidet",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe ihre Fähigkeit beneidet, drei Sprachen zu sprechen."},{t:2,s:"Viele Menschen haben seinen Erfolg und Reichtum beneidet."},{t:3,s:"Sie hat den langen Urlaub ihrer Freundin beneidet."},{t:4,s:"Er wurde von vielen Kollegen um seine Position beneidet."},{t:5,s:"Niemand hat sie um diese schwere Aufgabe beneidet."}]},
  "envious": {label:"neidisch",gender:"",plural:"—", ex5:[{t:1,s:"Ich war neidisch, als sie den Preis gewonnen hat."},{t:2,s:"Sei nicht neidisch auf das, was andere haben."},{t:3,s:"Er warf einen neidischen Blick auf mein neues Auto."},{t:4,s:"Sie ist ein wenig neidisch auf sein Glück."},{t:5,s:"Es gibt keinen Grund, neidisch zu sein."}]},
  "environment": {label:"Umwelt",gender:"die",plural:"Umwelten", ex5:[{t:1,s:"Die Umwelt ist sehr wichtig."},{t:2,s:"Die Umwelt hier ist ruhig."},{t:3,s:"Wir müssen die Umwelt schützen."},{t:4,s:"Er setzt sich für eine saubere Umwelt ein."},{t:5,s:"Die Umwelt beeinflusst unsere Gesundheit."}]},
  "environmental": {label:"umweltbezogen",gender:"",plural:"—", ex5:[{t:1,s:"Die umweltbezogenen Regeln wurden verschärft."},{t:2,s:"Die umweltbezogene Auswirkung ist groß."},{t:3,s:"Wir haben umweltbezogenes Recht studiert."},{t:4,s:"Es gibt viele umweltbezogene Herausforderungen."},{t:5,s:"Das ist ein umweltbezogenes Projekt."}]},
  "environmentalism": {label:"Umweltschutz",gender:"der",plural:"—", ex5:[{t:1,s:"Sie interessiert sich sehr für Umweltschutz und Recycling."},{t:2,s:"Der Umweltschutz ist für viele Menschen weltweit eine Priorität geworden."},{t:3,s:"Er hat ein Buch über die Geschichte des modernen Umweltschutzes geschrieben."},{t:4,s:"Umweltschutz beginnt im Alltag."},{t:5,s:"Der Umweltschutz ist eine wichtige Aufgabe für die Zukunft."}]},
