  "erode": {label:"erodieren",gender:"",plural:"—", ex5:[{t:1,s:"Der Fluss beginnt langsam, das Ufer zu erodieren."},{t:2,s:"Starker Regen kann den Boden erodieren lassen."},{t:3,s:"Die Wellen erodieren die Felsen an der Küste."},{t:4,s:"Wind und Wasser erodieren die Oberfläche des Berges."},{t:5,s:"Die Landschaft erodiert durch die ständige Witterung."}]},
  "eroded": {label:"erodiert",gender:"",plural:"—", ex5:[{t:1,s:"Der starke Regen hat das Flussufer erodiert."},{t:2,s:"Die Küstenlinie wurde von den starken Wellen erodiert."},{t:3,s:"Über Millionen von Jahren hat der Wind die Felsen erodiert."},{t:4,s:"Der Boden ist durch die Erosion stark erodiert."},{t:5,s:"Die Landschaft ist durch die Flut erodiert."}]},
