  "evans": {label:"Evans",gender:"",plural:"—", ex5:[{t:1,s:"Herr Evans ist unser neuer Geschichtslehrer."},{t:2,s:"Die Familie Evans hat uns zum Abendessen eingeladen."},{t:3,s:"Ich habe Evans heute Nachmittag in der Bibliothek gesehen."},{t:4,s:"Das Haus der Evans liegt am Ende der Straße."},{t:5,s:"Wir haben Evans gestern im Park getroffen."}]},
  "evanston": {label:"Evanston",gender:"",plural:"—", ex5:[{t:1,s:"Evanston ist für seine berühmte Universität bekannt."},{t:2,s:"Ich habe vier Jahre lang in Evanston gelebt."},{t:3,s:"Viele Studenten wohnen in Evanston."},{t:4,s:"Evanston liegt direkt am Michigansee."},{t:5,s:"Wir besuchen bald Freunde in Evanston."}]},
  "evaporate": {label:"verdampfen",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser in der Pfütze wird in der Sonne schnell verdampfen."},{t:2,s:"Manche Flüssigkeiten verdampfen bei Zimmertemperatur."},{t:3,s:"Sein Selbstvertrauen schien zu verdampfen, als er die Bühne betrat."},{t:4,s:"Der Alkohol ist schnell verdampft."},{t:5,s:"Man kann sehen, wie der Dampf aus der Suppe verdampft."}]},
  "evaporated": {label:"verdampft",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser in der Pfütze ist unter der Sonne verdampft."},{t:2,s:"All seine Hoffnungen sind verdampft, als er die Nachricht hörte."},{t:3,s:"Der Alkohol ist schnell von der Oberfläche verdampft."},{t:4,s:"Die Flüssigkeit ist vollständig verdampft."},{t:5,s:"Seine Begeisterung ist einfach verdampft."}]},
  "evaporating": {label:"verdampfend",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser in der Pfütze ist gerade schnell verdampfend."},{t:2,s:"Meine Geduld ist beim Warten in der Schlange am Verdampfen."},{t:3,s:"Man sieht den Dampf, der aus der heißen Suppe verdampft."},{t:4,s:"Die Flüssigkeit ist an der Luft verdampfend."},{t:5,s:"Der Tau ist unter der Sonne am Verdampfen."}]},
