  "exposure": {label:"Exposition",gender:"die",plural:"Expositionen", ex5:[{t:1,s:"Die Exposition ist bei diesem Bild zu hoch eingestellt."},{t:2,s:"Die Exposition gegenüber der Sonne verursachte einen Sonnenbrand."},{t:3,s:"Wir haben die Exposition so gering wie möglich gehalten."},{t:4,s:"Eine lange Exposition kann gesundheitliche Folgen haben."},{t:5,s:"Die richtige Exposition ist wichtig für gute Fotos."}]},
  "exposures": {label:"Expositionen",gender:"die",plural:"Expositionen", ex5:[{t:1,s:"Häufige Expositionen gegenüber Sonnenlicht können gesund sein."},{t:2,s:"Die Künstlerin hatte viele Expositionen zu verschiedenen Kulturen."},{t:3,s:"Er sorgt sich um die Expositionen seines Privatlebens im Internet."},{t:4,s:"Diese Expositionen zeigen die Vielfalt des Projekts."},{t:5,s:"Wir haben verschiedene Expositionen in der Ausstellung gesehen."}]},
  "expound": {label:"erläutern",gender:"",plural:"—", ex5:[{t:1,s:"Er erläuterte seine Ansichten ausführlich."},{t:2,s:"Der Lehrer erläuterte die schwierige Idee."},{t:3,s:"Sie erläuterte den Plan im Detail."},{t:4,s:"Können Sie mir das bitte näher erläutern?"},{t:5,s:"Er erläuterte den Sachverhalt sehr präzise."}]},
  "expounded": {label:"erläuterte",gender:"",plural:"—", ex5:[{t:1,s:"Der Professor erläuterte die Theorie zwei Stunden lang."},{t:2,s:"Er erläuterte seine Ansichten zur Bildung auf dem Treffen."},{t:3,s:"Sie erläuterte die Spielregeln für die neuen Spieler."},{t:4,s:"Er erläuterte den Vorfall ausführlich."},{t:5,s:"Der Experte erläuterte die komplexen Zusammenhänge."}]},
  "express": {label:"ausdrücken",gender:"",plural:"—", ex5:[{t:1,s:"Worte drücken Gefühle aus."},{t:2,s:"Wir möchten unseren Dank ausdrücken."},{t:3,s:"Er kann seine Meinung gut ausdrücken."},{t:4,s:"Kunst hilft dabei, sich auszudrücken."},{t:5,s:"Wie drückt man das auf Deutsch aus?"}]},
  "expressed": {label:"drückte aus",gender:"",plural:"—", ex5:[{t:1,s:"Sie drückte ihre Dankbarkeit mit einem Lächeln aus."},{t:2,s:"Er drückte seine Meinung während des Treffens klar aus."},{t:3,s:"Sie drückten ihre Bedenken bezüglich des neuen Plans aus."},{t:4,s:"Er drückte seine Freude über den Erfolg aus."},{t:5,s:"Sie drückte ihre Bewunderung für das Werk aus."}]},
  "expresses": {label:"drückt aus",gender:"",plural:"—", ex5:[{t:1,s:"Er drückt seine Gefühle durch Musik aus."},{t:2,s:"Sie drückt ihren Dank für das Geschenk aus."},{t:3,s:"Das Gedicht drückt die Liebe zur Natur aus."},{t:4,s:"Er drückt seine Zufriedenheit mit einem Lächeln aus."},{t:5,s:"Diese Kunst drückt eine tiefe Sehnsucht aus."}]},
  "expressing": {label:"ausdrückend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist geschickt darin, ihre Gefühle auszudrücken."},{t:2,s:"Er war gerade dabei, seinen Dank auszudrücken."},{t:3,s:"Kunst ist eine Art, sich auszudrücken."},{t:4,s:"Das Ausdrücken von Gedanken fällt ihm leicht."},{t:5,s:"Sie ist sehr gut im Ausdrücken ihrer Meinung."}]},
  "expression": {label:"Ausdruck",gender:"der",plural:"Ausdrücke", ex5:[{t:1,s:"Der Ausdruck änderte sich."},{t:2,s:"Sein Ausdruck ist sehr freundlich."},{t:3,s:"Wir lesen ihren Ausdruck in ihrem Gesicht."},{t:4,s:"Sie hat einen sehr ernsten Ausdruck."},{t:5,s:"Sein Ausdruck verriet seine Nervosität."}]},
  "expressionism": {label:"Expressionismus",gender:"der",plural:"—", ex5:[{t:1,s:"Er interessiert sich sehr für den deutschen Expressionismus."},{t:2,s:"Das Museum veranstaltete eine Ausstellung zum Expressionismus."},{t:3,s:"Der Expressionismus nutzt oft verzerrte Formen und Farben."},{t:4,s:"Der Expressionismus ist eine wichtige Epoche der Kunst."},{t:5,s:"Sie schreibt eine Arbeit über den Expressionismus."}]},
  "expressionist": {label:"Expressionist",gender:"der",plural:"Expressionisten", ex5:[{t:1,s:"Er ist ein berühmter Expressionist aus dem frühen 20. Jahrhundert."},{t:2,s:"Die Ausstellung zeigt viele Werke von Expressionisten."},{t:3,s:"Sie liebt den emotionalen Stil der expressionistischen Kunst."},{t:4,s:"Der Maler gilt als wichtiger Expressionist."},{t:5,s:"Viele Expressionisten lebten in dieser Zeit in Berlin."}]},
  "expressions": {label:"Ausdrücke",gender:"die",plural:"Ausdrücke", ex5:[{t:1,s:"Er hat viele verschiedene Gesichtsausdrücke, wenn er erzählt."},{t:2,s:"Manche englische Ausdrücke sind für Anfänger schwer zu verstehen."},{t:3,s:"Sie benutzte kreative Ausdrücke in ihrem neuesten Gedicht."},{t:4,s:"Seine Ausdrücke sind oft sehr lebendig."},{t:5,s:"Diese Sprache hat viele interessante Ausdrücke."}]},
  "expressive": {label:"ausdrucksstark",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat sehr ausdrucksstarke Augen, die ihre Gefühle zeigen."},{t:2,s:"Der Schauspieler lieferte eine ausdrucksstarke Darbietung auf der Bühne."},{t:3,s:"Sein Gesicht ist so ausdrucksstark, dass er kaum sprechen muss."},{t:4,s:"Das Gemälde zeigt ein sehr ausdrucksstarkes Porträt."},{t:5,s:"Sie erzählte die Geschichte mit einer ausdrucksstarken Mimik."}]},
