  "extent": {label:"Ausmaß",gender:"das",plural:"Ausmaße", ex5:[{t:1,s:"Das Ausmaß ist unbekannt."},{t:2,s:"Das Ausmaß des Schadens ist groß."},{t:3,s:"Wir haben das Ausmaß gemessen."},{t:4,s:"Das Ausmaß der Krise ist besorgniserregend."},{t:5,s:"Man kann das Ausmaß nur schwer einschätzen."}]},
  "extenuate": {label:"abmildern",gender:"",plural:"—", ex5:[{t:1,s:"Nichts kann eine solche Grausamkeit abmildern."},{t:2,s:"Die Tatsachen konnten seine Schuld nicht abmildern."},{t:3,s:"Sie nannten Gründe, um die Tat abzumildern."},{t:4,s:"Diese Umstände mildern das Urteil ab."},{t:5,s:"Man versuchte, die harten Worte abzumildern."}]},
