  "extinguish": {label:"löschen",gender:"",plural:"—", ex5:[{t:1,s:"Die Feuerwehr hat den Brand gelöscht."},{t:2,s:"Sie löschte die Kerze vor dem Schlafengehen."},{t:3,s:"Wasser löschte das kleine Feuer schnell."},{t:4,s:"Bitte löschen Sie das Feuer gründlich."},{t:5,s:"Er löschte seine Zigarette, bevor er das Gebäude betrat."}]},
  "extinguished": {label:"gelöscht",gender:"",plural:"—", ex5:[{t:1,s:"Die Feuerwehr hat das kleine Feuer schnell gelöscht."},{t:2,s:"Er hatte seine Zigarette gelöscht, bevor er das Gebäude betrat."},{t:3,s:"Alle Hoffnung war gelöscht, als das Rettungsteam niemanden fand."},{t:4,s:"Das Feuer wurde durch den Regen gelöscht."},{t:5,s:"Die Kerze war bereits gelöscht."}]},
