  "faithful": {label:"treu",gender:"",plural:"—", ex5:[{t:1,s:"Der Hund ist seinem Besitzer treu."},{t:2,s:"Er ist ein treuer Freund."},{t:3,s:"Wir sind uns immer treu geblieben."},{t:4,s:"Sie ist eine treue Mitarbeiterin."},{t:5,s:"Bleib mir treu."}]},
  "faithfully": {label:"treu",gender:"",plural:"—", ex5:[{t:1,s:"Der Hund wartete treu auf sein Herrchen."},{t:2,s:"Sie hat der Firma zwanzig Jahre treu gedient."},{t:3,s:"Bitte befolge die Anweisungen treu."},{t:4,s:"Er erledigt seine Aufgaben treu."},{t:5,s:"Sie bleibt ihren Prinzipien treu."}]},
  "faithfulness": {label:"Treue",gender:"die",plural:"—", ex5:[{t:1,s:"Er ist für seine Treue zu seiner Frau bekannt."},{t:2,s:"Treue ist ein wichtiger Teil unserer Freundschaft."},{t:3,s:"Der Hund ist für seine Treue berühmt."},{t:4,s:"Man sollte die Treue schätzen."},{t:5,s:"Ihre Treue ist bewundernswert."}]},
