  "fake": {label:"Fälschung",gender:"die",plural:"Fälschungen", ex5:[{t:1,s:"Die Tasche ist eine Fälschung."},{t:2,s:"Das Lächeln ist eine Fälschung."},{t:3,s:"Wir haben die Fälschung sofort erkannt."},{t:4,s:"Es handelte sich um eine billige Fälschung."},{t:5,s:"Er verkaufte mir eine Fälschung."}]},
  "faked": {label:"gefälscht",gender:"",plural:"—", ex5:[{t:1,s:"Er hat seine Krankheit gefälscht, um zu Hause zu bleiben."},{t:2,s:"Der Kriminelle hat seine Unterschrift auf dem Dokument gefälscht."},{t:3,s:"Sie hat während des Meetings ein Lächeln gefälscht."},{t:4,s:"Er hat die Beweise gefälscht."},{t:5,s:"Der Pass wurde gefälscht."}]},
  "faker": {label:"Hochstapler",gender:"der",plural:"Hochstapler", ex5:[{t:1,s:"Vertrau ihm nicht, er ist ein Hochstapler."},{t:2,s:"Das Gemälde wurde als Werk eines Hochstaplers entlarvt."},{t:3,s:"Sie konnte einen Hochstapler sofort erkennen."},{t:4,s:"Er ist als Hochstapler bekannt."},{t:5,s:"Der Hochstapler wurde gefasst."}]},
  "fakes": {label:"Fälschung",gender:"die",plural:"Fälschungen", ex5:[{t:1,s:"Sei vorsichtig, denn online werden viele Fälschungen verkauft."},{t:2,s:"Er erkennt die Fälschungen unter den Luxustaschen sofort."},{t:3,s:"Das Museum hat alle Fälschungen aus der Ausstellung entfernt."},{t:4,s:"Es ist schwer, diese Fälschung vom Original zu unterscheiden."},{t:5,s:"Der Handel mit Fälschungen ist illegal."}]},
  "faking": {label:"vortäuschen",gender:"",plural:"—", ex5:[{t:1,s:"Er täuschte eine Krankheit vor, um nicht zur Schule gehen zu müssen."},{t:2,s:"Hör auf, dein Lächeln vorzutäuschen; ich weiß, dass du traurig bist."},{t:3,s:"Sie wurde dabei erwischt, wie sie ihre Unterschrift vortäuschte."},{t:4,s:"Er täuscht oft vor, beschäftigt zu sein."},{t:5,s:"Man sollte nicht immer Gefühle vortäuschen."}]},
  "falafel": {label:"Falafel",gender:"die",plural:"Falafel", ex5:[{t:1,s:"Ich habe heute zum Mittagessen ein leckeres Falafel-Sandwich bestellt."},{t:2,s:"Falafel ist ein beliebtes nahöstliches Gericht aus Kichererbsen."},{t:3,s:"Sie hat gelernt, wie man zu Hause knusprige Falafel macht."},{t:4,s:"Möchtest du auch eine Portion Falafel probieren?"},{t:5,s:"Falafel schmecken am besten mit frischem Hummus."}]},
  "falcao": {label:"Falcao",gender:"",plural:"—", ex5:[{t:1,s:"Falcao ist für seine unglaublichen Schussfähigkeiten bekannt."},{t:2,s:"Viele Fans jubelten Falcao während des Spiels zu."},{t:3,s:"Falcao hat einen neuen Vertrag beim Verein unterschrieben."},{t:4,s:"Alle Augen waren auf Falcao gerichtet."},{t:5,s:"Falcao zeigte heute eine starke Leistung auf dem Platz."}]},
  "falco": {label:"Falco",gender:"der",plural:"—", ex5:[{t:1,s:"Falco ist ein talentierter Musiker aus unserer Schule."},{t:2,s:"Ich habe Falco eingeladen, unserer Lerngruppe beizutreten."},{t:3,s:"Falco hat mir eine lustige Geschichte über seine Katze erzählt."},{t:4,s:"Hast du Falco heute schon gesehen?"},{t:5,s:"Falco spielt sehr gut Gitarre."}]},
  "falcon": {label:"Falke",gender:"der",plural:"Falken", ex5:[{t:1,s:"Der Falke kreiste hoch über dem offenen Feld."},{t:2,s:"Ein Falke hat eine unglaubliche Sehkraft für die Jagd."},{t:3,s:"Ich sah einen Falken auf dem hohen Ast des Baumes sitzen."},{t:4,s:"Der Falke stürzte sich blitzschnell auf seine Beute."},{t:5,s:"Falken sind faszinierende Greifvögel."}]},
  "falconer": {label:"Falkner",gender:"der",plural:"Falkner", ex5:[{t:1,s:"Der Falkner trainierte den Vogel für die Jagd in der Wildnis."},{t:2,s:"Wir beobachteten, wie der Falkner den Falken in den Himmel entließ."},{t:3,s:"Der Falkner trug einen Lederhandschuh, um seine Hand zu schützen."},{t:4,s:"Ein Falkner braucht viel Geduld mit seinen Tieren."},{t:5,s:"Der Falkner erklärte uns die Kunst der Beizjagd."}]},
  "falconry": {label:"Falknerei",gender:"die",plural:"Falknereien", ex5:[{t:1,s:"Die Falknerei ist eine alte Jagdkunst."},{t:2,s:"Er praktiziert die Falknerei mit einem trainierten Falken."},{t:3,s:"Die Falknerei erfordert sehr viel Geduld."},{t:4,s:"Wir haben eine Vorführung der Falknerei besucht."},{t:5,s:"Die Falknerei hat eine lange Tradition."}]},
  "falcons": {label:"Falken",gender:"die",plural:"Falken", ex5:[{t:1,s:"Falken sind für ihre unglaubliche Geschwindigkeit bekannt."},{t:2,s:"Wir beobachteten die Falken, wie sie über der Klippe flogen."},{t:3,s:"Einige Falken jagen während des Tages."},{t:4,s:"Falken sind sehr geschickte Jäger."},{t:5,s:"Es gibt viele verschiedene Arten von Falken auf der Welt."}]},
  "falkirk": {label:"Falkirk",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben die Stadt Falkirk in Schottland besucht."},{t:2,s:"Das berühmte Schiffshebewerk befindet sich in Falkirk."},{t:3,s:"Er wuchs in einem kleinen Dorf in der Nähe von Falkirk auf."},{t:4,s:"Falkirk ist eine interessante Stadt für Touristen."},{t:5,s:"Hast du schon einmal von Falkirk gehört?"}]},
  "falkland": {label:"Falkland",gender:"",plural:"—", ex5:[{t:1,s:"Die Falklandinseln liegen im Atlantik."},{t:2,s:"Sie reisten für ihren Urlaub nach Falkland."},{t:3,s:"Die Geschichte von Falkland ist sehr interessant."},{t:4,s:"Das Klima auf Falkland ist oft rau."},{t:5,s:"Viele Touristen besuchen Falkland wegen der Natur."}]},
  "falklands": {label:"Falklandinseln",gender:"die",plural:"Falklandinseln", ex5:[{t:1,s:"Die Falklandinseln sind eine Inselgruppe im Südatlantik."},{t:2,s:"Viele Vögel ziehen jedes Jahr zu den Falklandinseln."},{t:3,s:"Sie schrieb ein Buch über ihre Reise zu den Falklandinseln."},{t:4,s:"Die Landschaft der Falklandinseln ist einzigartig."},{t:5,s:"Forscher untersuchen die Tierwelt auf den Falklandinseln."}]},
  "fall": {label:"fallen",gender:"",plural:"—", ex5:[{t:1,s:"Im Herbst fallen die Blätter von den Bäumen."},{t:2,s:"Die Preise fallen in dieser Jahreszeit."},{t:3,s:"Wir beobachten, wie der Regen fällt."},{t:4,s:"Er ist beim Laufen hingefallen."},{t:5,s:"Die Temperaturen fallen in der Nacht."}]},
  "fallacies": {label:"Fehlschlüsse",gender:"die",plural:"Fehlschlüsse", ex5:[{t:1,s:"Seine Argumentation basiert auf mehreren logischen Fehlschlüssen."},{t:2,s:"Wir müssen lernen, häufige Fehlschlüsse in den Nachrichten zu erkennen."},{t:3,s:"Viele Menschen glauben an Fehlschlüsse über Gesundheit und Ernährung."},{t:4,s:"Das Buch analysiert verschiedene logische Fehlschlüsse."},{t:5,s:"Man sollte vorsichtig bei Fehlschlüssen in der Debatte sein."}]},
  "fallacious": {label:"trugschlüssig",gender:"",plural:"—", ex5:[{t:1,s:"Es ist ein trugschlüssiges Argument, dass Geld immer glücklich macht."},{t:2,s:"Der Detektiv wies auf die trugschlüssige Begründung des Verdächtigen hin."},{t:3,s:"Viele Menschen haben die trugschlüssige Ansicht, dass Vitamine eine gesunde Ernährung ersetzen."},{t:4,s:"Die Logik hinter seiner Aussage ist trugschlüssig."},{t:5,s:"Man sollte keine trugschlüssigen Schlüsse ziehen."}]},
  "fallacy": {label:"Trugschluss",gender:"der",plural:"Trugschlüsse", ex5:[{t:1,s:"Es ist ein Trugschluss, dass Geld Freude kaufen kann."},{t:2,s:"Sein Argument beruhte auf einem logischen Trugschluss."},{t:3,s:"Der Lehrer wies auf den Trugschluss hin."},{t:4,s:"Man sollte sich nicht von diesem Trugschluss täuschen lassen."},{t:5,s:"Das ist ein klassischer Trugschluss in der Diskussion."}]},
  "fallback": {label:"Ausweichplan",gender:"der",plural:"Ausweichpläne", ex5:[{t:1,s:"Wir brauchen einen Ausweichplan, falls der erste Versuch fehlschlägt."},{t:2,s:"Etwas Bargeld zurückzulegen ist ein guter Ausweichplan für Notfälle."},{t:3,s:"Die Software bietet einen Ausweichplan, wenn die Internetverbindung abbricht."},{t:4,s:"Haben Sie immer einen Ausweichplan parat."},{t:5,s:"Der Ausweichplan hat uns vor großen Problemen bewahrt."}]},
  "fallen": {label:"gefallen",gender:"",plural:"—", ex5:[{t:1,s:"Die Blätter sind von den Bäumen gefallen."},{t:2,s:"Er hat sich in die Stadt gefallen, als er sie sah."},{t:3,s:"Der Schnee ist die ganze Nacht gefallen."},{t:4,s:"Die Vase ist vom Tisch gefallen."},{t:5,s:"Er ist tief in Gedanken gefallen."}]},
