  "falling": {label:"fallend",gender:"",plural:"—", ex5:[{t:1,s:"Die fallenden Blätter bedecken den Boden."},{t:2,s:"Ich beobachtete eine fallende Sternschnuppe."},{t:3,s:"Achten Sie auf fallende Steine am Wegrand."},{t:4,s:"Die fallenden Temperaturen kündigen den Winter an."},{t:5,s:"Er sah dem fallenden Regen zu."}]},
  "fallon": {label:"Fallon",gender:"",plural:"—", ex5:[{t:1,s:"Fallon ist eine sehr talentierte Musikerin."},{t:2,s:"Ich habe Fallon letzte Woche auf der Konferenz getroffen."},{t:3,s:"Fallon hat beschlossen, ihr eigenes Unternehmen zu gründen."},{t:4,s:"Fallon spielt hervorragend Gitarre."},{t:5,s:"Ich arbeite zusammen mit Fallon an einem Projekt."}]},
  "fallopian": {label:"Eileiter",gender:"der",plural:"Eileiter", ex5:[{t:1,s:"Der Arzt untersuchte den Eileiter."},{t:2,s:"Eine Entzündung im Eileiter kann Schmerzen verursachen."},{t:3,s:"Sie wurde wegen eines Verschlusses am Eileiter operiert."},{t:4,s:"Der Eileiter spielt eine wichtige Rolle bei der Empfängnis."},{t:5,s:"Die Untersuchung des Eileiters ergab keine Befunde."}]},
  "fallout": {label:"Folgen",gender:"die",plural:"Folgen", ex5:[{t:1,s:"Die Folgen des Skandals waren schwerwiegend."},{t:2,s:"Sie bereiteten sich auf die politischen Folgen vor."},{t:3,s:"Der radioaktive Niederschlag breitete sich weit aus."},{t:4,s:"Wir müssen mit den Folgen unseres Handelns leben."},{t:5,s:"Die Folgen der Entscheidung waren nicht absehbar."}]},
  "fallow": {label:"brachliegend",gender:"",plural:"—", ex5:[{t:1,s:"Der Bauer ließ das Feld ein Jahr lang brachliegen."},{t:2,s:"Sein kreatives Potenzial liegt seit Monaten brach."},{t:3,s:"Wir sollten unsere Talente nicht brachliegen lassen."},{t:4,s:"Das brachliegende Land muss neu bewirtschaftet werden."},{t:5,s:"Viele Flächen liegen in dieser Region brach."}]},
  "falls": {label:"fallen",gender:"",plural:"—", ex5:[{t:1,s:"Die Temperatur fällt in den Winternächten rapide."},{t:2,s:"Er fällt oft hin, wenn er versucht Schlittschuh zu laufen."},{t:3,s:"Der starke Regen fällt die ganze Nacht auf das Dach."},{t:4,s:"Die Blätter fallen im Herbst von den Bäumen."},{t:5,s:"Der Vorhang fällt nach dem letzten Akt."}]},
  "false": {label:"falsch",gender:"",plural:"—", ex5:[{t:1,s:"Diese Behauptung ist falsch."},{t:2,s:"Der Alarm war falsch."},{t:3,s:"Wir haben die falschen Daten verworfen."},{t:4,s:"Er hat eine falsche Entscheidung getroffen."},{t:5,s:"Das ist eine völlig falsche Annahme."}]},
  "falsehood": {label:"Lüge",gender:"die",plural:"Lügen", ex5:[{t:1,s:"Er wurde bei einer bewussten Lüge ertappt."},{t:2,s:"Es ist manchmal schwer, Wahrheit von Lüge zu unterscheiden."},{t:3,s:"Der Bericht war voller Lügen und Gerüchte."},{t:4,s:"Sie hat die Lüge schließlich zugegeben."},{t:5,s:"Eine Lüge führt oft zu weiteren Problemen."}]},
  "falsehoods": {label:"Lügen",gender:"die",plural:"Lügen", ex5:[{t:1,s:"Er erzählte viele Lügen, um seine Fehler zu verbergen."},{t:2,s:"Der Artikel war gespickt mit verschiedenen Lügen."},{t:3,s:"Wir müssen die Wahrheit von diesen Lügen unterscheiden."},{t:4,s:"Ihre Lügen kamen schließlich ans Licht."},{t:5,s:"Man sollte sich nicht auf Lügen stützen."}]},
  "falsely": {label:"fälschlicherweise",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde fälschlicherweise des Diebstahls beschuldigt."},{t:2,s:"Die Firma behauptete fälschlicherweise, das Produkt sei sicher."},{t:3,s:"Sie fühlte sich von anderen fälschlicherweise verurteilt."},{t:4,s:"Er wurde fälschlicherweise für einen Experten gehalten."},{t:5,s:"Die Daten wurden fälschlicherweise als korrekt markiert."}]},
  "falsetto": {label:"Falsett",gender:"das",plural:"Falsette", ex5:[{t:1,s:"Er sang die hohen Töne im Falsett."},{t:2,s:"Der Sänger ist für sein beeindruckendes Falsett bekannt."},{t:3,s:"Sie wechselte im Refrain in ein zartes Falsett."},{t:4,s:"Das Falsett erfordert eine spezielle Technik der Stimmbänder."},{t:5,s:"Mit einem gekonnten Falsett beendete er das Lied."}]},
  "falsification": {label:"Fälschung",gender:"die",plural:"Fälschungen", ex5:[{t:1,s:"Die Untersuchung deckte die Fälschung der Dokumente auf."},{t:2,s:"Die Fälschung von Wahlergebnissen ist ein schweres Verbrechen."},{t:3,s:"Er wurde wegen der Fälschung seiner Zeugnisse angeklagt."},{t:4,s:"Diese Unterschrift ist eine offensichtliche Fälschung."},{t:5,s:"Die Fälschung von Beweismitteln führte zu seiner Verurteilung."}]},
  "falsified": {label:"gefälscht",gender:"",plural:"—", ex5:[{t:1,s:"Der Zeuge hat die Beweise während des Prozesses gefälscht."},{t:2,s:"Er hat seine Unterlagen gefälscht, um den Job zu bekommen."},{t:3,s:"Der Wissenschaftler wurde entlassen, weil er die Daten gefälscht hat."},{t:4,s:"Die vorgelegten Dokumente waren komplett gefälscht."},{t:5,s:"Er hat seinen Lebenslauf gefälscht, um besser dazustehen."}]},
  "falsify": {label:"fälschen",gender:"",plural:"—", ex5:[{t:1,s:"Es ist strafbar, offizielle Dokumente zu fälschen."},{t:2,s:"Er versuchte, die Ergebnisse zu fälschen, um seinen Fehler zu vertuschen."},{t:3,s:"Der Forscher wurde beschuldigt, Daten fälschen zu wollen."},{t:4,s:"Man sollte niemals Beweise fälschen."},{t:5,s:"Versuche nicht, die Tatsachen zu fälschen."}]},
  "falsifying": {label:"fälschend",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde dabei erwischt, wie er die Finanzunterlagen fälschend manipulierte."},{t:2,s:"Das Fälschen von Daten ist in der Wissenschaft ein schweres Vergehen."},{t:3,s:"Sie bestritt, ihren Lebenslauf beim Fälschen der Angaben manipuliert zu haben."},{t:4,s:"Wer Daten fälschend verändert, riskiert seine Karriere."},{t:5,s:"Er wurde beim Fälschen der Unterschriften beobachtet."}]},
  "falter": {label:"wanken",gender:"",plural:"—", ex5:[{t:1,s:"Ihre Stimme begann zu wanken, als sie sprach."},{t:2,s:"Er ließ in seinem Einsatz niemals wanken."},{t:3,s:"Der Läufer kam kurz vor dem Ziel ins Wanken."},{t:4,s:"Lass deinen Mut in dieser Situation nicht wanken."},{t:5,s:"Seine Entschlossenheit begann zu wanken."}]},
  "faltered": {label:"wankte",gender:"",plural:"—", ex5:[{t:1,s:"Seine Stimme wankte, als er die erste Rede hielt."},{t:2,s:"Der Läufer wankte kurz, lief aber weiter."},{t:3,s:"Ihr Vertrauen wankte, als sie die schwere Prüfung sah."},{t:4,s:"Er wankte einen Moment, fand dann aber sein Gleichgewicht wieder."},{t:5,s:"Ihr Mut wankte angesichts der großen Herausforderung."}]},
  "faltering": {label:"wankend",gender:"",plural:"—", ex5:[{t:1,s:"Der Athlet wirkte gegen Ende des Rennens wankend."},{t:2,s:"Ihre Stimme klang wankend, als sie die schwierige Rede hielt."},{t:3,s:"Hör auf zu wanken und triff jetzt eine Entscheidung."},{t:4,s:"Mit wankendem Schritt ging er auf die Ziellinie zu."},{t:5,s:"Trotz wankender Zuversicht machte sie weiter."}]},
