  "fellowships": {label:"Stipendien",gender:"die",plural:"Stipendien", ex5:[{t:1,s:"Sie bewarb sich um mehrere Forschungsstipendien an der Universität."},{t:2,s:"Das Programm bietet Stipendien für talentierte junge Autoren."},{t:3,s:"Wir haben während unserer Zeit im Club starke Verbindungen aufgebaut."},{t:4,s:"Es gibt viele Stipendien für Studenten."},{t:5,s:"Er hat zwei Stipendien für seine Forschung erhalten."}]},
  "felon": {label:"Verbrecher",gender:"der",plural:"Verbrecher", ex5:[{t:1,s:"Die Polizei hat gestern Nacht den gefährlichen Verbrecher gefasst."},{t:2,s:"Nach dem Prozess wurde er als Verbrecher abgestempelt."},{t:3,s:"Der Verbrecher floh durch ein Fenster aus dem Gefängnis."},{t:4,s:"Jeder Verbrecher muss für seine Taten geradestehen."},{t:5,s:"Die Polizei sucht noch immer nach dem Verbrecher."}]},
  "felonies": {label:"Verbrechen",gender:"das",plural:"Verbrechen", ex5:[{t:1,s:"Er wurde wegen zweier schwerer Verbrechen angeklagt."},{t:2,s:"Der Anwalt argumentierte, dass es sich nicht um Verbrechen handelte."},{t:3,s:"Verbrechen werden viel härter bestraft als Vergehen."},{t:4,s:"Das Gesetz unterscheidet klar zwischen Verbrechen und kleineren Delikten."},{t:5,s:"Diese schweren Verbrechen erschütterten die gesamte Stadt."}]},
  "felons": {label:"Verbrecher",gender:"die",plural:"Verbrecher", ex5:[{t:1,s:"Das Gefängnis hält viele gefährliche Verbrecher fest."},{t:2,s:"In manchen Staaten dürfen Verbrecher nicht an Wahlen teilnehmen."},{t:3,s:"Die Polizei fing zwei Verbrecher, die aus dem Gefängnis ausgebrochen waren."},{t:4,s:"Die Gesellschaft muss vor diesen Verbrechern geschützt werden."},{t:5,s:"Alle Verbrecher wurden in ihre Zellen gebracht."}]},
  "felony": {label:"Verbrechen",gender:"das",plural:"Verbrechen", ex5:[{t:1,s:"Ein bewaffneter Raubüberfall ist ein schweres Verbrechen."},{t:2,s:"Er wurde letztes Jahr wegen eines Verbrechens verurteilt."},{t:3,s:"Ein Verbrechen kann eine lange Gefängnisstrafe nach sich ziehen."},{t:4,s:"Das war sein erstes schweres Verbrechen."},{t:5,s:"Jedes Verbrechen wird von der Staatsanwaltschaft genau untersucht."}]},
  "felt": {label:"fühlte",gender:"",plural:"—", ex5:[{t:1,s:"Ich fühlte mich vor der Prüfung nervös."},{t:2,s:"Sie fühlte sich glücklich, als sie das Geschenk sah."},{t:3,s:"Er fühlte sich nach der langen Reise müde."},{t:4,s:"Ich fühlte mich heute Morgen gar nicht gut."},{t:5,s:"Sie fühlte sich in der neuen Stadt sofort wohl."}]},
  "felton": {label:"Felton",gender:"",plural:"—", ex5:[{t:1,s:"Wir planen, nächstes Jahr nach Felton zu ziehen."},{t:2,s:"Felton ist eine kleine Stadt mit viel Charme."},{t:3,s:"Mein Cousin lebt in Felton und liebt das ruhige Leben dort."},{t:4,s:"Ich habe Felton im letzten Sommer besucht."},{t:5,s:"Felton ist ein schöner Ort zum Wohnen."}]},
  "fema": {label:"FEMA",gender:"die",plural:"—", ex5:[{t:1,s:"Die FEMA leistet Hilfe für Menschen, die von Katastrophen betroffen sind."},{t:2,s:"Nach dem Hurrikan arbeitete die lokale Regierung eng mit der FEMA zusammen."},{t:3,s:"Die FEMA hat Hilfsgüter in das Hochwassergebiet geschickt."},{t:4,s:"Viele Menschen vertrauen auf die Unterstützung der FEMA."},{t:5,s:"Die FEMA koordiniert die Rettungsarbeiten vor Ort."}]},
  "female": {label:"weiblich",gender:"",plural:"—", ex5:[{t:1,s:"Das weibliche Tier führt das Rudel an."},{t:2,s:"Der weibliche Vogel sang ein schönes Lied."},{t:3,s:"Wir haben die weiblichen Wähler gezählt."},{t:4,s:"Sie ist ein weibliches Mitglied des Vorstands."},{t:5,s:"Die weibliche Stimme war sehr klar zu hören."}]},
  "females": {label:"Frauen",gender:"die",plural:"Frauen", ex5:[{t:1,s:"Die Studie konzentriert sich auf die Gesundheit von Frauen in der Stadt."},{t:2,s:"Bei dieser Tierart sind die Weibchen meist größer als die Männchen."},{t:3,s:"Viele Frauen arbeiten als Führungskräfte in dieser Organisation."},{t:4,s:"Frauen spielen eine wichtige Rolle in der modernen Gesellschaft."},{t:5,s:"Die meisten Frauen stimmten dem Vorschlag zu."}]},
  "feminine": {label:"feminin",gender:"",plural:"—", ex5:[{t:1,s:"Sie trägt gerne feminine Kleidung, wie Kleider."},{t:2,s:"Das Zimmer war sehr feminin eingerichtet."},{t:3,s:"Manche Leute finden, diese Farbe ist ziemlich feminin."},{t:4,s:"Er bewundert ihre feminine Ausstrahlung."},{t:5,s:"Sie hat eine sehr feminine Stimme."}]},
  "femininity": {label:"Weiblichkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Sie ist stolz auf ihre natürliche Weiblichkeit."},{t:2,s:"Das Kleid unterstreicht ihre sanfte Weiblichkeit."},{t:3,s:"Verschiedene Kulturen definieren Weiblichkeit auf unterschiedliche Weise."},{t:4,s:"Sie drückt ihre Weiblichkeit durch ihre Kleidung aus."},{t:5,s:"Die Bedeutung von Weiblichkeit hat sich in der Gesellschaft gewandelt."}]},
  "feminism": {label:"Feminismus",gender:"der",plural:"—", ex5:[{t:1,s:"Sie ist seit vielen Jahren eine starke Unterstützerin des Feminismus."},{t:2,s:"Das Buch bietet eine moderne Perspektive auf den Feminismus."},{t:3,s:"Der Feminismus setzt sich für gleiche Rechte und Chancen für alle ein."},{t:4,s:"Sie beschäftigt sich intensiv mit dem Feminismus."},{t:5,s:"Der Feminismus hat die Gesellschaft nachhaltig geprägt."}]},
  "feminist": {label:"Feminist",gender:"der",plural:"Feministen", ex5:[{t:1,s:"Sie ist eine stolze Feministin, die für Geschlechtergleichheit kämpft."},{t:2,s:"Das Buch erforscht die Geschichte der feministischen Bewegung."},{t:3,s:"Er bezeichnet sich selbst als Feministen und unterstützt gleichen Lohn."},{t:4,s:"Sie ist eine bekannte Feministin in unserer Stadt."},{t:5,s:"Als Feminist setzt er sich für Frauenrechte ein."}]},
  "feminists": {label:"Feministinnen",gender:"die",plural:"Feministinnen", ex5:[{t:1,s:"Viele Feministinnen kämpfen für gleiche Rechte aller Frauen."},{t:2,s:"An der Konferenz nahmen viele berühmte Feministinnen teil."},{t:3,s:"Feministinnen haben eine Schlüsselrolle beim sozialen Wandel gespielt."},{t:4,s:"Die Arbeit dieser Feministinnen ist sehr wichtig."},{t:5,s:"Viele Feministinnen setzen sich für soziale Gerechtigkeit ein."}]},
  "femme": {label:"Femme",gender:"die",plural:"Femmes", ex5:[{t:1,s:"Sie kleidet sich gerne in einem sehr femininen Stil."},{t:2,s:"Die Modenschau betonte einen mutigen und femininen Look."},{t:3,s:"Sie identifiziert sich als Femme in der LGBTQ+-Community."},{t:4,s:"Ihr Stil ist sehr ausgeprägt femme."},{t:5,s:"Sie liebt es, sich feminin zu präsentieren."}]},
  "femoral": {label:"femoral",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt untersuchte die arteria femoralis sorgfältig."},{t:2,s:"Er erlitt während des Fußballspiels einen femoralen Bruch."},{t:3,s:"Der femorale Knochen ist der längste Knochen im Körper."},{t:4,s:"Die femorale Region wurde genau beobachtet."},{t:5,s:"Die Behandlung der femoralen Verletzung verlief gut."}]},
  "femur": {label:"Femur",gender:"der",plural:"Femura", ex5:[{t:1,s:"Der Femur ist der längste Knochen im menschlichen Körper."},{t:2,s:"Er hat sich bei einem Skiunfall den Femur gebrochen."},{t:3,s:"Der Arzt untersuchte den Femur des Patienten."},{t:4,s:"Ein Bruch des Femurs erfordert oft eine Operation."},{t:5,s:"Der Femur ist sehr stabil gebaut."}]},
  "fen": {label:"Moor",gender:"das",plural:"Moore", ex5:[{t:1,s:"Der seltene Vogel lebt im tiefen Moor."},{t:2,s:"Es ist gefährlich, nachts durch das Moor zu wandern."},{t:3,s:"Viele Pflanzen wachsen gut im feuchten Boden des Moors."},{t:4,s:"Das Moor ist ein wichtiges Ökosystem."},{t:5,s:"Wir haben das Moor bei unserem Ausflug besucht."}]},
