  "ferrari": {label:"Ferrari",gender:"der",plural:"Ferraris", ex5:[{t:1,s:"Er träumt davon, eines Tages einen roten Ferrari zu fahren."},{t:2,s:"Dieser Ferrari ist das schnellste Auto auf der Rennstrecke."},{t:3,s:"Sie sah einen neuen Ferrari draußen parken."},{t:4,s:"Ein Ferrari ist ein Symbol für Luxus und Geschwindigkeit."},{t:5,s:"Viele Menschen bewundern die Ferraris auf der Automesse."}]},
  "ferrell": {label:"Ferrell",gender:"",plural:"—", ex5:[{t:1,s:"Will Ferrell ist ein sehr berühmter Komiker."},{t:2,s:"Ich habe gestern einen Film mit Ferrell gesehen."},{t:3,s:"Die schauspielerische Leistung von Ferrell in diesem Film war urkomisch."},{t:4,s:"Ferrell ist ein talentierter Schauspieler."},{t:5,s:"Ich mag die Filme, in denen Ferrell mitspielt."}]},
