  "fictional": {label:"fiktiv",gender:"",plural:"—", ex5:[{t:1,s:"Sherlock Holmes ist eine berühmte fiktive Figur."},{t:2,s:"Dieser Film basiert auf einer fiktiven Geschichte."},{t:3,s:"Sie leben auf einer fiktiven Insel mitten im Ozean."},{t:4,s:"Das sind nur fiktive Namen in diesem Bericht."},{t:5,s:"Er hat eine fiktive Welt in seinem Roman erschaffen."}]},
  "fictitious": {label:"erfunden",gender:"",plural:"—", ex5:[{t:1,s:"Die Charaktere in diesem Roman sind völlig erfunden."},{t:2,s:"Er gab der Polizei einen erfundenen Namen."},{t:3,s:"Die Geschichte spielt in einem erfundenen Land."},{t:4,s:"Das ist eine völlig erfundene Geschichte."},{t:5,s:"Er musste sich eine erfundene Ausrede einfallen lassen."}]},
  "fiddle": {label:"Fiedel",gender:"die",plural:"Fiedeln", ex5:[{t:1,s:"Er lernte in seiner Jugend, die Fiedel zu spielen."},{t:2,s:"Die Band spielte ein schnelles Lied auf der Fiedel."},{t:3,s:"Sie bewahrt ihre Fiedel in einem Samtkasten auf."},{t:4,s:"Der Klang der Fiedel war sehr fröhlich."},{t:5,s:"Sie spielt oft auf einer alten Fiedel."}]},
  "fiddler": {label:"Fiedler",gender:"der",plural:"Fiedler", ex5:[{t:1,s:"Der Fiedler spielte eine lebhafte Melodie auf der Hochzeit."},{t:2,s:"Sie ist eine talentierte Fiedlerin, die Volksmusik liebt."},{t:3,s:"Der Fiedler tippte mit dem Fuß zum Takt der Musik."},{t:4,s:"Der Fiedler trat auf dem Marktplatz auf."},{t:5,s:"Viele Leute tanzten zur Musik des Fiedlers."}]},
  "fiddling": {label:"herumspielen",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, während des Meetings mit deinem Stift herumzuspielen."},{t:2,s:"Er spielte mit den Radioknöpfen herum, um einen Sender zu finden."},{t:3,s:"Sie verbrachte den ganzen Nachmittag damit, an ihren Haaren herumzuspielen."},{t:4,s:"Spiel nicht ständig mit dem Handy herum!"},{t:5,s:"Er spielt gerne an alten Geräten herum."}]},
  "fide": {label:"aufrichtig",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma unternahm eine aufrichtige Anstrengung, das Problem zu lösen."},{t:2,s:"Er ist ein aufrichtiger Experte auf dem Gebiet der Geschichte."},{t:3,s:"Sie lieferte eine aufrichtige Entschuldigung für ihre Verspätung."},{t:4,s:"Das ist ein aufrichtiger Versuch, die Situation zu verbessern."},{t:5,s:"Wir brauchen eine aufrichtige Zusammenarbeit aller Beteiligten."}]},
  "fidel": {label:"Fidel",gender:"",plural:"—", ex5:[{t:1,s:"Fidel plant, bald seine Großmutter zu besuchen."},{t:2,s:"Ich habe Fidel um Hilfe bei meinen Hausaufgaben gebeten."},{t:3,s:"Fidel malt in seiner Freizeit sehr gerne."},{t:4,s:"Fidel ist ein guter Freund von mir."},{t:5,s:"Hast du Fidel heute schon gesehen?"}]},
  "fidelity": {label:"Treue",gender:"die",plural:"—", ex5:[{t:1,s:"Sie schätzte Treue in Freundschaft über alles."},{t:2,s:"Der Hund zeigte seinem Herrchen große Treue."},{t:3,s:"Er schwor seiner Frau ewige Treue."},{t:4,s:"Die Treue zur Heimat ist vielen Menschen wichtig."},{t:5,s:"Sie bewies ihre Treue auch in schwierigen Zeiten."}]},
  "fidget": {label:"zappeln",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind zappelte auf seinem Stuhl."},{t:2,s:"Sie zappelte nervös mit ihrem Stift."},{t:3,s:"Er zappelte, während er auf die Nachrichten wartete."},{t:4,s:"Hör auf zu zappeln und sitz still!"},{t:5,s:"Die Kinder zappelten vor Aufregung."}]},
  "fiduciary": {label:"treuhänderisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Anwalt hat eine treuhänderische Pflicht, im besten Interesse seines Klienten zu handeln."},{t:2,s:"Finanzberater müssen eine treuhänderische Beziehung zu ihren Kunden pflegen."},{t:3,s:"Die Vorstandsmitglieder verletzten ihre treuhänderischen Pflichten."},{t:4,s:"Es ist wichtig, treuhänderisch zu handeln."},{t:5,s:"Diese Verantwortung ist rein treuhänderischer Natur."}]},
  "field": {label:"Feld",gender:"das",plural:"Felder", ex5:[{t:1,s:"Das Feld ist grün."},{t:2,s:"Das Feld ist sehr breit."},{t:3,s:"Wir sind über das Feld gelaufen."},{t:4,s:"Auf dem Feld wächst frisches Getreide."},{t:5,s:"Wir haben ein Picknick auf dem Feld gemacht."}]},
  "fielded": {label:"aufstellen",gender:"",plural:"—", ex5:[{t:1,s:"Der Bauer hat seine Kühe auf das grüne Feld gestellt."},{t:2,s:"Das Team hat für das Finale seine besten Spieler aufgestellt."},{t:3,s:"Sie hat die Fragen der Reporter souverän beantwortet."},{t:4,s:"Der Trainer hat eine starke Mannschaft auf dem Feld aufgestellt."},{t:5,s:"Er hat die schwierigen Anfragen gekonnt aufgestellt."}]},
  "fielder": {label:"Feldspieler",gender:"der",plural:"Feldspieler", ex5:[{t:1,s:"Der Feldspieler fing den hohen Ball mühelos."},{t:2,s:"Ein guter Feldspieler muss schnelle Reflexe haben."},{t:3,s:"Der mittlere Feldspieler rannte schnell, um den Ball zu fangen."},{t:4,s:"Die Feldspieler haben heute eine tolle Leistung gezeigt."},{t:5,s:"Er ist ein sehr talentierter Feldspieler."}]},
  "fielding": {label:"Feldarbeit",gender:"die",plural:"Feldarbeiten", ex5:[{t:1,s:"Das Team ist damit beschäftigt, die Anfragen der Presse zu beantworten."},{t:2,s:"Das Fangen des Balls erfordert schnelle Reflexe und Konzentration."},{t:3,s:"Er ist gut darin, Beschwerden von wütenden Kunden zu bearbeiten."},{t:4,s:"Die Verteidigung im Spiel erfordert viel Übung."},{t:5,s:"Er hat die Aufgabe, alle eingehenden Nachrichten zu sortieren."}]},
  "fields": {label:"Feld",gender:"das",plural:"Felder", ex5:[{t:1,s:"Die grünen Felder sehen im Frühling wunderschön aus."},{t:2,s:"Die Bauern arbeiten den ganzen Tag hart auf den Feldern."},{t:3,s:"Auf den Feldern blühen viele bunte Blumen."},{t:4,s:"Wir spazieren gerne über die weiten Felder."},{t:5,s:"Das Getreide auf den Feldern wächst in diesem Jahr sehr gut."}]},
  "fieldwork": {label:"Feldarbeit",gender:"die",plural:"Feldarbeiten", ex5:[{t:1,s:"Die Studenten führen ihre Feldarbeit im Wald durch."},{t:2,s:"Ihre Feldarbeit lieferte wichtige Daten für das Projekt."},{t:3,s:"Er verbrachte zwei Jahre mit Feldarbeit in Afrika."},{t:4,s:"Die Feldarbeit ist ein wesentlicher Bestandteil seiner Forschung."},{t:5,s:"Wir bereiten uns auf die bevorstehende Feldarbeit vor."}]},
  "fiend": {label:"Teufel",gender:"der",plural:"Teufel", ex5:[{t:1,s:"Er ist ein richtiger Schokoladenteufel; er kann den ganzen Tag nichts anderes essen."},{t:2,s:"Der Bösewicht in der Geschichte wurde als grausamer Teufel dargestellt."},{t:3,s:"Sie kann ein echter Teufel sein, wenn sie verärgert ist."},{t:4,s:"Er arbeitet wie ein Teufel, um das Ziel zu erreichen."},{t:5,s:"Man muss nicht gleich den Teufel an die Wand malen."}]},
  "fierce": {label:"heftig",gender:"",plural:"—", ex5:[{t:1,s:"Der Löwe ist sehr heftig."},{t:2,s:"Ein heftiger Sturm zog über das Land."},{t:3,s:"Wir standen einem heftigen Konkurrenten gegenüber."},{t:4,s:"Es gab eine heftige Diskussion im Unterricht."},{t:5,s:"Der Wind wehte heute besonders heftig."}]},
  "fiercely": {label:"heftig",gender:"",plural:"—", ex5:[{t:1,s:"Sie verteidigte ihre Freundin heftig."},{t:2,s:"Die beiden Mannschaften kämpften heftig gegeneinander."},{t:3,s:"Er widersprach dem Plan heftig."},{t:4,s:"Das Feuer loderte heftig."},{t:5,s:"Sie protestierte heftig gegen diese Entscheidung."}]},
