  "fiesta": {label:"Fiesta",gender:"die",plural:"Fiestas", ex5:[{t:1,s:"Die ganze Stadt nahm an der Fiesta auf dem Marktplatz teil."},{t:2,s:"Wir genossen eine bunte Fiesta mit Musik und leckerem Essen."},{t:3,s:"Gehst du heute Abend zur Fiesta?"},{t:4,s:"Die Fiesta war ein großes Ereignis für alle."},{t:5,s:"Überall hörte man die Musik der Fiesta."}]},
  "fife": {label:"Querpfeife",gender:"die",plural:"Querpfeifen", ex5:[{t:1,s:"Der junge Soldat lernte für die Parade die Querpfeife zu spielen."},{t:2,s:"Der Klang der Querpfeife hallte durch das kleine Dorf."},{t:3,s:"Er trug seine Querpfeife in einem ledernen Etui."},{t:4,s:"Sie spielt sehr schön auf der Querpfeife."},{t:5,s:"Die Querpfeife ist ein traditionelles Instrument."}]},
  "fifteen": {label:"fünfzehn",gender:"",plural:"—", ex5:[{t:1,s:"Es sind fünfzehn Schüler im Klassenzimmer."},{t:2,s:"Man braucht fünfzehn Minuten bis zum Bahnhof."},{t:3,s:"Sie ist heute fünfzehn Jahre alt geworden."},{t:4,s:"Wir treffen uns in fünfzehn Minuten."},{t:5,s:"Das Buch hat fünfzehn Kapitel."}]},
  "fifteenth": {label:"fünfzehnte",gender:"",plural:"—", ex5:[{t:1,s:"Sein Geburtstag ist am fünfzehnten Mai."},{t:2,s:"Sie belegte den fünfzehnten Platz im Rennen."},{t:3,s:"Wir feiern heute unseren fünfzehnten Hochzeitstag."},{t:4,s:"Das ist der fünfzehnte Versuch."},{t:5,s:"Er wohnt im fünfzehnten Stock."}]},
