  "fight": {label:"kämpfen",gender:"",plural:"—", ex5:[{t:1,s:"Boxer kämpfen hart im Ring."},{t:2,s:"Das Team kämpft sich zurück ins Spiel."},{t:3,s:"Wir kämpfen für unsere Rechte."},{t:4,s:"Sie müssen gegen die Kälte kämpfen."},{t:5,s:"Er kämpft jeden Tag für seine Träume."}]},
  "fighter": {label:"Kampfjet",gender:"der",plural:"Kampfjets", ex5:[{t:1,s:"Der Kampfjet flog sehr schnell über die Stadt."},{t:2,s:"Er träumt davon, Kampfjet-Pilot zu werden."},{t:3,s:"Der Kampfjet ist mit fortschrittlicher Technik ausgestattet."},{t:4,s:"Am Himmel sah man einen Kampfjet."},{t:5,s:"Die Wartung vom Kampfjet ist sehr komplex."}]},
  "fighters": {label:"Kämpfer",gender:"der",plural:"Kämpfer", ex5:[{t:1,s:"Die zwei Kämpfer betraten den Ring."},{t:2,s:"Feuerwehrleute sind mutige Kämpfer, die ihr Leben riskieren."},{t:3,s:"Die Kämpfer trainierten hart für die Meisterschaft."},{t:4,s:"Er ist ein erfahrener Kämpfer."},{t:5,s:"Alle Kämpfer zeigten großen Einsatz."}]},
  "fighting": {label:"streiten",gender:"",plural:"—", ex5:[{t:1,s:"Sie streiten sich gerade um ein kleines Spielzeug."},{t:2,s:"Hör sofort auf, mit deinem Bruder zu streiten."},{t:3,s:"Die Soldaten streiten für ihr Vaterland."},{t:4,s:"Warum streiten die Kinder immer wieder?"},{t:5,s:"Es ist nicht gut, sich wegen Kleinigkeiten zu streiten."}]},
  "fights": {label:"kämpft",gender:"",plural:"—", ex5:[{t:1,s:"Die zwei Brüder haben oft alberne Kämpfe."},{t:2,s:"Sie kämpft jedes Wochenende für Tierrechte."},{t:3,s:"Der Held kämpft im Buch gegen den bösen Schurken."},{t:4,s:"Er kämpft tapfer gegen seine Krankheit."},{t:5,s:"Das Team kämpft in jedem Spiel um den Sieg."}]},
  "figment": {label:"Einbildung",gender:"die",plural:"Einbildungen", ex5:[{t:1,s:"Der Geist war nur ein Produkt seiner Einbildung."},{t:2,s:"Ihre Ängste erwiesen sich als reine Einbildung durch Stress."},{t:3,s:"Das Monster war eine Einbildung, die sich Kinder ausgedacht hatten."},{t:4,s:"Das ist alles nur deine Einbildung."},{t:5,s:"Er verlor sich in seiner eigenen Einbildung."}]},
  "figs": {label:"Feigen",gender:"die",plural:"Feigen", ex5:[{t:1,s:"Ich habe frische Feigen auf dem lokalen Markt gekauft."},{t:2,s:"Getrocknete Feigen sind ein gesunder Snack für Kinder."},{t:3,s:"Sie gab geschnittene Feigen in ihren Morgenjoghurt."},{t:4,s:"Diese Feigen schmecken sehr süß."},{t:5,s:"Wir essen gerne Feigen zum Frühstück."}]},
  "figurative": {label:"bildhaft",gender:"",plural:"—", ex5:[{t:1,s:"Das Gedicht verwendet eine sehr bildhafte Sprache."},{t:2,s:"Nimm meine Worte nicht bildhaft, ich meinte sie ganz wörtlich."},{t:3,s:"Es ist eine bildhafte Darstellung des inneren Schmerzes des Künstlers."},{t:4,s:"Er beschrieb die Situation sehr bildhaft."},{t:5,s:"Diese bildhafte Beschreibung hilft uns, das Problem zu verstehen."}]},
  "figuratively": {label:"bildlich",gender:"",plural:"—", ex5:[{t:1,s:"Er brannte bildlich vor Wut, stand aber nicht wirklich in Flammen."},{t:2,s:"Der Ausdruck wird bildlich verwendet, um jemandem Glück zu wünschen."},{t:3,s:"Sie ist bildlich gesprochen das Herz unseres Teams."},{t:4,s:"Man muss den Satz bildlich verstehen."},{t:5,s:"Das kann man bildlich als einen Neuanfang betrachten."}]},
  "figure": {label:"Zahl",gender:"die",plural:"Zahlen", ex5:[{t:1,s:"Die Zahl ist sehr hoch."},{t:2,s:"Die Zahl der Teilnehmer ist gestiegen."},{t:3,s:"Wir rechnen die Kosten zusammen."},{t:4,s:"Kannst du diese Zahl auf dem Diagramm lesen?"},{t:5,s:"Die genaue Zahl ist noch nicht bekannt."}]},
  "figured": {label:"berechnet",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe endlich berechnet, wie man das Problem löst."},{t:2,s:"Sie berechnete, dass es besser wäre, früh zu gehen."},{t:3,s:"Er hat die Gesamtkosten der Reise auf einem Zettel berechnet."},{t:4,s:"Ich habe mir berechnet, wie viel Zeit ich brauche."},{t:5,s:"Wir haben die Lage genau berechnet."}]},
  "figurehead": {label:"Aushängeschild",gender:"das",plural:"Aushängeschilder", ex5:[{t:1,s:"Der Präsident ist nur ein Aushängeschild ohne echte Macht."},{t:2,s:"Er fungiert als Aushängeschild, während andere Entscheidungen treffen."},{t:3,s:"Der König wurde nach der Verfassung zum reinen Aushängeschild."},{t:4,s:"Sie will nicht nur ein Aushängeschild sein."},{t:5,s:"Das Unternehmen braucht mehr als nur ein Aushängeschild."}]},
  "figures": {label:"Zahlen",gender:"die",plural:"Zahlen", ex5:[{t:1,s:"Die Verkaufszahlen sind besser als im letzten Jahr."},{t:2,s:"Kannst du diese Zahlen auf dem Diagramm ablesen?"},{t:3,s:"Sie sammelt gerne kleine Spielzeugfiguren."},{t:4,s:"Die Zahlen zeigen eine positive Entwicklung."},{t:5,s:"Vergleiche bitte die Zahlen miteinander."}]},
  "figurine": {label:"Figur",gender:"die",plural:"Figuren", ex5:[{t:1,s:"Sie sammelt kleine Porzellanfiguren."},{t:2,s:"Eine Glasfigur stand auf dem Regal."},{t:3,s:"Er schnitzte eine kleine Figur aus Holz."},{t:4,s:"Diese Figur ist sehr kunstvoll gestaltet."},{t:5,s:"Ich habe eine schöne Figur als Geschenk gekauft."}]},
  "figurines": {label:"Figuren",gender:"die",plural:"Figuren", ex5:[{t:1,s:"Sie sammelt kleine Porzellanfiguren von ihren Reisen."},{t:2,s:"Das Regal ist voll mit bunten Tonfiguren."},{t:3,s:"Diese Holzfiguren wurden von einem lokalen Künstler geschnitzt."},{t:4,s:"Sie hat viele verschiedene Figuren im Schrank."},{t:5,s:"Diese Figuren sehen sehr lebendig aus."}]},
  "figuring": {label:"überlegend",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin gerade dabei, das Matheproblem zu lösen."},{t:2,s:"Sie überlegt, wie sie das kaputte Spielzeug reparieren kann."},{t:3,s:"Wir planen gerade unsere Sommerreise."},{t:4,s:"Ich bin am Überlegen, was wir als Nächstes tun."},{t:5,s:"Er ist damit beschäftigt, die Kosten auszurechnen."}]},
  "fiji": {label:"Fidschi",gender:"das",plural:"—", ex5:[{t:1,s:"Wir planen eine Reise nach Fidschi für nächsten Sommer."},{t:2,s:"Fidschi ist berühmt für seine schönen weißen Sandstrände."},{t:3,s:"Mein Freund lebt auf Fidschi und liebt das warme Wetter dort."},{t:4,s:"Fidschi ist ein tolles Reiseziel."},{t:5,s:"Ich möchte gerne einmal Fidschi besuchen."}]},
