  "filed": {label:"abgelegt",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat die wichtigen Dokumente im Schrank abgelegt."},{t:2,s:"Er hat seine Steuererklärung vor der Frist eingereicht."},{t:3,s:"Das Unternehmen hat eine Beschwerde über den schlechten Service eingereicht."},{t:4,s:"Alle Unterlagen wurden ordentlich abgelegt."},{t:5,s:"Er hat den Bericht gestern offiziell eingereicht."}]},
  "filename": {label:"Dateiname",gender:"der",plural:"Dateinamen", ex5:[{t:1,s:"Bitte ändere den Dateinamen in etwas Verständlicheres."},{t:2,s:"Ich finde die Datei nicht, weil ich den Dateinamen vergessen habe."},{t:3,s:"Der Dateiname enthält ungültige Zeichen."},{t:4,s:"Bitte gib einen neuen Dateinamen ein."},{t:5,s:"Der Dateiname ist zu lang für das System."}]},
  "files": {label:"Dateien",gender:"die",plural:"Dateien", ex5:[{t:1,s:"Bitte speichere alle Dateien in diesem Ordner."},{t:2,s:"Ich muss diese Dateien auf meinem Computer sortieren."},{t:3,s:"Er hat die wichtigen Dateien per E-Mail verschickt."},{t:4,s:"Kopiere die Dateien auf den USB-Stick."},{t:5,s:"Diese Dateien sind sehr wichtig für das Projekt."}]},
  "filesystem": {label:"Dateisystem",gender:"das",plural:"Dateisysteme", ex5:[{t:1,s:"Der Computer organisiert die Dateien im neuen Dateisystem."},{t:2,s:"Du solltest deine Daten sichern, bevor du das Dateisystem änderst."},{t:3,s:"Das Dateisystem ist wegen eines plötzlichen Stromausfalls abgestürzt."},{t:4,s:"Dieses Dateisystem ist sehr effizient."},{t:5,s:"Das Betriebssystem unterstützt das neue Dateisystem."}]},
  "filet": {label:"Filet",gender:"das",plural:"Filets", ex5:[{t:1,s:"Der Koch bereitete ein frisches Fischfilet zum Abendessen zu."},{t:2,s:"Ich habe beim örtlichen Metzger ein Rinderfilet gekauft."},{t:3,s:"Bitte entferne die Gräten aus dem Fischfilet."},{t:4,s:"Das Filet schmeckt hervorragend."},{t:5,s:"Wir grillen heute ein zartes Filet."}]},
  "filial": {label:"kindlich",gender:"",plural:"—", ex5:[{t:1,s:"Er empfand eine tiefe kindliche Pflicht gegenüber seinen Eltern."},{t:2,s:"Die Zeremonie war ein Zeichen ihres kindlichen Respekts."},{t:3,s:"Kindliche Liebe ist in vielen Kulturen ein wichtiger Wert."},{t:4,s:"Er zeigte kindliche Hingabe an seine Familie."},{t:5,s:"Das ist ein Ausdruck kindlicher Verehrung."}]},
  "filibuster": {label:"Filibuster",gender:"der",plural:"Filibuster", ex5:[{t:1,s:"Der Senator organisierte einen langen Filibuster."},{t:2,s:"Der Filibuster verzögerte die Abstimmung."},{t:3,s:"Sie nutzten einen Filibuster, um den Beschluss zu blockieren."},{t:4,s:"Ein Filibuster ist ein kontroverses politisches Instrument."},{t:5,s:"Die Sitzung wurde durch den Filibuster unnötig in die Länge gezogen."}]},
  "filigree": {label:"Filigran",gender:"das",plural:"Filigrane", ex5:[{t:1,s:"Der Silberring zeichnet sich durch ein zartes Filigran aus."},{t:2,s:"Sie bewunderte das kunstvolle Filigran auf der alten Schatulle."},{t:3,s:"Der Kunsthandwerker arbeitete stundenlang an dem Metallfiligran."},{t:4,s:"Die Arbeit besticht durch ihre feine Filigranität."},{t:5,s:"Das Schmuckstück ist mit aufwendigem Filigran verziert."}]},
  "filing": {label:"Ablage",gender:"die",plural:"Ablagen", ex5:[{t:1,s:"Sie verbrachte den Vormittag mit der Ablage wichtiger Dokumente."},{t:2,s:"Der Anwalt ist für die Ablage der rechtlichen Unterlagen verantwortlich."},{t:3,s:"Er ist sehr gut im Sortieren und in der Ablage von Informationen."},{t:4,s:"Die Ablage auf ihrem Schreibtisch ist immer perfekt organisiert."},{t:5,s:"Wir müssen heute noch die gesamte Ablage erledigen."}]},
