  "fillers": {label:"Füllstoff",gender:"der",plural:"Füllstoffe", ex5:[{t:1,s:"Diese Kissen enthalten weiche Füllstoffe."},{t:2,s:"Viele verarbeitete Lebensmittel enthalten verschiedene Füllstoffe."},{t:3,s:"Der Künstler nutzte Füllstoffe für die Skulptur."},{t:4,s:"Dieser Kunststoff dient als Füllstoff für das Produkt."},{t:5,s:"Man sollte auf ungesunde Füllstoffe verzichten."}]},
  "fillet": {label:"Filet",gender:"das",plural:"Filets", ex5:[{t:1,s:"Der Koch schnitt ein frisches Fischfilet."},{t:2,s:"Sie würzte das Lachsfilet mit frischen Kräutern."},{t:3,s:"Er lernte, wie man einen Fisch fachgerecht filetiert."},{t:4,s:"Wir essen heute Abend ein zartes Filet."},{t:5,s:"Das Filet vom Rind ist sehr hochwertig."}]},
  "fillets": {label:"Filets",gender:"die",plural:"Filets", ex5:[{t:1,s:"Wir haben zwei Lachsfilets für das Abendessen gekauft."},{t:2,s:"Das Rezept verlangt nach Hähnchenfilets ohne Knochen."},{t:3,s:"Diese Fischfilets lassen sich leicht braten."},{t:4,s:"Ich habe drei Filets in der Pfanne zubereitet."},{t:5,s:"Die Filets waren von sehr guter Qualität."}]},
  "filling": {label:"Füllung",gender:"die",plural:"Füllungen", ex5:[{t:1,s:"Sie füllt die Kiste mit alten Büchern."},{t:2,s:"Die Erdbeerfüllung in diesem Kuchen schmeckt hervorragend."},{t:3,s:"Ich bin gerade beim Ausfüllen des Formulars."},{t:4,s:"Dieser Pfannkuchen hat eine leckere Füllung."},{t:5,s:"Die Füllung für das Kissen ist sehr weich."}]},
  "fillings": {label:"Füllungen",gender:"die",plural:"Füllungen", ex5:[{t:1,s:"Der Zahnarzt prüfte meine alten Füllungen."},{t:2,s:"Diese Kuchen haben köstliche Füllungen aus Obst."},{t:3,s:"Sie braucht zwei neue Füllungen für ihre Karieslöcher."},{t:4,s:"Die Füllungen sind heute fast unsichtbar."},{t:5,s:"Alle Füllungen in meinen Zähnen sind in Ordnung."}]},
  "fills": {label:"füllen",gender:"",plural:"—", ex5:[{t:1,s:"Der Duft von Kaffee füllt den ganzen Raum."},{t:2,s:"Musik füllt mein Herz jeden Morgen mit Freude."},{t:3,s:"Er füllt die Flasche mit kaltem Wasser."},{t:4,s:"Das Licht füllt das Zimmer mit Wärme."},{t:5,s:"Sie füllt den Becher bis zum Rand."}]},
  "filly": {label:"Stute",gender:"die",plural:"Stuten", ex5:[{t:1,s:"Das junge Fohlen ist eine Stute."},{t:2,s:"Diese Stute sieht sehr gesund und munter aus."},{t:3,s:"Der Bauer kümmert sich liebevoll um die Stute."},{t:4,s:"Die Stute galoppiert über die Koppel."},{t:5,s:"Wir haben eine neue Stute auf dem Hof."}]},
  "film": {label:"Film",gender:"der",plural:"Filme", ex5:[{t:1,s:"Der Film fängt gleich an."},{t:2,s:"Der Film ist sehr lang."},{t:3,s:"Wir haben einen Film geschaut."},{t:4,s:"Das ist ein wirklich spannender Film."},{t:5,s:"Welchen Film möchtest du sehen?"}]},
  "filmed": {label:"gefilmt",gender:"",plural:"—", ex5:[{t:1,s:"Der ganze Film wurde in New York gedreht."},{t:2,s:"Sie haben das Konzert live für das Fernsehen gefilmt."},{t:3,s:"Mein Freund hat unser Schultheaterstück gestern gefilmt."},{t:4,s:"Die Szene wurde im Park gefilmt."},{t:5,s:"Wir haben unseren Ausflug mit der Kamera gefilmt."}]},
  "filming": {label:"Dreharbeiten",gender:"die",plural:"Dreharbeiten", ex5:[{t:1,s:"Das Team ist beim Filmen eines neuen Kinofilms im Park."},{t:2,s:"Die Dreharbeiten für den Dokumentarfilm beginnen nächsten Monat."},{t:3,s:"Ich habe gesehen, wie sie in der Stadt einen Werbespot filmten."},{t:4,s:"Das Filmen erfordert viel Geduld."},{t:5,s:"Wir haben beim Filmen viel Spaß gehabt."}]},
  "filmmaker": {label:"Filmemacher",gender:"der",plural:"Filmemacher", ex5:[{t:1,s:"Der berühmte Filmemacher dreht gerade einen neuen Film."},{t:2,s:"Sie träumt davon, eine erfolgreiche Filmemacherin zu werden."},{t:3,s:"Das Festival lud jeden jungen Filmemacher zur Teilnahme ein."},{t:4,s:"Der Filmemacher gab nach der Vorführung ein Interview."},{t:5,s:"Viele sehen in ihm einen begabten Filmemacher."}]},
  "filmmakers": {label:"Filmemacher",gender:"die",plural:"Filmemacher", ex5:[{t:1,s:"Viele Filmemacher versammeln sich hier zum jährlichen Festival."},{t:2,s:"Junge Filmemacher nutzen Smartphones, um Kunst zu schaffen."},{t:3,s:"Der Workshop richtet sich an angehende Filmemacher."},{t:4,s:"Die Filmemacher diskutierten über ihre neuesten Projekte."},{t:5,s:"Es ist wichtig, dass Filmemacher ihre Ideen teilen."}]},
  "filmmaking": {label:"Filmemachen",gender:"das",plural:"—", ex5:[{t:1,s:"Sie entschied sich dazu, Filmemachen an der Universität zu studieren."},{t:2,s:"Filmemachen erfordert viel Geduld und Kreativität."},{t:3,s:"Er interessiert sich schon seit seiner Kindheit für das Filmemachen."},{t:4,s:"Das Filmemachen ist ein faszinierender Prozess."},{t:5,s:"Durch das Filmemachen kann man seine eigene Geschichte erzählen."}]},
  "films": {label:"Filme",gender:"die",plural:"Filme", ex5:[{t:1,s:"Ich liebe es, am Wochenende Actionfilme zu schauen."},{t:2,s:"Sie drehen heute in der Innenstadt neue Filme."},{t:3,s:"Hast du in letzter Zeit gute Horrorfilme gesehen?"},{t:4,s:"Filme können uns in andere Welten entführen."},{t:5,s:"Wir schauen uns oft gemeinsam Filme an."}]},
  "filter": {label:"filtern",gender:"",plural:"—", ex5:[{t:1,s:"Die Maschine muss das Wasser filtern."},{t:2,s:"Man kann die Ergebnisse nach Datum filtern."},{t:3,s:"Wir müssen die Daten sorgfältig filtern."},{t:4,s:"Können Sie diese Liste für mich filtern?"},{t:5,s:"Das Programm hilft dabei, Spam zu filtern."}]},
  "filtered": {label:"gefiltert",gender:"",plural:"—", ex5:[{t:1,s:"Wir trinken zu Hause nur gefiltertes Wasser."},{t:2,s:"Das Sonnenlicht wurde durch die dichten Blätter gefiltert."},{t:3,s:"Sie hat den Kaffee gefiltert, bevor sie ihn servierte."},{t:4,s:"Die gefilterte Luft sorgt für ein besseres Klima."},{t:5,s:"Das gefilterte Öl ist nun klar und sauber."}]},
  "filtering": {label:"Filtern",gender:"das",plural:"—", ex5:[{t:1,s:"Das Filtern von Verunreinigungen aus dem Wasser ist wichtig."},{t:2,s:"Sie ist gerade dabei, ihre E-Mails zu filtern."},{t:3,s:"Das Filtern des Sonnenlichts durch die Bäume war wunderschön."},{t:4,s:"Durch das Filtern der Ergebnisse findet man genau das, was man sucht."},{t:5,s:"Das Filtern nimmt viel Zeit in Anspruch."}]},
  "filters": {label:"Filter",gender:"der",plural:"Filter", ex5:[{t:1,s:"Diese Wasserfilter machen das Leitungswasser sauber."},{t:2,s:"Sie benutzt Filter, um ihre Fotos zu bearbeiten."},{t:3,s:"Wechseln Sie die Luftfilter alle drei Monate."},{t:4,s:"Gute Filter sind für die Gesundheit wichtig."},{t:5,s:"Der Fotograf setzt verschiedene Filter ein."}]},
