  "filthy": {label:"schmutzig",gender:"",plural:"—", ex5:[{t:1,s:"Seine Stiefel waren schmutzig vom Matsch."},{t:2,s:"Das alte Zimmer war dunkel und schmutzig."},{t:3,s:"Sie weigerte sich, den schmutzigen Lappen anzufassen."},{t:4,s:"Deine Hände sind total schmutzig."},{t:5,s:"Wir müssen die schmutzige Wäsche waschen."}]},
  "filtration": {label:"Filterung",gender:"die",plural:"Filterungen", ex5:[{t:1,s:"Die Filterung des Wassers erfolgt durch eine moderne Anlage."},{t:2,s:"Eine gute Filterung entfernt kleinste Partikel."},{t:3,s:"Der Pool nutzt eine spezielle Sand-Filterung."},{t:4,s:"Die Filterung ist für die Wasserqualität entscheidend."},{t:5,s:"Nach der Filterung ist das Wasser klar."}]},
  "fin": {label:"Flosse",gender:"die",plural:"Flossen", ex5:[{t:1,s:"Der Fisch bewegte sanft seine Flosse."},{t:2,s:"Eine Haifischflosse schnitt durch das Wasser."},{t:3,s:"Der Taucher trug Flossen an seinen Füßen."},{t:4,s:"Die Flossen helfen dem Fisch bei der Steuerung."},{t:5,s:"Er hat sehr große Flossen an den Füßen."}]},
