  "firs": {label:"Tanne",gender:"die",plural:"Tannen", ex5:[{t:1,s:"Die Berge sind mit hohen Tannen bedeckt."},{t:2,s:"Wir haben letzten Winter einige Tannen im Garten gepflanzt."},{t:3,s:"Der Duft der Tannen erfüllte die kühle Morgenluft."},{t:4,s:"Die Tanne ist ein immergrüner Baum."},{t:5,s:"Im Wald stehen viele junge Tannen."}]},
  "first": {label:"erst",gender:"",plural:"—", ex5:[{t:1,s:"Sie kam als Erste ins Ziel."},{t:2,s:"Der erste Schritt ist entscheidend."},{t:3,s:"Wir haben das als Erste gemacht."},{t:4,s:"Das ist erst der Anfang."},{t:5,s:"Er war der Erste in der Schlange."}]},
