  "fisher": {label:"Fischer",gender:"der",plural:"Fischer", ex5:[{t:1,s:"Der alte Fischer fing heute Morgen einen großen Fisch."},{t:2,s:"Jeden Morgen fährt der Fischer aufs Meer hinaus."},{t:3,s:"Der Fischer reparierte sorgfältig seine Netze."},{t:4,s:"Der Fischer kennt das Wetter auf dem Meer genau."},{t:5,s:"Ein erfahrener Fischer kann das Wetter vorhersagen."}]},
  "fisheries": {label:"Fischerei",gender:"die",plural:"Fischereien", ex5:[{t:1,s:"Die Regierung versucht, die lokale Fischerei zu schützen."},{t:2,s:"Viele Menschen in dieser Stadt arbeiten in der Fischerei."},{t:3,s:"Wir besuchten die Fischerei, um mehr über nachhaltigen Fang zu lernen."},{t:4,s:"Die Fischerei ist ein wichtiger Wirtschaftszweig."},{t:5,s:"Diese Fischerei ist für ihre Qualität bekannt."}]},
  "fisherman": {label:"Fischer",gender:"der",plural:"Fischer", ex5:[{t:1,s:"Der Fischer warf sein Netz in den tiefen Ozean."},{t:2,s:"Ein alter Fischer erzählte uns Geschichten vom Meer."},{t:3,s:"Der Fischer fing heute Morgen einen großen Thunfisch."},{t:4,s:"Der Fischer ist schon früh bei der Arbeit."},{t:5,s:"Der Fischer kennt die besten Stellen zum Fangen."}]},
  "fishermen": {label:"Fischer",gender:"der",plural:"Fischer", ex5:[{t:1,s:"Die Fischer fuhren heute Morgen früh aufs Meer hinaus."},{t:2,s:"Viele Fischer benutzen Netze, um große Fische zu fangen."},{t:3,s:"Die Fischer waren mit ihrem großen Fang sehr zufrieden."},{t:4,s:"Die Fischer bereiten ihre Boote für den Tag vor."},{t:5,s:"Am Hafen trafen sich viele Fischer."}]},
  "fishers": {label:"Fischer",gender:"der",plural:"Fischer", ex5:[{t:1,s:"Die Fischer fuhren aufs Meer, bevor die Sonne aufging."},{t:2,s:"Lokale Fischer sorgen sich um die abnehmende Fischpopulation."},{t:3,s:"Die Fischer brachten heute Morgen einen riesigen Fang ein."},{t:4,s:"Die Fischer beobachten die Bedingungen auf dem Meer."},{t:5,s:"Die Fischer arbeiten in dieser Region oft zusammen."}]},
  "fishery": {label:"Fischerei",gender:"die",plural:"Fischereien", ex5:[{t:1,s:"Die lokale Fischerei liefert frischen Fisch an den Markt."},{t:2,s:"Er arbeitet in einer Lachsfischerei in Alaska."},{t:3,s:"Die Regierung versucht, die nachhaltige Fischerei zu schützen."},{t:4,s:"Diese Fischerei ist sehr modern ausgestattet."},{t:5,s:"Wir unterstützen die lokale Fischerei."}]},
  "fishes": {label:"Fische",gender:"die",plural:"Fische", ex5:[{t:1,s:"Viele bunte Fische schwimmen im Aquarium."},{t:2,s:"Manche Fische können ihre Farbe ändern, um sich zu verstecken."},{t:3,s:"Der Fluss ist voll von verschiedenen Arten von Fischen."},{t:4,s:"Die Fische im Teich sehen sehr gesund aus."},{t:5,s:"Wir haben heute im Meer viele Fische gesehen."}]},
  "fishing": {label:"Angeln",gender:"das",plural:"—", ex5:[{t:1,s:"Wir waren heute Morgen am See beim Angeln."},{t:2,s:"Angeln ist mein liebstes Hobby am Wochenende."},{t:3,s:"Sie genießen das Angeln am Fluss."},{t:4,s:"Möchtest du mit mir zum Angeln gehen?"},{t:5,s:"Das Angeln erfordert viel Geduld."}]},
  "fishy": {label:"faul",gender:"",plural:"—", ex5:[{t:1,s:"An der ganzen Sache ist etwas faul."},{t:2,s:"Das Geschäft klingt für mich ein bisschen faul."},{t:3,s:"Iss das Fleisch nicht, wenn es faul aussieht."},{t:4,s:"Die Geschichte klingt sehr faul."},{t:5,s:"Da ist doch etwas faul, oder?"}]},
  "fisk": {label:"Fisk",gender:"",plural:"—", ex5:[{t:1,s:"Herr Fisk ist mein Lieblingslehrer für Geschichte."},{t:2,s:"Die Familie Fisk ist in eine neue Nachbarschaft gezogen."},{t:3,s:"Ich habe Herrn Dr. Fisk eine E-Mail geschickt."},{t:4,s:"Fisk ist ein bekannter Name in dieser Stadt."},{t:5,s:"Hast du schon mit Herrn Fisk gesprochen?"}]},
  "fission": {label:"Kernspaltung",gender:"die",plural:"Kernspaltungen", ex5:[{t:1,s:"Die Kernspaltung setzt enorme Energie frei."},{t:2,s:"Bei der Kernspaltung wird ein schwerer Atomkern gespalten."},{t:3,s:"Kernkraftwerke nutzen die Kernspaltung zur Stromerzeugung."},{t:4,s:"Wir haben im Physikunterricht über Kernspaltung gesprochen."},{t:5,s:"Die Entdeckung der Kernspaltung war sehr wichtig."}]},
  "fissure": {label:"Spalte",gender:"die",plural:"Spalten", ex5:[{t:1,s:"Ein Erdbeben verursachte eine tiefe Spalte im Boden."},{t:2,s:"Wasser floss durch die Spalte im Fels."},{t:3,s:"Der Bergsteiger überquerte vorsichtig die schmale Spalte."},{t:4,s:"In der Wand ist eine kleine Spalte zu sehen."},{t:5,s:"Der Gletscher hat viele gefährliche Spalten."}]},
