  "fistful": {label:"Handvoll",gender:"die",plural:"Handvoll", ex5:[{t:1,s:"Er nahm eine Handvoll Popcorn aus der Schüssel."},{t:2,s:"Sie hielt eine Handvoll Wildblumen in der Hand."},{t:3,s:"Das Kind nahm sich eine Handvoll Süßigkeiten."},{t:4,s:"Ich habe nur eine Handvoll Erde genommen."},{t:5,s:"Sie streute eine Handvoll Samen in den Garten."}]},
  "fists": {label:"Fäuste",gender:"die",plural:"Fäuste", ex5:[{t:1,s:"Der wütende Mann ballte fest seine Fäuste."},{t:2,s:"Sie stießen zur Begrüßung ihre Fäuste zusammen."},{t:3,s:"Er hob seine Fäuste triumphierend in die Luft."},{t:4,s:"Die beiden Männer ließen ihre Fäuste sinken."},{t:5,s:"Sie ballte die Fäuste vor Aufregung."}]},
