  "fixture": {label:"Einrichtung",gender:"die",plural:"Einrichtungen", ex5:[{t:1,s:"Die Deckenleuchte ist eine feste Einrichtung in diesem Raum."},{t:2,s:"Wir müssen eine neue Badezimmereinrichtung installieren."},{t:3,s:"Er ist mittlerweile eine feste Größe in der örtlichen Bibliothek."},{t:4,s:"Diese Einrichtung ist sehr modern."},{t:5,s:"Die technische Einrichtung funktioniert einwandfrei."}]},
  "fixtures": {label:"Einrichtungen",gender:"die",plural:"Einrichtungen", ex5:[{t:1,s:"Wir müssen die alten Beleuchtungseinrichtungen ersetzen."},{t:2,s:"Das Haus wird mit allen Badezimmereinrichtungen vermietet."},{t:3,s:"Die Kücheneinrichtungen wurden letzten Monat modernisiert."},{t:4,s:"Die neuen Einrichtungen sind sehr praktisch."},{t:5,s:"Alle festen Einrichtungen sind im Preis enthalten."}]},
  "fizz": {label:"zischen",gender:"",plural:"—", ex5:[{t:1,s:"Die Limonade begann zu zischen, sobald ich die Flasche öffnete."},{t:2,s:"Ich mag das Geräusch des Zischens bei frischem Mineralwasser."},{t:3,s:"Die Badekugel begann zu zischen, als sie das warme Wasser berührte."},{t:4,s:"Das Getränk fing an zu zischen."},{t:5,s:"Man kann das Zischen der Bläschen hören."}]},
  "fizzy": {label:"prickelnd",gender:"",plural:"—", ex5:[{t:1,s:"Sie goss ein Glas prickelnde Limonade ein."},{t:2,s:"Das Getränk war kalt und prickelnd."},{t:3,s:"Er mochte die prickelnden Bläschen im Glas."},{t:4,s:"Ich trinke lieber prickelndes Wasser."},{t:5,s:"Das prickelnde Gefühl auf der Zunge ist erfrischend."}]},
  "fjord": {label:"Fjord",gender:"der",plural:"Fjorde", ex5:[{t:1,s:"Das Schiff fuhr durch einen schmalen Fjord."},{t:2,s:"Steile Klippen erhoben sich auf beiden Seiten des Fjords."},{t:3,s:"Norwegen ist berühmt für seine malerischen Fjorde."},{t:4,s:"Der Fjord ist an dieser Stelle sehr tief."},{t:5,s:"Wir bewunderten die Aussicht auf den Fjord."}]},
  "fjords": {label:"Fjorde",gender:"die",plural:"Fjorde", ex5:[{t:1,s:"Norwegen ist berühmt für seine wunderschönen, tiefen Fjorde."},{t:2,s:"Wir machten eine Bootsfahrt, um die Fjorde zu sehen."},{t:3,s:"Die Berge ragen steil über den Fjorden auf."},{t:4,s:"Die Fjorde in Norwegen sind beeindruckend."},{t:5,s:"Es gibt viele Fjorde entlang der Küste."}]},
  "flabbergasted": {label:"verblüfft",gender:"",plural:"—", ex5:[{t:1,s:"Ich war völlig verblüfft, als ich die überraschende Nachricht hörte."},{t:2,s:"Der Lehrer war über die plötzliche Antwort des Schülers verblüfft."},{t:3,s:"Sie sah verblüfft auf die unordentliche Küche."},{t:4,s:"Er blieb verblüfft stehen, weil er es nicht glauben konnte."},{t:5,s:"Wir waren alle verblüfft über das unerwartete Ergebnis."}]},
