  "flawless": {label:"makellos",gender:"",plural:"—", ex5:[{t:1,s:"Ihre Leistung war makellos."},{t:2,s:"Der Diamant war nahezu makellos."},{t:3,s:"Er gab eine makellose Antwort."},{t:4,s:"Sie hatte eine makellose Haut."},{t:5,s:"Das Design des Produkts ist einfach makellos."}]},
  "flawlessly": {label:"makellos",gender:"",plural:"—", ex5:[{t:1,s:"Die Ballerina tanzte makellos auf der Bühne."},{t:2,s:"Er spricht Englisch fast makellos, nachdem er im Ausland gelebt hat."},{t:3,s:"Die Maschine funktionierte den ganzen Tag einwandfrei."},{t:4,s:"Sie führte ihre Aufgabe makellos aus."},{t:5,s:"Alles lief reibungslos und makellos ab."}]},
  "flaws": {label:"Fehler",gender:"die",plural:"—", ex5:[{t:1,s:"Der Plan hat mehrere schwerwiegende Fehler."},{t:2,s:"Selbst die besten Produkte können geringfügige Mängel aufweisen."},{t:3,s:"Sie akzeptierte ihren Freund trotz seiner Charakterfehler."},{t:4,s:"Wir haben alle unsere kleinen Fehler."},{t:5,s:"Die Analyse zeigte einige grundlegende Mängel auf."}]},
  "flax": {label:"Flachs",gender:"der",plural:"—", ex5:[{t:1,s:"Bauern bauen Flachs an, um hochwertige Leinenstoffe herzustellen."},{t:2,s:"Sie verwendet Leinsamen in ihrem morgendlichen Smoothie für die Gesundheit."},{t:3,s:"Die alten Ägypter nutzten Flachs zur Herstellung von Kleidung."},{t:4,s:"Aus Flachs wird auch Leinöl gewonnen."},{t:5,s:"Der Anbau von Flachs hat eine lange Tradition."}]},
  "flea": {label:"Floh",gender:"der",plural:"Flöhe", ex5:[{t:1,s:"Der Hund kratzte sich an einem beißenden Floh."},{t:2,s:"Ein Floh kann überraschend weit springen."},{t:3,s:"Sie behandelten die Katze gegen Flöhe."},{t:4,s:"Ein einziger Floh kann sich schnell vermehren."},{t:5,s:"Flöhe sind kleine, aber lästige Parasiten."}]},
  "fleas": {label:"Flöhe",gender:"die",plural:"—", ex5:[{t:1,s:"Mein Hund braucht ein Bad, um die Flöhe loszuwerden."},{t:2,s:"Die Katze kratzte sich wegen der Flöhe."},{t:3,s:"Wir kauften ein spezielles Spray, um die Flöhe zu töten."},{t:4,s:"Flöhe sind sehr hartnäckig und schwer zu bekämpfen."},{t:5,s:"Man muss das ganze Haus behandeln, um alle Flöhe zu entfernen."}]},
  "fled": {label:"floh",gender:"",plural:"—", ex5:[{t:1,s:"Der Dieb floh vom Tatort, bevor die Polizei eintraf."},{t:2,s:"Das Kaninchen floh in die Büsche, als es den Hund sah."},{t:3,s:"Viele Familien flohen wegen des Hochwassers aus ihren Häusern."},{t:4,s:"Er floh vor seinen Problemen."},{t:5,s:"Das Tier floh in den Wald."}]},
  "fledged": {label:"flügge",gender:"",plural:"—", ex5:[{t:1,s:"Der junge Adler ist nun flügge und bereit zu fliegen."},{t:2,s:"Sie ist ein flügges Mitglied des Forschungsteams."},{t:3,s:"Der Vogel ist endlich flügge geworden und hat das Nest verlassen."},{t:4,s:"Die jungen Vögel sind jetzt fast flügge."},{t:5,s:"Mit der Zeit wurde sie eine flügge Fachkraft."}]},
