  "florists": {label:"Blumenhändler",gender:"der",plural:"Blumenhändler", ex5:[{t:1,s:"Die Blumenhändler haben in der Hochzeitssaison viel zu tun."},{t:2,s:"Ich habe den Blumenhändler gebeten, Rosen für meine Mutter zu arrangieren."},{t:3,s:"Viele Blumenhändler verkaufen exotische Blumen."},{t:4,s:"Mein lokaler Blumenhändler hat immer frische Ware."},{t:5,s:"Der Blumenhändler beriet mich bei der Auswahl des Straußes."}]},
  "floss": {label:"Zahnseide",gender:"die",plural:"—", ex5:[{t:1,s:"Vergiss nicht, jeden Abend Zahnseide zu benutzen."},{t:2,s:"Ich habe eine neue Packung Zahnseide mit Minzgeschmack gekauft."},{t:3,s:"Mein Zahnarzt sagte, ich solle öfter Zahnseide verwenden."},{t:4,s:"Zahnseide ist wichtig für die tägliche Zahnpflege."},{t:5,s:"Sie benutzt regelmäßig Zahnseide."}]},
  "flossing": {label:"Zahnseidebenutzung",gender:"die",plural:"—", ex5:[{t:1,s:"Tägliche Zahnseidebenutzung ist wichtig für gesundes Zahnfleisch."},{t:2,s:"Mein Zahnarzt erinnerte mich daran, dass Zahnseidebenutzung genauso wichtig ist wie Zähneputzen."},{t:3,s:"Nach seinem letzten Check-up hat er mit der regelmäßigen Zahnseidebenutzung begonnen."},{t:4,s:"Die Zahnseidebenutzung sollte Teil der Abendroutine sein."},{t:5,s:"Durch konsequente Zahnseidebenutzung bleibt mein Zahnfleisch gesund."}]},
  "flotation": {label:"Auftrieb",gender:"der",plural:"Auftriebe", ex5:[{t:1,s:"Die Schwimmweste hilft beim Auftrieb im Wasser."},{t:2,s:"Wir lernten das physikalische Prinzip des Auftriebs in der Schule."},{t:3,s:"Das Auftriebsmittel hielt das Boot an der Oberfläche."},{t:4,s:"Der Auftrieb sorgt dafür, dass Schiffe schwimmen können."},{t:5,s:"Ohne ausreichend Auftrieb würde das Objekt sinken."}]},
  "flotilla": {label:"Flottille",gender:"die",plural:"Flottillen", ex5:[{t:1,s:"Eine kleine Flottille von Booten überquerte die ruhige Bucht."},{t:2,s:"Die Fischerflottille stach vor Sonnenaufgang in See."},{t:3,s:"Eine Flottille von Yachten versammelte sich für das Rennen."},{t:4,s:"Die Flottille segelte gemeinsam in den Hafen ein."},{t:5,s:"Wir beobachteten die Flottille vom Ufer aus."}]},
  "flounder": {label:"straucheln",gender:"",plural:"—", ex5:[{t:1,s:"Er begann bei seinem Vortrag zu straucheln."},{t:2,s:"Die Firma begann nach dem Verlust zu straucheln."},{t:3,s:"Sie strauchelte bei der Suche nach den richtigen Worten."},{t:4,s:"Er strauchelt oft, wenn er unter Druck steht."},{t:5,s:"Das Projekt begann zu straucheln, als das Budget gekürzt wurde."}]},
  "floundering": {label:"strauchelnd",gender:"",plural:"—", ex5:[{t:1,s:"Der kleine Hund war im tiefen Schnee strauchelnd unterwegs."},{t:2,s:"Er ist immer noch strauchelnd mit seinen neuen Mathehausaufgaben beschäftigt."},{t:3,s:"Das Unternehmen war nach dem plötzlichen Börsencrash strauchelnd."},{t:4,s:"Man sieht ihn oft strauchelnd durch die schwierige Zeit gehen."},{t:5,s:"Sie war strauchelnd bemüht, das Gleichgewicht zu halten."}]},
  "flour": {label:"Mehl",gender:"das",plural:"Mehle", ex5:[{t:1,s:"Das Mehl ist verschüttet worden."},{t:2,s:"Das Mehl ist sehr fein."},{t:3,s:"Wir haben das Mehl gesiebt."},{t:4,s:"Ich brauche noch etwas Mehl für den Teig."},{t:5,s:"Das Mehl steht im Küchenschrank."}]},
  "flourish": {label:"gedeihen",gender:"",plural:"—", ex5:[{t:1,s:"Die Pflanzen gediehen prächtig im warmen Boden."},{t:2,s:"Die Stadt begann zu gedeihen, nachdem die neue Straße eröffnet wurde."},{t:3,s:"Ihr Geschäft begann unter ihrer Leitung zu gedeihen."},{t:4,s:"In diesem Klima gedeihen viele verschiedene Blumen."},{t:5,s:"Unter den richtigen Bedingungen wird das Projekt gedeihen."}]},
  "flourished": {label:"gediehen",gender:"",plural:"—", ex5:[{t:1,s:"Das kleine Unternehmen ist unter ihrer Führung gediehen."},{t:2,s:"Kunst und Kultur sind in dieser Zeit prächtig gediehen."},{t:3,s:"Der Garten ist nach dem starken Frühlingsregen gut gediehen."},{t:4,s:"Die Wirtschaft der Stadt ist in den letzten Jahren gediehen."},{t:5,s:"Ihre Talente sind in der neuen Umgebung voll gediehen."}]},
  "flourishes": {label:"gedeihen",gender:"",plural:"—", ex5:[{t:1,s:"Der Garten gedeiht dank ihrer sorgfältigen Pflege prächtig."},{t:2,s:"Sein Unternehmen gedeiht durch seine harte Arbeit sehr gut."},{t:3,s:"Die kleine Stadt gedeiht als beliebtes Reiseziel."},{t:4,s:"Pflanzen gedeihen am besten bei ausreichend Sonnenlicht."},{t:5,s:"Unter diesen Bedingungen kann das Projekt nur gedeihen."}]},
  "flourishing": {label:"blühend",gender:"",plural:"—", ex5:[{t:1,s:"Das Geschäft ist dank der neuen Strategien blühend."},{t:2,s:"Der Garten ist in der warmen Frühlingsluft sehr blühend."},{t:3,s:"Sie ist in ihrer neuen Rolle als Managerin richtig blühend."},{t:4,s:"Wir sehen eine blühende Landschaft vor uns."},{t:5,s:"Es ist schön, eine so blühende Entwicklung zu beobachten."}]},
