  "fluke": {label:"Glückstreffer",gender:"der",plural:"Glückstreffer", ex5:[{t:1,s:"Der Sieg im Spiel war ein totaler Glückstreffer."},{t:2,s:"Ich habe die Prüfung bestanden, aber es war ein bisschen ein Glückstreffer."},{t:3,s:"Sein Erfolg war kein Glückstreffer; er hat sehr hart gearbeitet."},{t:4,s:"Das war reiner Glückstreffer, dass wir den Zug noch erreicht haben."},{t:5,s:"Man sollte sich im Leben nicht nur auf Glückstreffer verlassen."}]},
  "flume": {label:"Wassergraben",gender:"der",plural:"Wassergräben", ex5:[{t:1,s:"Das Wasser schoss schnell durch den schmalen Wassergraben."},{t:2,s:"Sie bauten einen Wassergraben, um Baumstämme den Berg hinunter zu transportieren."},{t:3,s:"Der alte Wassergraben wird heute zur Bewässerung genutzt."},{t:4,s:"Der Wassergraben war nach dem starken Regen völlig überlaufen."},{t:5,s:"Wir säuberten den Wassergraben von Laub und Ästen."}]},
  "flung": {label:"werfen",gender:"",plural:"—", ex5:[{t:1,s:"Er warf seinen Rucksack auf den Boden und rannte in die Küche."},{t:2,s:"Sie warf das Fenster auf, um frische Luft hereinzulassen."},{t:3,s:"Der wütende Mann warf den Brief in den Kamin."},{t:4,s:"Er hat das Buch frustriert auf den Tisch geworfen."},{t:5,s:"Sie warf ihre Tasche in die Ecke des Zimmers."}]},
