  "foreground": {label:"Vordergrund",gender:"der",plural:"Vordergründe", ex5:[{t:1,s:"Der Künstler platzierte eine helle Blume im Vordergrund."},{t:2,s:"Die Berge sind im Hintergrund, nicht im Vordergrund."},{t:3,s:"Sie stand im Vordergrund des Familienfotos."},{t:4,s:"Im Vordergrund des Bildes sieht man einen alten Baum."},{t:5,s:"Das Motiv im Vordergrund ist sehr scharf fotografiert."}]},
  "forehand": {label:"Vorhand",gender:"die",plural:"Vorhände", ex5:[{t:1,s:"Ihre Vorhand ist der stärkste Teil ihres Spiels."},{t:2,s:"Er schlug den Ball mit einer kraftvollen Vorhand zurück."},{t:3,s:"Der Trainer korrigierte seinen Griff bei der Vorhand."},{t:4,s:"Er trainiert täglich seine Vorhand."},{t:5,s:"Mit der Vorhand erzielt er die meisten Punkte."}]},
  "forehead": {label:"Stirn",gender:"die",plural:"Stirnen", ex5:[{t:1,s:"Sie wischte sich den Schweiß von der Stirn."},{t:2,s:"Er hatte eine kleine Narbe auf der Stirn."},{t:3,s:"Die Mutter küsste das Baby auf die Stirn."},{t:4,s:"Sie legte ihre Hand auf seine Stirn."},{t:5,s:"Er faltete die Stirn vor Konzentration."}]},
  "foreheads": {label:"Stirnen",gender:"die",plural:"Stirnen", ex5:[{t:1,s:"Sie wischten sich nach dem Rennen den Schweiß von den Stirnen."},{t:2,s:"Die Mutter küsste ihre Kinder auf die Stirnen."},{t:3,s:"Er runzelte die Stirn, was Falten auf ihren Stirnen erzeugte."},{t:4,s:"Die Stirnen der Arbeiter waren voller Schmutz."},{t:5,s:"Sie berührten sich mit den Stirnen."}]},
  "foreign": {label:"fremd",gender:"",plural:"—", ex5:[{t:1,s:"Die Münze ist fremd."},{t:2,s:"Die Sprache ist mir fremd."},{t:3,s:"Wir haben fremde Gäste empfangen."},{t:4,s:"Er fühlt sich in der Stadt fremd."},{t:5,s:"Das ist eine fremde Kultur."}]},
