  "format": {label:"Format",gender:"das",plural:"Formate", ex5:[{t:1,s:"Das Format der Datei hat sich plötzlich geändert."},{t:2,s:"Dieses Format ist sehr übersichtlich und klar."},{t:3,s:"Wir haben das Format für die Präsentation festgelegt."},{t:4,s:"Bitte speichern Sie das Dokument in diesem Format."},{t:5,s:"Das neue Format spart viel Platz auf der Seite."}]},
  "formation": {label:"Formation",gender:"die",plural:"Formationen", ex5:[{t:1,s:"Die Formation der Soldaten hielt dem Angriff stand."},{t:2,s:"Die Flugzeuge flogen in einer engen Formation."},{t:3,s:"Wir behielten die Formation während des gesamten Tanzes bei."},{t:4,s:"Die taktische Formation der Mannschaft war perfekt."},{t:5,s:"Die Formation der Vögel am Himmel sah wunderschön aus."}]},
