  "fretted": {label:"sich gesorgt",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat sich den ganzen Tag über ihre Testergebnisse gesorgt."},{t:2,s:"Er hat sich über die kleinen Details des Projekts gesorgt."},{t:3,s:"Lass dich nicht von Dingen sorgen, die du nicht ändern kannst."},{t:4,s:"Sie hat sich wegen der Nachricht gesorgt."},{t:5,s:"Er hat sich zu sehr um die Zukunft gesorgt."}]},
  "fretting": {label:"sich sorgen",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, dich über Dinge zu sorgen, die du nicht kontrollieren kannst."},{t:2,s:"Sie sorgt sich den ganzen Tag über die Prüfungsergebnisse."},{t:3,s:"Es hat keinen Sinn, sich über verschüttete Milch zu sorgen."},{t:4,s:"Warum bist du immer am Sorgen?"},{t:5,s:"Er ist ständig am Sorgen, was morgen passieren wird."}]},
  "freud": {label:"Freud",gender:"",plural:"—", ex5:[{t:1,s:"Sigmund Freud ist der Vater der Psychoanalyse."},{t:2,s:"Viele Studenten studieren die Theorien von Freud im Psychologieunterricht."},{t:3,s:"Wir haben die Ideen von Freud während der Vorlesung heute diskutiert."},{t:4,s:"Freud hat die moderne Psychologie stark beeinflusst."},{t:5,s:"Das Werk von Freud ist sehr komplex."}]},
  "freudian": {label:"freudsch",gender:"",plural:"—", ex5:[{t:1,s:"Er machte einen freudschen Versprecher während seiner Rede."},{t:2,s:"Der Film erforscht freudsche Themen des Unterbewusstseins."},{t:3,s:"Ihre Traumanalyse folgte einem streng freudschen Ansatz."},{t:4,s:"Das ist eine sehr freudsche Interpretation der Situation."},{t:5,s:"Er hat eine freudsche Sicht auf die Dinge."}]},
