  "frontiers": {label:"Grenzen",gender:"die",plural:"Grenzen", ex5:[{t:1,s:"Die wissenschaftlichen Grenzen erweitern sich ständig."},{t:2,s:"Die Entdecker reisten über die Grenzen des unbekannten Landes hinaus."},{t:3,s:"Wir verschieben die Grenzen der modernen Technologie."},{t:4,s:"Er arbeitet an den Grenzen der medizinischen Forschung."},{t:5,s:"Die Grenzen des Wissens werden immer weiter gesteckt."}]},
  "fronting": {label:"zugewandt",gender:"",plural:"—", ex5:[{t:1,s:"Das Gebäude ist der belebten Hauptstraße zugewandt."},{t:2,s:"Er ist der Frontmann einer neuen Band für die Sommertour."},{t:3,s:"Das Hotel liegt direkt am schönen blauen Ozean."},{t:4,s:"Das Haus ist dem Fluss zugewandt."},{t:5,s:"Das Café ist dem Park zugewandt."}]},
  "frontline": {label:"Frontlinie",gender:"die",plural:"Frontlinien", ex5:[{t:1,s:"Ärzte stehen an der Frontlinie im Kampf gegen das Virus."},{t:2,s:"Die Soldaten wurden gestern an die Frontlinie geschickt."},{t:3,s:"Sie arbeitet an der Frontlinie im Kundenservice."},{t:4,s:"Wir müssen die Menschen an der Frontlinie unterstützen."},{t:5,s:"Er steht an der Frontlinie dieser wichtigen Bewegung."}]},
  "frontman": {label:"Frontmann",gender:"der",plural:"Frontmänner", ex5:[{t:1,s:"Der Frontmann der Band hat eine kraftvolle Stimme."},{t:2,s:"Jeder Frontmann braucht ein gutes Team im Hintergrund."},{t:3,s:"Er wurde der Frontmann, nachdem der ursprüngliche Sänger gegangen war."},{t:4,s:"Der Frontmann trat vor das Publikum."},{t:5,s:"Als Frontmann muss man die Menge begeistern können."}]},
  "frontrunner": {label:"Spitzenreiter",gender:"der",plural:"Spitzenreiter", ex5:[{t:1,s:"Sie ist die Spitzenreiterin im Rennen um das Bürgermeisteramt."},{t:2,s:"Der Athlet wurde nach der ersten Runde zum Spitzenreiter."},{t:3,s:"Er ist der Spitzenreiter für den Gewinn der Goldmedaille."},{t:4,s:"Der Spitzenreiter führt das Feld mit großem Vorsprung an."},{t:5,s:"Es ist schwer, den Spitzenreiter einzuholen."}]},
  "fronts": {label:"Vorderseite",gender:"die",plural:"Vorderseiten", ex5:[{t:1,s:"An den Vorderseiten dieser Häuser liegen schöne Gärten."},{t:2,s:"Die Laden-Vorderseiten sind für den Feiertag geschmückt."},{t:3,s:"Er steht an der Vorderseite der Schlange."},{t:4,s:"Die Vorderseite des Gebäudes wurde neu gestrichen."},{t:5,s:"Bitte gehen Sie zur Vorderseite des Hauses."}]},
  "frost": {label:"Frost",gender:"der",plural:"Fröste", ex5:[{t:1,s:"Frost bedeckte das Gras."},{t:2,s:"Der Frost ist heute Morgen sehr dick."},{t:3,s:"Wir haben den Frost von der Scheibe gekratzt."},{t:4,s:"Der erste Frost hat die Blumen zerstört."},{t:5,s:"Bei Frost sollte man vorsichtig fahren."}]},
  "frostbite": {label:"Erfrierung",gender:"die",plural:"Erfrierungen", ex5:[{t:1,s:"Er erlitt während der Wanderung eine Erfrierung."},{t:2,s:"Man sollte Handschuhe tragen, um Erfrierungen zu vermeiden."},{t:3,s:"Der Arzt behandelte seine Erfrierung sorgfältig."},{t:4,s:"Erfrierungen können bleibende Schäden hinterlassen."},{t:5,s:"Die erste Hilfe bei Erfrierungen ist sehr wichtig."}]},
  "frosted": {label:"vereist",gender:"",plural:"—", ex5:[{t:1,s:"Das Fenster war nach der kalten Nacht vereist."},{t:2,s:"Sie hat den Kuchen mit einer Zuckerglasur überzogen."},{t:3,s:"Das Gras war am frühen Morgen vereist."},{t:4,s:"Die vereisten Wege sind sehr rutschig."},{t:5,s:"Alles war vereist nach dem plötzlichen Kälteeinbruch."}]},
  "frosting": {label:"Zuckerglasur",gender:"die",plural:"Zuckerglasuren", ex5:[{t:1,s:"Sie verteilt die Zuckerglasur auf dem Geburtstagskuchen."},{t:2,s:"Die morgendliche Kälte lässt das Fensterglas beschlagen."},{t:3,s:"Ich liebe die süße Zuckerglasur auf diesen Cupcakes."},{t:4,s:"Die Zuckerglasur macht den Kuchen perfekt."},{t:5,s:"Sie hat die Zuckerglasur mit etwas Zitrone verfeinert."}]},
  "frosts": {label:"Fröste",gender:"die",plural:"Fröste", ex5:[{t:1,s:"Frühe morgendliche Fröste können die empfindlichen Blumen beschädigen."},{t:2,s:"Die kalten Herbstfröste kamen dieses Jahr früher als gewöhnlich."},{t:3,s:"Die Felder waren im Morgengrauen von weißen Frösten bedeckt."},{t:4,s:"Nach den ersten Frösten fallen die Blätter von den Bäumen."},{t:5,s:"Die Fröste im März sind gefährlich für die Obstbäume."}]},
  "frosty": {label:"frostig",gender:"",plural:"—", ex5:[{t:1,s:"Ein frostiger Morgen kühlte die Luft ab."},{t:2,s:"Das Fenster hatte eine frostige Schicht."},{t:3,s:"Sie warf ihm einen frostigen Blick zu."},{t:4,s:"Es ist heute Morgen sehr frostig draußen."},{t:5,s:"Der Wind wehte frostig durch die Straßen."}]},
  "froth": {label:"Schaum",gender:"der",plural:"Schäume", ex5:[{t:1,s:"Der Cappuccino hat eine dicke Schicht Schaum oben drauf."},{t:2,s:"Die Meereswellen bildeten weißen Schaum am Strand."},{t:3,s:"Sie schlug das Eiweiß zu einem leichten Schaum."},{t:4,s:"Das Bier hat einen schönen Schaum."},{t:5,s:"Überall war Schaum vom Spülmittel."}]},
  "frothy": {label:"schaumig",gender:"",plural:"—", ex5:[{t:1,s:"Ich trinke am liebsten einen Cappuccino mit schaumiger Milch."},{t:2,s:"Die Wellen waren schaumig, als sie gegen die Felsen schlugen."},{t:3,s:"Sie schlug die Sahne, bis sie leicht und schaumig war."},{t:4,s:"Der Drink sieht sehr schaumig aus."},{t:5,s:"Das Wasser ist ganz schaumig."}]},
  "frown": {label:"Stirnrunzeln",gender:"das",plural:"—", ex5:[{t:1,s:"Er zeigte ein Stirnrunzeln."},{t:2,s:"Das Stirnrunzeln war deutlich zu sehen."},{t:3,s:"Wir bemerkten ihr Stirnrunzeln sofort."},{t:4,s:"Ein Stirnrunzeln kann oft Unmut ausdrücken."},{t:5,s:"Er betrachtete das Problem mit einem Stirnrunzeln."}]},
  "frowned": {label:"runzelte die Stirn",gender:"",plural:"—", ex5:[{t:1,s:"Er runzelte die Stirn, als er das Chaos in der Küche sah."},{t:2,s:"Sie runzelte die Stirn bei der schwierigen Matheaufgabe."},{t:3,s:"Der Lehrer runzelte die Stirn über die Schüler, die ihre Handys nutzten."},{t:4,s:"Als er die Nachricht hörte, runzelte er die Stirn."},{t:5,s:"Sie runzelte die Stirn, weil sie nicht verstand."}]},
  "frowning": {label:"die Stirn runzelnd",gender:"",plural:"—", ex5:[{t:1,s:"Sie war unzufrieden und saß mit runzelnder Stirn da."},{t:2,s:"Warum sitzt du mit runzelnder Stirn vor deinem Computer?"},{t:3,s:"Der Lehrer hörte auf, die Stirn zu runzeln, als der Schüler sich entschuldigte."},{t:4,s:"Er schaute mit runzelnder Stirn auf den Plan."},{t:5,s:"Sie schaute mich mit runzelnder Stirn an."}]},
  "frowns": {label:"runzelt die Stirn",gender:"",plural:"—", ex5:[{t:1,s:"Er runzelt die Stirn, wann immer er Mathehausaufgaben machen muss."},{t:2,s:"Sie runzelt die Stirn bei den verwirrenden Anweisungen auf der Packung."},{t:3,s:"Der Lehrer runzelt die Stirn, wenn Schüler im Unterricht reden."},{t:4,s:"Jedes Mal, wenn er das hört, runzelt er die Stirn."},{t:5,s:"Sie runzelt die Stirn, weil sie mit dem Ergebnis unzufrieden ist."}]},
  "froze": {label:"froor",gender:"",plural:"—", ex5:[{t:1,s:"Der See froor im harten Winter zu."},{t:2,s:"Ich froor vor Schreck, als ich die Schlange sah."},{t:3,s:"Die Rohre froren wegen der Kälte ein."},{t:4,s:"Er froor mitten im Satz vor Überraschung ein."},{t:5,s:"Das Wasser im Eimer froor über Nacht."}]},
  "frozen": {label:"gefroren",gender:"",plural:"—", ex5:[{t:1,s:"Der See ist im Winter gefroren."},{t:2,s:"Das Essen ist tief gefroren."},{t:3,s:"Wir haben das gefrorene Fleisch aufgetaut."},{t:4,s:"Die gefrorenen Beeren schmecken gut."},{t:5,s:"Der Boden ist heute völlig gefroren."}]},
