  "frustrate": {label:"frustrieren",gender:"",plural:"—", ex5:[{t:1,s:"Verspätungen frustrieren uns."},{t:2,s:"Der Fehler frustriert sie sehr."},{t:3,s:"Wir frustrieren den Plan durch unsere Einwände."},{t:4,s:"Ständige Änderungen frustrieren das Team."},{t:5,s:"Es frustriert mich, wenn Dinge nicht klappen."}]},
  "frustrated": {label:"frustriert",gender:"",plural:"—", ex5:[{t:1,s:"Sie fühlte sich frustriert."},{t:2,s:"Das Team ist frustriert über das Ergebnis."},{t:3,s:"Wir waren alle frustriert von der Situation."},{t:4,s:"Er wirkt heute sehr frustriert."},{t:5,s:"Nach dem langen Warten waren sie frustriert."}]},
  "frustrates": {label:"frustrieren",gender:"",plural:"—", ex5:[{t:1,s:"Das langsame Internet frustriert mich wirklich."},{t:2,s:"Es frustriert ihn, wenn er das Rätsel nicht lösen kann."},{t:3,s:"Der mangelnde Fortschritt frustriert das ganze Team."},{t:4,s:"Ständig unterbrochen zu werden, frustriert mich sehr."},{t:5,s:"Es frustriert sie, dass niemand auf ihre E-Mail antwortet."}]},
  "frustrating": {label:"frustrierend",gender:"",plural:"—", ex5:[{t:1,s:"Es ist sehr frustrierend, wenn die Internetverbindung abbricht."},{t:2,s:"Lange Wartezeiten am Flughafen sind ziemlich frustrierend."},{t:3,s:"Sie fand die Matheaufgabe extrem frustrierend."},{t:4,s:"Es ist frustrierend, wenn man immer wieder von vorne anfangen muss."},{t:5,s:"Die ständige Ungewissheit ist sehr frustrierend."}]},
  "frustratingly": {label:"frustrierend",gender:"",plural:"—", ex5:[{t:1,s:"Der Computer ist heute frustrierend langsam."},{t:2,s:"Er war frustrierend vage bezüglich seiner Pläne."},{t:3,s:"Die Lösung war frustrierend einfach."},{t:4,s:"Das Wetter ist heute frustrierend wechselhaft."},{t:5,s:"Er hat mich frustrierend lange warten lassen."}]},
  "frustration": {label:"Frustration",gender:"die",plural:"Frustrationen", ex5:[{t:1,s:"Seine ständigen Unterbrechungen verursachten bei mir viel Frustration."},{t:2,s:"Die langsame Internetverbindung führte zu großer Frustration."},{t:3,s:"Sie äußerte ihre Frustration über die komplizierte Anleitung."},{t:4,s:"Nach der Niederlage war die Frustration im Team groß."},{t:5,s:"Er konnte seine Frustration kaum verbergen."}]},
  "frustrations": {label:"Frustrationen",gender:"die",plural:"Frustrationen", ex5:[{t:1,s:"Er äußerte seine Frustrationen über das langsame Internet."},{t:2,s:"Das Erlernen eines neuen Instruments bringt anfangs viele Frustrationen mit sich."},{t:3,s:"Sie versuchte, ihre Frustrationen während des langen Meetings zu verbergen."},{t:4,s:"Wir müssen über unsere Frustrationen offen sprechen."},{t:5,s:"Er hat viele Frustrationen in seinem Beruf erlebt."}]},
  "fry": {label:"braten",gender:"",plural:"—", ex5:[{t:1,s:"Wir braten die Eier in der Pfanne."},{t:2,s:"Der Koch brät gerade das Fleisch."},{t:3,s:"Wir braten den Fisch sehr knusprig."},{t:4,s:"Kannst du bitte die Zwiebeln kurz braten?"},{t:5,s:"Sie brät das Gemüse mit etwas Öl."}]},
  "frye": {label:"Frye",gender:"",plural:"—", ex5:[{t:1,s:"Herr Frye ist mein Lieblingslehrer für Geschichte."},{t:2,s:"Ich habe morgen einen Termin bei Dr. Frye."},{t:3,s:"Hast du Frye heute bei dem Treffen gesehen?"},{t:4,s:"Herr Frye hat uns sehr geholfen."},{t:5,s:"Wir müssen Frye noch über die Änderung informieren."}]},
  "fryer": {label:"Fritteuse",gender:"die",plural:"Fritteusen", ex5:[{t:1,s:"Die Fritteuse ist sehr heiß, seien Sie also vorsichtig."},{t:2,s:"Ich habe eine neue Heißluftfritteuse gekauft, um gesünder zu kochen."},{t:3,s:"Bitte reinigen Sie die Fritteuse, nachdem Sie mit dem Kochen fertig sind."},{t:4,s:"Die Fritteuse steht auf der Arbeitsplatte."},{t:5,s:"Er hat das Öl in der Fritteuse gewechselt."}]},
  "frying": {label:"braten",gender:"",plural:"—", ex5:[{t:1,s:"Sie brät gerade ein paar Eier zum Frühstück."},{t:2,s:"Sei vorsichtig beim Braten von Fisch, das Öl kann spritzen."},{t:3,s:"Er liebt es, Hähnchenflügel als Snack zu braten."},{t:4,s:"Das Braten von Fleisch erfordert eine heiße Pfanne."},{t:5,s:"Beim Braten in der Küche sollte man das Fenster öffnen."}]},
  "fta": {label:"Freihandelsabkommen",gender:"das",plural:"Freihandelsabkommen", ex5:[{t:1,s:"Die beiden Länder haben letztes Jahr ein neues Freihandelsabkommen unterzeichnet."},{t:2,s:"Dieses Freihandelsabkommen hilft, Zölle auf importierte Waren zu senken."},{t:3,s:"Lokale Landwirte sind besorgt über die Auswirkungen des Freihandelsabkommens."},{t:4,s:"Das Freihandelsabkommen fördert den wirtschaftlichen Austausch."},{t:5,s:"Die Verhandlungen über ein neues Freihandelsabkommen dauern an."}]},
