  "ftp": {label:"File Transfer Protocol",gender:"das",plural:"—", ex5:[{t:1,s:"Sie können die Dateien per File Transfer Protocol hochladen."},{t:2,s:"Der Server unterstützt sichere File Transfer Protocol-Verbindungen."},{t:3,s:"Ich benötige Ihre Zugangsdaten für das File Transfer Protocol."},{t:4,s:"Das File Transfer Protocol ist ein Standard für die Datenübertragung."},{t:5,s:"Wir nutzen das File Transfer Protocol für unsere Backups."}]},
  "fuchsia": {label:"Fuchsia",gender:"das",plural:"—", ex5:[{t:1,s:"Sie trug ein leuchtendes Kleid in Fuchsia zur Party."},{t:2,s:"Ich habe eine Wand in einem kräftigen Fuchsia gestrichen."},{t:3,s:"Die Blumen im Garten haben einen tiefen Ton in Fuchsia."},{t:4,s:"Fuchsia ist eine sehr auffällige Farbe."},{t:5,s:"Dieser Schal passt perfekt zu ihrem Outfit in Fuchsia."}]},
  "fudge": {label:"Fudge",gender:"das",plural:"Fudges", ex5:[{t:1,s:"Ich habe für die Party selbstgemachtes Schokoladen-Fudge zubereitet."},{t:2,s:"Möchtest du ein Stück von diesem cremigen Fudge probieren?"},{t:3,s:"Sie liebt den Geschmack von Erdnussbutter-Fudge."},{t:4,s:"Das Fudge schmeckt sehr süß und lecker."},{t:5,s:"Wir haben das Fudge als Dessert serviert."}]},
  "fuel": {label:"Treibstoff",gender:"der",plural:"Treibstoffe", ex5:[{t:1,s:"Der Treibstoff wurde knapp."},{t:2,s:"Der Treibstoff ist momentan sehr teuer."},{t:3,s:"Wir haben frischen Treibstoff nachgefüllt."},{t:4,s:"Das Auto benötigt einen speziellen Treibstoff."},{t:5,s:"Der Treibstoff reicht für die lange Reise aus."}]},
  "fueled": {label:"angeheizt",gender:"",plural:"—", ex5:[{t:1,s:"Das Feuer wurde durch trockenes Holz angeheizt."},{t:2,s:"Ihr Ehrgeiz wurde durch ihren Traum angeheizt."},{t:3,s:"Die Debatte wurde durch falsche Gerüchte angeheizt."},{t:4,s:"Seine Wut wurde durch die Provokation angeheizt."},{t:5,s:"Die Stimmung wurde durch die Musik angeheizt."}]},
  "fueling": {label:"betankend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lastwagen ist gerade beim Betanken für die lange Fahrt."},{t:2,s:"Die hohe Nachfrage ist das, was das schnelle Wachstum der Branche befeuert."},{t:3,s:"Wir befeuern das Lagerfeuer mit trockenem Holz aus dem Garten."},{t:4,s:"Das Flugzeug wird gerade betankt."},{t:5,s:"Er ist dabei, den Ofen mit Holz zu befeuern."}]},
  "fuelled": {label:"betankt",gender:"",plural:"—", ex5:[{t:1,s:"Das Auto wurde vor der langen Reise voll betankt."},{t:2,s:"Seine Wut hat den Streit noch weiter befeuert."},{t:3,s:"Das Gerücht wurde durch falsche Informationen befeuert."},{t:4,s:"Das Feuer wurde mit trockenem Holz befeuert."},{t:5,s:"Die Debatte wurde durch neue Beweise befeuert."}]},
  "fuelling": {label:"betankend",gender:"",plural:"—", ex5:[{t:1,s:"Der Lastwagen ist gerade beim Betanken an der Tankstelle."},{t:2,s:"Die hohe Nachfrage befeuert das schnelle Wachstum des Unternehmens."},{t:3,s:"Sie betanken das Flugzeug vor dem langen Flug."},{t:4,s:"Das Schiff ist gerade beim Betanken im Hafen."},{t:5,s:"Wir sind gerade dabei, den Ofen zu befeuern."}]},
  "fuels": {label:"Treibstoffe",gender:"die",plural:"Treibstoffe", ex5:[{t:1,s:"Das Auto benötigt verschiedene Arten von Treibstoffen."},{t:2,s:"Hohe Preise für Treibstoffe betreffen jeden."},{t:3,s:"Das Unternehmen produziert saubere Energie und Treibstoffe."},{t:4,s:"Es gibt viele verschiedene Treibstoffe auf dem Markt."},{t:5,s:"Wir müssen die Treibstoffe effizienter nutzen."}]},
  "fugitive": {label:"Flüchtige",gender:"der/die",plural:"Flüchtigen", ex5:[{t:1,s:"Die Polizei sucht nach dem gefährlichen Flüchtigen."},{t:2,s:"Der Flüchtige ist letzte Nacht über die Grenze entkommen."},{t:3,s:"Er lebte zehn Jahre lang als Flüchtiger."},{t:4,s:"Der Flüchtige wurde schließlich gefasst."},{t:5,s:"Die Suche nach dem Flüchtigen dauert an."}]},
  "fugitives": {label:"Flüchtige",gender:"die",plural:"Flüchtige", ex5:[{t:1,s:"Die Polizei sucht nach den Flüchtigen, die entkommen sind."},{t:2,s:"Der Film handelt von zwei Flüchtigen auf der Flucht."},{t:3,s:"Die Grenzschutzbeamten haben die Flüchtigen in der Nacht gefasst."},{t:4,s:"Die Flüchtigen versteckten sich in einem alten Haus."},{t:5,s:"Man konnte die Flüchtigen im Wald entdecken."}]},
