  "guacamole": {label:"die Guacamole",gender:"die",plural:"—", ex5:[{t:1,s:"Ich liebe es, Chips mit frischer Guacamole zu essen."},{t:2,s:"Wir haben für die Party eine leckere Guacamole zubereitet."},{t:3,s:"Ist noch Guacamole im Kühlschrank?"},{t:4,s:"Diese Guacamole schmeckt besonders gut mit etwas Limette."},{t:5,s:"Ohne Guacamole schmecken die Tacos nur halb so gut."}]},
  "guadalajara": {label:"Guadalajara",gender:"",plural:"—", ex5:[{t:1,s:"Ich plane, nächsten Sommer Guadalajara zu besuchen."},{t:2,s:"Guadalajara ist die zweitgrößte Stadt in Mexiko."},{t:3,s:"Mein Freund ist wegen seines Jobs nach Guadalajara gezogen."},{t:4,s:"Guadalajara ist bekannt für seine lebendige Kultur."},{t:5,s:"Man sagt, dass das Wetter in Guadalajara das ganze Jahr über angenehm ist."}]},
