  "guangdong": {label:"Guangdong",gender:"",plural:"—", ex5:[{t:1,s:"Mein Freund zieht für seinen neuen Job nach Guangdong."},{t:2,s:"Guangdong ist berühmt für sein köstliches Dim Sum."},{t:3,s:"Das Wetter in Guangdong kann im Sommer sehr schwül sein."},{t:4,s:"Guangdong ist eine wirtschaftlich starke Provinz."},{t:5,s:"Wir haben Freunde, die in Guangdong leben."}]},
  "guangzhou": {label:"Guangzhou",gender:"",plural:"—", ex5:[{t:1,s:"Meine Firma hat eine Niederlassung in Guangzhou."},{t:2,s:"Das Wetter in Guangzhou ist recht schwül."},{t:3,s:"Wir fliegen für eine Geschäftsreise nach Guangzhou."},{t:4,s:"Guangzhou ist eine große Stadt in Südchina."},{t:5,s:"Er arbeitet seit zwei Jahren in Guangzhou."}]},
  "guano": {label:"Guano",gender:"der",plural:"—", ex5:[{t:1,s:"Landwirte nutzten Guano als natürlichen Dünger."},{t:2,s:"Die Insel war einst reich an Guano."},{t:3,s:"Guano ist wegen seines hohen Stickstoffgehalts wertvoll."},{t:4,s:"Der Handel mit Guano war früher sehr bedeutend."},{t:5,s:"Man findet Guano oft auf abgelegenen Inseln."}]},
  "guarantee": {label:"garantieren",gender:"",plural:"—", ex5:[{t:1,s:"Marken garantieren eine gewisse Qualität."},{t:2,s:"Wir garantieren eine Rückerstattung bei Defekten."},{t:3,s:"Der Erfolg ist nicht immer zu garantieren."},{t:4,s:"Ich kann dir nicht garantieren, dass es klappt."},{t:5,s:"Dieses Unternehmen garantiert faire Arbeitsbedingungen."}]},
