  "guaranteeing": {label:"garantierend",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind dabei, die Qualität des Produkts zu garantieren."},{t:2,s:"Harte Arbeit ist garantierend für seinen Erfolg."},{t:3,s:"Die neue Politik ist garantierend für gleiche Rechte."},{t:4,s:"Das Unternehmen ist garantierend für Sicherheit am Arbeitsplatz."},{t:5,s:"Diese Maßnahme ist garantierend für eine bessere Zukunft."}]},
  "guarantees": {label:"garantieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma garantiert für die Qualität ihrer Produkte."},{t:2,s:"Harte Arbeit garantiert bessere Ergebnisse in der Zukunft."},{t:3,s:"Diese Garantie garantiert eine kostenlose Reparatur für ein Jahr."},{t:4,s:"Ich garantiere dir, dass alles gut wird."},{t:5,s:"Er garantiert den Erfolg des Projekts."}]},
