  "guaranty": {label:"Garantie",gender:"die",plural:"Garantien", ex5:[{t:1,s:"Die Bank verlangt eine finanzielle Garantie für das Darlehen."},{t:2,s:"Diese Urkunde dient als Garantie für die Produktqualität."},{t:3,s:"Er unterschrieb die Garantie, um die Schulden seines Freundes zu decken."},{t:4,s:"Man braucht eine schriftliche Garantie für den Kauf."},{t:5,s:"Die Garantie gilt für alle technischen Mängel."}]},
  "guard": {label:"Wächter",gender:"der",plural:"Wächter", ex5:[{t:1,s:"Die Wächter bewachen das Tor."},{t:2,s:"Der Wächter ist sehr aufmerksam."},{t:3,s:"Wir wachen über die Tür."},{t:4,s:"Ein wachsamer Wächter steht am Eingang."},{t:5,s:"Die Wächter schützen das Schloss."}]},
  "guarded": {label:"bewacht",gender:"",plural:"—", ex5:[{t:1,s:"Der Palast wird von vielen Soldaten bewacht."},{t:2,s:"Er hat sein Geheimnis sorgfältig bewacht."},{t:3,s:"Der Hund bewachte das Haus die ganze Nacht."},{t:4,s:"Das Gebäude ist rund um die Uhr bewacht."},{t:5,s:"Der Schatz wird gut bewacht."}]},
