  "guardian": {label:"Vormund",gender:"der",plural:"Vormünder", ex5:[{t:1,s:"Der Hund agiert als treuer Beschützer für das kleine Kind."},{t:2,s:"Eltern sind die natürlichen Vormünder ihrer Kinder."},{t:3,s:"Die Statue steht als Wächter vor dem Stadttor."},{t:4,s:"Er ist der gesetzliche Vormund des Jungen."},{t:5,s:"Der Vormund muss bei der Entscheidung zustimmen."}]},
  "guardians": {label:"Vormünder",gender:"die",plural:"Vormünder", ex5:[{t:1,s:"Eltern sind die natürlichen Vormünder ihrer Kinder."},{t:2,s:"Die alten Statuen fungierten als Wächter des Tors."},{t:3,s:"Wir brauchen die gesetzlichen Vormünder, um diese Papiere zu unterschreiben."},{t:4,s:"Die Vormünder trafen sich mit dem Lehrer."},{t:5,s:"Alle Vormünder müssen informiert werden."}]},
  "guardianship": {label:"Vormundschaft",gender:"die",plural:"Vormundschaften", ex5:[{t:1,s:"Sie stand unter der Vormundschaft ihrer Tante."},{t:2,s:"Das Kind benötigt eine gesetzliche Vormundschaft."},{t:3,s:"Sie übernahmen die Vormundschaft für die verwaisten Tiere."},{t:4,s:"Die Vormundschaft wurde vom Gericht angeordnet."},{t:5,s:"Die Vormundschaft endet mit der Volljährigkeit."}]},
