  "gumbo": {label:"Gumbo",gender:"das",plural:"Gumbos", ex5:[{t:1,s:"Sie kochte einen köstlichen Teller Gumbo mit Meeresfrüchten."},{t:2,s:"Gumbo ist ein beliebtes Gericht in den südlichen Vereinigten Staaten."},{t:3,s:"Möchtest du etwas würziges Gumbo probieren?"},{t:4,s:"Das Gumbo im Restaurant schmeckte hervorragend."},{t:5,s:"Jeder hat sein eigenes Rezept für ein traditionelles Gumbo."}]},
  "gummy": {label:"gummig",gender:"",plural:"—", ex5:[{t:1,s:"Ich liebe es, Gummibärchen zu essen, wenn ich Filme schaue."},{t:2,s:"Der Boden fühlte sich wegen der verschütteten Limonade gummig an."},{t:3,s:"Meine Hände wurden gummig, nachdem ich mit dem Kleber gespielt hatte."},{t:4,s:"Das Fleisch war zäh und hatte eine gummige Konsistenz."},{t:5,s:"Nach dem Regen wurde der Boden im Garten schlammig und gummig."}]},
