  "herder": {label:"Hirte",gender:"der",plural:"Hirten", ex5:[{t:1,s:"Der Hirte führte die Schafe zur Weide."},{t:2,s:"Ein wettergegerbter Hirte bewachte die Herde."},{t:3,s:"Der Hirte pfiff nach seinem Hund."},{t:4,s:"Die Hirten leben oft ein einfaches Leben."},{t:5,s:"Der Hirte treibt die Tiere ins Tal."}]},
