  "heterogeneity": {label:"Heterogenität",gender:"die",plural:"Heterogenitäten", ex5:[{t:1,s:"Die Heterogenität der Gruppe macht unsere Diskussionen sehr interessant."},{t:2,s:"Die Stadt ist für die kulturelle Heterogenität ihrer Bewohner bekannt."},{t:3,s:"Wir müssen die Heterogenität der gesammelten Daten berücksichtigen."},{t:4,s:"Die Heterogenität der Meinungen führte zu einer langen Debatte."},{t:5,s:"Man sollte die Heterogenität der Zielgruppe nicht unterschätzen."}]},
  "heterogeneous": {label:"heterogen",gender:"",plural:"—", ex5:[{t:1,s:"Die Klasse war sehr heterogen zusammengesetzt."},{t:2,s:"Sie untersuchten eine heterogene Gruppe von Teilnehmern."},{t:3,s:"Die Mischung war heterogen und nicht einheitlich."},{t:4,s:"Es ist eine heterogene Gesellschaft mit vielen verschiedenen Kulturen."},{t:5,s:"Die Datenlage ist sehr heterogen."}]},
