  "heuristic": {label:"Heuristik",gender:"die",plural:"Heuristiken", ex5:[{t:1,s:"Wir nutzen eine einfache Heuristik, um dieses mathematische Problem zu lösen."},{t:2,s:"Der heuristische Ansatz half uns, die Antwort schnell zu finden."},{t:3,s:"Er entwickelte eine neue Heuristik für bessere Entscheidungsfindungen."},{t:4,s:"Eine gute Heuristik spart oft viel Zeit."},{t:5,s:"Diese Heuristik ist in der Informatik weit verbreitet."}]},
  "heuristics": {label:"Heuristiken",gender:"die",plural:"Heuristiken", ex5:[{t:1,s:"Er verwendet einfache Heuristiken, um schnelle Geschäftsentscheidungen zu treffen."},{t:2,s:"Manchmal kann das Vertrauen auf mentale Heuristiken zu kognitiven Verzerrungen führen."},{t:3,s:"Das Team wandte verschiedene Heuristiken an, um das komplexe Rätsel zu lösen."},{t:4,s:"Heuristiken helfen uns dabei, den Alltag effizient zu bewältigen."},{t:5,s:"Wissenschaftler untersuchen, wie Heuristiken unsere Urteile beeinflussen."}]},
