  "how": {label:"wie",gender:"",plural:"—", ex5:[{t:1,s:"Weißt du, wie man Klavier spielt?"},{t:2,s:"Wie war dein Tag in der Schule heute?"},{t:3,s:"Ich frage mich, wie sie die Arbeit so schnell beendet haben."},{t:4,s:"Wie funktioniert diese Maschine eigentlich?"},{t:5,s:"Lass uns sehen, wie sich die Dinge entwickeln."}]},
  "howard": {label:"Howard",gender:"",plural:"—", ex5:[{t:1,s:"Howard ist ein sehr freundlicher Mann."},{t:2,s:"Ich arbeite zusammen mit Howard im Krankenhaus."},{t:3,s:"Howard hat mir geholfen, mein kaputtes Fahrrad zu reparieren."},{t:4,s:"Gestern habe ich Howard im Park getroffen."},{t:5,s:"Howard ist mein bester Kollege."}]},
  "howdy": {label:"Hallo",gender:"",plural:"—", ex5:[{t:1,s:"Der freundliche Cowboy winkte und sagte: „Hallo, Partner!“"},{t:2,s:"Er sagte jedem, den er traf, ein fröhliches Hallo."},{t:3,s:"Sag einfach Hallo, wenn du in den Laden gehst."},{t:4,s:"Ein freundliches Hallo ist der beste Weg, ein Gespräch zu beginnen."},{t:5,s:"Er begrüßte uns alle mit einem herzlichen Hallo."}]},
  "howe": {label:"Howe",gender:"",plural:"—", ex5:[{t:1,s:"Herr Howe ist unser neuer Geschichtslehrer."},{t:2,s:"Ich habe auf der Konferenz eine Person namens Howe kennengelernt."},{t:3,s:"Die Familie Howe ist in das Haus nebenan eingezogen."},{t:4,s:"Ich habe Herrn Howe heute Morgen begrüßt."},{t:5,s:"Herr Howe erklärt die Geschichte sehr gut."}]},
  "howell": {label:"Howell",gender:"",plural:"—", ex5:[{t:1,s:"Herr Howell ist unser neuer Mathematiklehrer."},{t:2,s:"Ich habe im Park eine Person namens Howell getroffen."},{t:3,s:"Howell hat ein interessantes Buch über Geschichte geschrieben."},{t:4,s:"Die Schüler mögen Herrn Howell sehr."},{t:5,s:"Ich habe mit Howell über sein Buch gesprochen."}]},
  "howes": {label:"Funktionsweise",gender:"die",plural:"Funktionsweisen", ex5:[{t:1,s:"Der Lehrer erklärt die Funktionsweise und die Gründe der wissenschaftlichen Theorie."},{t:2,s:"Du solltest die Funktionsweise dieser komplexen Maschine verstehen."},{t:3,s:"Er kennt die Funktionsweise der Reparatur eines kaputten Waschbeckens genau."},{t:4,s:"Wir haben die Funktionsweise des Geräts analysiert."},{t:5,s:"Die Funktionsweise dieses Systems ist sehr effizient."}]},
  "however": {label:"jedoch",gender:"",plural:"—", ex5:[{t:1,s:"Es regnete; wir sind jedoch losgegangen."},{t:2,s:"Der Plan schlug fehl; die Hoffnung blieb jedoch bestehen."},{t:3,s:"Wir haben es versucht; es ist jedoch zerbrochen."},{t:4,s:"Er ist sehr beschäftigt, jedoch hilft er uns immer."},{t:5,s:"Der Weg ist steil, jedoch lohnt es sich."}]},
  "howie": {label:"Howie",gender:"",plural:"—", ex5:[{t:1,s:"Howie ist mein bester Freund aus der Grundschule."},{t:2,s:"Ich habe Howie eingeladen, mit uns den Film anzusehen."},{t:3,s:"Howie spielt am Wochenende sehr gerne Fußball."},{t:4,s:"Ich treffe mich heute mit Howie."},{t:5,s:"Howie ist ein wirklich guter Freund."}]},
  "howl": {label:"heulen",gender:"",plural:"—", ex5:[{t:1,s:"Der Wolf heulte den Mond an."},{t:2,s:"Der Wind heulte durch die Bäume."},{t:3,s:"Der Hund hat die ganze Nacht geheult."},{t:4,s:"Man kann den Wolf in der Ferne heulen hören."},{t:5,s:"Die Hunde heulen oft, wenn es dunkel wird."}]},
  "howling": {label:"heulend",gender:"",plural:"—", ex5:[{t:1,s:"Wir hörten nachts einen heulenden Wolf in der Ferne."},{t:2,s:"Der heulende Wind hielt uns die ganze Nacht wach."},{t:3,s:"Sie fühlte sich einsam, als sie den heulenden Wind draußen hörte."},{t:4,s:"Ein heulender Sturm zieht über das Land."},{t:5,s:"Wir saßen drinnen und hörten dem heulenden Wind zu."}]},
  "howls": {label:"heult",gender:"",plural:"—", ex5:[{t:1,s:"Der Wolf heult jede Nacht den Vollmond an."},{t:2,s:"Wir hörten die einsamen Heuler der Kojoten in der Ferne."},{t:3,s:"Der Wind heult während des Sturms durch die Bäume."},{t:4,s:"Wenn der Wind heult, bleibe ich lieber zu Hause."},{t:5,s:"Jeden Abend heult der Hund, wenn er allein ist."}]},
  "hows": {label:"Vorgehensweise",gender:"die",plural:"Vorgehensweisen", ex5:[{t:1,s:"Wir müssen die Vorgehensweise bei diesem Projekt besprechen."},{t:2,s:"Das Buch erklärt die Vorgehensweise beim Bau eines Computers."},{t:3,s:"Jeder kennt das Was, aber niemand kennt die Vorgehensweise."},{t:4,s:"Wir haben unsere Vorgehensweise grundlegend geändert."},{t:5,s:"Die genaue Vorgehensweise ist in der Anleitung beschrieben."}]},
  "hpv": {label:"HPV",gender:"das",plural:"—", ex5:[{t:1,s:"Ärzte empfehlen eine HPV-Impfung zur Vorbeugung."},{t:2,s:"Regelmäßige Untersuchungen helfen, Probleme durch HPV früh zu erkennen."},{t:3,s:"Die meisten Menschen wissen nicht, dass sie mit HPV infiziert sind."},{t:4,s:"Das HPV kann bei Frauen zu Gebärmutterhalskrebs führen."},{t:5,s:"Die Aufklärung über HPV ist sehr wichtig."}]},
  "href": {label:"href",gender:"das",plural:"—", ex5:[{t:1,s:"Vergiss nicht, das href-Attribut zu deinem Link hinzuzufügen."},{t:2,s:"Der Wert für href sollte eine gültige URL sein."},{t:3,s:"Ich habe das href aktualisiert, damit es auf die neue Seite verweist."},{t:4,s:"Das href muss korrekt im HTML-Code stehen."},{t:5,s:"Prüfe bitte, ob das href auf die richtige Datei zeigt."}]},
