  "hubby": {label:"Ehemann",gender:"der",plural:"Ehemänner", ex5:[{t:1,s:"Mein Ehemann kocht heute Abend das Essen."},{t:2,s:"Ich habe eine schöne Krawatte für meinen Ehemann gekauft."},{t:3,s:"Mein Ehemann und ich machen morgen einen Ausflug."},{t:4,s:"Mein Ehemann hilft mir immer bei der Arbeit."},{t:5,s:"Ich verbringe den Abend mit meinem Ehemann."}]},
  "huber": {label:"Huber",gender:"",plural:"—", ex5:[{t:1,s:"Herr Huber ist unser neuer Mathelehrer."},{t:2,s:"Ich habe Herrn Huber angerufen, um nach den Hausaufgaben zu fragen."},{t:3,s:"Der Bericht wurde von Dr. Huber verfasst."},{t:4,s:"Herr Huber erklärt die Aufgaben sehr gut."},{t:5,s:"Ich habe mich bei Herrn Huber für die Hilfe bedankt."}]},
  "hubert": {label:"Hubert",gender:"",plural:"—", ex5:[{t:1,s:"Hubert arbeitet als Koch in einem berühmten französischen Restaurant."},{t:2,s:"Ich habe Hubert letztes Wochenende zu meiner Geburtstagsparty eingeladen."},{t:3,s:"Hubert ist sehr geschickt darin, kaputte Elektronik zu reparieren."},{t:4,s:"Hubert kocht wirklich hervorragend."},{t:5,s:"Ich treffe mich am Samstag mit Hubert."}]},
  "hubris": {label:"Hochmut",gender:"der",plural:"—", ex5:[{t:1,s:"Sein Hochmut führte zu einem jähen Fall."},{t:2,s:"Der Plan scheiterte an purem Hochmut."},{t:3,s:"Der Hochmut machte ihn blind für die Risiken."},{t:4,s:"Hochmut kommt bekanntlich vor dem Fall."},{t:5,s:"Lass dich nicht von deinem Hochmut leiten."}]},
  "hubristic": {label:"hochmütig",gender:"",plural:"—", ex5:[{t:1,s:"Seine hochmütige Behauptung, er könne nicht scheitern, erwies sich als falsch."},{t:2,s:"Der hochmütige General ignorierte alle Warnungen seiner Berater."},{t:3,s:"Eine solch hochmütige Haltung führt oft zu einem harten Absturz."},{t:4,s:"Er trat sehr hochmütig gegenüber seinen Kollegen auf."},{t:5,s:"Mit seiner hochmütigen Art macht er sich keine Freunde."}]},
  "hubs": {label:"Knotenpunkt",gender:"der",plural:"Knotenpunkte", ex5:[{t:1,s:"Frankfurt ist ein wichtiger Knotenpunkt für den internationalen Flugverkehr."},{t:2,s:"Der Bahnhof dient als zentraler Knotenpunkt für Pendler."},{t:3,s:"Wir müssen die logistischen Knotenpunkte effizienter gestalten."},{t:4,s:"Diese Stadt entwickelt sich zu einem technologischen Knotenpunkt."},{t:5,s:"Der Knotenpunkt verbindet alle wichtigen Zugstrecken miteinander."}]},
  "huckleberry": {label:"Heidelbeere",gender:"die",plural:"Heidelbeeren", ex5:[{t:1,s:"Wir haben im Wald frische Heidelbeeren gesammelt."},{t:2,s:"Die Heidelbeeren schmecken besonders gut mit Sahne."},{t:3,s:"Ich backe heute einen Kuchen mit Heidelbeeren."},{t:4,s:"Heidelbeeren sind sehr gesund und enthalten viele Vitamine."},{t:5,s:"Wir haben Heidelbeeren auf dem Markt gekauft."}]},
  "huddersfield": {label:"Huddersfield",gender:"",plural:"—", ex5:[{t:1,s:"Er ist nach Huddersfield gezogen, um seinen neuen Job anzufangen."},{t:2,s:"Huddersfield ist eine schöne Stadt in West Yorkshire."},{t:3,s:"Wir sind mit dem Zug nach Huddersfield gefahren, um die Stadt zu besuchen."},{t:4,s:"Huddersfield hat viele interessante Sehenswürdigkeiten."},{t:5,s:"Ich habe ein paar Tage in Huddersfield verbracht."}]},
