  "huddled": {label:"zusammengekuschelt",gender:"",plural:"—", ex5:[{t:1,s:"Die kalten Welpen saßen zusammengekuschelt da."},{t:2,s:"Wir haben uns während des Gewitters zusammengekuschelt."},{t:3,s:"Die Spieler standen zusammengekuschelt auf dem Feld."},{t:4,s:"Die Kinder saßen zusammengekuschelt vor dem Kamin."},{t:5,s:"Die Vögel saßen zusammengekuschelt auf dem Ast."}]},
  "hudson": {label:"Hudson",gender:"",plural:"—", ex5:[{t:1,s:"Das Schiff fuhr langsam den Hudson River entlang."},{t:2,s:"Hudson ist ein beliebter Vorname für Jungen in dieser Stadt."},{t:3,s:"Wir sind mit der Fähre über den Hudson gefahren, um die Aussicht zu genießen."},{t:4,s:"Der Hudson ist ein sehr bekannter Fluss."},{t:5,s:"Wir haben den Hudson von der Brücke aus betrachtet."}]},
  "hue": {label:"Farbton",gender:"der",plural:"Farbtöne", ex5:[{t:1,s:"Die Blumen zeigen jeden erdenklichen Farbton."},{t:2,s:"Die Herbstblätter nahmen einen tiefroten Farbton an."},{t:3,s:"Er strich die Wand in einem sanften blauen Farbton."},{t:4,s:"Dieser Farbton passt sehr gut zu deiner Hose."},{t:5,s:"Der Himmel veränderte seinen Farbton bei Sonnenuntergang."}]},
  "hued": {label:"gefärbt",gender:"",plural:"—", ex5:[{t:1,s:"Der Sonnenuntergang war in Orange und Pink gefärbt."},{t:2,s:"Sie trug ein Kleid, das wie das tiefe Blau des Meeres gefärbt war."},{t:3,s:"Die Blätter waren in Gold und Rot gefärbt."},{t:4,s:"Der Himmel war von der Abendsonne rötlich gefärbt."},{t:5,s:"Die Blumen waren in kräftigen Farben gefärbt."}]},
  "hues": {label:"Farbtöne",gender:"die",plural:"Farbtöne", ex5:[{t:1,s:"Der Sonnenuntergang malte den Himmel in verschiedenen Farbtönen."},{t:2,s:"Der Wald zeigt im Herbst wunderschöne goldene Farbtöne."},{t:3,s:"Sie liebt Blumen mit hellen und lebendigen Farbtönen."},{t:4,s:"Das Gemälde enthält viele verschiedene Farbtöne."},{t:5,s:"Die Natur bietet uns im Frühling frische Farbtöne."}]},
  "huey": {label:"Huey",gender:"",plural:"—", ex5:[{t:1,s:"Huey ist mein bester Freund aus der Grundschule."},{t:2,s:"Ich habe gesehen, wie Huey gestern im Park Fußball gespielt hat."},{t:3,s:"Huey hat mir erzählt, dass er Pilot werden möchte."},{t:4,s:"Huey ist immer sehr gut gelaunt."},{t:5,s:"Ich habe Huey schon lange nicht mehr getroffen."}]},
  "huff": {label:"Schnauben",gender:"das",plural:"—", ex5:[{t:1,s:"Er verließ das Zimmer mit einem wütenden Schnauben."},{t:2,s:"Warum reagierst du gleich mit so einem Schnauben?"},{t:3,s:"Sie stieß ein Schnauben aus und ging gekränkt weg."},{t:4,s:"Lass das Schnauben, es bringt uns nicht weiter."},{t:5,s:"Nach dem Streit hörte man nur noch ihr Schnauben."}]},
