  "hulu": {label:"Hulu",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe gestern Abend einen tollen Film auf Hulu geschaut."},{t:2,s:"Hast du ein Abonnement bei Hulu?"},{t:3,s:"Hulu bietet viele interessante Fernsehsendungen an."},{t:4,s:"Wir schauen am Wochenende eine Serie auf Hulu."},{t:5,s:"Gibt es diese Sendung auch auf Hulu?"}]},
  "hum": {label:"Summen",gender:"das",plural:"—", ex5:[{t:1,s:"Sie summt gerne ihr Lieblingslied beim Kochen."},{t:2,s:"Die Maschine fing an, leise zu summen."},{t:3,s:"Kennst du die Melodie, die er gerade summt?"},{t:4,s:"Das Summen der Bienen ist im Sommer laut."},{t:5,s:"Ich mag das entspannende Summen des Ventilators."}]},
  "human": {label:"Mensch",gender:"der",plural:"Menschen", ex5:[{t:1,s:"Menschen passen sich schnell an."},{t:2,s:"Irren ist menschlich."},{t:3,s:"Wir schätzen die Menschenrechte sehr."},{t:4,s:"Jeder Mensch hat seine eigene Geschichte."},{t:5,s:"Der Mensch lernt aus seinen Fehlern."}]},
  "humane": {label:"human",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen eine humanere Art finden, Tiere zu behandeln."},{t:2,s:"Die Reform zielt auf humanere Bedingungen ab."},{t:3,s:"Es ist eine humane Tat, Bedürftigen zu helfen."},{t:4,s:"Die Behandlung der Gefangenen muss human sein."},{t:5,s:"Wir setzen uns für eine humane Gesellschaft ein."}]},
  "humanely": {label:"human",gender:"",plural:"—", ex5:[{t:1,s:"Die streunenden Tiere sollten human behandelt werden."},{t:2,s:"Die Organisation sorgt dafür, dass Nutztiere human gehalten werden."},{t:3,s:"Die Kriegsgefangenen wurden von den Wachen human behandelt."},{t:4,s:"Es ist wichtig, alle Wesen human zu behandeln."},{t:5,s:"Sie haben das Problem auf eine humane Weise gelöst."}]},
  "humanism": {label:"Humanismus",gender:"der",plural:"—", ex5:[{t:1,s:"Die Kunst der Renaissance war stark vom Humanismus geprägt."},{t:2,s:"Seine Philosophie wurzelt in den Werten des Humanismus."},{t:3,s:"Der Humanismus betont die Bedeutung des menschlichen Potenzials."},{t:4,s:"Wir diskutieren heute oft über den neuen Humanismus."},{t:5,s:"Der Humanismus stellt den Menschen in den Mittelpunkt."}]},
  "humanist": {label:"Humanist",gender:"der",plural:"Humanisten", ex5:[{t:1,s:"Er ist ein überzeugter Humanist, der sich für soziale Gerechtigkeit einsetzt."},{t:2,s:"Als Humanist glaubt er an die Vernunft und die Würde des Menschen."},{t:3,s:"Die Gesellschaft braucht mehr Humanisten wie ihn."},{t:4,s:"Er vertritt ein humanistisches Weltbild, das den Menschen in den Mittelpunkt stellt."},{t:5,s:"Sie wurde für ihr Engagement als Humanistin sehr geschätzt."}]},
  "humanistic": {label:"humanistisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule verfolgt einen humanistischen Bildungsansatz."},{t:2,s:"Sie vertritt eine humanistische Perspektive auf aktuelle soziale Fragen."},{t:3,s:"Der Verein legt großen Wert auf humanistische Werte wie Mitgefühl."},{t:4,s:"Das war eine sehr humanistische Geste von ihm."},{t:5,s:"Sie hat ein humanistisch geprägtes Weltbild."}]},
  "humanitarian": {label:"humanitär",gender:"",plural:"—", ex5:[{t:1,s:"Die Organisation leistet humanitäre Hilfe für die betroffenen Gebiete."},{t:2,s:"Er erhielt eine Auszeichnung für seine humanitären Bemühungen."},{t:3,s:"Sie starteten eine humanitäre Mission in das Krisengebiet."},{t:4,s:"Es ist eine humanitäre Pflicht, Bedürftigen zu helfen."},{t:5,s:"Die Lage erfordert sofortige humanitäre Unterstützung."}]},
  "humanities": {label:"Geisteswissenschaften",gender:"die",plural:"Geisteswissenschaften", ex5:[{t:1,s:"Sie studiert Geisteswissenschaften an der Universität."},{t:2,s:"Die Geisteswissenschaften helfen uns, die menschliche Kultur zu verstehen."},{t:3,s:"Viele Studenten finden die Geisteswissenschaften sehr bereichernd."},{t:4,s:"Die Forschung in den Geisteswissenschaften ist vielfältig."},{t:5,s:"Er hat einen Abschluss in den Geisteswissenschaften gemacht."}]},
  "humanity": {label:"Menschheit",gender:"die",plural:"—", ex5:[{t:1,s:"Die Menschheit steht vor großen globalen Herausforderungen."},{t:2,s:"Wir tragen eine Verantwortung für die gesamte Menschheit."},{t:3,s:"Die Geschichte der Menschheit ist faszinierend."},{t:4,s:"Das ist ein wichtiger Fortschritt für die Menschheit."},{t:5,s:"Die Menschheit muss zusammenarbeiten, um den Planeten zu schützen."}]},
  "humankind": {label:"Menschheit",gender:"die",plural:"—", ex5:[{t:1,s:"Der wissenschaftliche Fortschritt kommt der gesamten Menschheit zugute."},{t:2,s:"Wir müssen die Erde für das Wohl der Menschheit bewahren."},{t:3,s:"Die Geschichte der Menschheit ist voller bedeutender Entdeckungen."},{t:4,s:"Dies betrifft die gesamte Menschheit gleichermaßen."},{t:5,s:"Das Überleben der Menschheit hängt von nachhaltigem Handeln ab."}]},
  "humanly": {label:"menschlich",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben alles menschlich Mögliche getan, um das Gebäude zu retten."},{t:2,s:"Es ist nicht menschlich fair, von ihr zu verlangen, die ganze Nacht zu arbeiten."},{t:3,s:"Das Rettungsteam handelte so schnell, wie es menschlich möglich war."},{t:4,s:"Er hat alles menschlich Mögliche versucht."},{t:5,s:"Das übersteigt unsere menschlich begrenzten Fähigkeiten."}]},
  "humanoid": {label:"humanoid",gender:"",plural:"—", ex5:[{t:1,s:"Der Roboter hatte ein sehr humanoides Aussehen."},{t:2,s:"Wissenschaftler entwickeln immer fortschrittlichere humanoide Roboter."},{t:3,s:"Einige Science-Fiction-Filme zeigen humanoide Außerirdische."},{t:4,s:"Die Figur wirkte fast menschlich, also humanoid."},{t:5,s:"Humanoide Roboter werden in der Industrie immer wichtiger."}]},
  "humans": {label:"Mensch",gender:"der",plural:"Menschen", ex5:[{t:1,s:"Menschen brauchen täglich Wasser zum Überleben."},{t:2,s:"Kommunikation ist für alle Menschen wichtig."},{t:3,s:"Menschen haben viele erstaunliche Technologien entwickelt."},{t:4,s:"Jeder Mensch hat seine eigenen Stärken und Schwächen."},{t:5,s:"Die Menschen sind sehr unterschiedlich."}]},
