  "humbled": {label:"demütig",gender:"",plural:"—", ex5:[{t:1,s:"Die Freundlichkeit der Leute machte mich demütig."},{t:2,s:"Sie war demütig, als sie den Preis entgegennahm."},{t:3,s:"Diese Erfahrung hat ihn demütig gemacht."},{t:4,s:"Ich bin demütig angesichts dieser großen Ehre."},{t:5,s:"Er wurde durch den Erfolg demütig."}]},
  "humbling": {label:"demütigend",gender:"",plural:"—", ex5:[{t:1,s:"Der Sieg war eine demütigende Erfahrung für den Sportler."},{t:2,s:"Es ist ein demütigendes Gefühl, so talentierte Leute zu sehen."},{t:3,s:"Sie erzählte eine demütigende Geschichte aus ihrer Jugend."},{t:4,s:"Das war eine sehr demütigende Lektion für ihn."},{t:5,s:"Solche Momente wirken oft demütigend."}]},
