  "humiliation": {label:"Demütigung",gender:"die",plural:"Demütigungen", ex5:[{t:1,s:"Die öffentliche Demütigung war für ihn schwer zu ertragen."},{t:2,s:"Sie empfand tiefe Demütigung, als sie vor allen ausgeschimpft wurde."},{t:3,s:"Das Team erlitt eine bittere Demütigung."},{t:4,s:"Er wollte die Demütigung nicht einfach hinnehmen."},{t:5,s:"Diese Erfahrung war eine große Demütigung für sie."}]},
  "humility": {label:"Demut",gender:"die",plural:"—", ex5:[{t:1,s:"Er nahm den Preis mit großer Demut entgegen."},{t:2,s:"Wahre Führungspersönlichkeiten zeichnen sich oft durch Demut aus."},{t:3,s:"Sie zeigte Demut, als man sie auf ihren Fehler hinwies."},{t:4,s:"Man sollte auch im Erfolg Demut bewahren."},{t:5,s:"Seine Demut beeindruckt mich sehr."}]},
  "humming": {label:"Summen",gender:"das",plural:"—", ex5:[{t:1,s:"Sie summte eine süße Melodie beim Kochen."},{t:2,s:"Die Katze machte ein leises Summen beim Schnurren."},{t:3,s:"Ich konnte ihn im Nebenzimmer vor sich hin summen hören."},{t:4,s:"Das Summen der Bienen war im Garten zu hören."},{t:5,s:"Er begleitete das Lied mit einem leisen Summen."}]},
