  "humorist": {label:"Humorist",gender:"der",plural:"Humoristen", ex5:[{t:1,s:"Der Humorist brachte das ganze Publikum zum Lachen."},{t:2,s:"Ein bekannter Humorist hat diese Kolumne geschrieben."},{t:3,s:"Der Humorist nahm das tägliche Leben auf lustige Art aufs Korn."},{t:4,s:"Er ist ein sehr begabter Humorist."},{t:5,s:"Der Humorist erzählte Witze über den Alltag."}]},
  "humorous": {label:"humorvoll",gender:"",plural:"—", ex5:[{t:1,s:"Er hat uns eine sehr humorvolle Geschichte erzählt."},{t:2,s:"Der Lehrer erklärt die Dinge auf eine humorvolle Weise."},{t:3,s:"Ich schaue mir gerne humorvolle Filme auf Netflix an."},{t:4,s:"Sie hat eine sehr humorvolle Art zu sprechen."},{t:5,s:"Das war ein humorvoller Abend mit Freunden."}]},
  "humour": {label:"Humor",gender:"der",plural:"—", ex5:[{t:1,s:"Er hat einen großartigen Sinn für Humor."},{t:2,s:"Das Buch ist voll von trockenem Humor."},{t:3,s:"Ich liebe seinen schwarzen Humor."},{t:4,s:"Humor hilft einem, schwierige Zeiten zu überstehen."},{t:5,s:"Sie hat viel Humor und lacht gerne."}]},
  "hump": {label:"Höcker",gender:"der",plural:"Höcker", ex5:[{t:1,s:"Das Kamel hat einen großen Höcker auf seinem Rücken."},{t:2,s:"Achte auf den Höcker auf der Straße."},{t:3,s:"Sie spürte einen Höcker unter dem Teppich."},{t:4,s:"Der Boden hat einen kleinen Höcker."},{t:5,s:"Kamele speichern Fett in ihrem Höcker."}]},
  "humpback": {label:"Buckelwal",gender:"der",plural:"Buckelwale", ex5:[{t:1,s:"Wir haben einen Buckelwal aus dem Ozean springen sehen."},{t:2,s:"Buckelwale sind für ihre langen und komplexen Gesänge bekannt."},{t:3,s:"Die Bootstour bietet die Chance, einen Buckelwal zu beobachten."},{t:4,s:"Ein Buckelwal kann sehr groß werden."},{t:5,s:"Ich habe im Fernsehen eine Dokumentation über Buckelwale gesehen."}]},
