  "ibrahim": {label:"Ibrahim",gender:"der",plural:"—", ex5:[{t:1,s:"Ibrahim plant, nächste Woche seine Verwandten zu besuchen."},{t:2,s:"Ibrahim hat den ersten Preis bei der wissenschaftlichen Messe der Schule gewonnen."},{t:3,s:"Könntest du Ibrahim bitte sagen, dass ich draußen warte?"},{t:4,s:"Ich habe Ibrahim heute im Park getroffen."},{t:5,s:"Ibrahim hilft mir oft bei meinen Hausaufgaben."}]},
  "ibs": {label:"Reizdarmsyndrom",gender:"das",plural:"—", ex5:[{t:1,s:"Sie bewältigt ihr Reizdarmsyndrom durch eine gesunde Ernährung."},{t:2,s:"Stress kann oft Symptome eines Reizdarmsyndroms auslösen."},{t:3,s:"Er ging zum Arzt, weil er vermutete, dass er das Reizdarmsyndrom hat."},{t:4,s:"Das Reizdarmsyndrom ist eine sehr unangenehme Erkrankung."},{t:5,s:"Mein Arzt hat mir Tipps gegen das Reizdarmsyndrom gegeben."}]},
  "ibuprofen": {label:"Ibuprofen",gender:"das",plural:"—", ex5:[{t:1,s:"Ich habe gegen meine Kopfschmerzen Ibuprofen genommen."},{t:2,s:"Hast du Ibuprofen in deiner Tasche?"},{t:3,s:"Der Arzt empfahl, Ibuprofen gegen die Schmerzen einzunehmen."},{t:4,s:"Ibuprofen hilft mir immer sehr schnell."},{t:5,s:"Du solltest Ibuprofen nur nach Anweisung einnehmen."}]},
  "icarus": {label:"Ikarus",gender:"der",plural:"—", ex5:[{t:1,s:"Die Geschichte von Ikarus lehrt uns, vorsichtig zu sein."},{t:2,s:"Ikarus flog mit seinen Flügeln zu nah an die Sonne."},{t:3,s:"Viele Künstler haben die Szene des Sturzes von Ikarus gemalt."},{t:4,s:"Der Mythos von Ikarus ist eine bekannte Erzählung."},{t:5,s:"Ikarus ist ein klassisches Beispiel für menschliche Hybris."}]},
  "icc": {label:"Internationaler Strafgerichtshof",gender:"der",plural:"—", ex5:[{t:1,s:"Der Internationale Strafgerichtshof untersucht schwere Verbrechen gegen die Menschlichkeit."},{t:2,s:"Der Sitz vom Internationaler Strafgerichtshof befindet sich in den Niederlanden."},{t:3,s:"Viele Länder unterstützen die juristische Arbeit vom Internationaler Strafgerichtshof."},{t:4,s:"Der Internationale Strafgerichtshof setzt sich für Gerechtigkeit ein."},{t:5,s:"Die Urteile vom Internationaler Strafgerichtshof sind international bedeutend."}]},
  "ice": {label:"Eis",gender:"das",plural:"Eise", ex5:[{t:1,s:"Das Eis ist geschmolzen."},{t:2,s:"Das Eis auf dem See ist sehr dick."},{t:3,s:"Wir haben Eis in das Getränk gegeben."},{t:4,s:"Das Eis knackte unter unseren Schritten."},{t:5,s:"Ich brauche frisches Eis für die Gäste."}]},
  "iceberg": {label:"Eisberg",gender:"der",plural:"Eisberge", ex5:[{t:1,s:"Ein riesiger Eisberg schwamm im Meer."},{t:2,s:"Der größte Teil von einem Eisberg liegt unter Wasser."},{t:3,s:"Das Schiff wich dem Eisberg aus."},{t:4,s:"Wir sahen einen Eisberg am Horizont."},{t:5,s:"Der Eisberg glänzte in der Sonne."}]},
  "icebergs": {label:"Eisberge",gender:"die",plural:"Eisberge", ex5:[{t:1,s:"Große Eisberge trieben im kalten Nordmeer."},{t:2,s:"Schiffe müssen nachts vorsichtig wegen der Eisberge sein."},{t:3,s:"Wir haben viele Eisberge auf unserer Reise in die Arktis gesehen."},{t:4,s:"Die Eisberge leuchten im Licht der Mitternachtssonne."},{t:5,s:"Überall im Wasser waren Eisberge zu sehen."}]},
  "icebreaker": {label:"Eisbrecher",gender:"der",plural:"Eisbrecher", ex5:[{t:1,s:"Der Eisbrecher bahnte sich einen Weg durch das gefrorene Meer."},{t:2,s:"Wir haben ein lustiges Eisbrecher-Spiel vor dem Meeting gemacht."},{t:3,s:"Der Kapitän steuerte den Eisbrecher sehr vorsichtig."},{t:4,s:"Ein mächtiger Eisbrecher befreite die feststeckenden Schiffe."},{t:5,s:"Der Eisbrecher ist für die Arktis ausgerüstet."}]},
  "iced": {label:"vereist",gender:"",plural:"—", ex5:[{t:1,s:"Ich hätte gerne einen Eiskaffee ohne Zucker."},{t:2,s:"Der Kuchen war kunstvoll mit Zuckerguss vereist."},{t:3,s:"Die Straßen waren nach dem Wintersturm völlig vereist."},{t:4,s:"Wir trinken einen vereisten Tee im Sommer."},{t:5,s:"Die Scheiben waren am Morgen komplett vereist."}]},
  "iceland": {label:"Island",gender:"das",plural:"—", ex5:[{t:1,s:"Ich träume davon, eines Tages Island zu besuchen."},{t:2,s:"Das Wetter in Island kann sehr kalt sein."},{t:3,s:"Viele Touristen reisen nach Island, um die Vulkane zu sehen."},{t:4,s:"Island ist bekannt für seine heißen Quellen."},{t:5,s:"Die Landschaft von Island ist einzigartig."}]},
  "icelandic": {label:"isländisch",gender:"",plural:"—", ex5:[{t:1,s:"Ich lerne, wie man traditionelles isländisches Essen kocht."},{t:2,s:"Die isländische Landschaft ist berühmt für ihre Vulkane und Gletscher."},{t:3,s:"Sie hört in ihrer Freizeit gerne isländische Musik."},{t:4,s:"Die isländische Sprache ist sehr alt."},{t:5,s:"Er liest gerne isländische Sagen."}]},
  "ices": {label:"vereisen",gender:"",plural:"—", ex5:[{t:1,s:"Sie vereist den Kuchen mit süßem Vanilleguss."},{t:2,s:"Der See vereist während der kältesten Wintermonate."},{t:3,s:"Er kühlt seinen Knöchel, um die Schwellung nach dem Spiel zu lindern."},{t:4,s:"Die Leitungen vereisen bei diesem Frost schnell."},{t:5,s:"Man vereist den Fisch, um ihn frisch zu halten."}]},
  "icicle": {label:"Eiszapfen",gender:"der",plural:"Eiszapfen", ex5:[{t:1,s:"Ein langer Eiszapfen hing an der Dachkante."},{t:2,s:"Pass auf den herabfallenden Eiszapfen unter dem Dachvorsprung auf."},{t:3,s:"Der Eiszapfen schmolz schnell in der warmen Nachmittagssonne."},{t:4,s:"Überall am Haus hingen spitze Eiszapfen."},{t:5,s:"Der Eiszapfen ist vor dem Fenster gewachsen."}]},
  "icing": {label:"Zuckerguss",gender:"der",plural:"Zuckergüsse", ex5:[{t:1,s:"Sie hat den Geburtstagskuchen mit rosa Zuckerguss verziert."},{t:2,s:"Ich liebe den süßen Zuckerguss auf diesen Cupcakes."},{t:3,s:"Der Bäcker ist damit beschäftigt, die Plätzchen mit Zuckerguss zu überziehen."},{t:4,s:"Der Zuckerguss muss erst richtig fest werden."},{t:5,s:"Kannst du den Kuchen noch mit etwas Zuckerguss bestreichen?"}]},
