  "icon": {label:"Symbol",gender:"das",plural:"Symbole", ex5:[{t:1,s:"Das Symbol auf dem Bildschirm leuchtet."},{t:2,s:"Sie ist ein wahres Symbol ihrer Generation."},{t:3,s:"Wir haben auf das kleine Symbol getippt."},{t:4,s:"Klicke auf das Symbol, um das Programm zu öffnen."},{t:5,s:"Das Symbol stellt einen Ordner dar."}]},
  "iconic": {label:"ikonisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Eiffelturm ist ein ikonisches Symbol von Paris."},{t:2,s:"Er spielte eine ikonische Rolle in diesem berühmten Film."},{t:3,s:"Die Band performte ihren ikonischen Song beim Konzert."},{t:4,s:"Das Gebäude ist ein ikonisches Wahrzeichen der Stadt."},{t:5,s:"Ihr Stil ist absolut ikonisch."}]},
