  "iconoclastic": {label:"ikonoklastisch",gender:"",plural:"—", ex5:[{t:1,s:"Ihre ikonoklastische Kunst stellte alle Konventionen infrage."},{t:2,s:"Der ikonoklastische Denker lehnte die Ideen seiner Lehrer ab."},{t:3,s:"Sein ikonoklastischer Stil machte ihn berühmt und gehasst zugleich."},{t:4,s:"Sie verfolgt einen ikonoklastischen Ansatz in ihrer Arbeit."},{t:5,s:"Seine ikonoklastischen Ansichten sorgten für Aufsehen."}]},
  "iconography": {label:"Ikonografie",gender:"die",plural:"Ikonografien", ex5:[{t:1,s:"Der Professor erklärte die religiöse Ikonografie des Gemäldes."},{t:2,s:"Sie erforscht die Ikonografie antiker Zivilisationen."},{t:3,s:"Die Ikonografie zu verstehen hilft bei der Interpretation der Kunst."},{t:4,s:"Die Ikonografie dieses Werks ist sehr komplex."},{t:5,s:"Er schreibt seine Abschlussarbeit über christliche Ikonografie."}]},
  "icons": {label:"Symbole",gender:"die",plural:"Symbole", ex5:[{t:1,s:"Diese Symbole stehen für verschiedene Ordner auf meinem Computer."},{t:2,s:"Sie gilt als eine der Mode-Ikonen unserer Zeit."},{t:3,s:"Klicke auf die kleinen Symbole, um mehr Details zu sehen."},{t:4,s:"Auf dem Desktop befinden sich viele Symbole."},{t:5,s:"Diese Symbole helfen bei der schnellen Navigation."}]},
