  "ignites": {label:"entzündet",gender:"",plural:"—", ex5:[{t:1,s:"Ein Funke entzündet den Kraftstoff im Motor."},{t:2,s:"Dieser kleine Konflikt entzündet oft eine viel größere Auseinandersetzung."},{t:3,s:"Das trockene Gras entzündet sich bei der Sommerhitze leicht."},{t:4,s:"Ein Feuerzeug entzündet die Zigarette."},{t:5,s:"Die Zündvorrichtung entzündet das Gas zuverlässig."}]},
  "igniting": {label:"entzündend",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind gerade dabei, das Lagerfeuer für das Fest zu entzünden."},{t:2,s:"Das Streichholz war für das Entzünden des trockenen Grases verantwortlich."},{t:3,s:"Seine Rede war erfolgreich darin, die Leidenschaft der Menge zu entzünden."},{t:4,s:"Das Entzünden des Grills erfordert etwas Geduld."},{t:5,s:"Er war damit beschäftigt, die Kerzen entzündend durch den Raum zu gehen."}]},
  "ignition": {label:"Zündung",gender:"die",plural:"Zündungen", ex5:[{t:1,s:"Drehen Sie den Schlüssel in der Zündung, um das Auto zu starten."},{t:2,s:"Es gibt ein Problem mit der Zündung."},{t:3,s:"Der Mechaniker hat die Zündung an meinem LKW repariert."},{t:4,s:"Die Zündung des Motors funktionierte heute Morgen nicht."},{t:5,s:"Eine defekte Zündung kann dazu führen, dass der Motor ausgeht."}]},
  "ignoble": {label:"unwürdig",gender:"",plural:"—", ex5:[{t:1,s:"Er fand ein unwürdiges Ende, verraten von seinen engsten Verbündeten."},{t:2,s:"Zu lügen, um sich selbst zu retten, war eine unwürdige Tat."},{t:3,s:"Sie weigerte sich, auf solch unwürdige Taktiken herabzusinken."},{t:4,s:"Es ist unwürdig, andere für den eigenen Vorteil zu benutzen."},{t:5,s:"Er verließ den Raum auf eine unwürdige Weise."}]},
