  "ignored": {label:"ignoriert",gender:"",plural:"—", ex5:[{t:1,s:"Er hat das Warnschild an der Tür ignoriert."},{t:2,s:"Sie hat seine unhöflichen Kommentare ignoriert und ging weg."},{t:3,s:"Die Katze hat das Spielzeug ignoriert, das ich für sie gekauft habe."},{t:4,s:"Mein Vorschlag wurde völlig ignoriert."},{t:5,s:"Er hat mich heute Morgen einfach ignoriert."}]},
  "ignores": {label:"ignoriert",gender:"",plural:"—", ex5:[{t:1,s:"Er ignoriert immer meine Nachrichten."},{t:2,s:"Die Katze ignoriert das Spielzeug und schläft."},{t:3,s:"Sie ignoriert den Lärm und liest weiter."},{t:4,s:"Er ignoriert konsequent jeden Rat."},{t:5,s:"Das Programm ignoriert diesen Fehler einfach."}]},
  "ignoring": {label:"ignorierend",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, meine Nachrichten zu ignorieren und rede mit mir."},{t:2,s:"Er ist dabei, den Rat seiner Lehrer zu ignorieren."},{t:3,s:"Die Katze ist mich am ignorieren, weil ich sie nicht gefüttert habe."},{t:4,s:"Warum bist du dabei, alle Warnungen zu ignorieren?"},{t:5,s:"Er geht weiter, während er meine Anrufe ignoriert."}]},
