  "illusion": {label:"Illusion",gender:"die",plural:"Illusionen", ex5:[{t:1,s:"Der Trick war eine geschickte Illusion."},{t:2,s:"Er machte sich keine Illusionen über das Risiko."},{t:3,s:"Der Spiegel erzeugte die Illusion von mehr Raum."},{t:4,s:"Ich gebe mich keiner Illusion hin."},{t:5,s:"Das ist nur eine optische Illusion."}]},
  "illusions": {label:"Illusionen",gender:"die",plural:"Illusionen", ex5:[{t:1,s:"Der Zauberer zeigte erstaunliche Illusionen."},{t:2,s:"Er lebte in einer Welt voller Illusionen."},{t:3,s:"Das Gemälde erzeugte faszinierende optische Illusionen."},{t:4,s:"Man sollte sich keine falschen Illusionen machen."},{t:5,s:"Die Show bestand aus vielen verschiedenen Illusionen."}]},
