  "impudent": {label:"unverschämt",gender:"",plural:"—", ex5:[{t:1,s:"Der unverschämte Junge streckte die Zunge heraus."},{t:2,s:"Ihre unverschämte Antwort führte zu einem Tadel."},{t:3,s:"Es war unverschämt, am ersten Tag mehr Geld zu fordern."},{t:4,s:"Er hat eine unverschämte Art an sich."},{t:5,s:"Das ist eine unverschämte Forderung."}]},
  "impudently": {label:"unverschämt",gender:"",plural:"—", ex5:[{t:1,s:"Der Junge antwortete unverschämt."},{t:2,s:"Sie streckte unverschämt die Zunge heraus."},{t:3,s:"Er grinste den Lehrer unverschämt an."},{t:4,s:"Sie verhielt sich unverschämt gegenüber den Gästen."},{t:5,s:"Er redete unverschämt mit seinem Chef."}]},
