  "inadequacies": {label:"Unzulänglichkeiten",gender:"die",plural:"Unzulänglichkeiten", ex5:[{t:1,s:"Der Bericht hebt die Unzulänglichkeiten des aktuellen Systems hervor."},{t:2,s:"Er wurde sich während des Meetings seiner eigenen Unzulänglichkeiten bewusst."},{t:3,s:"Wir müssen diese Unzulänglichkeiten beheben, bevor wir das Projekt starten."},{t:4,s:"Die Unzulänglichkeiten der Planung waren offensichtlich."},{t:5,s:"Man sollte die Unzulänglichkeiten nicht ignorieren."}]},
  "inadequacy": {label:"Unzulänglichkeit",gender:"die",plural:"Unzulänglichkeiten", ex5:[{t:1,s:"Er fühlte eine gewisse Unzulänglichkeit im Vergleich zu seinen Kollegen."},{t:2,s:"Der Bericht betonte die Unzulänglichkeit der aktuellen Sicherheitsmaßnahmen."},{t:3,s:"Sie kämpfte in ihrem neuen Job mit Gefühlen der Unzulänglichkeit."},{t:4,s:"Die Unzulänglichkeit der Vorbereitung war klar erkennbar."},{t:5,s:"Er war sich der Unzulänglichkeit seiner Argumente bewusst."}]},
  "inadequate": {label:"unzulänglich",gender:"",plural:"—", ex5:[{t:1,s:"Die Lebensmittelversorgung war für die große Menschenmenge unzulänglich."},{t:2,s:"Er fühlte sich unzulänglich, weil er die Aufgabe nicht beenden konnte."},{t:3,s:"Die aktuellen Sicherheitsmaßnahmen sind völlig unzulänglich."},{t:4,s:"Eine unzulängliche Vorbereitung führt oft zu Problemen."},{t:5,s:"Das Ergebnis ist leider unzulänglich."}]},
