  "incitement": {label:"Anstiftung",gender:"die",plural:"Anstiftungen", ex5:[{t:1,s:"Die Rede wurde als Anstiftung zur Gewalt gewertet."},{t:2,s:"Er wurde wegen Anstiftung zum Aufruhr angeklagt."},{t:3,s:"Online-Plattformen werden auf Anstiftung überwacht."},{t:4,s:"Anstiftung zu Straftaten ist verboten."},{t:5,s:"Die Polizei ermittelt wegen Anstiftung."}]},
  "inciting": {label:"aufhetzen",gender:"",plural:"—", ex5:[{t:1,s:"Die Rede wurde beschuldigt, zur Gewalt aufzuhetzen."},{t:2,s:"Er wurde verhaftet, weil er die Leute zum Aufstand aufhetzte."},{t:3,s:"Hör auf, deinen Bruder gegen mich aufzuhetzen."},{t:4,s:"Es ist gefährlich, die Massen aufzuhetzen."},{t:5,s:"Sie wurde dafür bestraft, Unruhen aufzuhetzen."}]},
  "incivility": {label:"Unhöflichkeit",gender:"die",plural:"Unhöflichkeiten", ex5:[{t:1,s:"Der Kunde war schockiert über die Unhöflichkeit des Kellners."},{t:2,s:"Es gibt keine Entschuldigung für solche Unhöflichkeit am Arbeitsplatz."},{t:3,s:"Seine Unhöflichkeit gegenüber den Gästen ruinierte die Party."},{t:4,s:"Ich kann seine ständige Unhöflichkeit nicht tolerieren."},{t:5,s:"Unhöflichkeit ist ein Zeichen mangelnder Erziehung."}]},
  "inclement": {label:"ungünstig",gender:"",plural:"—", ex5:[{t:1,s:"Das Spiel wurde wegen des ungünstigen Wetters abgesagt."},{t:2,s:"Wir sollten uns bei der Wanderung auf ungünstige Bedingungen vorbereiten."},{t:3,s:"Ungünstiges Wetter verursachte heute viele Flugverspätungen."},{t:4,s:"Bei ungünstigem Wetter bleiben wir lieber zu Hause."},{t:5,s:"Das ungünstige Klima macht die Ernte schwierig."}]},
  "inclination": {label:"Neigung",gender:"die",plural:"Neigungen", ex5:[{t:1,s:"Sie hat eine Neigung zur Kunst."},{t:2,s:"Er spürte keine Neigung zu streiten."},{t:3,s:"Meine Neigung ist es, erst einmal abzuwarten."},{t:4,s:"Er hat eine natürliche Neigung zur Musik."},{t:5,s:"Ich habe keine Neigung, heute auszugehen."}]},
  "inclinations": {label:"Neigungen",gender:"die",plural:"Neigungen", ex5:[{t:1,s:"Er hat künstlerische Neigungen, daher liebt er das Malen."},{t:2,s:"Jeder hat unterschiedliche Neigungen, wenn es um Musik geht."},{t:3,s:"Ihre natürlichen Neigungen führten sie zu einer Karriere in der Wissenschaft."},{t:4,s:"Man sollte seine beruflichen Neigungen früh erkennen."},{t:5,s:"Unsere Neigungen bestimmen oft unsere Freizeitgestaltung."}]},
  "incline": {label:"Neigung",gender:"die",plural:"Neigungen", ex5:[{t:1,s:"Die Straße hat eine steile Neigung."},{t:2,s:"Ich neige dazu, dir zuzustimmen."},{t:3,s:"Er neigte den Kopf, um besser zuzuhören."},{t:4,s:"Das Gelände weist eine starke Neigung auf."},{t:5,s:"Die Neigung des Daches ist sehr steil."}]},
  "inclined": {label:"geneigt",gender:"",plural:"—", ex5:[{t:1,s:"Der Boden ist leicht zur Tür hin geneigt."},{t:2,s:"Er ist geneigt, deinem Plan zuzustimmen."},{t:3,s:"Wir gingen den geneigten Pfad hinauf zum Hügel."},{t:4,s:"Ich bin geneigt, dir zu glauben."},{t:5,s:"Das geneigte Dach lässt das Wasser gut abfließen."}]},
  "include": {label:"enthalten",gender:"",plural:"—", ex5:[{t:1,s:"Der Preis enthält die Mehrwertsteuer."},{t:2,s:"Das Set enthält eine Bedienungsanleitung."},{t:3,s:"Wir enthalten niemanden, wir laden alle ein."},{t:4,s:"Dieses Produkt enthält keine künstlichen Zusatzstoffe."},{t:5,s:"Die Liste enthält alle wichtigen Informationen."}]},
