  "incognito": {label:"inkognito",gender:"",plural:"—", ex5:[{t:1,s:"Der Prominente reiste inkognito, um Fans zu vermeiden."},{t:2,s:"Er wollte den Markt inkognito besuchen."},{t:3,s:"Manchmal macht es Spaß, inkognito auszugehen."},{t:4,s:"Er blieb den ganzen Abend inkognito."},{t:5,s:"Sie reiste inkognito durch das Land."}]},
  "incoherent": {label:"inkohärent",gender:"",plural:"—", ex5:[{t:1,s:"Er war so müde, dass seine Rede inkohärent wurde."},{t:2,s:"Der Aufsatz war inkohärent und hatte keinen klaren Punkt."},{t:3,s:"Sie hinterließ letzte Nacht eine inkohärente Nachricht."},{t:4,s:"Seine Argumentation war völlig inkohärent."},{t:5,s:"Die Antwort war inkohärent und verwirrend."}]},
