  "incomes": {label:"Einkommen",gender:"das",plural:"Einkommen", ex5:[{t:1,s:"Menschen mit unterschiedlichen Einkommen haben unterschiedliche Bedürfnisse."},{t:2,s:"Ihre Familieneinkommen sind in diesem Jahr gestiegen."},{t:3,s:"Viele Menschen suchen nach Wegen, ihre Einkommen zu erhöhen."},{t:4,s:"Die Einkommen variieren je nach Beruf."},{t:5,s:"Wir vergleichen die verschiedenen Einkommen in der Region."}]},
  "incoming": {label:"eingehend",gender:"",plural:"—", ex5:[{t:1,s:"Der eingehende Flug hat eine Stunde Verspätung."},{t:2,s:"Wir müssen täglich alle eingehenden E-Mails prüfen."},{t:3,s:"Die eingehenden Einnahmen stiegen im letzten Quartal."},{t:4,s:"Bitte bearbeiten Sie die eingehende Post."},{t:5,s:"Die eingehenden Anrufe werden weitergeleitet."}]},
