  "inconsequential": {label:"belanglos",gender:"",plural:"—", ex5:[{t:1,s:"Der Fehler war gering und völlig belanglos."},{t:2,s:"Sie stritten sich eine Stunde lang über ein belangloses Detail."},{t:3,s:"Sein Einwand erschien für das Endergebnis belanglos."},{t:4,s:"Lass uns keine Zeit mit belanglosen Dingen verschwenden."},{t:5,s:"Das ist eine belanglose Angelegenheit."}]},
  "inconsiderate": {label:"rücksichtslos",gender:"",plural:"—", ex5:[{t:1,s:"Es war rücksichtslos von ihm, die Musik so laut aufzudrehen."},{t:2,s:"Sei nicht so rücksichtslos gegenüber deinen Nachbarn."},{t:3,s:"Sie ist niemals rücksichtslos zu anderen Menschen."},{t:4,s:"Sein rücksichtsloses Verhalten hat viele verärgert."},{t:5,s:"Es ist rücksichtslos, den Müll einfach liegen zu lassen."}]},
