  "insufficiently": {label:"unzureichend",gender:"",plural:"—", ex5:[{t:1,s:"Der Raum war zum Lesen unzureichend beleuchtet."},{t:2,s:"Er hatte sich unzureichend auf die schwierige Prüfung vorbereitet."},{t:3,s:"Die Beweise waren unzureichend klar, um seine Schuld zu beweisen."},{t:4,s:"Das Projekt wurde unzureichend geplant."},{t:5,s:"Die Mitarbeiter wurden unzureichend informiert."}]},
  "insular": {label:"insulär",gender:"",plural:"—", ex5:[{t:1,s:"Das Dorf hatte eine insuläre, misstrauische Sicht auf Außenstehende."},{t:2,s:"Seine insuläre Denkweise ignorierte die weitere Welt."},{t:3,s:"Die insuläre Unternehmenskultur lehnte neue Ideen ab."},{t:4,s:"Das Leben in der Gemeinschaft war sehr insulär."},{t:5,s:"Er kritisierte die insuläre Haltung der Gruppe."}]},
