  "insulation": {label:"Isolierung",gender:"die",plural:"Isolierungen", ex5:[{t:1,s:"Gute Isolierung hält das Haus warm."},{t:2,s:"Sie haben eine zusätzliche Isolierung auf dem Dachboden angebracht."},{t:3,s:"Die Isolierung blockiert die kalte Luft effektiv."},{t:4,s:"Eine moderne Isolierung spart viel Energie."},{t:5,s:"Die Isolierung der Fenster ist beschädigt."}]},
  "insulator": {label:"Isolator",gender:"der",plural:"Isolatoren", ex5:[{t:1,s:"Gummi ist ein guter Isolator."},{t:2,s:"Ein Isolator blockiert den Wärmefluss."},{t:3,s:"Die Ummantelung des Kabels dient als Isolator."},{t:4,s:"In der Elektrotechnik ist ein Isolator sehr wichtig."},{t:5,s:"Glas kann als elektrischer Isolator verwendet werden."}]},
  "insulin": {label:"Insulin",gender:"das",plural:"—", ex5:[{t:1,s:"Menschen mit Diabetes benötigen oft Insulin."},{t:2,s:"Insulin hilft dabei, den Blutzuckerspiegel zu regulieren."},{t:3,s:"Ihr Körper produziert nicht genug Insulin."},{t:4,s:"Die Spritze enthält lebenswichtiges Insulin."},{t:5,s:"Der Arzt überwacht den Insulinspiegel des Patienten."}]},
  "insult": {label:"Beleidigung",gender:"die",plural:"Beleidigungen", ex5:[{t:1,s:"Diese Beleidigung saß tief."},{t:2,s:"Die Beleidigung war sehr hart."},{t:3,s:"Wir haben die Beleidigung einfach ignoriert."},{t:4,s:"Er entschuldigte sich für die Beleidigung."},{t:5,s:"Eine solche Beleidigung ist absolut inakzeptabel."}]},
