  "insurance": {label:"Versicherung",gender:"die",plural:"Versicherungen", ex5:[{t:1,s:"Die Versicherung deckt den Schaden ab."},{t:2,s:"Die Versicherung ist ziemlich teuer."},{t:3,s:"Wir haben eine Versicherung abgeschlossen."},{t:4,s:"Hast du eine gute Versicherung?"},{t:5,s:"Die Versicherung zahlt im Notfall."}]},
  "insurances": {label:"Versicherungen",gender:"die",plural:"Versicherungen", ex5:[{t:1,s:"Wir haben verschiedene Versicherungen verglichen, um den besten Plan zu finden."},{t:2,s:"Es gibt viele Arten von Versicherungen für dein Zuhause."},{t:3,s:"Er hat seine Versicherungen vor der Auslandsreise überprüft."},{t:4,s:"Man sollte seine Versicherungen regelmäßig kontrollieren."},{t:5,s:"Diese Versicherungen bieten unterschiedliche Leistungen an."}]},
