  "insurgents": {label:"Aufständische",gender:"die",plural:"Aufständische", ex5:[{t:1,s:"Die Aufständischen griffen die Basis bei Nacht an."},{t:2,s:"Die Armee nahm während der Schlacht mehrere Aufständische gefangen."},{t:3,s:"Die Aufständischen forderten einen Regierungswechsel."},{t:4,s:"Die Aufständischen verschanzten sich im Gebirge."},{t:5,s:"Die Aufständischen kontrollieren nun die Stadt."}]},
  "insuring": {label:"versichern",gender:"",plural:"—", ex5:[{t:1,s:"Er lässt sein neues Auto gegen Unfälle versichern."},{t:2,s:"Die Firma muss alle Mitarbeiter krankenversichern."},{t:3,s:"Wir versichern unser Haus gegen Feuerschäden."},{t:4,s:"Man sollte wertvolle Gegenstände versichern."},{t:5,s:"Das Unternehmen versichert seine Angestellten gegen Risiken."}]},
