  "intranet": {label:"Intranet",gender:"das",plural:"Intranets", ex5:[{t:1,s:"Alle Mitarbeiter nutzen das interne Intranet."},{t:2,s:"Die neue Richtlinie steht im Intranet."},{t:3,s:"Über das Intranet tauschen wir Dokumente aus."},{t:4,s:"Das Intranet ist heute leider nicht erreichbar."},{t:5,s:"Bitte loggen Sie sich im Intranet ein."}]},
  "intransigence": {label:"Unnachgiebigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Die Gespräche scheiterten an seiner Unnachgiebigkeit."},{t:2,s:"Ihre Unnachgiebigkeit verärgerte den gesamten Vorstand."},{t:3,s:"Jahrelange Unnachgiebigkeit hat die Fronten verhärtet."},{t:4,s:"Wegen seiner Unnachgiebigkeit gab es keine Einigung."},{t:5,s:"Die Unnachgiebigkeit beider Seiten blockierte den Deal."}]},
