  "intravenous": {label:"intravenös",gender:"",plural:"—", ex5:[{t:1,s:"Der Patient erhielt intravenöse Flüssigkeit."},{t:2,s:"Intravenöse Medikamente wirken oft schneller."},{t:3,s:"Der Arzt legte einen intravenösen Zugang."},{t:4,s:"Die Behandlung erfolgt meist intravenös."},{t:5,s:"Intravenöse Injektionen müssen steril sein."}]},
  "intravenously": {label:"intravenös",gender:"",plural:"—", ex5:[{t:1,s:"Das Medikament wurde im Krankenhaus intravenös verabreicht."},{t:2,s:"Er bekam Flüssigkeit intravenös zugeführt."},{t:3,s:"Vitamine können zur besseren Aufnahme intravenös gegeben werden."},{t:4,s:"Die Infusion wurde intravenös angeschlossen."},{t:5,s:"Das Mittel wirkt am besten, wenn man es intravenös spritzt."}]},
