  "introductions": {label:"Vorstellungen",gender:"die",plural:"Vorstellungen", ex5:[{t:1,s:"Der Lehrer machte kurze Vorstellungen vor dem Unterricht."},{t:2,s:"Das Buch enthält interessante Vorstellungen zu jedem Kapitel."},{t:3,s:"Wir tauschten bei dem Treffen formelle Vorstellungen aus."},{t:4,s:"Nach den Vorstellungen begannen wir mit der Arbeit."},{t:5,s:"Die Vorstellungen der neuen Kollegen verliefen gut."}]},
  "introductory": {label:"einführend",gender:"",plural:"—", ex5:[{t:1,s:"Dies ist ein einführender Kurs für Informatik."},{t:2,s:"Er hielt eine einführende Rede bei der Konferenz."},{t:3,s:"Das Buch hat ein einführendes Kapitel über Geschichte."},{t:4,s:"Das war ein sehr einführendes Gespräch."},{t:5,s:"Hier ist eine einführende Erklärung zum Thema."}]},
  "introspection": {label:"Introspektion",gender:"die",plural:"Introspektionen", ex5:[{t:1,s:"Ein ruhiger Abend ermöglichte eine tiefe Introspektion."},{t:2,s:"Durch Introspektion verstand sie ihre Ängste."},{t:3,s:"Sein Tagebuch war ein Protokoll seiner Introspektion."},{t:4,s:"Introspektion hilft dabei, sich selbst besser zu verstehen."},{t:5,s:"Manchmal braucht man Zeit für die eigene Introspektion."}]},
  "introspective": {label:"introspektiv",gender:"",plural:"—", ex5:[{t:1,s:"Er ist ein ruhiger und introspektiver Mensch."},{t:2,s:"Das Lied hat eine sehr introspektive Stimmung."},{t:3,s:"Sie verbrachte die Nacht in einer introspektiven Stimmung."},{t:4,s:"Er wirkt oft sehr introspektiv."},{t:5,s:"Ein introspektiver Blick in das eigene Innere kann helfen."}]},
  "introvert": {label:"Introvertierte",gender:"der/die",plural:"Introvertierte", ex5:[{t:1,s:"Ich bin ein Introvertierter, daher mag ich ruhige Orte."},{t:2,s:"Es ist völlig in Ordnung, ein Introvertierter zu sein."},{t:3,s:"Er ist ein Introvertierter, der gerne Bücher liest."},{t:4,s:"Viele Introvertierte schätzen die Stille."},{t:5,s:"Als Introvertierter braucht man Zeit für sich selbst."}]},
  "introverted": {label:"introvertiert",gender:"",plural:"—", ex5:[{t:1,s:"Er ist ziemlich introvertiert und liest lieber allein."},{t:2,s:"Viele introvertierte Menschen führen gerne tiefgründige Gespräche."},{t:3,s:"Sie fühlte sich in großen Menschenmengen etwas introvertiert."},{t:4,s:"Er ist ein sehr introvertierter Mensch."},{t:5,s:"Es ist keine Schande, introvertiert zu sein."}]},
  "intrude": {label:"eindringen",gender:"",plural:"—", ex5:[{t:1,s:"Ich möchte nicht in Ihr privates Gespräch eindringen."},{t:2,s:"Die lauten Nachbarn dringen oft in meine Lernzeit ein."},{t:3,s:"Bitte dringen Sie nicht in den gesperrten Bereich ein."},{t:4,s:"Das Wasser begann in den Keller einzudringen."},{t:5,s:"Man sollte nicht in die Privatsphäre anderer eindringen."}]},
  "intruder": {label:"Eindringling",gender:"der",plural:"Eindringlinge", ex5:[{t:1,s:"Der Alarm ging los, als ein Eindringling das Haus betrat."},{t:2,s:"Der Hund bellte den Eindringling im Garten an."},{t:3,s:"Wir haben Kameras installiert, um jeden Eindringling zu fassen."},{t:4,s:"Der Eindringling wurde schnell entdeckt."},{t:5,s:"Die Polizei sucht nach dem Eindringling."}]},
  "intruders": {label:"Eindringlinge",gender:"die",plural:"Eindringlinge", ex5:[{t:1,s:"Das Sicherheitssystem ist darauf ausgelegt, Eindringlinge zu stoppen."},{t:2,s:"Der Hund bellte laut, um uns vor den Eindringlingen zu warnen."},{t:3,s:"Wir müssen die Fenster abschließen, um Eindringlinge fernzuhalten."},{t:4,s:"Die Eindringlinge wurden von der Polizei gefasst."},{t:5,s:"Es gibt immer wieder Eindringlinge in diesem Gebiet."}]},
  "intruding": {label:"eindringend",gender:"",plural:"—", ex5:[{t:1,s:"Entschuldigen Sie, dass ich in Ihr privates Gespräch eindringe."},{t:2,s:"Helles Licht war in den dunklen Raum eindringend."},{t:3,s:"Bitte hören Sie auf, in meinen persönlichen Bereich einzudringen."},{t:4,s:"Ich habe das Gefühl, dass du in meine Privatsphäre eindringst."},{t:5,s:"Es ist unangenehm, wenn jemand ohne Erlaubnis eindringt."}]},
  "intrusion": {label:"Eindringen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Sicherheitssystem erkennt jedes unbefugte Eindringen."},{t:2,s:"Ich entschuldige mich für das Eindringen, aber ich muss mit Ihnen sprechen."},{t:3,s:"Ihre ständigen Fragen fühlten sich wie ein Eindringen in meine Privatsphäre an."},{t:4,s:"Das Eindringen in das Gebäude wurde sofort gemeldet."},{t:5,s:"Wir müssen uns gegen jedes Eindringen schützen."}]},
  "intrusions": {label:"Eindringungen",gender:"die",plural:"Eindringungen", ex5:[{t:1,s:"Das Sicherheitssystem erkennt jede Art von unbefugten Eindringungen."},{t:2,s:"Sie empfand diese Anrufe als Eindringungen in ihre Privatsphäre."},{t:3,s:"Wir müssen das Netzwerk vor digitalen Eindringungen schützen."},{t:4,s:"Es gab mehrere Eindringungen in das System."},{t:5,s:"Wir arbeiten daran, zukünftige Eindringungen zu verhindern."}]},
  "intrusive": {label:"aufdringlich",gender:"",plural:"—", ex5:[{t:1,s:"Hör bitte auf, so aufdringliche Fragen über mein Leben zu stellen."},{t:2,s:"Das helle Licht wirkte im dunklen Raum aufdringlich."},{t:3,s:"Sie empfand sein Verhalten als ziemlich aufdringlich."},{t:4,s:"Aufdringliche Menschen können sehr anstrengend sein."},{t:5,s:"Er hat eine sehr aufdringliche Art an sich."}]},
  "intubation": {label:"Intubation",gender:"die",plural:"Intubationen", ex5:[{t:1,s:"Der Patient benötigte eine dringende Intubation, um atmen zu können."},{t:2,s:"Die Intubation ist ein Standardverfahren bei einer Vollnarkose."},{t:3,s:"Der Arzt bereitete die Instrumente für eine sichere Intubation vor."},{t:4,s:"Nach der Intubation wurde der Patient an das Beatmungsgerät angeschlossen."},{t:5,s:"Die Intubation verlief ohne Komplikationen."}]},
  "intuition": {label:"Intuition",gender:"die",plural:"Intuitionen", ex5:[{t:1,s:"Unsere Intuition hat uns den richtigen Weg gewiesen."},{t:2,s:"Sie besitzt eine erstaunlich scharfe Intuition."},{t:3,s:"Wir vertrauen bei dieser Entscheidung auf unsere Intuition."},{t:4,s:"Manchmal sollte man seiner Intuition einfach folgen."},{t:5,s:"Seine Intuition hat ihn selten im Stich gelassen."}]},
  "intuitive": {label:"intuitiv",gender:"",plural:"—", ex5:[{t:1,s:"Die neue Software hat eine sehr intuitive Benutzeroberfläche."},{t:2,s:"Sie hat ein intuitives Gespür für die Bedürfnisse anderer Menschen."},{t:3,s:"Die Bedienung dieser Kamera ist sehr intuitiv gestaltet."},{t:4,s:"Er fand eine intuitive Lösung für das schwierige Problem."},{t:5,s:"Die Steuerung des Spiels ist einfach und intuitiv."}]},
  "intuitively": {label:"intuitiv",gender:"",plural:"—", ex5:[{t:1,s:"Ich wusste intuitiv, dass etwas nicht stimmte."},{t:2,s:"Kinder lernen intuitiv, wie man Tablets benutzt."},{t:3,s:"Sie hat intuitiv verstanden, wobei ich Hilfe brauchte."},{t:4,s:"Er hat die Situation intuitiv richtig eingeschätzt."},{t:5,s:"Wir haben uns intuitiv für den kürzeren Weg entschieden."}]},
