  "investigation": {label:"Untersuchung",gender:"die",plural:"Untersuchungen", ex5:[{t:1,s:"Die Untersuchung hat begonnen."},{t:2,s:"Die Untersuchung ist sehr umfassend."},{t:3,s:"Wir haben die Untersuchung geleitet."},{t:4,s:"Eine gründliche Untersuchung ist notwendig."},{t:5,s:"Die Ergebnisse der Untersuchung werden bald veröffentlicht."}]},
  "investigational": {label:"investigativ",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt verschrieb dem Patienten ein investigatives Medikament."},{t:2,s:"Die Firma führt investigative Studien zu neuen Impfstoffen durch."},{t:3,s:"Diese investigative Therapie zeigt vielversprechende Ergebnisse."},{t:4,s:"Investigative Methoden sind in der Forschung wichtig."},{t:5,s:"Der Patient nimmt an einer investigativen Studie teil."}]},
  "investigations": {label:"Untersuchungen",gender:"die",plural:"Untersuchungen", ex5:[{t:1,s:"Die Polizei hat Untersuchungen zu dem Unfall eingeleitet."},{t:2,s:"Weitere Untersuchungen sind nötig, um den Fall zu lösen."},{t:3,s:"Der Nachrichtenbericht erwähnte laufende Untersuchungen."},{t:4,s:"Mehrere Untersuchungen werden gleichzeitig durchgeführt."},{t:5,s:"Diese Untersuchungen dauerten mehrere Monate."}]},
  "investigative": {label:"investigativ",gender:"",plural:"—", ex5:[{t:1,s:"Die Polizei bildete ein investigatives Team zur Aufklärung des Falls."},{t:2,s:"Sie arbeitet als investigative Journalistin für eine große Zeitung."},{t:3,s:"Das Komitee erstellt einen investigativen Bericht über den Unfall."},{t:4,s:"Journalismus muss oft investigativ sein, um die Wahrheit zu finden."},{t:5,s:"Der investigative Ansatz der Behörden war sehr gründlich."}]},
  "investigator": {label:"Ermittler",gender:"der",plural:"Ermittler", ex5:[{t:1,s:"Der Ermittler kam am Tatort an."},{t:2,s:"Sie arbeitet als private Ermittlerin."},{t:3,s:"Der leitende Ermittler stellte viele Fragen."},{t:4,s:"Jeder Ermittler muss den Hinweisen präzise folgen."},{t:5,s:"Der Ermittler hat den Fall schnell gelöst."}]},
  "investigators": {label:"Ermittler",gender:"der",plural:"Ermittler", ex5:[{t:1,s:"Die Ermittler suchen nach weiteren Hinweisen."},{t:2,s:"Zwei Ermittler kamen am Tatort an."},{t:3,s:"Die Ermittler befragten alle Zeugen."},{t:4,s:"Alle Ermittler trafen sich zur Besprechung."},{t:5,s:"Die Ermittler konnten den Fall erfolgreich abschließen."}]},
