  "invitation": {label:"Einladung",gender:"die",plural:"Einladungen", ex5:[{t:1,s:"Die Einladung ist angekommen."},{t:2,s:"Die Einladung ist formell."},{t:3,s:"Wir haben eine Einladung verschickt."},{t:4,s:"Hast du die Einladung erhalten?"},{t:5,s:"Er nahm die Einladung dankend an."}]},
  "invitational": {label:"Einladungsturnier",gender:"das",plural:"Einladungsturniere", ex5:[{t:1,s:"Er gewann das jährliche Einladungsturnier im Golf."},{t:2,s:"Nur Top-Athleten können an diesem Einladungsturnier teilnehmen."},{t:3,s:"Das Einladungsturnier im Tennis zog viele berühmte Spieler an."},{t:4,s:"Das Einladungsturnier findet jedes Jahr statt."},{t:5,s:"Sie bereitet sich auf das Einladungsturnier vor."}]},
  "invitations": {label:"Einladungen",gender:"die",plural:"Einladungen", ex5:[{t:1,s:"Ich habe gestern Einladungen für meine Geburtstagsparty verschickt."},{t:2,s:"Sie hat diesen Monat viele Hochzeitseinladungen erhalten."},{t:3,s:"Die Einladungen waren mit schönen Blumen gestaltet."},{t:4,s:"Ich habe die Einladungen an alle Freunde verteilt."},{t:5,s:"Ich warte auf die Einladungen für das Fest."}]},
  "invite": {label:"einladen",gender:"",plural:"—", ex5:[{t:1,s:"Wir laden unsere Freunde zu uns ein."},{t:2,s:"Der Gastgeber lädt uns ein."},{t:3,s:"Wir laden das Team ein."},{t:4,s:"Ich möchte ihn zum Abendessen einladen."},{t:5,s:"Wir planen, alle bald einzuladen."}]},
