  "ism": {label:"Ismus",gender:"der",plural:"Ismen", ex5:[{t:1,s:"Jeder politische Ismus hat seine Anhänger."},{t:2,s:"Er hat jeden Ismus studiert, den er finden konnte."},{t:3,s:"Manchmal folgen Menschen einem Ismus ohne nachzudenken."},{t:4,s:"Dieser neue Ismus verändert die Gesellschaft."},{t:5,s:"Es gibt verschiedene Ismen in der Philosophie."}]},
  "ismail": {label:"Ismail",gender:"",plural:"—", ex5:[{t:1,s:"Ismail ist mein Partner für das Gruppenprojekt."},{t:2,s:"Ich habe Ismail heute Morgen an der Bushaltestelle gesehen."},{t:3,s:"Ismail spielt hervorragend Klavier."},{t:4,s:"Ismail ist ein sehr netter Kollege."},{t:5,s:"Ich habe Ismail gestern im Park getroffen."}]},
  "iso": {label:"ISO",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen folgt bei der Qualitätssicherung den ISO-Normen."},{t:2,s:"Die ISO-Zertifizierung bestätigt die Qualität unserer Produkte."},{t:3,s:"Wir müssen unser System aktualisieren, um die ISO-Anforderungen zu erfüllen."},{t:4,s:"Die Einhaltung der ISO-Richtlinien ist uns sehr wichtig."},{t:5,s:"Viele internationale Firmen arbeiten nach ISO-Standards."}]},
  "isolate": {label:"isolieren",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen die Ursache des Problems isolieren."},{t:2,s:"Das Labor ist dabei, den Stoff zu isolieren."},{t:3,s:"Der Forscher versucht, die Probe zu isolieren."},{t:4,s:"Es ist schwierig, das Virus vollständig zu isolieren."},{t:5,s:"Wir isolieren die betroffene Komponente für weitere Tests."}]},
  "isolated": {label:"isoliert",gender:"",plural:"—", ex5:[{t:1,s:"Das Dorf liegt völlig isoliert in den Bergen."},{t:2,s:"Dieser Vorfall ist ein isolierter Einzelfall."},{t:3,s:"Manchmal fühle ich mich in der großen Stadt isoliert."},{t:4,s:"Das Haus steht sehr isoliert auf dem Land."},{t:5,s:"Er lebt ein sehr isoliertes Leben ohne viele Kontakte."}]},
  "isolates": {label:"isoliert",gender:"",plural:"—", ex5:[{t:1,s:"Das Gebirge isoliert die beiden Täler voneinander."},{t:2,s:"Diese neue Politik isoliert das kleine Start-up-Unternehmen."},{t:3,s:"Der Wissenschaftler isoliert das Virus für seine Studie."},{t:4,s:"Die dicke Wand isoliert den Lärm von draußen."},{t:5,s:"Er isoliert seine Arbeit konsequent von seinem Privatleben."}]},
  "isolating": {label:"isolierend",gender:"",plural:"—", ex5:[{t:1,s:"Er isoliert sich zunehmend von seinen Freunden."},{t:2,s:"Die Wand wirkt isolierend gegen den Lärm von draußen."},{t:3,s:"Wir sind gerade dabei, den Erreger isolierend zu behandeln."},{t:4,s:"Er ist sehr isolierend in seinem Verhalten gegenüber Kollegen."},{t:5,s:"Das Material wirkt stark isolierend gegen Kälte."}]},
  "isolation": {label:"Isolation",gender:"die",plural:"Isolationen", ex5:[{t:1,s:"Die soziale Isolation kann sehr belastend sein."},{t:2,s:"Die Isolation des Gebäudes schützt vor Kälte."},{t:3,s:"Wir haben die Isolation des Patienten aufgehoben."},{t:4,s:"Er leidet unter der totalen Isolation."},{t:5,s:"Isolation ist in dieser Situation nicht die Lösung."}]},
  "isolationism": {label:"Isolationismus",gender:"der",plural:"—", ex5:[{t:1,s:"Das Land wandte sich vom Isolationismus ab und öffnete sich dem Welthandel."},{t:2,s:"Einige politische Gruppen vertreten weiterhin den Isolationismus."},{t:3,s:"Isolationismus kann zu einem Mangel an internationaler Zusammenarbeit führen."},{t:4,s:"Der Isolationismus hat die Außenpolitik des Landes lange geprägt."},{t:5,s:"Kritiker warnen vor den Folgen des Isolationismus."}]},
