  "isometric": {label:"isometrisch",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben isometrische Übungen gemacht, um den Rumpf zu stärken."},{t:2,s:"Der Architekt zeichnete eine isometrische Ansicht des Gebäudes."},{t:3,s:"Isometrisches Training ist sehr effektiv für den Muskelerhalt."},{t:4,s:"Die isometrische Darstellung hilft beim Verständnis der Struktur."},{t:5,s:"Durch isometrische Anspannung wird die Muskulatur gezielt gefordert."}]},
  "isotope": {label:"Isotop",gender:"das",plural:"Isotope", ex5:[{t:1,s:"Ein Isotop hat das gleiche Element, aber eine andere Masse."},{t:2,s:"Kohlenstoff kommt in verschiedenen Isotopen vor."},{t:3,s:"Ein bestimmtes Isotop wird zur Altersbestimmung alter Objekte genutzt."},{t:4,s:"Radioaktive Isotope werden in der Medizin verwendet."},{t:5,s:"Die Untersuchung der Isotope liefert wichtige wissenschaftliche Daten."}]},
  "isotopes": {label:"Isotop",gender:"das",plural:"Isotope", ex5:[{t:1,s:"Wissenschaftler nutzen Kohlenstoff-Isotope zur Altersbestimmung von Fossilien."},{t:2,s:"Manche Isotope sind instabil und setzen Strahlung frei."},{t:3,s:"Das Labor untersucht verschiedene Isotope von Sauerstoff."},{t:4,s:"Radioaktive Isotope finden in der Medizin breite Anwendung."},{t:5,s:"Die Bestimmung der Isotope hilft bei der Analyse von Bodenproben."}]},
  "isotopic": {label:"isotopisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Forscher analysierten die isotopische Zusammensetzung des Gesteins."},{t:2,s:"Die Studie konzentriert sich auf isotopische Variationen im Wasser."},{t:3,s:"Sie verwendeten einen isotopischen Tracer, um den chemischen Fluss zu verfolgen."},{t:4,s:"Isotopische Signaturen geben Aufschluss über die Herkunft der Probe."},{t:5,s:"Die isotopische Analyse ist ein Standardverfahren in der Geochemie."}]},
  "isp": {label:"Internetanbieter",gender:"der",plural:"Internetanbieter", ex5:[{t:1,s:"Ich muss bei meinem Internetanbieter wegen der langsamen Geschwindigkeit anrufen."},{t:2,s:"Welchen Internetanbieter nutzen Sie für Ihren Anschluss zu Hause?"},{t:3,s:"Der Internetanbieter versprach, die Verbindung bis morgen zu reparieren."},{t:4,s:"Ich habe meinen Vertrag beim Internetanbieter gekündigt."},{t:5,s:"Ein guter Internetanbieter ist für das Homeoffice sehr wichtig."}]},
  "isps": {label:"Internetanbieter",gender:"der",plural:"Internetanbieter", ex5:[{t:1,s:"Viele Internetanbieter bieten ihren Kunden verschiedene Geschwindigkeits-Pakete an."},{t:2,s:"Man sollte die Preise verschiedener Internetanbieter vergleichen, bevor man unterschreibt."},{t:3,s:"Einige Internetanbieter haben eine bessere Netzabdeckung in ländlichen Regionen."},{t:4,s:"Es gibt zahlreiche Internetanbieter auf dem deutschen Markt."},{t:5,s:"Die Kunden wechseln oft zwischen verschiedenen Internetanbietern."}]},
  "israel": {label:"Israel",gender:"das",plural:"—", ex5:[{t:1,s:"Sie planen für nächsten Sommer eine Reise nach Israel."},{t:2,s:"Israel hat eine sehr reiche und lange Geschichte."},{t:3,s:"Mein Cousin arbeitet derzeit in Israel."},{t:4,s:"Das Klima in Israel ist im Sommer sehr heiß."},{t:5,s:"Ich möchte gerne einmal die historischen Stätten in Israel besuchen."}]},
