  "jeopardizing": {label:"gefährdend",gender:"",plural:"—", ex5:[{t:1,s:"Er gefährdet seine Gesundheit, indem er zu viel arbeitet."},{t:2,s:"Zu schnelles Fahren ist gefährdend für alle auf der Straße."},{t:3,s:"Sie hatte Angst, ihre Karriere durch einen Fehler zu gefährden."},{t:4,s:"Er ist dabei, sein Ansehen durch solche Aussagen zu gefährden."},{t:5,s:"Das ist ein gefährdendes Verhalten für das ganze Team."}]},
  "jeopardy": {label:"Gefahr",gender:"die",plural:"Gefahren", ex5:[{t:1,s:"Sein leichtsinniges Verhalten brachte seine Karriere in Gefahr."},{t:2,s:"Die Zukunft der Firma ist aufgrund der niedrigen Verkäufe in Gefahr."},{t:3,s:"Bringe deine Gesundheit nicht durch das Auslassen von Mahlzeiten in Gefahr."},{t:4,s:"Das Projekt schwebt in großer Gefahr."},{t:5,s:"Er hat sich in Gefahr begeben."}]},
