  "jersey": {label:"Trikot",gender:"das",plural:"Trikots", ex5:[{t:1,s:"Er trug das Trikot seiner Mannschaft zum Spiel."},{t:2,s:"Der Stoff vom Trikot ist sehr angenehm zu tragen."},{t:3,s:"Sie hat sich ein gestreiftes Trikot gekauft."},{t:4,s:"Das Trikot ist aus weicher Baumwolle."},{t:5,s:"Ich wasche mein Trikot nach jedem Training."}]},
  "jerseys": {label:"Trikots",gender:"",plural:"—", ex5:[{t:1,s:"Die Spieler tragen ihre Trikots für das Spiel."},{t:2,s:"Ich möchte Trikots von meinen Lieblingsfußballern kaufen."},{t:3,s:"Der Laden verkauft Trikots in vielen verschiedenen Größen."},{t:4,s:"Wir haben neue Trikots für das Team bestellt."},{t:5,s:"Alle Trikots sind nach dem Spiel schmutzig geworden."}]},
  "jerusalem": {label:"Jerusalem",gender:"",plural:"—", ex5:[{t:1,s:"Jerusalem ist eine sehr alte und historische Stadt."},{t:2,s:"Viele Menschen reisen jedes Jahr nach Jerusalem."},{t:3,s:"Ich möchte eines Tages Jerusalem besuchen."},{t:4,s:"Jerusalem hat eine faszinierende Geschichte."},{t:5,s:"Die Architektur in Jerusalem ist einzigartig."}]},
