  "jesse": {label:"Jesse",gender:"",plural:"—", ex5:[{t:1,s:"Jesse lernt gerade schwimmen."},{t:2,s:"Ich warte darauf, dass Jesse ankommt."},{t:3,s:"Jesse hat beschlossen, dem Fußballteam beizutreten."},{t:4,s:"Jesse geht heute zum Training."},{t:5,s:"Ich habe Jesse gestern im Park gesehen."}]},
  "jessica": {label:"Jessica",gender:"",plural:"—", ex5:[{t:1,s:"Jessica ist eine tolle Lehrerin an unserer Schule."},{t:2,s:"Ich rufe Jessica an, um zu fragen, ob sie Zeit hat."},{t:3,s:"Jessica liebt es, durch die Welt zu reisen."},{t:4,s:"Jessica hat mir heute bei der Arbeit geholfen."},{t:5,s:"Ich treffe mich später mit Jessica."}]},
  "jessie": {label:"Jessie",gender:"",plural:"—", ex5:[{t:1,s:"Jessie ist meine beste Freundin in der Schule."},{t:2,s:"Ich habe Jessie angerufen, um nach den Hausaufgaben zu fragen."},{t:3,s:"Jessie spielt in ihrer Freizeit sehr gerne Klavier."},{t:4,s:"Ich verbringe viel Zeit mit Jessie."},{t:5,s:"Jessie hat mir ein schönes Lied vorgespielt."}]},
  "jest": {label:"Scherz",gender:"der",plural:"Scherze", ex5:[{t:1,s:"Er hat es nur als Scherz gesagt."},{t:2,s:"Nimm seine Worte nicht ernst, es war nur ein Scherz."},{t:3,s:"Sie machte einen kleinen Scherz über meine unordentlichen Haare."},{t:4,s:"Das war doch nur ein Scherz von ihm."},{t:5,s:"Er versteht keinen Scherz."}]},
  "jester": {label:"Hofnarr",gender:"der",plural:"Hofnarren", ex5:[{t:1,s:"Der König lachte über die Witze des Hofnarrs."},{t:2,s:"Der Hofnarr trug eine bunte Mütze mit kleinen Glocken."},{t:3,s:"Ein Hofnarr unterhielt die Gäste auf dem königlichen Fest."},{t:4,s:"Früher hatte jeder König seinen eigenen Hofnarr."},{t:5,s:"Der Hofnarr machte lustige Grimassen, um alle zu erheitern."}]},
  "jesuit": {label:"Jesuit",gender:"der",plural:"Jesuiten", ex5:[{t:1,s:"Er besuchte eine Schule der Jesuiten in seiner Heimatstadt."},{t:2,s:"Die Jesuiten sind für ihre Bildungsarbeit bekannt."},{t:3,s:"Sie lernte heute im Unterricht viel über die Geschichte der Jesuiten."},{t:4,s:"Ein Jesuit leitet das Internat in der Nähe."},{t:5,s:"Der Jesuit widmete sein Leben dem Studium und der Lehre."}]},
  "jesuits": {label:"Jesuiten",gender:"",plural:"—", ex5:[{t:1,s:"Die Jesuiten sind für ihren Fokus auf Bildung bekannt."},{t:2,s:"Er studierte Geschichte an einer von Jesuiten gegründeten Schule."},{t:3,s:"Viele Jesuiten reisten um die Welt, um ihren Glauben zu verbreiten."},{t:4,s:"Die Jesuiten legten großen Wert auf wissenschaftliche Forschung."},{t:5,s:"Man findet Schulen der Jesuiten in vielen verschiedenen Ländern."}]},
  "jesus": {label:"Jesus",gender:"der",plural:"—", ex5:[{t:1,s:"Jesus, du hast mich erschreckt!"},{t:2,s:"Sie glauben an die Lehren von Jesus."},{t:3,s:"Jesus, schau dir dieses Chaos an!"},{t:4,s:"Viele Menschen folgen den Wegen von Jesus."},{t:5,s:"Die Geschichte von Jesus ist weltweit bekannt."}]},
  "jet": {label:"Jet",gender:"der",plural:"Jets", ex5:[{t:1,s:"Der Jet hob pünktlich ab."},{t:2,s:"Dieser Jet ist extrem schnell."},{t:3,s:"Wir sind in den Jet eingestiegen."},{t:4,s:"Der Jet flog hoch über den Wolken."},{t:5,s:"Ein moderner Jet benötigt eine lange Landebahn."}]},
  "jetpack": {label:"Jetpack",gender:"das",plural:"Jetpacks", ex5:[{t:1,s:"Er träumte davon, eines Tages mit einem Jetpack zu fliegen."},{t:2,s:"Der Held benutzte ein Jetpack, um dem Bösewicht zu entkommen."},{t:3,s:"Moderne Technik macht Jetpacks immer praktischer."},{t:4,s:"Mit einem Jetpack könnte man den Stau einfach überfliegen."},{t:5,s:"Das Jetpack ist ein faszinierendes Gerät aus der Science-Fiction."}]},
  "jets": {label:"Jets",gender:"",plural:"—", ex5:[{t:1,s:"Wir beobachteten die Jets, wie sie am Himmel flogen."},{t:2,s:"Die Flugschau zeigte viele moderne militärische Jets."},{t:3,s:"Der Lärm der Jets war ohrenbetäubend."},{t:4,s:"Am Flughafen starteten heute mehrere Jets gleichzeitig."},{t:5,s:"Die Jets hinterließen weiße Streifen am blauen Himmel."}]},
