  "jeweler": {label:"Juwelier",gender:"der",plural:"Juweliere", ex5:[{t:1,s:"Der Juwelier bewertete den Diamantring."},{t:2,s:"Ein geschickter Juwelier passte die Ringgröße an."},{t:3,s:"Der Juwelier polierte die alte Halskette."},{t:4,s:"Ich habe den Juwelier um Rat gefragt."},{t:5,s:"Der Juwelier arbeitet sehr präzise."}]},
