  "jeweller": {label:"Juwelier",gender:"der",plural:"Juweliere", ex5:[{t:1,s:"Der Juwelier polierte sorgfältig den Diamantring."},{t:2,s:"Ich ging zum örtlichen Juwelier, um meine Uhr reparieren zu lassen."},{t:3,s:"Der geschickte Juwelier fertigte eine schöne Halskette von Hand an."},{t:4,s:"Der Juwelier zeigt uns die neuen Ringe."},{t:5,s:"Mein Juwelier ist sehr vertrauenswürdig."}]},
  "jewellery": {label:"Schmuck",gender:"der",plural:"—", ex5:[{t:1,s:"Sie trägt gerne handgefertigten Schmuck."},{t:2,s:"Ich habe ein Stück Schmuck für meine Mutter gekauft."},{t:3,s:"Ihre Schmucksammlung ist sehr beeindruckend."},{t:4,s:"Dieser Schmuck glänzt wunderschön."},{t:5,s:"Sie liebt es, Schmuck zu tragen."}]},
  "jewelry": {label:"Schmuck",gender:"der",plural:"—", ex5:[{t:1,s:"Der Schmuck strahlte im Licht."},{t:2,s:"Der Schmuck ist ziemlich teuer."},{t:3,s:"Wir haben Schmuck getragen."},{t:4,s:"Dieser Schmuck passt perfekt zu ihrem Kleid."},{t:5,s:"Sie hat ihren Schmuck in einer kleinen Schatulle."}]},
  "jewels": {label:"Juwelen",gender:"die",plural:"Juwelen", ex5:[{t:1,s:"Die Königin trug viele helle Juwelen."},{t:2,s:"Sie bewahrte ihre Juwelen in einer kleinen Schatulle auf."},{t:3,s:"Das Geschäft verkauft teure Juwelen."},{t:4,s:"Die Juwelen funkeln im Sonnenlicht."},{t:5,s:"Er bewundert die Juwelen in der Vitrine."}]},
  "jewish": {label:"jüdisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie feierten den jüdischen Feiertag mit der Familie."},{t:2,s:"Er studiert jüdische Geschichte an der Universität."},{t:3,s:"Das Gemeindezentrum veranstaltet viele jüdische Kulturveranstaltungen."},{t:4,s:"Das ist eine jüdische Tradition."},{t:5,s:"Sie interessieren sich für jüdische Kunst."}]},
  "jews": {label:"Juden",gender:"die",plural:"Juden", ex5:[{t:1,s:"Die Geschichte der Juden ist sehr lang und komplex."},{t:2,s:"Viele Juden feiern jedes Jahr Chanukka."},{t:3,s:"Das Museum zeigt Artefakte von Juden, die in der Region lebten."},{t:4,s:"Die Juden pflegen ihre Traditionen weltweit."},{t:5,s:"Das Zusammenleben der Juden ist ein wichtiges Thema."}]},
  "jfk": {label:"JFK",gender:"",plural:"—", ex5:[{t:1,s:"Mein Flug landet um Mitternacht am Flughafen JFK."},{t:2,s:"Wir haben ein Taxi vom JFK zum Hotel genommen."},{t:3,s:"Der JFK ist einer der geschäftigsten Flughäfen der Welt."},{t:4,s:"Am JFK herrscht immer viel Betrieb."},{t:5,s:"Wir müssen uns am JFK beeilen, um den Anschlussflug zu erreichen."}]},
