  "jocular": {label:"scherzhaft",gender:"",plural:"—", ex5:[{t:1,s:"Sein scherzhafter Ton lockerte die Stimmung im Raum sofort auf."},{t:2,s:"Sie machte eine scherzhafte Bemerkung über die lange Verspätung."},{t:3,s:"Der Professor war für seine scherzhaften Vorlesungen bekannt."},{t:4,s:"Er hat eine sehr scherzhafte Art zu reden."},{t:5,s:"Das war nur ein scherzhafter Kommentar."}]},
  "jocularity": {label:"Scherzhaftigkeit",gender:"die",plural:"Scherzhaftigkeiten", ex5:[{t:1,s:"Er ist für seine Scherzhaftigkeit selbst in ernsten Besprechungen bekannt."},{t:2,s:"Seine Scherzhaftigkeit lockerte die Stimmung im Raum auf."},{t:3,s:"Wir genossen seine Scherzhaftigkeit während der langen Autofahrt."},{t:4,s:"Mit ihrer Scherzhaftigkeit nimmt sie die Spannung aus dem Alltag."},{t:5,s:"Seine natürliche Scherzhaftigkeit macht ihn sehr beliebt."}]},
