  "junkyard": {label:"Schrottplatz",gender:"der",plural:"Schrottplätze", ex5:[{t:1,s:"Wir haben auf dem örtlichen Schrottplatz nützliche Autoteile gefunden."},{t:2,s:"Die alten kaputten Maschinen wurden zum Schrottplatz gebracht."},{t:3,s:"Er verbrachte sein Wochenende damit, auf dem Schrottplatz nach Schätzen zu suchen."},{t:4,s:"Der Schrottplatz ist riesig."},{t:5,s:"Wir besuchen den Schrottplatz regelmäßig."}]},
  "juno": {label:"Juno",gender:"die",plural:"—", ex5:[{t:1,s:"Juno ist ein beliebter Vorname für Mädchen in dieser Stadt."},{t:2,s:"Ich habe meine Katze nach der römischen Göttin Juno benannt."},{t:3,s:"Juno war überrascht, als ihre Freunde eine Party für sie organisierten."},{t:4,s:"In der Mythologie ist Juno die Königin der Götter."},{t:5,s:"Juno feiert heute ihren Geburtstag mit vielen Gästen."}]},
