  "jupiter": {label:"Jupiter",gender:"der",plural:"—", ex5:[{t:1,s:"Jupiter ist der größte Planet in unserem Sonnensystem."},{t:2,s:"Wissenschaftler schickten eine Sonde, um die Atmosphäre des Jupiter zu erforschen."},{t:3,s:"Man kann den Jupiter heute Nacht klar am Himmel sehen."},{t:4,s:"Der Jupiter hat ein sehr starkes Magnetfeld."},{t:5,s:"Viele Monde umkreisen den Planeten Jupiter."}]},
  "jurassic": {label:"jura",gender:"",plural:"—", ex5:[{t:1,s:"Das Museum besitzt eine Sammlung von Fossilien aus dem Jura."},{t:2,s:"Viele riesige Dinosaurier lebten während der Zeit des Jura."},{t:3,s:"Der Film handelt von einem Park voller Kreaturen aus dem Jura."},{t:4,s:"Geologen untersuchen die Gesteinsschichten aus dem Jura."},{t:5,s:"Die Epoche des Jura fasziniert viele Kinder."}]},
  "juries": {label:"Geschworenengericht",gender:"das",plural:"Geschworenengerichte", ex5:[{t:1,s:"Die Geschworenengerichte beraten derzeit über das Urteil im Gerichtssaal."},{t:2,s:"Verschiedene Geschworenengerichte können basierend auf den Beweisen zu unterschiedlichen Schlüssen kommen."},{t:3,s:"Es ist die Pflicht der Geschworenengerichte, sich beide Seiten genau anzuhören."},{t:4,s:"Die Geschworenengerichte müssen unparteiisch bleiben."},{t:5,s:"Die Entscheidung der Geschworenengerichte ist für den Fall entscheidend."}]},
  "jurisdiction": {label:"Rechtsprechung",gender:"die",plural:"Rechtsprechungen", ex5:[{t:1,s:"Der Fall fiel außerhalb der Rechtsprechung dieses Gerichts."},{t:2,s:"Jeder Staat hat seine eigene Rechtsprechung."},{t:3,s:"Die Polizei hatte keine Rechtsprechung jenseits der Grenze."},{t:4,s:"Das liegt außerhalb meiner Rechtsprechung."},{t:5,s:"Die Rechtsprechung in diesem Bereich ist sehr komplex."}]},
  "jurisdictional": {label:"zuständigkeitsbedingt",gender:"",plural:"—", ex5:[{t:1,s:"Dieser Fall liegt außerhalb der zuständigkeitsbedingten Grenzen unseres lokalen Gerichts."},{t:2,s:"Sie debattieren über zuständigkeitsbedingte Fragen bezüglich des Grenzstreits."},{t:3,s:"Der Vertrag definiert klar die zuständigkeitsbedingten Grenzen beider Nationen."},{t:4,s:"Es gab zuständigkeitsbedingte Schwierigkeiten bei der Klage."},{t:5,s:"Die zuständigkeitsbedingten Regeln müssen eingehalten werden."}]},
  "jurisdictions": {label:"Rechtsgebiet",gender:"das",plural:"Rechtsgebiete", ex5:[{t:1,s:"Das Verbrechen ereignete sich in verschiedenen Rechtsgebieten."},{t:2,s:"Verschiedene Staaten haben ihre eigenen Rechtsgebiete."},{t:3,s:"Dieser Fall fällt in unsere lokalen Rechtsgebiete."},{t:4,s:"Die Gesetze unterscheiden sich je nach Rechtsgebiet."},{t:5,s:"Die Zusammenarbeit zwischen den Rechtsgebieten ist wichtig."}]},
  "jurisprudence": {label:"Rechtswissenschaft",gender:"die",plural:"Rechtswissenschaften", ex5:[{t:1,s:"Er studiert Rechtswissenschaft an der Universität."},{t:2,s:"Der Professor ist ein Experte für moderne Rechtswissenschaft."},{t:3,s:"Dieser Fall ist ein klassisches Beispiel in der Rechtswissenschaft."},{t:4,s:"Die Rechtswissenschaft hilft uns, Gesetze besser zu verstehen."},{t:5,s:"Sie hat ein Buch über Rechtswissenschaft veröffentlicht."}]},
  "jurist": {label:"Jurist",gender:"der",plural:"Juristen", ex5:[{t:1,s:"Der berühmte Jurist schrieb ein Buch über Menschenrechte."},{t:2,s:"Sie ist eine angesehene Juristin im Bereich des Völkerrechts."},{t:3,s:"Der Jurist analysierte den historischen Kontext des neuen Gesetzes."},{t:4,s:"Als Jurist achtet er sehr auf Details."},{t:5,s:"Viele Juristen diskutierten über die Reform."}]},
  "juror": {label:"Geschworene",gender:"der",plural:"Geschworenen", ex5:[{t:1,s:"Der Geschworene wurde gebeten, unparteiisch zu bleiben."},{t:2,s:"Jeder Geschworene hörte dem Zeugen aufmerksam zu."},{t:3,s:"Es ist eine ernste staatsbürgerliche Pflicht, ein Geschworener zu sein."},{t:4,s:"Der Geschworene nahm an der Beratung teil."},{t:5,s:"Der Geschworene achtete auf jedes Detail der Aussage."}]},
