  "know": {label:"wissen",gender:"",plural:"—", ex5:[{t:1,s:"Wir wissen die richtige Antwort."},{t:2,s:"Das Team weiß genau, was der Plan ist."},{t:3,s:"Wir wissen den Weg zum Bahnhof."},{t:4,s:"Ich weiß nicht, wie spät es ist."},{t:5,s:"Er weiß viel über die Geschichte."}]},
  "knowing": {label:"wissend",gender:"",plural:"—", ex5:[{t:1,s:"Das Wissen um die Wahrheit ist wichtig."},{t:2,s:"Sie hat ein gutes Gespür für das Wissen, was Leute brauchen."},{t:3,s:"Wissend, wie er ist, wird er bestimmt zu spät kommen."},{t:4,s:"Ein wissender Blick wurde zwischen ihnen ausgetauscht."},{t:5,s:"Das wissende Lächeln verriet ihn."}]},
  "knowingly": {label:"wissentlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie lächelte wissentlich, als sie die Nachricht hörte."},{t:2,s:"Er hat wissentlich gegen die Regeln des Spiels verstoßen."},{t:3,s:"Sie sahen sich wissentlich an."},{t:4,s:"Man sollte nicht wissentlich lügen."},{t:5,s:"Er hat den Fehler wissentlich ignoriert."}]},
