  "knows": {label:"weiß",gender:"",plural:"—", ex5:[{t:1,s:"Jeder weiß, dass die Erde rund ist."},{t:2,s:"Sie weiß, wie man drei Sprachen spricht."},{t:3,s:"Mein Hund weiß genau, wie meine Stimme klingt."},{t:4,s:"Er weiß die Antwort auf diese Frage."},{t:5,s:"Sie weiß schon, was zu tun ist."}]},
  "knoxville": {label:"Knoxville",gender:"",plural:"—", ex5:[{t:1,s:"Knoxville ist eine bedeutende Stadt im US-Bundesstaat Tennessee."},{t:2,s:"Wir planen eine Reise, die auch einen Stopp in Knoxville beinhaltet."},{t:3,s:"Die Universität befindet sich mitten in Knoxville."},{t:4,s:"Knoxville liegt in einer sehr schönen Region."},{t:5,s:"Viele Menschen besuchen Knoxville wegen der Nähe zu den Bergen."}]},
  "knuckle": {label:"Knöchel",gender:"der",plural:"Knöchel", ex5:[{t:1,s:"Er ließ seine Knöchel knacken, bevor er zu tippen begann."},{t:2,s:"Sie wischte mit dem Knöchel einen Fleck vom Tisch."},{t:3,s:"Seine Knöchel wurden weiß, als er das Lenkrad fest umklammerte."},{t:4,s:"Ich habe mir beim Sport den Knöchel leicht gestoßen."},{t:5,s:"Man sieht die Knöchel deutlich, wenn man die Hand zur Faust ballt."}]},
  "knuckles": {label:"Fingerknöchel",gender:"die",plural:"Fingerknöchel", ex5:[{t:1,s:"Meine Fingerknöchel wurden weiß, weil ich das Seil so fest hielt."},{t:2,s:"Er klopfte mit den Fingerknöcheln an die schwere Holztür."},{t:3,s:"Nach drei Stunden Klavierspielen schmerzen ihre Fingerknöchel."},{t:4,s:"Er hat sehr ausgeprägte Fingerknöchel."},{t:5,s:"Beim Boxen schützt man die Fingerknöchel mit Bandagen."}]},
  "koala": {label:"Koala",gender:"der",plural:"Koalas", ex5:[{t:1,s:"Der Koala schlief friedlich im Baum."},{t:2,s:"Ein Koala frisst hauptsächlich Eukalyptusblätter."},{t:3,s:"Der Koala klammerte sich fest an den Ast."},{t:4,s:"Wir haben im Zoo einen Koala beobachtet."},{t:5,s:"Jeder liebt es, einen Koala zu sehen."}]},
  "koalas": {label:"Koalas",gender:"die",plural:"Koalas", ex5:[{t:1,s:"Koalas schlafen viele Stunden am Tag."},{t:2,s:"Viele Touristen möchten in Australien Koalas sehen."},{t:3,s:"Koalas fressen fast ausschließlich Eukalyptus."},{t:4,s:"In freier Wildbahn sind Koalas manchmal schwer zu finden."},{t:5,s:"Die Koalas in diesem Schutzgebiet sind sehr gut versorgt."}]},
