  "koch": {label:"Koch",gender:"der",plural:"Köche", ex5:[{t:1,s:"Der Koch bereitet ein köstliches Abendessen zu."},{t:2,s:"Robert Koch war ein berühmter Arzt und Mikrobiologe."},{t:3,s:"Wir studieren die wissenschaftliche Arbeit von Robert Koch."},{t:4,s:"Der Koch in diesem Restaurant ist sehr erfahren."},{t:5,s:"Jeder Koch hat seine eigenen Geheimrezepte."}]},
  "kodak": {label:"Kodak",gender:"die",plural:"—", ex5:[{t:1,s:"Mein Großvater benutzte eine alte Kodak-Kamera."},{t:2,s:"Kodak war früher ein sehr berühmtes Unternehmen."},{t:3,s:"Ich fand eine alte Rolle Kodak-Film in der Schublade."},{t:4,s:"Viele verbinden den Namen Kodak mit der analogen Fotografie."},{t:5,s:"Kodak hat die Geschichte der Fotografie maßgeblich geprägt."}]},
  "kofi": {label:"Kofi",gender:"der",plural:"—", ex5:[{t:1,s:"Kofi ist ein sehr freundlicher Schüler."},{t:2,s:"Ich spiele jeden Samstag mit Kofi Fußball."},{t:3,s:"Hat Kofi seine Hausaufgaben schon fertig?"},{t:4,s:"Ich habe Kofi gestern in der Stadt getroffen."},{t:5,s:"Kofi ist ein guter Freund von mir."}]},
  "kohl": {label:"Kohl",gender:"der",plural:"Kohle", ex5:[{t:1,s:"Sie betonte ihre Augen mit schwarzem Kohl."},{t:2,s:"Schon im alten Ägypten wurde Kohl als Kosmetikum verwendet."},{t:3,s:"Ein wenig Kohl lässt die Augen ausdrucksstärker wirken."},{t:4,s:"Kohl wird oft für ein dramatisches Augen-Make-up genutzt."},{t:5,s:"Das Auftragen von Kohl erfordert etwas Übung."}]},
  "kohler": {label:"Kohler",gender:"",plural:"—", ex5:[{t:1,s:"Mein Vater arbeitet seit über zwanzig Jahren bei Kohler."},{t:2,s:"Wir haben uns entschieden, eine neue Armatur von Kohler in der Küche zu installieren."},{t:3,s:"Kohler ist eine bekannte Marke für hochwertige Badezimmerausstattung."},{t:4,s:"Die Firma Kohler hat ihren Hauptsitz in den USA."},{t:5,s:"Wir haben Produkte von Kohler in unserem neuen Haus eingebaut."}]},
  "kohli": {label:"Kohli",gender:"",plural:"—", ex5:[{t:1,s:"Kohli ist ein legendärer Cricketspieler."},{t:2,s:"Jeder jubelte, als Kohli einen Punkt erzielte."},{t:3,s:"Ich habe eine Biografie über Kohli gelesen."},{t:4,s:"Viele Menschen bewundern die sportliche Leistung von Kohli."},{t:5,s:"Kohli ist ein bekannter Name im Sport."}]},
  "koi": {label:"Koi",gender:"der",plural:"Kois", ex5:[{t:1,s:"Der Gartenteich ist voll mit bunten Koi."},{t:2,s:"Sie füttert jeden Nachmittag gerne die Koi."},{t:3,s:"Ein wunderschöner Koi schwamm langsam unter der Brücke hindurch."},{t:4,s:"In diesem Teich leben viele prachtvolle Koi."},{t:5,s:"Die Haltung von Koi ist ein beliebtes Hobby."}]},
  "kolkata": {label:"Kalkutta",gender:"",plural:"—", ex5:[{t:1,s:"Kalkutta ist eine bedeutende Stadt im Osten Indiens."},{t:2,s:"Sie reist nach Kalkutta, um historische Sehenswürdigkeiten zu besuchen."},{t:3,s:"Das Essen in Kalkutta ist für seine einzigartigen Gewürze berühmt."},{t:4,s:"Kalkutta ist eine sehr lebhafte Metropole."},{t:5,s:"Viele Touristen besuchen Kalkutta wegen der reichen Kultur."}]},
  "komodo": {label:"Komodo",gender:"",plural:"—", ex5:[{t:1,s:"Der Komodowaran ist die größte lebende Echsenart."},{t:2,s:"Wir haben eine Reise zum Komodo-Nationalpark geplant, um die Warane zu sehen."},{t:3,s:"Komodo ist eine wunderschöne Insel in Indonesien."},{t:4,s:"Auf Komodo kann man die beeindruckende Natur erleben."},{t:5,s:"Die Komodo-Inseln sind bei Reisenden sehr beliebt."}]},
