  "lets": {label:"lassen",gender:"",plural:"—", ex5:[{t:1,s:"Meine Mutter lässt mich am Wochenende Spiele spielen."},{t:2,s:"Der Lehrer lässt uns heute früher nach Hause gehen."},{t:3,s:"Er lässt niemanden seine Gitarre berühren."},{t:4,s:"Mein Vater lässt mich sein Fahrrad benutzen."},{t:5,s:"Sie lässt ihre Kinder immer frei spielen."}]},
