  "levin": {label:"Levin",gender:"",plural:"—", ex5:[{t:1,s:"Herr Levin ist unser neuer Geschichtslehrer."},{t:2,s:"Ich habe Levin gestern in der Bibliothek getroffen."},{t:3,s:"Levin hat ein sehr interessantes Buch über Wissenschaft geschrieben."},{t:4,s:"Levin hat mir von seinen Plänen erzählt."},{t:5,s:"Wir besuchen zusammen mit Levin den Kurs."}]},
  "levine": {label:"Levine",gender:"",plural:"—", ex5:[{t:1,s:"Herr Levine ist mein Lieblingslehrer für Geschichte an der Schule."},{t:2,s:"Ich habe ein interessantes Buch von Dr. Levine gelesen."},{t:3,s:"Levine hat mich angerufen, um das neue Projekt zu besprechen."},{t:4,s:"Wir warten noch auf die Antwort von Levine."},{t:5,s:"Levine arbeitet sehr sorgfältig."}]},
  "levitate": {label:"schweben",gender:"",plural:"—", ex5:[{t:1,s:"Der Zauberer ließ die Karte über seiner Hand schweben."},{t:2,s:"Im Film hat die Hauptfigur die Kraft zu schweben."},{t:3,s:"Es ist unmöglich für einen Menschen, ohne Ausrüstung zu schweben."},{t:4,s:"Die Blätter schweben sanft durch die Luft."},{t:5,s:"Die Magnetschwebebahn kann über den Schienen schweben."}]},
  "levitation": {label:"Levitation",gender:"die",plural:"Levitationen", ex5:[{t:1,s:"Der Zauberer vollführte einen erstaunlichen Akt der Levitation."},{t:2,s:"Geschichten über Levitation tauchen in vielen Kulturen auf."},{t:3,s:"Wissenschaftler erforschen die magnetische Levitation für Züge."},{t:4,s:"Die Levitation ist ein klassisches Thema in der Zauberkunst."},{t:5,s:"Er behauptete, er habe eine echte Levitation gesehen."}]},
