  "liabilities": {label:"Verbindlichkeiten",gender:"die",plural:"Verbindlichkeiten", ex5:[{t:1,s:"Die Firma muss ihre Verbindlichkeiten bis zum Jahresende begleichen."},{t:2,s:"Hohe Zinsen haben unsere finanziellen Verbindlichkeiten deutlich erhöht."},{t:3,s:"Man sollte alle aktuellen Verbindlichkeiten prüfen, bevor man einen neuen Kredit aufnimmt."},{t:4,s:"Wir müssen unsere Verbindlichkeiten reduzieren."},{t:5,s:"Die Verbindlichkeiten des Unternehmens sind gestiegen."}]},
  "liability": {label:"Haftung",gender:"die",plural:"Haftungen", ex5:[{t:1,s:"Das Unternehmen übernahm die Haftung für den Fehler."},{t:2,s:"Das alte Auto wurde zu einer finanziellen Belastung."},{t:3,s:"Die Versicherung deckt einen Teil der Haftung ab."},{t:4,s:"Wir müssen die Haftung für den Schaden klären."},{t:5,s:"Er trägt die volle Haftung für sein Handeln."}]},
  "liable": {label:"haftbar",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind für jeden Schaden haftbar, den Sie verursachen."},{t:2,s:"Das Unternehmen ist für verlorene Gegenstände nicht haftbar."},{t:3,s:"Wer zu schnell fährt, ist anfällig für Unfälle."},{t:4,s:"Er ist für sein Verhalten persönlich haftbar."},{t:5,s:"Wir sind für die Folgen dieser Entscheidung haftbar."}]},
