  "lipped": {label:"umrandet",gender:"",plural:"—", ex5:[{t:1,s:"Sie umrandete beim Teetrinken den Rand der Tasse mit ihren Lippen."},{t:2,s:"Er umrandete die Worte stumm mit seinen Lippen, ohne ein Geräusch zu machen."},{t:3,s:"Die Tasse war mit einem goldenen Design umrandet."},{t:4,s:"Der Teller war mit einem blauen Muster umrandet."},{t:5,s:"Ihre Augen waren mit dunklem Kajal umrandet."}]},
  "lips": {label:"Lippen",gender:"die",plural:"Lippen", ex5:[{t:1,s:"Sie trug etwas roten Lippenstift auf ihre Lippen auf."},{t:2,s:"Er biss sich nervös auf die Lippen."},{t:3,s:"Der kalte Wind machte meine Lippen trocken."},{t:4,s:"Sie lächelte mit geschlossenen Lippen."},{t:5,s:"Ich benutze im Winter oft eine Creme für die Lippen."}]},
